UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8'::uuid, 'დედების გულახდილი საუბარი 💬', 'თავს არასაკმარისად კარგ დედად გრძნობთ? დაუყოვნებლივ შეუერთდით Anacan-ის საზოგადოებას, წაიკითხეთ სხვა დედების მხარდამჭერი კომენტარები და დამშვიდდით.'),
  ('4a0eb59e-113c-42ab-af5f-e0f64f837b44', 'აღმოაჩინეთ ახალი ადგილები. ☕', 'ყოველდღიურმა რუტინამ დაგღალათ? ჩვენს აპლიკაციაში იპოვეთ კაფე, სადაც ბავშვის ეტლით მარტივად შეხვალთ, და ყავის შესვენება მოიწყვეთ.'),
  ('4c4da832-707f-472e-a209-374acff11d94', 'დამხმარე საოჯახო საქმეებში! 🧹', 'ხელსახოცის აღება და მტვრის გადაწმენდა ან ცოცხით თამაში სურს? თქვენი მიბაძვა მისი განვითარების შესანიშნავი მაჩვენებელია.'),
  ('ca45e311-dc2b-43fe-aa24-08a197d26f0a', 'ბავშვის განვითარებასთან დაკავშირებით კითხვები გაქვთ? 🤖', 'თუ 13-14 თვის ასაკთან დაკავშირებით რაიმე გაღელვებთ, ღამის საათებშიც კი მისწერეთ ჩვენს Anacan AI ასისტენტს.'),
  ('2064ec2b-0483-4d3b-9453-106b6b9f32f8', 'პირველი გამოცდილება ფანქრებით. 🖍', '️ მიეცით მისთვის შესაფერისი მსხვილი ფანქრები და სიყვარულით უყურეთ, როგორ ჯღაბნის ფურცელზე. იქნებ მომავალი მხატვარი იზრდება!'),
  ('7f86b541-f24f-46cc-bf72-a538c8e62fa0', 'საკუთარი სათამაშოებით მარტო თამაში. 🧩', 'თუნდაც მცირე ხნით დამოუკიდებლად თამაში დამოუკიდებლობისკენ გადადგმული დიდი ნაბიჯია. შორიდან დააკვირდით.'),
  ('f945146d-2bbb-40d9-95f6-29bdc7f3be6d', 'ზრდა გრძელდება. 📏', 'თქვენი ბავშვის ტანსაცმელი უკვე პატარაა! ზრდისა და განვითარების თვალყურის დევნების განყოფილებაში დაამატეთ სიმაღლისა და წონის ახალი მაჩვენებლები და დააკვირდით მის განვითარებას.'),
  ('241a81f3-8158-4d3c-a8b2-640a1b060696', 'პრეტენზიულ კვებასთან გამკლავება. 🍲', 'ზოგიერთ დღეს შეიძლება საყვარელ საკვებზეც კი უარი თქვას. ნუ დააძალებთ, უბრალოდ სხვადასხვა ალტერნატივა შესთავაზეთ.'),
  ('4716a93b-966d-4c69-b174-c2a48e9a09fa', 'საღამოს აბაზანა. 🛁', 'თბილი აბაზანა დღის მტვრის ჩამოსაბანად სახალისოცაა, ამასთანავე ამშვიდებს ბავშვს და შესანიშნავად ამზადებს ძილისთვის.'),
  ('dbbcb16c-cf48-47f7-92ab-992ed2fab247', 'სხეულის ნაწილებს ცნობს. 👃', 'ითამაშეთ „სად არის შენი ცხვირი?“ ან „სად არის შენი ყური?“. როცა სწორად მიუთითებს, ტაში დაუკარით და გაამხნევეთ.'),
  ('0ffbde04-3193-4b21-aa17-136db5de3c72', 'ემოციების დღიური 📝', 'როცა თავს მარტოსულად იგრძნობთ, თქვენი გრძნობები განწყობის დღიურში გადმოიტანეთ. ყველა ქალი გადის ამ გზას — თქვენ ძლიერი ხართ.'),
  ('7cdfa7f4-2c92-497d-9290-43caf53d8a56', 'სიმშვიდის საჭიროება 🤫', 'ოთახში სიმშვიდე ხმის საზომის დახმარებით შეინარჩუნეთ. ღამით შეწყვეტილი ძილი დილის განწყობას როგორც ბავშვს, ისე თქვენც გიფუჭებთ.'),
  ('f39f5c34-c612-4758-a438-ed52b2d49ba8', 'გემშვიდობებით 👋', 'როცა ვინმე კარიდან გადის, ბავშვი თავისი ინიციატივით ხელს უქნევს და ემშვიდობება! ეს შესანიშნავი სოციალური რეფლექსია. ხშირად გაამხნევეთ.'),
  ('0dcb1657-4eeb-47c5-a193-84ed106d43bc', 'ნუ მოგერიდებათ კითხვა 🤖', 'ფიქრობთ, რომ ძილის რუტინაში რაღაცას არასწორად აკეთებთ? ყველაფერი, რაც გაეჭვებთ, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს და დამშვიდდით.'),
  ('10d800e4-c6bd-4325-b22e-385edaca8f7f', 'ღამით გაღვიძებები გრძელდება? 😴', 'თუ ბოლო დღეებში ბავშვს ძილი კვლავ აერია, Anacan-ის ძილის ტაიმერით გააანალიზეთ გრაფიკი და რეჟიმში არსებული ხარვეზები აღმოაჩინეთ.'),
  ('319cae50-0492-468a-98e4-1b38563ab7ea', '14 თვისკენ! დარჩა 10 დღე! 🎂', 'დაუჯერებელია! ზუსტად 10 დღეში თქვენი პატარა 14 თვის გახდება. ყოველი გასული დღით ის სულ უფრო დამოუკიდებელ პიროვნებად ყალიბდება.'),
  ('0cc0cda4-4fef-4e92-9af2-cd065cfee008', 'თქვენ საუკეთესო ხართ! 💖', 'ბავშვის გაზრდა მარათონს ჰგავს. ამ საღამოს ცოტა დრო საკუთარ თავს დაუთმეთ, უყურეთ საყვარელ ფილმს ან უბრალოდ მშვიდად დაისვენეთ.'),
  ('781ac9f7-7fd3-4466-9d70-0b41dd1e954a', 'სათამაშოებს დაათრევს! 🧸', 'თოკით გამოსაქაჩი სათამაშოები ან პატარა ურიკები, რომლებსაც შეუძლია მიაწვეს, ახლა მისი საყვარელი გასართობია. ეს წონასწორობის შენარჩუნების შესანიშნავი ვარჯიშია!'),
  ('7dec83e1-5089-42b4-a2b5-f3d997eb1138', 'საკუთარ კვებაზეც იზრუნეთ. 🥗', 'ენერგიულ ბავშვთან ფეხის აწყობა რთულია. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ გემრიელი და ვიტამინებით მდიდარი კერძი, რომელიც ენერგიის აღდგენაში დაგეხმარებათ.'),
  ('6942d3e7-d39d-4aee-b8a0-ef2313920693', '„მე თვითონ!“ — სიჯიუტე. 🧦', 'თუ წინდის ჩაცმას ან დამოუკიდებლად ჭამას ცდილობს, ხელს ნუ შეუშლით. დამოუკიდებლობის განცდა სწორედ ასეთი პატარა მცდელობებით ვითარდება.'),
  ('c0c8236b-5e7c-45b1-a5c1-d45f005b603c', 'ემოციური განმუხტვა. 📝', 'ზოგჯერ ყველაფერი შეიძლება ზედმეტად რთული მოგეჩვენოთ. განწყობის დღიურში ჩაწერეთ თქვენი ფიქრები და დაღლილობის შესახებ, რათა დღის სტრესი მოიხსნათ.'),
  ('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb', 'აღმოჩენები სუფთა ჰაერზე. 🌳', 'პარკში ფოთლებზე შეხება და ქვების შეგროვება მის მგრძნობელობით აღქმას ავითარებს. გასეირნებისთვის ახალი პარკი შეარჩიეთ.'),
  ('96b02483-42a2-4868-a751-d817b0144951', 'არ დაგავიწყდეთ წყლის დალევა. 💧', 'ბავშვმაც და თქვენც! ენერგიული თამაშის შემდეგ და კვებებს შორის აუცილებლად დალიეთ წყალი, რათა ორგანიზმში სითხის საკმარისი დონე შეინარჩუნოთ.'),
  ('d89100dc-a7f8-49dd-8358-e3c63248fa5d', 'პატარა დამხმარე საქმეს შეუდგა! 🧹', 'თქვენ გბაძავთ, ხელში ტილოს იღებს და მტვერს წმენდს ან ცოცხით თამაშობს? ბავშვები ყველაზე უკეთ დაკვირვებით სწავლობენ.'),
  ('eea0806e-a72b-42f1-b1c3-b7a791619a96', 'ძილის რეჟიმი შეიცვალა? 😴', 'თუ დღის ძილი ერთამდე შემცირდა, გარდამავალ პერიოდში ღამის ძილის ხანგრძლივობა შეიძლება გაიზარდოს. ძილის ტაიმერის საშუალებით თვალი ადევნეთ ბოლო დღეების განრიგს.'),
  ('15bfc39a-e833-4e38-b7fc-bc13ef473b00', 'დამოუკიდებლად თამაშის დრო 🧸', 'ბავშვს უკვე შეუძლია 10-15 წუთის განმავლობაში დამოუკიდებლად გაერთოს სათამაშოებით. ეს ყურადღების კონცენტრაციის ხანგრძლივობის ზრდაზე მიუთითებს. დატკბით სიმშვიდით.'),
  ('99045f34-6450-4abd-856c-64fd61405e7b', 'თქვენი ხმის ტონს იგებს 🗣️', 'როდესაც მკაცრი ხმით ეუბნებით „არას“, ჩერდება და გიყურებთ? ის უკვე იწყებს ემოციებისა და აკრძალვების გაგებას!'),
  ('dc953aca-0624-4e7e-a96b-11f2b35b9a14', 'მუსიკის ძალა 🎶', 'საღამოობით უმიზეზოდ ატეხილი ჭირვეულობის დასამშვიდებლად სცადეთ მსუბუქი კლასიკური მუსიკის ჩართვა. ხშირად ეს მარტივი ხერხი სასწაულებს ახდენს.'),
  ('1eee6b26-c3fa-460c-8e48-030eb1e5a77c', 'ფერად-ფერადი ჯღაბნილი! 🖍', '️ ოთახის ერთ კუთხეში მისთვის შესაფერისი მსხვილი ფერადი ფანქრები და დიდი ფურცელი დაუდეთ. არ დაგავიწყდეთ მისი პირველი ხელოვნების ნიმუშების ბავშვის ალბომში უკვდავყოფა!'),
  ('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69', 'ექსპერტის დახმარება გჭირდებათ? 🤖', 'ისეთი კითხვები, როგორიცაა „როგორ განვუვითარო მეტყველება 14 თვის ბავშვს?“, ღამის საათებშიც კი დაუსვით ჩვენს Anacan AI ასისტენტს.'),
  ('f1854aec-f168-4789-a191-8a1fa96c3cd8', 'უსაფრთხოების ზომები უნდა განაახლოთ. 🛡', '️ როცა ბავშვი დამოუკიდებლად სიარულსა და კარადების გაღებას იწყებს, საფრთხეებიც მატულობს. ბავშვის უსაფრთხოების საკეტების შესარჩევად გადახედეთ ჩვენს რეკომენდებული პროდუქტების სიას.'),
  ('02d67440-3e37-4d1c-99f8-cbfa7aadda52', 'ჯანსაღი წასახემსებლის დროა. 🍎', 'დაუშრეტელი ენერგიის მქონე ბავშვებისთვის ხილის ნაჭრები ან ბოსტნეულის ჩხირები შესანიშნავი არჩევანია. მიეცით საშუალება, თავად დაიჭიროს და ჭამოს.'),
  ('4a197291-3001-4afb-9a70-d4320bd260b2', '„ეს რა არის?“ პერიოდი. ☝', '️ ბავშვი ყველაფერზე თითით მიგითითებთ და მის სახელს გეკითხებათ. მოთმინებით უთხარით თითოეული საგნის სახელი — ეს მის ლექსიკურ მარაგს სწრაფად გაამდიდრებს.'),
  ('8938f1b0-220a-48ac-b5f5-33db3613995c', 'მამიკოს ზღაპრის საათი. 👨‍🍼', 'დღეს საღამოს ზღაპრის წაკითხვა და ბავშვის დაძინება მამას მიანდეთ, თავად კი ცოტა შეისვენეთ.'),
  ('47ea2f2a-adf0-473a-a6a2-47218a354bbd', 'მაიმუნივით ცოცავს! 🧗‍♂', '️ ცდილობს დამოუკიდებლად აძვრეს დივანზე ან დაბალ ავეჯზე. უსაფრთხოდ მოაწყვეთ გარემო და მიეცით საშუალება, თქვენი მეთვალყურეობით მოსინჯოს ეს გაბედული მოძრაობები.'),
  ('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d', 'ჰაეროვანი კოცნები! 👋', 'ის უკვე შეგნებულად უქნევს ხელს მიმავალ ადამიანებს და ჰაეროვან კოცნას უგზავნის? დატკბით მისი ამ საყვარელი და სოციალური ჟესტით.'),
  ('ea4bc86f-6869-478f-98a6-52bb8dc4c40f', 'დაძინება უფრო მარტივი ხდება. 🌙', 'ყოველ საღამოს ერთნაირი თანმიმდევრობით შესრულებული მოქმედებები (აბაზანა, ზღაპარი, განათების ჩაბნელება) მას უფრო ადვილად დაძინებაში დაეხმარება.'),
  ('3d197dae-8e31-468d-8d92-41ba68985a62', 'უკვე ზუსტად 14 თვისაა! 🎉', 'გილოცავთ! ბავშვის დაბადებიდან ზუსტად 14 თვე გავიდა! ახლავე შექმენით განსაკუთრებული თემატური ფოტო ბავშვის ფოტოსესიის საშუალებით და ეს სიხარული Anacan-ის საზოგადოებაში გააზიარეთ!'),
  ('9052004a-46e9-4652-8de2-61f2a8f774d7', 'დაღლილობა და სიამაყე💖', 'ამ საღამოს მეუღლესთან ერთად აღნიშნეთ ამ 14 თვის დაღლილობაც და სიამაყეც. თქვენ შესანიშნავი გუნდი ხართ!'),
  ('dde3a118-6b4b-4b86-b077-744218b7fcd7', 'რამხელა გზა გამოიარა თქვენმა ბავშვმა! 📈', 'პირველი დღეების შიში ძლიერმა დედობრივმა თავდაჯერებამ შეცვალა. იამაყეთ საკუთარი თავით!'),
  ('33a2089a-67cc-4441-bb79-483ad77a1a42', 'დრო საკუთარ თავსაც დაუთმეთ. 🛁', 'მთელი დღე ფეხზე გაატარეთ. დაღლილობა განწყობის დღიურში ჩაინიშნეთ, რათა თავი უკეთ იგრძნოთ, შემდეგ კი ფინჯანი ცხელი ჩაით დაისვენეთ.'),
  ('625bdfef-2359-4843-aaac-6c8411b1963b', 'ნივთების სროლის ხელოვნება. 🎾', 'თუ ბავშვი სათამაშოებს ან საკვებს იატაკზე ყრის და თვალს აყოლებს, ეს ცელქობა კი არა, გრავიტაციის აღმოჩენაა. მოთმინება გამოიჩინეთ და მსხვრევადი ნივთების ნაცვლად გამძლე ნივთებით თამაშის უფლება მიეცით.'),
  ('ee0ba9ab-4b88-462e-aae9-f9a207218204', 'ნაბიჯები უკან და გვერდულად! 🦀', 'ახლა ბავშვი არა მხოლოდ წინ, არამედ უკან და გვერდულად სიარულსაც ცდის. ეს წონასწორობისა და მოტორული უნარების გასავითარებლად შესანიშნავი ვარჯიშია!'),
  ('21478892-353c-43fd-ba31-59c9aeb8255d', 'ენერგიის ბომბი დედებისთვის! 🥗', 'მოძრავი ბავშვები დედებისგან ორმაგ ენერგიას მოითხოვენ! დააჯილდოეთ საკუთარი თავი — ჯანსაღი რეცეპტებიდან საინტერესო კერძი შეარჩიეთ და მოამზადეთ.'),
  ('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e', 'ალო, ვინ არის? 📱', 'პულტს ან ტელეფონს ყურთან იდებს და თქვენავით ლაპარაკს ცდილობს? არ გამოტოვოთ მიბაძვის ეს საყვარელი მომენტები.'),
  ('ab819835-a2e1-481b-91b5-5391eb6051e8', 'თვალი ადევნეთ ძილის რეჟიმს. ⏱️', 'დღის ძილი მხოლოდ ერთამდე შემცირდა? როცა თქვენს ბავშვს ჩაეძინება, ჩართეთ ძილის ტაიმერი და გრაფიკზე შეამოწმეთ, როგორ ეგუება ის ახალ რეჟიმს.'),
  ('44b33bc4-3602-4265-9fe5-30b5609015de', 'დროა, მამებიც ჩაერთონ ბავშვის მოვლაში. 👨‍🍼', 'საღამოს თამაშები ხშირად ძალიან ენერგიულია. დღეს საღამოს ბავშვთან დაჭერობანა და დაძინების ჯერი მამას გადააბარეთ, თავად კი დაისვენეთ.'),
  ('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95', 'ემპათიის გრძნობა იღვიძებს! 💖', 'როცა ვინმე ტირის ან მოწყენილია, თქვენი ბავშვი მასთან მიდის და მოფერებას ცდილობს? მისი ემოციური ინტელექტი შესანიშნავად ვითარდება.'),
  ('e569bdf3-a845-44dc-852b-5318a0cf6a72', 'დაუსრულებელი ენერგია სუფთა ჰაერზე! 🌳', 'თქვენმა თავისუფლად მოსეირნე ბავშვმა ენერგია რომ დახარჯოს, დედებისთვის მეგობრულ ადგილებში იპოვეთ უსაფრთხო და ახალი პარკები, სადაც კომფორტულად შეძლებთ წასვლას.'),
  ('381afc75-3dbd-4716-b5ea-3af987c642dc', 'დღის ძილისთვის წინააღმდეგობის გაწევა. 😴', 'თამაში ხომ ძილზე ბევრად საინტერესოა! დაძინებამდე ნახევარი საათით ადრე შეწყვიტეთ აქტიური თამაშები და უფრო მშვიდ საქმიანობაზე გადადით.'),
  ('3ed2bd45-e711-4e56-bdc9-29b31e605069', 'კითხვა გაქვთ? 🤖', 'ისეთი მნიშვნელოვანი კითხვები, როგორიცაა „რატომ არ ჭამს ჩემი ბავშვი ზოგიერთ დღეს არაფერს?“, შეგიძლიათ ღამის საათებშიც დაუსვათ ჩვენს Anacan AI ასისტენტს და მიიღოთ მხარდაჭერა.'),
  ('718ac202-3ddd-463e-90fd-d1367161e2b5', 'როგორ გავუმკლავდეთ საკვების არჩევითობას. 🍲', 'ზოგიერთ დღეს ბავშვმა შეიძლება თავის საყვარელ საკვებზეც კი უარი თქვას. ნუ დააძალებთ — უბრალოდ სცადეთ ჩვენს აპში მოცემული სხვადასხვა ალტერნატიული რეცეპტი.'),
  ('9693a098-adc4-4d19-ab73-4c5cc195a25e', 'მე თვითონ გავწმენდ! 🧽', 'როცა მაგიდას წმენდთ, მასაც უნდა ტილო? თქვენს პატარა დამხმარეს უსაფრთხო დავალება მიეცით. ეს მის თავდაჯერებას საოცრად გაზრდის.'),
  ('98ba1e51-63c6-4c73-891d-99f1b14f3495', 'თეთრი ხმაურის ძალა. 🎶', 'თუ აქტიური დღის შთაბეჭდილებების ან კბილების ამოჭრის გამო ვერ იძინებს, თეთრი ხმაურის ფუნქციაში წვიმის ხმა ჩართეთ და ოთახში მშვიდი გარემო შექმენით.'),
  ('f5a87b81-5f64-4d75-abaf-6fd718e53fc5', 'ჯანსაღი წასახემსებლები. 🍎', 'ხილის ნაჭრები ან იოგურტი ამ ასაკისთვის შესანიშნავი წასახემსებელია. ჩვენს აპში მოცემულ ბავშვთა რეცეპტებში განსხვავებული და გემრიელი იდეები აღმოაჩინეთ.'),
  ('0b365564-8d23-4572-9881-7a4b9e2159bf', 'პირველი ნახატები! 🖍', '️ მას ძალიან უყვარს მსხვილი ფანქრებით ქაღალდზე ჯღაბნა. მისი პირველი ნამუშევრები სამომავლოდ შეინახეთ განყოფილებაში „ბავშვის ფოტოსესია“.'),
  ('c0638659-03fe-4ca5-b078-76057498811f', 'დედასთან ყოფნის დაჟინებული სურვილი 🥰', 'ტუალეტში შესვლის დროსაც კი კარს მიღმა გელოდებათ და ტირის. განშორების შფოთვა პიკს აღწევს. ყოველ ჯერზე აგრძნობინეთ, რომ უსაფრთხოდაა.'),
  ('f2ba1614-ef41-4060-97ee-0fe66e58b884', 'წყლის სმის ჩვევა მნიშვნელოვანია. 💧', 'აქტივობის მატებასთან ერთად წყურვილიც იზრდება. თამაშის დროს და ჭამის შემდეგ მისთვის წყლის შეთავაზება არ დაგავიწყდეთ.'),
  ('356f85b5-b941-4e2e-8218-18498e652ff8', 'კუბიკებით ციხესიმაგრეს აშენებს 🧱', 'ცდილობს, ორი ან სამი სათამაშო კუბიკი ერთმანეთზე დააწყოს. ჩუმად დააკვირდით მის ამ პატარა საინჟინრო მცდელობებს.'),
  ('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3', 'თეთრი ხმაურის ძალა. 🎶', 'თუ აქტიური დღის შთაბეჭდილებების ან კბილების ამოჭრის გამო ვერ იძინებს, თეთრი ხმაურის ჩანაწერებიდან წვიმის ხმა ჩართეთ და ოთახში მშვიდი გარემო შექმენით.'),
  ('f73e2678-7057-466b-a01a-218bff7ab963', 'კბილების გახეხვა სახალისოა. 🪥', 'სურს, კბილის ჯაგრისი თავად დაიჭიროს? მისთვის შესაფერისი რბილი ჯაგრისების გამოყენებით, სარკის წინ ერთად გაიხეხეთ კბილები და ეს ჩვევა ჩამოუყალიბეთ.'),
  ('58b586ed-1396-42c6-81f5-29f087488332', 'ადვილად ჩაძინება. 🌙', 'აქტიური დღის შემდეგ ოთახში სინათლეს დაუწიეთ, ხმას ჩაუწიეთ და ძილისთვის მოამზადეთ — მშვიდი, ნელი ხმით ზღაპარი წაუკითხეთ.'),
  ('82b39d0a-8bac-4430-a17f-2937f0af35e1', 'თქვენი ენერგიაც შეიძლება ამოიწუროს. 🥗', 'ძალიან დაიღალეთ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ვიტამინებით სავსე სმუზი, რომელიც ენერგიას სწრაფად აღგიდგენთ, და საკუთარი თავი დააჯილდოეთ.'),
  ('917ef6a5-ae0d-4133-b145-53d60f762945', 'ბურთი მომიტანე! 🧠', 'მას უკვე ძალიან კარგად ესმის მარტივი მითითებები. როცა რამეს სთხოვთ და ის სიხარულით მოგიტანთ, ეს იმაზე მიუთითებს, რომ მისი გონებრივი შესაძლებლობები სწრაფად ვითარდება.'),
  ('1bf6a974-24ed-47b3-8587-a38235ea120e', 'სამზარეულოს აღმოჩენა! 🍳', 'ქვაბები, კოვზები და პლასტმასის ჭურჭელი მის საყვარელ სათამაშოებად იქცა. უსაფრთხო კარადები ღია დატოვეთ, რათა ბავშვმა ისინი გამოიკვლიოს.'),
  ('88b4c840-5c20-4f9f-8b89-4530da60297b', 'უსაფრთხოების ზომები უნდა განაახლოთ! 🛡', '️ რაც უფრო თავისუფლად გადაადგილდება და კარადებს აღებს, მით მეტი საფრთხე ჩნდება. აუცილებლად გადახედეთ ჩვენს რეკომენდებული პროდუქტების სიას, სადაც ბავშვებისგან დამცავ საკეტებსა და კუთხის დამცავებს იპოვით.'),
  ('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3', 'დამამშვიდებელი აბაზანა. 🛁', 'თბილი აბაზანა არა მხოლოდ დღის განმავლობაში დაგროვილი ენერგიის დახარჯვაში ეხმარება და ართობს, არამედ კუნთებსაც ადუნებს და ძილისთვის შესანიშნავად ამზადებს.'),
  ('409e6b49-8ccb-4975-92b1-c12021092540', 'ძილის წინ წაკითხული ზღაპარი ჯადოსნურია. 📖', 'ძილის წინ წაკითხული მოკლე ამბავი ბავშვის წარმოსახვას ავითარებს და თქვენ შორის ემოციურ კავშირსაც აძლიერებს.'),
  ('6b7d6637-7328-44aa-b6c8-47c73df3a6f3', 'ზრდის ტემპი სწრაფია. 📏', 'თქვენს ბავშვს ტანსაცმელი ისევ უპატარავდება! განვითარების მონიტორინგის განყოფილებაში დაამატეთ სიმაღლისა და წონის ახალი მაჩვენებლები და დააფიქსირეთ მისი ჯანსაღი განვითარება.'),
  ('807127b9-417f-43a0-9bca-9ef33fbdadb8', 'პასუხი სხეულის ენით 🗣️', 'როდესაც ეკითხებით, „წავიდეთ?“, ხელებს მაღლა სწევს, ხოლო როცა ეუბნებით „არა“, თავს აქნევს. მისი გაგების უნარი საოცრად გაიზარდა!'),
  ('2cca6125-c540-4b9b-9a06-6121b60507e5', 'თავგადასავალი სუფთა ჰაერზე! 🌳', 'სახლში ენერგიას ვერ ხარჯავს? შეარჩიეთ უსაფრთხო პარკი, სადაც საბავშვო ეტლით კომფორტულად გაისეირნებთ, და ერთად დატკბით სუფთა ჰაერით.'),
  ('73b001a8-93ab-4798-bca3-094a519e468a', 'მიეცით ემოციებს თავისუფლება. 📝', 'ყველა დღე მარტივად არ გადის და ზოგჯერ ყველაფერი შეიძლება ზედმეტად რთული მოგეჩვენოთ. ჩაიწერეთ თქვენი გრძნობები განწყობის დღიურში და გათავისუფლდით დღის სტრესისგან.'),
  ('d452b163-e134-4c64-90b8-7e561b20c6f9', 'სიტყვებს ვბაძავთ! 🗣', '️ ცდილობს თქვენ მიერ წარმოთქმული სიტყვების ან ცხოველების ხმების გამეორებას? ენთუზიაზმით შეხვდით მის მცდელობებს, რათა საკუთარი აზრის გამოხატვის სურვილი გაუძლიერდეს.'),
  ('80913e3b-4640-4efe-ae49-ce789db16fd1', 'დღის შესანიშნავი დასასრული. ✨', 'დღესაც გააკეთეთ საუკეთესო, რაც დედას შეეძლო. დახუჭეთ თვალები, იამაყეთ საკუთარი თავით და მშვიდად დაიძინეთ.'),
  ('8e332da4-937a-4f7f-af67-edbe9e325d0e', 'ნაბიჯები უფრო თავდაჯერებულია! 🏃‍♂', '️ ის უკვე თავისუფლად დადის მთელ სახლში და ზოგჯერ სირბილსაც კი ცდილობს. მისი ასეთი გაბედული მოძრაობები სიამაყით გავსებთ და, ამავდროულად, მუდმივად ფხიზლად ყოფნას გაიძულებთ!'),
  ('b5982bde-910f-4d42-bc5f-8e5e9b2e683f', 'ალერგიაზე ეჭვი 🤖', 'ახალი საკვები მიეცით და ლოყებზე სიწითლე შენიშნეთ? სანამ შეშფოთდებით, პირველი ნაბიჯების შესახებ Anacan AI-სგან შეიტყვეთ.'),
  ('0deab7a8-9a3b-4827-969f-f24303c70419', 'კბილების ამოჭრის ტკივილი 🦷', 'ღრძილები ისევ გაუწითლდა და ნერწყვდენა არ წყდება? მოამზადეთ ცივი კბილების ამოსაჭრელი სათამაშოები.'),
  ('46166e0f-606a-46ff-86d4-07304bc93180', 'წყლის სმის ჩვევა მნიშვნელოვანია. 💧', 'აქტივობის მატებასთან ერთად წყურვილიც ძლიერდება. თამაშის დროს და ჭამის შემდეგ მისთვის წყლის შეთავაზება არ დაგავიწყდეთ.'),
  ('9e232723-1401-4819-8b29-1e4636b3edc3', 'პირველი ნახატები! 🖍', '️ ძალიან უყვარს მსხვილი ფანქრებით ქაღალდზე ჯღაბნა. მისი პირველი ნამუშევრები სამომავლოდ შეინახეთ ბავშვის ფოტოსესიის განყოფილებაში.'),
  ('2423bd81-d7d2-4b3e-b97a-32a10186bc3d', 'როლური თამაშები იწყება. 🧸', 'ცდილობს, სათამაშო დათუნიას აჭამოს ან წყალი დაალევინოს? ეს ყველაზე საყვარელი დასტურია იმისა, თუ რამდენად ყურადღებით გაკვირდებათ და გბაძავთ!'),
  ('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc', 'შეკითხვა გაქვთ? 🤖', '„ნორმალურია, რომ ჩემი ბავშვი საჭმელს არჩევს?“ — მსგავსი ან ნებისმიერი სხვა შემაწუხებელი შეკითხვა, თუნდაც გვიან ღამით, ჩვენს Anacan AI ასისტენტს დაუსვით.'),
  ('d4f6586e-25f9-4dd3-9a6b-1408627d49eb', 'დღის ძილისთვის თავის არიდება. 😴', 'თამაში ყოველთვის უფრო მიმზიდველია, ვიდრე ძილი. თუ ჩაძინება უჭირს, Anacan-ის ძილის ტაიმერით ბოლო დღეების განრიგს გადახედეთ და მისი რეჟიმი შესაბამისად შეცვალეთ.'),
  ('13b16a71-31e8-44cf-bbf4-b97f55c8f45e', 'გარეთ ამინდი ბოლომდე ნათელი არ არის? ⛅', 'ამინდისა და ჩაცმულობის ხელსაწყო მყისიერად გეტყვით ქარის სიჩქარეს, რომელსაც ფანჯრიდან ვერ შეამჩნევთ.'),
  ('807a2e9f-2fb3-4378-94cf-0ad756854f25', 'პერსონალური ზღაპარი 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი ბავშვია: მამაცი ბავშვი, რომელიც ვარსკვლავებისკენ მიიწევს.'),
  ('d08fdb3f-542d-478d-95e6-72b2d85a8a9a', '15 თვემდე 5 დღე დარჩა! 🎈', 'უკუთვლა დასასრულს უახლოვდება! ახლა უკვე ერთ ჭერქვეშ ცხოვრობთ პატარა პიროვნებასთან, რომელიც დადის და ყველაფერი ესმის. გაიღიმეთ!'),
  ('25f37869-be99-4918-83ae-dd5fecd2f5ce', 'ერთად სამზარეულოში. 🥦', 'საჭმლის მომზადებისას მიეცით ბავშვს არამტვრევადი პლასტმასის ჯამი და ხის კოვზი — დაე, მანაც მოამზადოს თავისი კერძი.'),
  ('c0b75b28-86cb-44ea-8bc4-de62c31fae30', 'წინასწარ დაგეგმვა სიმშვიდეს მოგიტანთ. 📝', 'ხვალინდელი საქმეები ან კვების გეგმა მოკლე ჩანაწერებით წინასწარ მოაწესრიგეთ და დასაძინებლად მშვიდად დაწექით.'),
  ('e47ea433-71bf-4c11-8e6e-6edbaec03292', 'ყველაფერზე თითით მიგითითებთ. ☝', '️ ეს შეკითხვის — „ეს რა არის?“ — უხმო ვერსიაა. მისი ცნობისმოყვარეობის შესანარჩუნებლად მოთმინებით გაუმეორეთ ყველა იმ საგნის სახელი, რომელზეც მიგითითებთ.'),
  ('09564db7-642f-496e-b113-4fd15ad5aefe', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებებთან გამკლავება მთლიანად საკუთარ თავზე ნუ აიღებთ. გააღვიძეთ პარტნიორიც — გუნდად ყოფნა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('30d6fd90-986c-491d-9a4a-39c6c9f48f69', 'განვითარების შემოწმება 🤖', 'გჭირდებათ ინფორმაცია 15 თვის ასაკში განვითარების ნახტომების შესახებ? გადახედეთ კრიზისების კალენდარს.'),
  ('661b0ef0-cce8-4702-8d5a-2f90901198ad', 'კითხვის სიყვარული. 📖', 'დასურათებული წიგნების ფურცვლა და თქვენი კითხვის მოსმენა ლექსიკური მარაგის გასამდიდრებლად შესანიშნავი საშუალებაა. ყოველდღე, თუნდაც 10 წუთით, ერთად იკითხეთ წიგნი.'),
  ('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2', 'თქვენი ხმის ტონს იგებს 🗣️', 'როცა მკაცრი ხმით ეუბნებით „არას“, ჩერდება და გიყურებთ? ის უკვე იწყებს ემოციებისა და აკრძალვების გაგებას!'),
  ('553f302d-8ba0-44d9-9d9d-e356d494f003', 'ძილისწინა რუტინა. 😴', 'თბილი აბაზანა და სუფთა პიჟამა მას დაამშვიდებს და ძილისთვის შესანიშნავად მოამზადებს.'),
  ('ed9814d4-d919-40b0-833b-d118d90c1727', 'დამოუკიდებლობის ძიებაში. 🥣', 'როცა თასის ან კოვზის დამოუკიდებლად დაჭერა მოუნდება, მიეცით ამის შესაძლებლობა. არეულობა სწავლის პროცესის ყველაზე სახალისო ნაწილია.'),
  ('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e', 'თქვენც გჭირდებათ ენერგია. 🥗', 'მთელი დღე ფეხზე ხართ. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ გემრიელი წასახემსებელი, რომელიც ენერგიის აღდგენაში დაგეხმარებათ.'),
  ('6df61827-7605-47d2-aeef-a4e811b4d8c8', 'სწრაფი აღმოჩენები! 🏃‍♂', '️ ის უკვე თავდაჯერებულად დადის ოთახიდან ოთახში და ყველაფერს უნდა შეეხოს. დარწმუნდით, რომ სახლი უსაფრთხოა და დატკბით მისი აქტიურობით.'),
  ('c9b2a6a2-258b-4f8c-96f9-86282d8d8145', 'ემოციური განტვირთვა. 📝', 'დამღლელი დღის შემდეგ განწყობის დღიურში თქვენი გრძნობების ჩაწერით გათავისუფლდით დღის სტრესისგან. თქვენ შესანიშნავი დედა ხართ!'),
  ('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267', 'თქვენ გმირი ხართ! ✨', 'სიყვარული და ზრუნვა, რომელსაც 450 დღის განმავლობაში იჩენდით, ფასდაუდებელია. ახლა კომფორტულად მოეწყვეთ და ამ მშვენიერი დღის შემდეგ მშვიდად დაიძინეთ.'),
  ('4df5ec18-5365-45c2-a49d-90ce26310b0b', 'ზუსტად 15 თვისაა! 🎉', 'როგორ სწრაფად მიფრინავს დრო! ბავშვის დაბადებიდან ზუსტად 1 წელი და 3 თვე გავიდა. გილოცავთ.'),
  ('a50254b7-b2f0-44b3-8ee9-5246bba08038', 'ბედნიერება ოჯახურ სუფრასთან. 🍲', 'მას უკვე შეუძლია თქვენთან ერთად იგივე კერძები მიირთვას. აღმოაჩინეთ მთელი ოჯახისთვის გემრიელი კერძები ჩვენს აპლიკაციაში მოცემული რეცეპტებით და აღნიშნეთ ეს პატარა იუბილე.'),
  ('157a98b7-1825-4699-b38d-85781cd21cf3', 'ოთახებს შორის მარათონი 🏃‍♂️', 'ის უკვე უბრალოდ კი არ დადის, თითქმის დარბის! წონასწორობის დაცვა დღითი დღე უმჯობესდება. განვითარების ტრეკერში სიამაყით აღნიშნეთ ეს აქტიური პერიოდი.'),
  ('47ea1c98-c71a-45d9-b06c-d95aa3da437b', 'მამას სათამაშო მოედანი 👨‍👧', 'მთელი დღე მის კვალდაკვალ სირბილმა დაგღალათ. საღამოს მორიგეობა მამას ეკუთვნის! იატაკზე კოტრიალი და დაჭერობანას თამაში მას მიანდეთ.'),
  ('9b3b08e6-de82-413f-9e4b-6da904b304a3', 'ნუ ინერვიულებთ, თუ დღეს სახლში დიდი არეულობაა.', 'ბავშვებს მოწესრიგებული სახლები კი არა, ბედნიერი დედები ახსოვთ. დაისხით ყავა და დაისვენეთ.'),
  ('67b35eea-eab9-41c5-88b7-f31e283eddd9', 'ბავშვი სახლში ენერგიას ვერ ხარჯავს და ჭირვეულობს?  ⛅', 'ბუნება საუკეთესო დამამშვიდებელია. შეამოწმეთ ამინდი, შეურჩიეთ შესაფერისი ტანსაცმელი და პირდაპირ პარკისკენ გაემართეთ.'),
  ('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9', '„ეს რა არის?“ პერიოდი ☝️', 'ყველაფერზე თითით მიგანიშნებთ და თავისებურ ხმას გამოსცემს. მას სურს, რომ სამყარო დაასახელოთ. მოთმინებით უთხარით თითოეული ნივთის სახელი, რომელზეც მიგანიშნებთ.'),
  ('d4a833e4-9676-4c95-baa2-923b9117c325', 'სიჩუმეა საჭირო 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმაურის საზომით შეამოწმეთ გარემოში დეციბელების დონე და მოერიდეთ უეცარ ხმაურს.'),
  ('088ce5b1-9a8e-4d7d-8f55-017e0cc63605', 'გაქვთ შეკითხვა? 🤖', 'თქვენი 15 თვის ბავშვის განვითარებასთან დაკავშირებით რაიმე გაღელვებთ? ნუ დაიკარგებით ინტერნეტში — პირდაპირ მისწერეთ Anacan AI-ს და მიიღეთ მეცნიერულად დასაბუთებული პასუხი.'),
  ('b6c6ae0a-2aaa-45b3-b8de-d4785923503c', 'ჯადოსნური ზღაპარი 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი მამაც გმირზე, რომელიც სამყაროს იკვლევს. ძილის წინ დრო კიდევ უფრო სასიამოვნო გახადეთ.'),
  ('c4cd946e-4029-4937-a10b-6f87983c2067', 'დღის ერთ ძილზე გადასვლა 🥱', 'დილით დაძინება აღარ სურს და რეჟიმი აირია? ის იზრდება! იწყება დღის ორი ძილიდან ერთ ძილზე გადასვლა. ნელ-ნელა მოარგეთ რუტინა.'),
  ('2517046a-f369-483a-b1e2-38f6320720ad', 'თბილი აბაზანა ამშვიდებს. 🛁', 'დღის დაღლილობისა და მტვრის მოსაშორებლად წყალში თამაში მას გაართობს და ძილისთვის შესანიშნავად მოამზადებს.'),
  ('258818a7-034e-4b93-86ea-97e8e01d3126', 'ბრაზის შეტევები? 🌪', '️ როცა საკუთარი ემოციების გამოხატვა არ შეუძლია, შეიძლება გაბრაზდეს და ატირდეს. თუ ამ საკითხთან დაკავშირებით დახმარება გჭირდებათ, გაიარეთ კონსულტაცია Anacan AI-სთან და გაეცანით სწორ მიდგომას.'),
  ('ca5a1958-0c22-4c62-874b-c3b801f70118', 'სიტყვების გაგების უნარი. 🧠', 'როცა ეუბნებით, რომ ფეხსაცმელი მოიტანოს, პოულობს და მოაქვს? ეს იმაზე მიუთითებს, რომ მისი გონებრივი შესაძლებლობები სწრაფად ვითარდება. ხშირად შეაქეთ!'),
  ('63bf2d84-bd96-49e0-9c51-b1f59bd85995', 'ხილის დროა! 🍎', 'ენერგიის აღსადგენად მოუმზადეთ სეზონური ხილისგან შემდგარი ფერადი და თვალისმომჭრელი თეფში.'),
  ('72ba71ca-1652-48f5-bc29-c321459f659a', 'თეთრი ხმების ძალა 🎶', 'თუ აქტიური დღის შემდეგ ვერ იძინებს, ოთახში თეთრი ხმებიდან ოკეანის ან წვიმის ხმა ჩართეთ და მშვიდი გარემო შეუქმენით.'),
  ('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea', 'მენიუს პატარა დიქტატორი 🥣', 'გუშინ საყვარელ კერძს დღეს გვერდზე სწევს? ამ ასაკში საკვების არჩევითობა ნორმალურია. ნუ შეშინდებით — ჯანსაღ რეცეპტებში განსხვავებული ალტერნატივები მოძებნეთ.'),
  ('54788c72-cfe2-4f75-82f0-ba29d942e404', 'ცხოველების ხმების მიბაძვა! 🐱', 'ითამაშეთ თამაში „რა ხმას გამოსცემს კატა?“. ასეთი მარტივი და სახალისო მიბაძვები შესანიშნავი საფუძველია მისი მეტყველების დასაწყებად.'),
  ('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa', 'აღიდგინეთ ენერგია 🥑', 'თუ ბავშვი დანაყრდა, ახლა თქვენი ჯერია. ყოველდღიურ ფაციფუცში სადილი ფეხზე მდგომმა არ მიირთვათ. ჯანსაღი რეცეპტებიდან ენერგიის მომცემი წასახემსებელი შეარჩიეთ და დივანზე წამოწექით.'),
  ('f3a87482-9f2e-4700-94d8-d413093ea00a', 'საღამოს რუტინის ძალა 🛀', 'თბილი აბაზანა ყოველთვის ჭრის. საღამოს რუტინა არასდროს დაარღვიოთ, რადგან ის ბავშვის ტვინს აძლევს სიგნალს, რომ ძილის დროა.'),
  ('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981', 'დღის ტკბილი მომენტები. 📸', 'ბავშვის ფოტოსესიით უკვდავყავით მისი დღევანდელი ნებისმიერი სახალისო საქციელი ან ახლად შეძენილი უნარი.'),
  ('21100889-9857-4170-a0a6-59c3dec113f8', 'საზღვრებს ამოწმებს. 🛑', 'მიუხედავად იმისა, რომ უარი უთხარით, მაინც იმ ნივთისკენ იწევს? ეს სიჯიუტე არ არის — ბავშვი უბრალოდ ამოწმებს, როგორ მოქმედებს წესები. მოთმინება გამოიჩინეთ.'),
  ('66da2b8a-fe86-40dc-b027-d36d46f5091a', 'წიგნის ფურცვლით განვითარებული გონება 📖', 'სქელფურცლებიანი წიგნების გვერდებს ფურცლავს და სურათებზე რეაგირებს? მისი მხედველობითი მეხსიერება ვითარდება. ხშირად წაუკითხეთ ფერადი ზღაპრების წიგნები.'),
  ('5991e165-7b36-40d5-be3a-c6729cd8e924', 'დალაგება თუ დასვენება? 🛋️', 'როცა ბავშვს სძინავს, ჭურჭლის სარეცხი მანქანისკენ ნუ გაიქცევით. წამოწექით დივანზე, დახუჭეთ თვალები და 15 წუთის განმავლობაში უბრალოდ ისუნთქეთ. რობოტი ხომ არ ხართ? არა.'),
  ('67273a71-3d6d-40e2-b209-34b098335818', 'ის ყოველდღე სულ უფრო იზრდება.📸', 'ახლავე გახსენით ბავშვის ფოტოსესია და მისი ეს გულწრფელი მომენტი სამუდამოდ აღბეჭდეთ.'),
  ('d17f36fc-9cb8-4df2-a29e-60891f565b13', 'დამოუკიდებლად ჭამის სურვილი 🥄', 'კოვზს ხელიდან გართმევთ და თავად სურს ჭამა. საჭმელი დაეღვრება და დაისვრება, მაგრამ ეს მისი მოტორული უნარების განვითარებისთვის მნიშვნელოვანია. მიეცით დამოუკიდებლად მოქმედების საშუალება.'),
  ('145c55e0-770c-4adc-a15b-4bd94389378f', 'სახიფათო ზონებზე წვდომა ⚡', 'ბავშვი გაიზარდა და ახლა იმ თაროებსაც სწვდება, რომლებსაც ადრე ვერ წვდებოდა. ტელევიზორის სადგამი, კუთხეები... სასწრაფოდ გადახედეთ სახლის უსაფრთხოებას.'),
  ('b6ac32de-f983-4a93-89fc-cb209586570b', 'უკანა კბილები ამოსდის? 🦷', 'ღრძილები შეშუპებული აქვს და ხელს პირში იდებს? შესაძლოა, უკანა კბილები ამოსდიოდეს. შეამოწმეთ კბილების ამოსვლის ტრეკერი და მიეცით ცივი კბილის სათამაშოები.'),
  ('d2fd7757-cdd9-4cc6-b45c-347ada81b748', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა მკვეთრი განათება და ეკრანი გამორთეთ. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182', 'უეცარი გაღვიძებები 😭', 'შუაღამისას ყვირილით იღვიძებს და ვერ მშვიდდება? ტირილის ხმა ტირილის ანალიზს მოასმენინეთ და გაარკვიეთ, მიზეზი ღამის შიშია თუ ტკივილი.'),
  ('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1', 'დიდი ემოციები, პატარა სხეული 🛑', 'როცა სასურველს ვერ იღებს, იატაკზე ეცემა? ეს ადრეული ასაკისთვის დამახასიათებელი ცნობილი ისტერიკებია. შეინარჩუნეთ სიმშვიდე, დაამყარეთ მასთან თვალით კონტაქტი და უთხარით, რომ მის გვერდით ხართ.'),
  ('d33491b0-9722-4db2-ae48-c019740b7411', 'ერთიანობის სულისკვეთება 🥂', 'გაიხსენეთ პარტნიორთან ერთად პირველი დღეები და ის უძილო ღამეები და გაიღიმეთ. აქამდე მარტივად არ მოსულხართ! ეს გუნდური გამარჯვებაა.'),
  ('138aeaf3-e845-4d03-b6db-2a04410076a7', 'კვლავ არჩევს საკვებს? 🥦', 'თუ ზოგიერთ საკვებზე უარს ამბობს, ნუ ინერვიულებთ. დამატებითი კვების დაწყებული ბავშვებისთვის განკუთვნილი რეცეპტებიდან სცადეთ საკვების განსხვავებულად და სახალისოდ მიწოდების იდეები.'),
  ('2f302f24-3142-4182-84a0-2782c5ce8394', 'ემოციური განტვირთვა. 📝', 'ძალიან დამღლელი დღე გქონდათ? ბავშვის დაძინების შემდეგ განწყობის დღიურში თქვენი გრძნობების ჩაწერით დღის სტრესი მოიხსენით.'),
  ('8b269aa5-a26e-4c52-b247-14a7194a3d35', 'მარათონი სახლში! 🏃‍♂', 'ის უკვე მხოლოდ სიარულს აღარ სჯერდება — თითქოს სირბილს ცდილობს. დატკბით მისი პატარა ფეხების ტყაპატყუპით, მაგრამ თვალიც არ მოაშოროთ!'),
  ('8ee97257-b3d6-4144-ad9a-91e2e54c967a', 'დაჭერობანა სუფთა ჰაერზე. 🌳', 'სახლში ენერგიას ბოლომდე ვერ ხარჯავს? ერთად გადით სუფთა ჰაერზე და მიეცით საშუალება, პარკში თავისუფლად ირბინოს და კარგად დაიღალოს.'),
  ('e84402f2-45d4-40ce-ae96-610f12a3e06b', 'პატარა დამხმარე საქმეში ჩაერთო! 🧹', 'სურს, ხელში ტილო აიღოს და მტვერი გადაწმინდოს ან ცოცხით ითამაშოს? თქვენი მიბაძვა მისი სწავლის პროცესის ყველაზე საყვარელი ნაწილია.'),
  ('ed63e2e3-10b5-4bd6-9b06-a81622e913eb', 'ძილის რუტინა უსაფრთხოების განცდას აძლევს. 🌙', 'ყოველ საღამოს ერთი და იმავე თანმიმდევრობით შესრულებული მოქმედებები (აბაზანა, ზღაპარი, განათების ჩაქრობა) დაეხმარება, უფრო მშვიდად ჩაეძინოს.'),
  ('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35', 'სიტყვების გაგების უნარი. 🧠', 'როცა სთხოვთ, ფეხსაცმელი მოგიტანოთ, პოულობს და მოაქვს? ეს იმაზე მეტყველებს, რომ მისი ინტელექტი სწრაფად ვითარდება. ხშირად შეაქეთ და წაახალისეთ!'),
  ('ce1fc21a-8f96-4c92-b928-5126f2240b1d', 'თქვენც გჭირდებათ ენერგია. 🥗', 'მთელი დღე ფეხზე ხართ. არ დაგავიწყდეთ, თქვენთვის ვიტამინებით მდიდარი და გემრიელი წასახემსებელი მოამზადოთ.'),
  ('d8cf1dda-3655-48e8-9316-6481b7ea82ba', 'ბრაზის შეტევები? 🌪', '️ როცა საკუთარი აზრის გამოხატვას ვერ ახერხებს, შეიძლება გაბრაზდეს და ატირდეს. თუ ამ საკითხში დახმარება გჭირდებათ, გაიარეთ კონსულტაცია Anacan AI-სთან და გაეცანით სწორ მიდგომას.'),
  ('2b9c6af1-1706-4704-b2ce-29e57d4866f4', 'მამის ჯერია. 👨‍🍼', 'დღეს საღამოს ზღაპრის წაკითხვა და ბავშვის დაძინება მამას მიანდეთ, თავად კი ცოტა შეისვენეთ.'),
  ('8db205c2-0561-48d8-8b6c-61fc68065e2a', 'კოშკის აშენების ხელოვნება. 🧱', '3-4 კუბიკის ერთმანეთზე დაწყობა და შემდეგ მათი დანგრევა ერთ-ერთი საყვარელი საქმიანობაა. ეს თამაში თვალისა და ხელის კოორდინაციას სწრაფად ავითარებს.'),
  ('e513a042-7558-4dae-8bc5-5e2b5e5d74fa', 'კომფორტი სახლის გარეთ. ☕', 'ყოველდღიურმა რუტინამ დაგღალათ? დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფე, სადაც ბავშვის ეტლით თავისუფლად შეხვალთ, და ყავის დასალევად შეისვენეთ.'),
  ('6537418f-2c88-443b-b40f-e07f0ccd5801', 'თეთრი ხმების ძალა. 🎶', 'თუ აქტიური დღის შემდეგ დაძინება უჭირს, ოთახში თეთრი ხმებიდან ოკეანის ან წვიმის ხმა ჩართეთ და მშვიდი გარემო შეუქმენით.'),
  ('c45968e1-c58f-48dd-a705-2dc4c22325e0', 'ზრდის ტემპი. 📏', 'ტანსაცმელი ისევ დაუპატარავდა! განვითარების მონიტორინგის განყოფილებაში სიმაღლისა და წონის ახალი მაჩვენებლები დაამატეთ და ჯანსაღი განვითარების გრაფიკი განაახლეთ.'),
  ('f13027ff-0446-4962-9c51-398d40234b5a', 'პირველი ნახატები! 🖍', '️ უყვარს ქაღალდზე მსხვილი ფანქრებით ჯღაბნა. დიდი სიყვარულით ადევნეთ თვალი მის პირველ ნამუშევრებს.'),
  ('3b86e3a2-b53e-4603-a4b1-a57fc531000c', 'თავად სურს ჭამა! 🥄', 'მიუხედავად იმისა, რომ ტანსაცმელი და ირგვლივ ყველაფერი შეიძლება დასვაროს, მიეცით საშუალება, კოვზი თავად დაიჭიროს. ეს ძალიან მნიშვნელოვანია მისი კუნთების კოორდინაციისა და დამოუკიდებლობისთვის.'),
  ('ce4d24a9-fdbd-44df-93c0-058cf5d834aa', 'ტკბილი ჩახუტებები! 🤗', 'როცა მოულოდნელად გეხუტებათ და თქვენს კოცნას ცდილობს, ეს მისი სიყვარულის ენაა. დატკბით ამ განუმეორებელი წუთებით და ბავშვის ფოტოსესიაში სამუდამოდ აღბეჭდეთ.'),
  ('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7', 'წიგნების კითხვისადმი ინტერესი. 📖', 'მიეცით საშუალება, ილუსტრირებული წიგნის გვერდები თავად გადაფურცლოს. თქვენი ხმით ზღაპრების მოსმენა მის ლექსიკურ მარაგს ამდიდრებს.'),
  ('1cb9115d-9cf4-466e-adbe-8fa808d6b45c', 'ძილის რეჟიმს ვაკვირდებით. ⏱️', 'თუ დღის ძილი ერთამდე შემცირდა, საღამოს ბავშვი უფრო ადრე დაიღლება. შეგიძლიათ, ღამის ძილის დრო ოდნავ ადრე გადმოწიოთ.'),
  ('42c60ff7-6aed-4b88-96d2-512be311f08c', 'არ დაგავიწყდეთ წყლის დალევა. 💧', 'აქტიურ მოძრაობასთან ერთად წყურვილიც იზრდება. თამაშის დროს და ჭამის შემდეგ რეგულარულად შესთავაზეთ წყალი.'),
  ('9a860f2e-97a8-4151-9a68-ed86235ecd75', '„ეს რა არის?“ პერიოდი. ☝', '️ ყველაფერზე თითით მიგანიშნებთ და გეკითხებათ, რა ჰქვია. მოთმინებით დაუსახელეთ ყველაფერი — ეს მისთვის გარემომცველი სამყაროს შეცნობის გზაა.'),
  ('09bd2033-24ed-4376-ba68-6795f9e6d0fa', 'მუსიკაზე ცეკვავს! 🎶', 'როგორც კი რიტმულ ხმას გაიგონებს, აქეთ-იქით ირწევა და ცეკვავს? ეს ენერგიული წუთები ვიდეოს სახით ატვირთეთ ბავშვის ალბომში.'),
  ('899ab05b-717c-4e03-b941-aadf4ad85007', 'დამოუკიდებლად თამაშის უნარი. 🧩', 'თუნდაც მცირე ხნით დამოუკიდებლად თამაში იმაზე მიუთითებს, რომ ბავშვის ყურადღების უნარი ვითარდება. ასეთ დროს სიყვარულით დააკვირდით მას შორიდან.'),
  ('98938324-49d8-43fc-bdde-202849487b20', 'თბილი აბაზანა ამშვიდებს. 🛁', 'დღის მტვრისა და დაღლილობის მოსაშორებლად წყალში თამაში მას გაართობს და ძილისთვის შესანიშნავად მოამზადებს.'),
  ('67d07afb-a906-4267-ae07-195da32a67d1', 'საზღვრებს ამოწმებს. 🛑', 'მიუხედავად იმისა, რომ „არა“ უთხარით, მაინც იმ ნივთისკენ იწევს? ეს სიჯიუტე კი არა, წესების შესწავლის მცდელობაა. იყავით თანმიმდევრული და მომთმენი.'),
  ('71f533be-645b-4990-ac46-86ad77f1a038', 'ხილის დროა! 🍎', 'ენერგიის აღსადგენად მოუმზადეთ სეზონური ხილისგან შემდგარი ფერადი და მიმზიდველი თეფში.'),
  ('cbf7129c-f3df-44ab-928f-9f74910675e9', 'საკუთარი თავი არ დაივიწყოთ! 💖', 'ბავშვის დაძინებიდან პირველი საათი მხოლოდ თქვენ გეკუთვნით. არაფერი აკეთოთ — უბრალოდ დაკავდით საყვარელი საქმიანობით და დაისვენეთ.'),
  ('569d0003-c871-435a-ae9b-f4e977441a16', '16 თვემდე სულ რაღაც 10 დღე დარჩა! 🎂', 'დაუჯერებელია! ზუსტად 10 დღეში თქვენი პატარა 16 თვის გახდება. ამ დღის აღსანიშნავად პატარა ტორტის ან ფოტოსესიის დაგეგმვა დაიწყეთ.'),
  ('6f0da037-da86-424d-bd6d-1e6d3aefe4db', 'ნუ მოგერიდებათ კითხვა 🤖', 'ფიქრობთ, რომ ძილის რუტინაში რაღაცას არასწორად აკეთებთ? ყველაფერი, რაც გაეჭვებთ, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს და დამშვიდდით.'),
  ('b0d45a27-101a-4c13-b494-715c8c48dda4', 'მთელი დაღლილობა გვერდზე გადადეთ. 🥂', 'არ დაგავიწყდეთ, რომ დღეს საღამოს, ბავშვის დაძინების შემდეგ, პარტნიორთან ერთად თქვენი გუნდური გამარჯვება აღნიშნოთ!'),
  ('8878ea41-701a-4729-9437-858b0e0448ae', 'ბურთის სროლის თამაში! ⚽', 'ბურთს უბრალოდ კი არ აგორებს, არამედ ხელებს მაღლა სწევს და ცდილობს, თქვენკენ ისროლოს! მისი ეს სპორტული მცდელობები დაუყოვნებლივ დაამატეთ ბავშვის ალბომში ვიდეოს სახით.'),
  ('d2eace3f-d381-45ba-bfbb-2db61f670769', 'ვინ არის ოჯახის ალბომში? 🖼', '️ ფოტოების დათვალიერებისას, როცა ეკითხებით: „სად არის ბებია?“, თითით სწორად მიუთითებს? მისი მეხსიერება და სახეების ამოცნობის უნარი სწრაფად ვითარდება.'),
  ('f2055f25-61d4-4680-83b3-954a3f1a9671', 'საინჟინრო მცდელობები 🧱', 'ცდილობს, სათამაშო კუბები ერთმანეთზე დააწყოს, მაგრამ ისინი ეცემა. ყურადღებით ცდილობს ხელახლა. ჩუმად დააკვირდით მის მცდელობებს.'),
  ('458a103b-d07a-4e59-ac24-1d9dafc323f0', 'სივრცე დედისთვის ☕', 'სახლში ყოფნით ენერგია გამოგელიათ. დედებისთვის მეგობრული ადგილებიდან შეარჩიეთ მყუდრო კაფე, სადაც კომფორტულად მოკალათდებით, და საკუთარ თავს დრო დაუთმეთ.'),
  ('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e', 'ჭირვეულობა პიკზეა ☁️', 'არაფერი მოსწონს და ყველაფერზე ტირის? შესაძლოა, უკანა ძირითადი კბილები ამოსდის. კბილების ამოსვლის ტრეკერში მონიშნეთ ეს პროცესი.'),
  ('ed11b132-51fc-4e86-99e0-021b6675020e', 'ღამის იავნანა 🎶', 'ვერცერთი ხმა ვერ ამშვიდებს ისე, როგორც დედის ხმა. ამ საღამოს უბრალოდ გულში ჩაიკარით და ხმადაბლა უმღერეთ.'),
  ('07f52bf7-1174-455b-9c35-8391687a69fe', 'განვითარების შემოწმება 🤖', 'გჭირდებათ ინფორმაცია 16 თვის ასაკში განვითარების ნახტომების შესახებ? სთხოვეთ Anacan AI-ს მოკლე, ზუსტი და პედიატრების მიერ დადასტურებული სია.'),
  ('c016a9a1-5e0d-434a-ba4b-907c1125a45a', '16 თვემდე სულ რაღაც 5 დღე დარჩა! 🎈', 'უკუთვლა თითქმის დასრულდა! ტორტი შეკვეთილი და სამოსი მზად გაქვთ? უკვე შეარჩიეთ მხიარული იდეები ბავშვის ფოტოსესიისთვის.'),
  ('d94026ce-ef2a-4e93-b559-9f926c9f245d', 'დამამშვიდებელი ხმები. 🎶', 'თუ აქტიური აღმოჩენებით სავსე დღის შემდეგ თქვენი ბავშვი ვერ მშვიდდება, ოთახში თეთრი ხმებიდან წვიმის ხმა ჩართეთ და მყუდრო გარემო შექმენით.'),
  ('523911e7-6ac9-424d-9f11-0729711fb179', 'სენსორული თამაშები. 🌾', 'დიდ ჯამში ჩაყარეთ ცოტა ბრინჯი ან მაკარონი და შიგნით სათამაშოები დამალეთ. მიეცით ბავშვს საშუალება, ისინი ხელებით იპოვოს და შეხების შეგრძნება განივითაროს.'),
  ('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533', 'დამოუკიდებლად თამაშის დრო 🧸', 'ბავშვს უკვე შეუძლია 10-15 წუთის განმავლობაში დამოუკიდებლად გაერთოს თავისი სათამაშოებით. ეს ყურადღების კონცენტრაციის ხანგრძლივობის ზრდის ნიშანია. დატკბით სიმშვიდით.'),
  ('adb7bf26-343c-4ba5-8233-149cdef6b1f2', 'მუსიკის ძალა 🎶', 'სცადეთ, საღამოს უმიზეზოდ ატეხილი ჭირვეულობა მსუბუქი კლასიკური მუსიკით შეამსუბუქოთ. ხშირად ეს მარტივი ხრიკი სასწაულს ახდენს.'),
  ('8bf81bea-dee2-4f82-9f28-f1e6a128a812', 'როცა მოთმინება გეწურებათ. 📝', 'ზოგჯერ ბავშვის ენერგიამ შეიძლება სრულიად გამოგფიტოთ. გახსენით თქვენი განწყობის დღიური და თავისუფლად დაწერეთ, რამ დაგღალათ დღეს ყველაზე მეტად.'),
  ('977f5267-192c-40d2-9215-420a5a54d255', 'ჩანგლის გამოყენებაზე გადასვლა. 🍴', 'ის უკვე ცდილობს, საკვების ნაჭრები ჩანგლით წამოაგოს და შეჭამოს. დამატებით კვებაზე გადასული ბავშვებისთვის რეცეპტების განყოფილებიდან მოამზადეთ საკვები, რომლის ჩანგლით აღებაც მარტივია.'),
  ('c22aaf03-7bb2-467b-9c9d-ca82637af893', 'თავად იხდის ფეხსაცმელს 👟', 'ჩაცმა უკვე ჭიდაობას დაემსგავსა? ის წინდებსა და ფეხსაცმელს თავად იძრობს. აღფრთოვანდით მისი მოტორული უნარით!'),
  ('3f154cd8-81d2-425b-aa71-ec2864247772', 'ეს ჩემია! 🧸', 'როცა რამეს ართმევთ, აპროტესტებს და ტირის? მას საკუთრების განცდა უძლიერდება. ეს ხასიათის ჩამოყალიბების მნიშვნელოვანი ნაწილია.'),
  ('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27', 'დღეს ბავშვს მამა აბანავებს. 👨‍🍼', 'დღეს საღამოს წყალში თამაშითა და უხვი ქაფით ბავშვის დაბანა და დაძინება მამას მიანდეთ, თავად კი დაისვენეთ.'),
  ('b60defb6-6a44-41ab-8087-7dec23cd3f5c', 'რა მოვამზადო? 🍲', 'დამატებითი კვების მენიუს იდეები ამოგეწურათ? ინტერნეტში ძებნას ნუ გადაჰყვებით — ახალი გემოები ჯანსაღი რეცეპტების განყოფილებაში აღმოაჩინეთ.'),
  ('35d30a24-8966-43d1-afce-6f79d49ebcec', 'სპეციალისტის მხარდაჭერა. 🤖', '„ჩემი ბავშვი მკბენს, როგორ მოვიქცე?“ — ქცევასთან დაკავშირებული ასეთი და სხვა ახალი კითხვები ჩვენს Anacan AI ასისტენტს დაუსვით.'),
  ('5c715c5a-b613-43a0-9f22-5f59af3ae1fc', 'გახდის ხელოვნება. 🧦', 'ჩაცმა რთულია, მაგრამ გახდა ძალიან სახალისოა! მიეცით საშუალება, თავად სცადოს ქუდის, წინდების ან ფეხსაცმლის გახდა.'),
  ('d3844bde-9596-474d-adfe-9c81a7e0ff26', 'უფროსების ნივთები საინტერესოა. 👜', 'თქვენს ჩანთაში ქექვა ან მამის ფეხსაცმლის ჩაცმის მცდელობა მისი საყვარელი საქმიანობაა. მიეცით საშუალება, თქვენი უსაფრთხო ნივთები შეისწავლოს.'),
  ('17b19954-1449-474d-a0b9-d199021947cc', 'ჯანმრთელი დედა, ჯანმრთელი ბავშვი 🥑', 'თქვენი რკინისა და კალციუმის მარაგი ამოწურულია. ჯანსაღი რეცეპტებიდან მოამზადეთ სალათი, რომელიც სწრაფად მზადდება და ენერგიას შეგინარჩუნებთ.'),
  ('68c3e726-41d6-481a-91d7-a89fa5795172', 'ჯღაბნის ხელოვნება 🖍️', 'როდესაც ფანქარს აძლევთ, ქაღალდზე ჯღაბნას ცდილობს? ეს წვრილი მოტორიკის შესანიშნავი სავარჯიშოა. დარწმუნდით, რომ ფანქრები უსაფრთხოა.'),
  ('ab2f1bd1-caf0-41b5-b8ae-89ec60663539', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებას მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('24b47242-9a10-48f7-a928-0a19449b984a', 'ჩააქრეთ სინათლე 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა კაშკაშა სინათლე და ეკრანი გამორთეთ. მელატონინი მხოლოდ მშვიდ გარემოში გამოიყოფა.'),
  ('2d66c314-cb67-48c8-93d1-be3249bad125', 'განძის ძიება ბუნებაში. 🍂', 'პარკში სეირნობისას სხვადასხვა ფოთოლი ან გირჩი შეაგროვეთ. დედებისთვის მეგობრულ ადგილებში აღმოაჩინეთ ახალი პარკები განსხვავებული ბუნებრივი პეიზაჟებით.'),
  ('98db8b9f-36cd-4968-86c5-ed66999457de', 'ცხოველების ხმები 🐶', 'კატის დანახვისას კნავის, ძაღლის დანახვისას კი ცდილობს, „ჰაფ-ჰაფ“ თქვას? სიტყვების მარაგი ცხოველების ხმებით იწყება. ითამაშეთ ეს თამაში მასთან ერთად.'),
  ('8e91be33-56a9-43aa-bf49-8aa525510abf', 'განძის ძიება ბუნებაში. 🍂', 'პარკში სეირნობისას სხვადასხვა ფოთოლი ან გირჩი შეაგროვეთ. დედებისთვის მეგობრულ ადგილებში აღმოაჩინეთ ახალი პარკები განსხვავებული ბუნებრივი პეიზაჟებით.'),
  ('a9e6c327-e70b-4cd7-9bed-cb9d250622ba', 'დამამშვიდებელი ხმები. 🎶', 'თუ აქტიური აღმოჩენებით სავსე დღის შემდეგ თქვენი ბავშვი ვერ მშვიდდება, ოთახში თეთრი ხმებიდან წვიმის ხმა ჩართეთ და მშვიდი გარემო შეუქმენით.'),
  ('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'შევსებისა და დაცლის დროა! 📦', 'ჩააწყვეთ სათამაშოები დიდ ყუთში, შემდეგ კი ყველა ერთად იატაკზე გადმოყარეთ! მიზეზ-შედეგობრივი კავშირის ეს თამაში მის ლოგიკურ აზროვნებას ავითარებს.'),
  ('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26', 'გულითადი საუბარი გჭირდებათ 💬', 'გაწუხებთ ფიქრი, რომ ძველებური თქვენ ვეღარასდროს იქნებით? გაუზიარეთ ეს დროებითი განცდა Anacan-ის საზოგადოების სხვა დედებს.'),
  ('2980029e-45df-4043-851c-f7839d81a721', 'ხვალ 16 თვის ხდება! 🎉', 'მზად ხართ? ხვალ ზუსტად 16 თვის ხდება! გაათავისუფლეთ ადგილი ტელეფონის მეხსიერებაში, რათა ხვალ ბავშვის ფოტოსესიაზე მისი ყველაზე საყვარელი მიმიკები აღბეჭდოთ.'),
  ('5d958416-87e8-44f2-8b6e-cde98e63822d', 'დღეს ჭკვიან ზღაპრებში 🪄', 'ჭკვიან ზღაპრებში შექმენით მამაცი და საყვარელი ცხოველების ამბავი და ოთახი ჯადოსნურ სივრცედ აქციეთ.'),
  ('679e2936-6a93-4a92-9069-b372c4d3f661', 'საღამოს ზღაპარი ჯადოსნურია. 📖', 'ახლა უკვე ისიც გიჩვენებთ წიგნში მოცემულ სურათებს. ძილის წინ ერთად წაკითხული პატარა ამბავი თქვენს შორის კავშირს წარმოუდგენლად აძლიერებს.'),
  ('86b4bb0f-0f98-485c-9149-10540747f598', 'ზუსტად 16 თვისაა! 🎂', 'დაუჯერებელია, არა? ზუსტად 16 თვე გავიდა იმ ამაღელვებელი დღიდან, როდესაც პირველად აიყვანეთ ხელში! ახლა საუკეთესო დროა, ეს საოცარი ზრდა აღნიშნოთ. შეარჩიეთ თემა ბავშვის ფოტოსესიაში, უკვდავყავით ყველაზე საყვარელი კადრი და აუცილებლად გაუზიარეთ ეს სიამაყე Anacan-ის საზოგადოების სხვა დედებს!'),
  ('fbb768fe-d41f-4451-8978-b683840f7855', 'შევსებისა და დაცლის დროა! 📦', 'ჩაყაროს სათამაშოები დიდ ყუთში, შემდეგ კი ყველა ერთად იატაკზე გადმოყაროს! მიზეზ-შედეგობრიობაზე დაფუძნებული ეს თამაში მის ლოგიკურ აზროვნებას ავითარებს.'),
  ('714f8ced-9ccc-40ff-a807-9428279f86d4', 'მარტივად დაძინება. 🌙', 'აქტიური დღის შემდეგ ოთახში განათება ჩააქრეთ და მშვიდი ხმით იავნანა უმღერეთ, რათა ღრმად დაძინებაში დაეხმაროთ.'),
  ('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4', 'არჩევანის უფლება მიეცით. 👕', 'წითელ მაისურს ჩაიცვამ თუ ლურჯს? – მცირე არჩევანის შეთავაზება სიჯიუტეს ამცირებს და საკუთარი თავის აღქმას აძლიერებს.'),
  ('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe', 'რთული დამალობანა! 🙈', 'თუ სათამაშოს ორი სხვადასხვა გადასაფარებლის ქვეშ დამალავთ, მაინც ადვილად პოულობს? ესე იგი, საგნის მუდმივობის აღქმა სრულად ჩამოუყალიბდა.'),
  ('373a30b7-4c10-4d16-b029-a2c123ab28b9', 'სირბილის ვარჯიში იწყება! 🏃‍♂', '️ სწრაფი ნაბიჯები უკვე პატარა გარბენად იქცევა. მართალია, მუხლების დაცვა უფრო რთულდება, მაგრამ მისი თავისუფლებით გამოწვეული სიხარულის ყურება ყველაფრად ღირს!'),
  ('5a23341a-91f5-4bdf-a760-e7b99f610283', 'ახალი ტექსტურების გასასინჯად მზადაა. 🥦', 'საკვების ფერებისა და ფორმების ცვლით მადა გაუღვიძეთ. იდეებისთვის შთაგონება მიიღეთ განყოფილებიდან „რეცეპტები ბავშვებისთვის, რომლებიც დამატებითი კვების დაწყებას აპირებენ“.'),
  ('6581c209-98c5-4f79-adf1-c7b985567899', 'თქვენ ნამდვილი გმირი ხართ. 🛁', 'მთელი დღე დაუღალავ ბავშვზე ზრუნავდით. ახლა ცხელი ჩაი დაისხით, არაფერზე იფიქროთ და უბრალოდ დაისვენეთ.'),
  ('1705b7a5-fb30-4cc3-974a-91a4210ec2a2', 'ეს დრო მხოლოდ თქვენთვისაა. 🛁', 'ბავშვს ჩაეძინა და სახლშიც სიმშვიდემ დაისადგურა. ახლა ტელეფონი გვერდზე გადადეთ, საყვარელი ფილმი ჩართეთ და უბრალოდ არაფრის კეთებით დატკბით.'),
  ('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb', 'უკან და გვერდულად სიარული! 🦀', 'ბავშვი უკვე მხოლოდ წინ კი არ მიდის, არამედ წონასწორობას უკან და გვერდულად ნაბიჯების გადადგმითაც ცდის. აუცილებლად გადაიღეთ ეს სახალისო მომენტები.'),
  ('f05a8717-d544-48fb-a529-17361118fee2', 'ზრდის ნახტომი! 📏', 'გრძნობთ, რომ თქვენი ბავშვი სიმაღლეში გაიზარდა? შეიყვანეთ მისი ახალი მონაცემები წონის მონიტორინგის განყოფილებაში და ნახეთ, როგორ მიიწევს ზემოთ განვითარების გრაფიკი.'),
  ('75798a4e-e59c-4911-827e-b1622b37ae33', 'თმის დავარცხნა და კბილების გახეხვა. 🪥', 'ბავშვი გიყურებთ და სავარცხელს თმაზე ისვამს ან კბილის ჯაგრისი პირთან მიაქვს. ახლა საუკეთესო დროა, რომ თამაშით ასწავლოთ თავის მოვლის ჩვევები.'),
  ('784b1d1b-2c53-42bf-a43b-d6b6e3121aba', 'ოჯახური ვახშამი. 🍲', 'დღეს საღამოს სახლში საჭმლის მომზადება არ გსურთ? ჩვენს აპლიკაციაში მოცემულ რუკაზე იპოვეთ რესტორნები, რომლებსაც ბავშვებისთვის ცალკე მენიუ და საბავშვო სკამი აქვთ.'),
  ('b328273f-0602-46a6-a82b-54d47ec1b77d', 'ღრმად ჩაისუნთქეთ. ✨', 'შესაძლოა, ყოველი დღე თქვენი გეგმის მიხედვით არ წარიმართოს და ზოგჯერ სახლიც მოუწესრიგებელი დარჩეს. სრულყოფილი არ უნდა იყოთ — მისთვის თქვენ საუკეთესო ხართ.'),
  ('755229fb-26a0-4a27-af2c-49bb6a367386', 'სიმშვიდის მომგვრელი რუტინა. 🌙', 'ღამის ძილის წინ ოთახში სინათლის ჩაქრობა და ჩურჩულით საუბარი ბავშვსაც შეანელებს და დასაძინებლად მოამზადებს.'),
  ('ae949749-3a87-49dc-a4ae-057b9e3594b1', 'ჯღაბნიდან გააზრებულ ხაზებამდე! 🖍', '️ როდესაც ხელში ფანქარს იღებს, მხოლოდ წერტილების ნაცვლად გრძელი ხაზების დახატვას ცდილობს. ამ პატარა ხელოვნების ნიმუშს ფოტო გადაუღეთ და დაუყოვნებლივ დაამატეთ ბავშვის ალბომში.'),
  ('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9', 'განძის ძიება ბუნებაში. 🍂', 'ეზოში ან პარკში ფოთლებისა და პატარა ქვების შეგროვება და შესწავლა ბავშვის სენსორული განვითარებისთვის შესანიშნავი აქტივობაა.'),
  ('1b65f6b1-f423-43f5-bc48-5ffb574c7c74', 'განტვირთვა წყალში თამაშით. 🛁', 'თბილ აბაზანაში წყალში ჩაყრილი სათამაშოებით თამაში ბავშვს დღის სტრესის მოხსნაში ეხმარება და თან ძალიან სახალისოა.'),
  ('bc0b7dcc-fdc0-4664-bff5-56183ea22258', 'ორსაფეხურიანი მითითებები ესმის! 🧠', 'როდესაც ეუბნებით: „აიღე ფეხსაცმელი და მომეცი“, ორივე მოქმედებას თანმიმდევრულად ასრულებს? ეს მისი გონებრივი განვითარების საოცარი ნახტომის ნიშანია!'),
  ('c18b2eee-ba78-43cc-89fd-423a464819d2', 'დედის ენერგია ძალიან მნიშვნელოვანია. 🥗', 'ბავშვის უკან გამუდმებით სირბილმა დაგღალათ. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან თქვენთვის გემრიელი და ვიტამინებით მდიდარი კერძი მოამზადეთ.'),
  ('bf80d71f-c8bb-4983-b046-1ee91c367f20', 'სპეციალისტის მხარდაჭერა. 🤖', '„სიტყვები ესმის, მაგრამ რატომ ლაპარაკობს ცოტას?“ — მსგავსი კითხვები, რომლებიც გაღელვებთ, დაუსვით ჩვენს Anacan AI ასისტენტს და მიიღეთ დამამშვიდებელი პასუხები.'),
  ('cd0e822c-b843-41fa-9a3e-f4b682a848ae', 'კოვზის დამოუკიდებლად გამოყენება. 🥄', 'კოვზის პირთან მიტანისას საკვებს უფრო ნაკლებად აქცევს. შეაქეთ მისი ნატიფი მოტორული უნარები და მიეცით დამოუკიდებლად მოქმედების საშუალება.'),
  ('d6374c1a-94a0-4de3-855d-6a8d4e9a29af', 'სათამაშოების მიმართ თანაგრძნობა. 🧸', 'სათამაშო დათუნიას ეფერება, აჭმევს ან საბანს აფარებს? ეს საყვარელი როლური თამაშები აჩვენებს, რამდენად კარგად ვითარდება მისი ემოციური ინტელექტი.'),
  ('299405ea-50dc-48c1-ba2a-233941bf627c', 'მამასთან ზღაპრის დრო. 👨‍🍼', 'დღეს საღამოს ზღაპრის წაკითხვა და ბავშვის დაძინება მამას მიანდეთ, თქვენ კი მცირე შესვენება მოიწყვეთ.'),
  ('7ad6ef35-e677-498c-8bc2-cc3e84535415', 'უსაფრთხოების ზომები უნდა განახლდეს. 🛡️', 'კარადებისა და უჯრების გაღება მისი საყვარელი გასართობია. აუცილებლად გაეცანით ბავშვებისგან დამცავი საკეტების ჩამონათვალს ჩვენს რეკომენდებულ პროდუქტებში.'),
  ('ec2361c8-31f7-458e-ad6e-506355b447a5', 'ახალი სიმაღლეები დაპყრობილია! 🧗‍♂', '️ მას უკვე შეუძლია უფრო მაღლა მისწვდეს და ავეჯზე უფრო მარტივად აძვრეს. დროა, სახლში უსაფრთხოების ზომები კიდევ ერთხელ გადაამოწმოთ.'),
  ('21888245-7cf1-48e4-a08b-53389aa39131', 'წყლის დალევა სახალისო გახადეთ. 💧', 'აქტიური სირბილი და თამაშები წყურვილს იწვევს. ხშირად შესთავაზეთ წყალი ფერადი წყლის ბოთლით, რათა ორგანიზმში სითხის ბალანსი შეინარჩუნოს.'),
  ('4595ac68-2033-4a66-a4d9-1146030382ed', 'დღის შეჯამება. ✨', 'არ ხართ ვალდებული, ყოველდღე იდეალური იყოთ. თუ დღეს რაღაცის გაკეთება ვერ მოასწარით, არა უშავს. თქვენი ბავშვისთვის საუკეთესო ხართ.'),
  ('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85', 'რიტმის შეგრძნება უმტკიცდება! 🎶', 'საყვარელი სიმღერის პირველივე წამების გაგონებისას მოძრაობას იწყებს და იღიმის? ეს ენერგიული მომენტები ბავშვის ფოტოსესიის ფუნქციით გადაიღეთ და ოჯახის ჯგუფში გააზიარეთ.'),
  ('33b8d80d-5434-483c-b198-c7b20c73321d', 'სხეულის ნაწილებს უფრო დეტალურად ცნობს. 👂', 'ისეთ ახალ კითხვებზე სწორი პასუხის გაცემა, როგორებიცაა „სად არის შენი მუცელი?“ და „სად არის შენი ყური?“, აჩვენებს, რამდენად სწრაფად სწავლობს ბავშვი.'),
  ('87029bf7-0808-4eac-a180-0abfa62f0b48', 'ერთად წაიკითხეთ წიგნი. 📖', 'ახლა უკვე მხოლოდ გვერდებს კი არ ფურცლავს, არამედ წიგნში გამოსახულ ცხოველებსა თუ საგნებზე თითით მიგითითებთ და ელოდება, რომ მათ სახელებს ეტყვით.'),
  ('cc468aff-f9d2-4961-b955-bf2eaa13f7ef', 'როგორ მიმდინარეობს ზრდა? 📏', 'ტანსაცმლის სახელოები და შარვლის ტოტები ისევ უმოკლდება! შეიყვანეთ ახალი მაჩვენებლები წონის მონიტორინგის განყოფილებაში და თვალი ადევნეთ განვითარების გრაფიკის ზრდას.'),
  ('308b629a-7190-416d-8240-7f61a2fe4d68', 'ბრაზი, როცა საკუთარი თავის გამოხატვა უჭირს. 🌪', '️ როცა სასურველს ვერ იღებს ან ვერ ახერხებს საკუთარი აზრის გადმოცემას, გაბრაზება და ტირილი ნორმალურია. მის სიმაღლეზე დაიხარეთ და უთხარით, რომ მისი გრძნობები გესმით.'),
  ('78541e65-2128-40ff-8cb4-1e0d54454519', 'მიეცით თქვენს ემოციებს გასაქანი. 📝', 'ძალიან დამღლელი დღე გქონდათ? ბავშვის დაძინების შემდეგ განწყობის დღიურში თქვენი ემოციები ჩაწერეთ და დღის სტრესი მოიხსენით.'),
  ('7ea95622-1f8d-4996-8638-aeeafe28a802', 'აღმოაჩინეთ ახალი ადგილები. ☕', 'ყოველდღიურმა რუტინამ დაგღალათ? დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფეები, სადაც ბავშვთან ერთად კომფორტულად მიხვალთ და საბავშვო მენიუც დაგხვდებათ.'),
  ('58ff14f8-978e-4eec-8b86-a777de1b33ba', 'სათამაშოების შეგროვებისა და დალაგების თამაში. 🧺', 'თქვენი პატარა, რომელსაც სათამაშოების ყუთიდან გადმოყრა უყვარს, ახლა რამდენიმე მათგანის უკან ჩალაგებასაც სწავლობს. ერთად იმღერეთ დალაგების სიმღერა და ეს საქმე სახალისო თამაშად აქციეთ.'),
  ('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81', 'ძილის რეჟიმი იცვლება? ⏱️', 'თუ დღის ძილი უკვე ერთამდე შემცირდა, ღამის ძილზე გადასვლის დროც შეიძლება ოდნავ შეიცვალოს. Anacan-ის ძილის ტაიმერით თვალი ადევნეთ დღევანდელ განრიგს და ახალი რეჟიმი მოარგეთ.'),
  ('e71126af-730c-4cca-8daa-1682609e21a1', 'ფიგურების შესაბამის ჭრილებში მოთავსება (თავსატეხები). 🧩', 'ბავშვი ცდილობს, წრე მრგვალ ჭრილში მოათავსოს, კვადრატი კი — კვადრატულში. ასეთი ლოგიკური თამაშები მის მოთმინებასა და ყურადღებას ავითარებს.'),
  ('069cc383-0002-41b5-ba19-4172c6d6b10f', 'ჩაძინება გაუჭირდა? 😴', 'აქტიური აღმოჩენები ზოგჯერ ბავშვს აღგზნებულ მდგომარეობაში ტოვებს. ჩართეთ ძილის ტაიმერი, დაძინებამდე ოთახის განათება მინიმუმამდე შეამცირეთ და ზღაპარი წაუკითხეთ.'),
  ('1beeca23-44cf-48f8-9b07-fc08412e7809', 'გმადლობთ და გთხოვთ. 🙏', 'როდესაც რამეს აძლევს ან იღებს, უკვე თავს უქნევს ან თავის ენაზე მადლიერებას გამოხატავს. სწორედ ახლაა სოციალური წესების სწავლების დრო!'),
  ('eb807359-495c-4338-a628-e4dd3e405226', 'ვაკვირდებით სიმაღლისა და წონის მატებას. 📏', 'ტანსაცმელი ისევ დაუპატარავდა? განაახლეთ მონაცემები წონის მონიტორინგის განყოფილებაში და შეადგინეთ განვითარების გრაფიკი მე-500 დღისთვის.'),
  ('158d01ac-e4e7-4be6-959c-37e93007ee0b', 'წიგნში ცხოველებს ცნობს. 🐶', 'როდესაც ეკითხებით: „სად არის ძაღლი?“, თითით მიგითითებთ? ლექსიკური მარაგის გასამდიდრებლად წიგნში გამოსახული საგნების ფერების დასახელებაც დაიწყეთ.'),
  ('9e266e10-1251-4668-af5f-a58fe3b3f537', 'უსაფრთხოების ზომები გადასახედია. 🛡️', 'ბავშვს უკვე უფრო მაღლა შეუძლია მიწვდომა. კიდევ ერთხელ შეამოწმეთ სუფრის გადასაფარებლები და ბასრი კუთხეები. საჭიროების შემთხვევაში გადახედეთ რეკომენდებულ პროდუქტებს.'),
  ('ca40c713-93a7-4e51-9b1b-8465a3151e1f', 'მამასთან ცელქობის დროა. 👨‍🍼', 'საღამოს ენერგიული ნაწილი მამას მიანდეთ. მათი სიცილით სავსე თამაშები არა მხოლოდ მათ კავშირს აძლიერებს, არამედ თქვენც დასვენების საშუალებას გაძლევთ.'),
  ('17791a06-d7d3-466d-acee-c2689fa82589', 'სენსორული თამაშები. 🌾', 'დიდ ჯამში ჩაყარეთ ბრინჯი ან ქვიშა და შიგნით სათამაშოები დამალეთ. მათი ხელებით ძებნა წვრილი მოტორიკის განვითარებისთვის შეუცვლელი აქტივობაა.'),
  ('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3', 'ტანსაცმლის არჩევის უფლება. 👕', 'ლურჯი მაისურის ჩაცმა გინდა თუ მწვანის? ორი ვარიანტის შეთავაზება ბავშვს საკუთარი თავის შეგრძნებას უძლიერებს და სიჯიუტეს ოდნავ ამცირებს.'),
  ('e6632c98-233d-431d-adc3-c5f78c1c7a37', 'წყლის თამაშებით მოდუნება. 🛁', 'თბილი აბაზანა და წყლის ჩხრიალი დღის მთელ დაღლილობას გააქრობს. წყალში სხვადასხვა ზომის ჭურჭელი ჩააწყვეთ და ბავშვს მოცულობის ცნება გააცანით.'),
  ('148de716-5fb6-4776-96cc-81e2d00b53b8', 'გააზიარეთ თქვენი გრძნობები. ✨', 'ზოგჯერ შეიძლება ყველაფერი ერთდროულად დაგატყდეთ თავს. დღის ბოლოს, შინაგანი სიმშვიდის მოსაპოვებლად, თქვენთვის საყვარელ ჰობის დაუთმეთ დრო.'),
  ('b3ddea65-cbd9-4fdd-900d-8914e021db1f', 'ბურთს მიზნისკენ ისვრის! ⚽', 'ბურთს უკვე უბრალოდ კი არ აგორებს, არამედ გარკვეული მიმართულებით სროლას ცდილობს. ეს თვალისა და ხელის კოორდინაციის განვითარების აშკარა მაჩვენებელია.'),
  ('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3', 'წყლის დალევა სახალისო გახადეთ. 💧 A', 'აქტიურ ბავშვებს მალე სწყურდებათ. რეგულარულად შესთავაზეთ წყალი ფერადი და საინტერესო ბოთლით, რათა მის ორგანიზმს გაუწყლოება არ დაემუქროს.'),
  ('2f67b26a-192a-4bd5-87f9-5f376ff164e3', 'ორსაფეხურიანი დავალებები. 🧠', 'აიღე სათამაშო და ყუთში ჩადე. ასეთი რთული დავალებების შესრულება მის მაღალ აღქმის უნარზე მიუთითებს.'),
  ('bf0e882a-2f6d-4439-b170-c9adaeed59cd', 'მუსიკაზე თავის რიტმში ცეკვავს. 🎶', 'ახლა უკვე უბრალოდ კი არ ირწევა, არამედ მუსიკის ტემპის შესაბამისად ტაშს უკრავს ან ტრიალებს.'),
  ('c522fcf6-60fc-463a-b943-7933f5ac5c70', 'ძილის წინ მოყოლილი ზღაპარი ჯადოსნურია. 📖', 'მიეცით საშუალება, სურათების დათვალიერებისას ზღაპარი თავის ენაზე მოჰყვეს. ეს მომავალში წიგნების კითხვის ჩვევის საფუძველია.'),
  ('19e05272-ac3b-430f-bbad-b5c770118fd3', 'საიუბილეო ზეიმი! 🎈', 'აღნიშნეთ ეს დღე პატარა ტორტით ან მისი საყვარელი ხილით. იმის ხილვა, თუ როგორ სწრაფად იზრდება, თქვენთვის ყველაზე დიდი ჯილდოა.'),
  ('52e84dda-8f2e-4dce-9b8e-b095190c1816', 'მადლობა გადაუხადეთ საკუთარ თავს. ✨', 'მადლობა გადაუხადეთ საკუთარ თავს იმ თავდადებისთვის, სიყვარულისა და მოთმინებისთვის, რომელსაც 500 დღის განმავლობაში იჩენდით. ახლა მშვიდად დაიძინეთ — ხვალ ახალი ეტაპი იწყება!'),
  ('7cc24719-4bcf-403b-9178-3f6a80317c26', 'შესანიშნავი 500 დღე.🎉', 'შეგიძლიათ დაიჯეროთ?! მშობიარობიდან ზუსტად 500 დღე გავიდა!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid, 'დედის დამუხტვა 🔋', 'დღის აურზაურმა მთელი ენერგია გამოგაცალათ? საკუთარი თავის დავიწყებით ბავშვის გაზრდა გმირობა არ არის. ბავშვი უსაფრთხო ადგილას მოათავსეთ და 10-წუთიანი შესვენება მოიწყვეთ ყავის დასალევად.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'სიჩქარის ლიმიტი გადაჭარბებულია 🏃‍♂️', 'უკვე კი არ დადის, თითქმის დარბის! მისთვის დაწევა სულ უფრო რთულდება. განვითარების ტრეკერში სიჩქარის ეს ახალი რეკორდი აღნიშნეთ და სახლში დაბრკოლებები მოაშორეთ.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'უსიტყვო ურთიერთგაგება 🫂', 'დღეს ძალიან დაიღალეთ. როცა ბავშვი დაიძინებს, პარტნიორთან ერთად დივანზე უბრალოდ გვერდიგვერდ მოკალათდით, არაფერზე ისაუბროთ და სიჩუმით დატკბით.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'რა სჭირდება თქვენს სხეულს 🥑', 'ხელები ან წელი გტკივათ? ბავშვი უკვე დამძიმდა. ჯანსაღი რეცეპტებიდან კალციუმითა და ცილებით მდიდარი მსუბუქი სადილი შეარჩიეთ და კუნთები გააძლიერეთ.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'წარმოსახვითი თამაშები იწყება 🧸', 'სათამაშო დათვის გამოკვებას ან დაძინებას ცდილობს? მისი წარმოსახვა იღვიძებს! სიამაყით დააკვირდით შორიდან ემპათიის გამოვლენის ამ შესანიშნავ მცდელობებს.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'მამასთან თამაშის დრო 👨‍👧', 'მოთმინების ბოლო ზღვარზე ხართ? ამ საღამოს იატაკზე კოტრიალსა და ღიტინის თამაშებს მამამ მიხედოს.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'აღმოჩენები სამზარეულოში. 🍎', 'ხილის რეცხვისას ნება მიეცით, თავადაც დაგეხმაროთ. წყლის ხმა და ხილის ფერები მის ინტერესს შეინარჩუნებს.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'სიტყვებით წინადადებების შედგენის მცდელობა. 🗣', '️ ცდილობს ორი სიტყვის გაერთიანებას, მაგალითად, „დე-და, მომეცი“ ან „მა-მა, ნახე“? ეს მეტყველების განვითარებაში საოცარი წინსვლაა!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'ჯადოსნური ღამის ფონი 🪄', 'უჭირს დაძინება? თეთრი ხმაურის ვარიანტებიდან ჩაურთეთ დამამშვიდებელი ფონი, რომელიც მხოლოდ მდინარის ხმებისგან შედგება.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'პატარა მხატვარი საქმეშია 🖍️', 'როცა ფანქარს აძლევთ, ქაღალდზე (ან კედელზე) ჯღაბნის? მისი ნატიფი მოტორიკა სწრაფად ვითარდება. დროა, გასარეცხი საღებავები შეიძინოთ.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'მამასთან ზღაპრების დრო. 👨‍🍼', 'საღამოს ბოლო ენერგიული თამაშები მამას მიანდეთ. მათი ერთად სიცილი თქვენთვის დასვენების საუკეთესო ფონი იქნება.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'ამინდის კვლევა ⛅', 'გარეთ ქარია თუ უბრალოდ სიგრილეა? მხოლოდ ფანჯრიდან გახედვით ნუ განსაზღვრავთ. ამინდისა და ჩაცმულობის ხელსაწყო წამებში შემოგთავაზებთ ზუსტ სამოსს.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'გააზიარეთ გამოცდილება 💬', 'ფიქრი — „ჩემი ბავშვიც ასეთია?“ — მოსვენებას არ გაძლევთ? შეუერთდით Anacan-ის საზოგადოებას, წაიკითხეთ 16 თვის ბავშვების სხვა დედების ისტორიები და შვებით ამოისუნთქეთ.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'დამამშვიდებელი აბაზანა. 🛁', 'ძილის წინ თბილ წყალში თამაში მთელი დღის დაძაბულობას მოხსნის. წყალში ცოტაოდენი ეთერზეთი დაამატეთ და მშვიდი გარემო შექმენით.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'კიბეზე დამოუკიდებლად ასვლის მცდელობა. 🪜', 'ახლა უკვე თქვენს ხელზე მოჭიდებული უფრო თავდაჯერებულად ადის. ფეხის კუნთების გასაძლიერებლად ხელს ნუ შეუშლით, უბრალოდ მის უსაფრთხოებაზე იზრუნეთ.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'სია თქვენს ჯიბეში 🛒', 'ყოველდღიურ ქაოსში დაგავიწყდათ, შამპუნი გათავდა თუ სველი ხელსახოცები? ნუ შეინახავთ ყველაფერს გონებაში — ჩაწერეთ საყიდლების სიაში და თქვენს პარტნიორთან დაასინქრონეთ.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'კითხვა გაქვთ? 🤖', 'ისეთი კითხვები, როგორიცაა „რატომ გახშირდა ღამით გაღვიძება?“, ღამის საათებშიც კი დაუსვით ჩვენს Anacan AI ასისტენტს და პასუხი მყისიერად მიიღეთ.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'გიპოვე! 🙈', 'თვალებს ხელებით იფარავს და „ჭიტას“ თამაშობს? ის სულ უფრო უკეთ აცნობიერებს, რომ საგნები მაშინაც არსებობენ, როცა მათ ვერ ხედავს.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ პარტნიორთან პირისპირ დასხედით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ფიზიკურ და ემოციურ ტვირთს მართლაც ანახევრებს.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'პედიატრიული კითხვები 🤖', 'რას უნდა ელოდოთ ბავშვის განვითარებისგან 16-18 თვის ასაკში? ინტერნეტში შემაშინებელი ამბების კითხვის ნაცვლად, Anacan AI-ს ზუსტი, სპეციალისტის მიერ მომზადებული შეჯამება სთხოვეთ.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'წიგნების სიყვარული 📖', 'თავისუფლად ფურცლავს წიგნს და თითით ეხება სურათებს? კითხვის ჩვევა სწორედ ახლა ყალიბდება. ერთად დაასახელეთ, რას ხედავთ სურათებზე.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'უეცრად ყვირილით გაიღვიძა?', 'ეს შეიძლება ღამის შიში იყოს. ხმა ტირილის ანალიზს მოასმენინეთ და გაარკვიეთ, პრობლემა ფიზიკურია თუ ფსიქოლოგიური.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'სახლის საქმეებს შეუძლია მოიცადოს 🛑', 'იატაკი არ არის მოწმენდილი? იყოს ასე. დასვრილი სახლის დალაგება შესაძლებელია, მაგრამ გამოფიტული დედის აღდგენას დიდი დრო სჭირდება. წამოწექით დივანზე და უბრალოდ სიმშვიდეს მოუსმინეთ.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'ლოგიკური თამაშები 🧱', '3-4 კუბს ერთმანეთზე აწყობს და კოშკს აშენებს? განვითარების მონიტორში აუცილებლად აღნიშნეთ მოტორული უნარების ეს გამარჯვება! შეაქეთ მისი პატარა საინჟინრო მცდელობები.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'დაძინება უფრო მარტივი გახადეთ. 🌙', 'ოთახში განათება მინიმუმამდე შეამცირეთ და ჩუმად, ჩურჩულით ისაუბრეთ. ეს მის ნერვულ სისტემას მიანიშნებს, რომ დასვენების დროა.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'ენერგიის აღდგენის დრო. 🍎', 'როცა ბავშვს სძინავს, თქვენც 20 წუთით დახუჭეთ თვალები. საოჯახო საქმეები არასდროს ილევა, თქვენი ენერგია კი შეიძლება ამოიწუროს. გაუფრთხილდით თავს.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'პატარა დამხმარე. 🧺', 'როცა სათამაშოებს ყუთში ალაგებთ, მასაც მოაქვს და დებს ერთ-ერთს? აუცილებლად შეაქეთ ასეთი პატარა დახმარებისთვის და მადლობა გადაუხადეთ.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'ჭკვიანი ზღაპრის მაგია 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი ბავშვი იქნება: მამაცი პატარა, რომელიც ჯადოსნურ ტყეში სეირნობს.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'დედის პირადი დრო 🎧', 'როგორც კი ბავშვი დაიძინებს, სამზარეულოში ნუ გაიქცევით. გაიკეთეთ ყურსასმენები, ჩართეთ საყვარელი სიმღერა და 15 წუთით უბრალოდ საკუთარ თავს დაუთმეთ დრო.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'დაჟინებით ცდილობს, თავად ჭამოს. 🥄', 'თუ კოვზს ხელიდან გართმევთ, ხელს ნუ შეუშლით. ტანსაცმელი რომც დაისვაროს, დამოუკიდებლად ჭამა მისი დამოუკიდებლობის ერთ-ერთი ყველაზე მნიშვნელოვანი გამოვლინებაა.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'ტკბილი ძილი 🌙', 'დღეს ძალიან დაიღალეთ. სანამ ბავშვს სძინავს, თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ, რომ მასაც მშვიდად ეძინოს და თქვენც დაისვენოთ.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'კვების ტაიმერი ⏱️', 'კვების დროის კონტროლი ახლა უფრო მარტივია! ჩართეთ კვების ტაიმერი და ყურადღებით აკონტროლეთ თქვენი ბავშვის დღიური ნორმა.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'რბოლა დაიწყო! 🏃‍♀️', 'თქვენი 17 თვის პატარა მკვლევარი სახლში ქარიშხალს ატრიალებს? ენერგიის დასახარჯად „დედებისთვის მეგობრულ ადგილებში“ ახლომდებარე ახალი პარკი აღმოაჩინეთ.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'გემრიელი და განსხვავებული! 🥦', 'ფიქრობთ, დღეს რა განსხვავებული მოუმზადოთ? დამატებითი კვების დაწყების ეტაპზე მყოფი ბავშვებისთვის „რეცეპტების“ განყოფილებაში გემრიელი იდეები დაგხვდებათ.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'ჩაწერეთ თქვენი გრძნობები 📝', 'დედობა ზოგჯერ დამღლელია და ეს სრულიად ნორმალურია. „განწყობის დღიურში“ ჩაწერეთ, რამ დაგღალათ დღეს ყველაზე მეტად, და შვება იგრძენით.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'დილის სიურპრიზი 💩', 'დღის პირველი საფენი უკვე გამოუცვალეთ? არ დაგავიწყდეთ ამის აპლიკაციის საფენების ტრეკერში მონიშვნა, რათა ჰიგიენის რუტინა მარტივად ვაკონტროლოთ!'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'შემომხედე! ☝️', 'თქვენი ყურადღების მისაქცევად ხმებს გამოსცემს და თითით მისთვის საინტერესო საგანზე მიუთითებს. გაიზიარეთ მისი აღმოჩენები და დაუდასტურეთ: „დიახ, ეს ბურთია“.'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'კოვზი მინდა! 🥄', 'თავად სურს ჭამა და საკვების ნახევარს ტანსაცმელზე იყრის? სისუფთავეზე ნუ გაამახვილებთ ყურადღებას. სწორედ ახლა ეყრება საფუძველი დამოუკიდებლად კვების ჩვევას.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'დღის შეჯამება 📝', 'როცა თავს არასაკმარისად კარგ დედად გრძნობთ, განწყობის დღიურში დღევანდელი პატარა წარმატებები ჩაიწერეთ. (მაგალითად: გავაცინე, დავანაყრე). თქვენ შესანიშნავი ხართ.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'საუბარი უფრო სერიოზული ხდება 🗣️', 'გაუგებარი სიტყვებით რაღაცას გიყვებათ და თან ჟესტებსაც იყენებს? იმავე სერიოზულობით ჩაერთეთ დიალოგში — ეს მეტყველების განვითარებისთვის აუცილებელია.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'სუფთა ჰაერის ძალა 🌙', 'დაძინებაზე უარს ამბობს? გააღეთ ფანჯარა და ოთახი კარგად გაანიავეთ. გრილი და სუფთა ჰაერი ჩაძინებას ყოველთვის ამარტივებს.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'ალერგიაზე ეჭვი გაქვთ? 🤖', 'ახალი ხილი მიეცით და კანი გაუწითლდა? სანამ შეშინდებით, Anacan AI-ისგან შეიტყვეთ, რა პირველი ნაბიჯები უნდა გადადგათ ბავშვებში საკვებისმიერი ალერგიის დროს.'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'დღის ძილი 😴', 'ჩართეთ ძილის ტაიმერი! გააანალიზეთ 17 თვის ბავშვის დღის ძილის ხანგრძლივობა და უფრო ზუსტად დაგეგმეთ მისი საღამოს დაძინება.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'კომფორტის ძიებაში 🍼', 'ეძებთ საუკეთესო სითხისგან დაცულ ჭიქას, რომ ბავშვმა დამოუკიდებლად დალიოს? რეკომენდებული პროდუქტების განყოფილებაში იხილეთ დედების ყველაზე საყვარელი არჩევანი.'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'ნუ დაივიწყებთ საკუთარ თავს! ☕', 'თქვენი ენერგია თქვენი ბავშვისთვის უმნიშვნელოვანესია. ჯანსაღი რეცეპტებიდან მოიმზადეთ გემრიელი და ენერგიის მომცემი სმუზი.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'ბლოგი და ყავა 📖', 'ბავშვს ჩაეძინა, ახლა თქვენი დროა! წაიკითხეთ ჩვენი ახალი ბლოგპოსტი და შეიტყვეთ ძალიან საინტერესო ფაქტები აქტიური ბავშვების ფსიქოლოგიის შესახებ.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'კომფორტული გასეირნება 👟', 'პარკში ბავშვის კვალდაკვალ სირბილისთვის ორივეს კომფორტული ფეხსაცმელი გჭირდებათ? რეკომენდებული პროდუქტების განყოფილებაში გაეცანით საუკეთესო ვარიანტებს.'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'კითხვა გაქვთ? 🤔', 'ფიქრობთ, როგორ გაუმკლავდეთ ბავშვის მზარდ სიჯიუტეს? Anacan AI მზად არის, ექსპერტული რჩევებით დაუყოვნებლივ გიპასუხოთ!'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'კუჭ-ნაწლავის შემოწმება ⏱️', 'დღიურად გამოყენებული საფენების რაოდენობის მონიტორინგი კვების ხარისხის შეფასებაში დაგეხმარებათ. დღევანდელი გამოცვლები ჩვენს აპლიკაციაში მონიშნეთ?'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'ოჯახური ვახშამი 🍲', 'რას მისცემთ მას ვახშმად? დამატებითი კვების რეცეპტებში იპოვით ჯანსაღი კერძების იდეებს, რომლებსაც მთელი ოჯახი სიამოვნებით მიირთმევს.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'თქვენი დედობის ისტორია 📝', 'თითოეული დედის ისტორია უნიკალურია. წაიკითხეთ ჩვენს ბლოგებში სხვა დედების რეალური გამოცდილებები და ისტორიები და მიიღეთ შთაგონება.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'სირბილი პარკში 👟', 'პირველ ნაბიჯებს მალე სირბილიც მოჰყვება. პირველი ფეხსაცმლის შესარჩევად გაეცანით „რეკომენდებული პროდუქტების“ განყოფილებაში წარმოდგენილ ჯანსაღ მოდელებს.'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'სიმშვიდე ოთახში 🌊', 'დღეს ჩაძინება უჭირს? ჩართეთ ოკეანის ტალღების ხმა „თეთრი ხმების“ განყოფილებიდან — ეს ნერვულ სისტემას დაამშვიდებს და ჩაძინებას გაუადვილებს.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'ცილების მარაგი როგორია? 🍗', 'ბავშვის ზრდისთვის ცილა აუცილებელია! კვების მონიტორინგის ხელსაწყოთი შეაფასეთ მისი ყოველდღიური კვების ბალანსი და შეავსეთ დანაკლისი.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'ძილის ტაიმერი ჩართულია? ⏳', 'ბავშვის დაძინებას იწყებთ? ჩართეთ ტაიმერი, გააანალიზეთ, რამდენი დრო სჭირდება მას ჩაძინებისთვის და გაიგეთ, როგორ გააუმჯობესოთ ეს რუტინა.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'თქვენი ჭკვიანი დამხმარე 🤖', 'რატომ დაკარგა ბავშვმა უეცრად მადა? ეს და სხვა შემაშფოთებელი კითხვები Anacan AI-ს მისწერეთ და დაუყოვნებლივ მიიღეთ მეცნიერულ მტკიცებულებებზე დაფუძნებული პასუხი.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'შეივსეთ ენერგიით 🔋', 'მზად ხართ დატვირთული დღისთვის? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან შეარჩიეთ გემრიელი და ვიტამინებით მდიდარი საუზმე.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'კომფორტის ძიებაში 🍼', 'ეძებთ საუკეთესო სითხეგაუმტარ ჭიქას, რომ ბავშვმა დამოუკიდებლად დალიოს? რეკომენდებული პროდუქტების განყოფილებაში გაეცანით დედების ყველაზე საყვარელ ვარიანტებს.'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'თქვენ ამას შეძლებთ! 💪', 'რთული დღე გქონდათ? მოუსმინეთ თქვენს შინაგან ხმას განწყობის დღიურში. გახსოვდეთ, ეს მხოლოდ რთული დღეა და არა ცუდი ცხოვრება.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'კვების ანგარიში 📊', 'კვების კონტროლის ინსტრუმენტში შეიყვანეთ, რა მიირთვა თქვენმა ბავშვმა დღეს. ვნახოთ, მიიღო თუ არა მან დღეს ყველა საჭირო ვიტამინი?'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'ღრმად ჩაისუნთქეთ ✨', 'არ არის აუცილებელი, ყველაფერი იდეალური იყოს. თქვენ ისედაც საუკეთესო დედა ხართ! განწყობის დღიურში დღის სტრესი მოიშორეთ და დაისვენეთ.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'სიმაღლეში გაიზარდა? 🦒', 'ამჩნევთ, რომ ტანსაცმელი დაუპატარავდა? განვითარების მონიტორინგში ახალი მონაცემები შეიყვანეთ და ნახეთ, როგორ აიწია ზრდის მრუდმა.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'კვების ნორმა 🥣', 'დღეს საკმარისი ცილა მიიღო? კვების მონიტორინგის ხელსაწყოთი გააანალიზეთ თქვენი ბავშვის ყოველდღიური მენიუ და შეავსეთ ნაკლოვანებები.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'დამამშვიდებელი ხმა 🌧️', 'დღის მღელვარების გამო ვერ იძინებს? თეთრი ხმებიდან წვიმის ხმა აირჩიეთ და დაეხმარეთ მის ნერვულ სისტემას, ბუნებრივად დამშვიდდეს.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'დღევანდელი დღე განსხვავებული იყოს 🌟', 'სახლის რუტინამ დაგღალათ? გახსენით დედებისა და ბავშვებისთვის მეგობრული ადგილების ჩვენი რუკა და იპოვეთ ახალი კაფე, სადაც თქვენს ბავშვთან ერთად კომფორტულად მოკალათდებით.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'პატარა ვარსკვლავი! 📸', 'მისი საყვარელი ღიმილი ფასდაუდებელია! ბავშვის ფოტოსესიის ფუნქციით გამოიყენეთ სხვადასხვა ჩარჩო და ეს დღე სამუდამოდ აღბეჭდეთ.'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'დღის საოცრება 🖼️', 'განსაკუთრებული შტრიხი 520-ე დღისთვის! ატვირთეთ ყველაზე ძვირფასი და სახალისო ფოტოები ბავშვის ალბომში, რათა წლების შემდეგ ისინი ღიმილით გაიხსენოთ.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'განვითარების ნახტომი? 📈', 'ბავშვი ბევრს ტირის ან ძილი დაერღვა? გაიარეთ კონსულტაცია Anacan AI-სთან და დააზუსტეთ, ხომ არ არის ეს მე-17 თვის განვითარების ნახტომის კვირა.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'დამამშვიდებელი რუტინა 🌙', 'მშვენიერი დღის დასასრულია. ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან იავნანა აირჩიეთ და მშვიდად დატკბით დღის დასასრულით.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'სუფთა ჰაერის ძიებაში 🌳', 'სახლში ყოფნა მოგბეზრდათ? გახსენით დედებისთვის მოსახერხებელი ადგილების რუკა და აღმოაჩინეთ ახალი პარკი, სადაც ბავშვთან ერთად კომფორტულად გაისეირნებთ.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'ძილის დრო მოვიდა ⏱️', 'ბავშვის დაძინებას იწყებთ? ჩართეთ ძილის ტაიმერი, ჩაინიშნეთ, რამდენად იცავთ რეჟიმს და გააანალიზეთ ძილის ნორმა.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'როგორია დილის მადა? 🥣', 'მნიშვნელოვანია, დღე ჯანსაღად დაიწყოთ! კვების კონტროლის ხელსაწყოთი გამოთვალეთ დღევანდელი ვიტამინების საჭიროება და დაგეგმეთ მენიუ.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'ტანსაცმელი დაუპატარავდა? 📏', 'ამჩნევთ, რომ თქვენი ბავშვი უცებ გაიზარდა? შეიყვანეთ ახალი მონაცემები წონის მონიტორში და გაეცანით ჯანსაღი ზრდის გრაფიკს.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'კვების ტაიმერი ⏱️', 'რამდენ ხანს გრძელდება კვება? ჩართეთ კვების ტაიმერი და აკონტროლეთ რეჟიმი, რათა საკვები სრულად გადამუშავდეს.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'სასარგებლო საკითხავი 📖', 'ბავშვს სძინავს, თქვენ კი რას აკეთებთ? დედობის შესახებ მეტი ცოდნისა და გამოცდილების მისაღებად წაიკითხეთ უახლესი სტატიები ჩვენს ბლოგების განყოფილებაში.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'იდეალური საბავშვო ჭიქის ძიებაში 🥤', 'ეძებთ მოსახერხებელ ჭიქას, საიდანაც სითხე არ იღვრება? გაეცანით დედების მიერ ყველაზე ხშირად გამოცდილი პროდუქტების ჩამონათვალს რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'ყავის შესვენება ☕', 'დღეს სახლიდან გასვლა გსურთ? დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფე საბავშვო კუთხით და საკუთარ თავსაც დაუთმეთ დრო.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'ემოციური განტვირთვა 📝', 'დღეს ყველაფერი გეგმის მიხედვით ვერ წავიდა? თავს ნუ დაიდანაშაულებთ. ჩაიწერეთ თქვენი შინაგანი განცდები განწყობის დღიურში და გონება გაითავისუფლეთ.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'დილის რუტინა 💩', 'დღის პირველი საფენი გამოუცვალეთ? განავლის ფერი და კონსისტენცია ნაწლავების ჯანმრთელობაზე მიანიშნებს. ახლავე მონიშნეთ საფენების ტრეკერში!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'ენერგია ქალებისთვის 🥗', 'ყოველდღიური ფუსფუსი დამღლელია. საკუთარ თავს ნუ დაივიწყებთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ გემრიელი სალათი, რომელიც ენერგიით სწრაფად აგავსებთ.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'თეთრი ხმაურის მაგია 🌧️', 'ძალიან დატვირთული დღე გქონდათ? ოთახში თეთრი ხმაურიდან წვიმის ხმა ჩართეთ, რათა თქვენმა ბავშვმა ადვილად დაიძინოს, თქვენ კი მშვიდად ამოისუნთქოთ.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'დღის ყველაზე ტკბილი მომენტი 📸', 'დღეს რაიმე უჩვეულო და სასაცილო გააკეთა? ბავშვის ფოტოსესიის სახალისო ჩარჩოებით აღბეჭდეთ ეს მომენტი და სამუდამო მოგონებად აქციეთ.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'თავად ჭამა სურს! 🥦', 'დამოუკიდებლობისკენ მიისწრაფვის? დამატებითი კვების დაწყებისას რეცეპტებიდან შეარჩიეთ გემრიელი ულუფები, რომელთა ხელში დაჭერაც ადვილია და რომლებიც არ იფანტება.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'სიჯიუტესთან გამკლავება 🤖', 'ყველაფერზე უარს ამბობს? თუ არ იცით, როგორ გაუმკლავდეთ ამ ასაკისთვის დამახასიათებელ ჭირვეულობას, ახლავე მიმართეთ Anacan AI-ს რჩევისთვის.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'ვნახოთ, საკმარისად ეძინა თუ არა 😴', 'როგორ ეძინა ღამით? ძილის ტაიმერის ჩანაწერების მიხედვით გააანალიზეთ, შეასრულა თუ არა თქვენმა ბავშვმა ძილის დღიური ნორმა.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'რა გაწუხებთ? 🤖', 'შვილის განვითარებასთან დაკავშირებით ეჭვები გაქვთ? მისწერეთ ჩვენს AI ექსპერტ-ასისტენტ Anacan-ს, მიიღეთ მეცნიერულად დასაბუთებული პასუხები და დამშვიდდით.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'ყოველი კერძი — განსხვავებული გემო 🍲', 'აღარ მოგიწევთ ფიქრი: „დღეს რა მოვამზადო?“ დამატებითი კვების დაწყების შემდეგ ბავშვებისთვის რეცეპტების განყოფილებაში მრავალფეროვანი და ჯანსაღი მენიუები დაგხვდებათ.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'გამოყოფის დღიური ანგარიში 💩', 'დილით საფენის გამოცვლისას ჩანიშვნა არ დაგავიწყდეთ! დღის განმავლობაში საფენების გამოცვლის სიხშირეზე დაკვირვება დაგეხმარებათ გაიგოთ, იღებს თუ არა ბავშვი საკმარის სითხეს.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'ეს თქვენც გჭირდებათ 🥗', 'ენერგია გეწურებათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ვიტამინებით მდიდარი სმუზი. თქვენ ძლიერი უნდა იყოთ!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'დაუვიწყარი მოგონებები 🖼️', 'ატვირთეთ მისი საუკეთესო ფოტოები ბავშვის ალბომში და უსაფრთხოდ შეინახეთ, რათა მომავალში დღევანდელ საყვარელ მომენტებს ღიმილით გადახედოთ.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'რას გრძნობდით დღეს? 💖', 'რაც უნდა დაღლილი იყოთ, მისი სურნელის შეგრძნებისას ყველაფერი გავიწყდებათ, არა? განწყობის დღიურში ჩაინიშნეთ თქვენი დღევანდელი ემოციები და დაისვენეთ.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'კვება ტაიმერით ⏱️', 'ბავშვი დიდხანს ზის სუფრასთან? ჩართეთ კვების ტაიმერი, დაიცავით კვების რეჟიმი და თავიდან აიცილეთ უმადობა.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'დილის თამაშები 🧩', 'ერთად ვსწავლობთ! აუცილებლად წაიკითხეთ ბლოგების განყოფილებაში ჩვენი სტატია თამაშების შესახებ, რომლებიც ხელს უწყობს 17.5 თვის ბავშვების გონებრივ განვითარებას.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', '„მიყვარხარ“ ჩახუტება 🫂', 'მოულოდნელად მოდის, კისერზე გეხვევათ ან სახეზე გეფერებათ? ის უკვე ფიზიკურად გამოხატავს თავის სიყვარულს. დატკბით ამ წამით.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'მამისგან მიღებული ნუგეში 🫂', 'როცა ბავშვი ღამით იღვიძებს, ხან თქვენ ადექით, ხან — თქვენი პარტნიორი. გუნდურად იმოქმედეთ და პასუხისმგებლობა თანაბრად გაინაწილეთ.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'ალერგიაზე ეჭვი 🤖', 'ბავშვს ახალი საკვები მიეცით და ლოყებზე სიწითლე შენიშნეთ? სანამ შეშინდებით, პირველი ნაბიჯების შესახებ Anacan AI-ს ჰკითხეთ.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'სახლში ყოფნა გთრგუნავთ?☕', '„დედებისთვის მეგობრულ ადგილებს“ შორის იპოვეთ უახლოესი კაფე, სადაც თქვენც განიტვირთებით და ბავშვიც გაერთობა.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'თქვენი ხმის ტონს ხვდება 🗣️', 'როცა მკაცრი ხმით ეუბნებით „არა“, ჩერდება და გიყურებთ? მას უკვე კარგად ესმის ემოციები და აკრძალვები. დაიცავით საზღვრები.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში გამორთეთ ყველა მკვეთრი განათება და ეკრანი. მელატონინი მხოლოდ მშვიდ გარემოში გამოიყოფა.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'ძილის ნორმა ⏱️', 'ძილის დროა! გაააქტიურეთ ძილის ტაიმერი. გააანალიზეთ გრაფიკი, რათა დარწმუნდეთ, რომ ბავშვი ძილის დღიურ ნორმას იცავს.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'იზრუნეთ საკუთარ თავზე 🥗', 'ბავშვის დევნით დაიღალეთ? ქალებისთვის განკუთვნილ ჯანსაღ რეცეპტებში აღმოაჩინეთ გემრიელი სალათა, რომელიც მყისიერად შეგმატებთ ენერგიას.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'დილის სისუფთავე 🧻', 'როგორ ჩაიარა დღის განმავლობაში საფენის პირველმა გამოცვლამ? აპში შეიტანეთ მონაცემები გამონაყოფის შესახებ და მარტივად აკონტროლეთ ბავშვის კუჭ-ნაწლავის სისტემის მუშაობა.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'ტკბილი მოგონებები 📸', 'დღეს გაკეთებული ყველაზე სახალისო საქციელი ბავშვის ალბომში დაამატეთ. წლების შემდეგ ამ კადრების დათვალიერებისას ბევრს იცინებთ.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'სითხისგან დამცავი ჭიქა 🥤', 'სირბილის დროს წყლის დალევა უყვარს, მაგრამ ტანსაცმელს ისველებს? რეკომენდებული პროდუქტების განყოფილებაში დედების მიერ შერჩეული ყველაზე მოსახერხებელი სითხისგან დამცავი ჭიქები დაათვალიერეთ.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'ტანსაცმელი პატარავდება! 📏', 'პატარას სახელოები ისევ დაუმოკლდა? შეიყვანეთ ახალი მონაცემები წონის ტრეკერში და განვითარების გრაფიკზე ამაყად შეამოწმეთ, როგორ იმატებს სიმაღლესა და წონას.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'დამოუკიდებლად თამაშის დრო 🧸', 'მას უკვე შეუძლია 10-15 წუთის განმავლობაში დამოუკიდებლად გაერთოს თავისი სათამაშოებით. ეს ყურადღების კონცენტრაციის ხანგრძლივობის ზრდაზე მიუთითებს. დატკბით სიჩუმით.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'გარეთ ამინდი გაურკვეველია? ⛅', 'ამინდისა და ტანსაცმლის ხელსაწყო მყისიერად გეტყვით ქარის სიჩქარეს, რომელსაც ფანჯრიდან ვერ შეამჩნევთ, და სწორად შერჩეულ სამოსსაც გირჩევთ.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'მასაჟის დრო 💆‍♂️', 'ბავშვის დაძინების შემდეგ, დღის სტრესის მოსახსნელად, თქვენ და თქვენმა პარტნიორმა ერთმანეთს მხრების მასაჟი გაუკეთეთ. თქვენ ერთი გუნდი ხართ!'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'ვიტამინების მარაგი 🥦', 'კვების კონტროლის ხელსაწყოთი დღევანდელი მენიუ შეამოწმეთ. საჭირო ვიტამინების შესავსებად ბავშვის რეცეპტებში ფერადი ულუფები გელოდებათ!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'ზედმეტად ჯიუტია? 🤖', 'სიტყვა „არა“ პირიდან არ სცილდება? 17.5 თვის ბავშვის ჭირვეულობასთან გასამკლავებლად ჩვენი Anacan AI დამხმარისგან მეცნიერულად დასაბუთებული ფსიქოლოგიური რჩევები მიიღეთ.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'სიმშვიდით სავსე საღამო 🌊', 'დროა, ოთახში მშვიდი გარემო შექმნათ. თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ და მის ნერვულ სისტემას ღრმა ძილში გადასვლაში დაეხმარეთ.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'გამოცდა სასადილო მაგიდასთან ⏱️', 'ჭამის პროცესი ძალიან დიდხანს გრძელდება? ჩართეთ კვების ტაიმერი, დაიცავით რეკომენდებული ხანგრძლივობა და უმადობის მიზეზებიც გააანალიზეთ.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'ყოველდღიური თერაპია 📝', 'დედობა ზოგჯერ ემოციურ ატრაქციონს ჰგავს. გახსენით განწყობის დღიური, დღევანდელი დაღლილობა ფურცელზე გადმოიტანეთ და შვება იგრძენით.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'ყავის დრო მოვიდა ☕', 'ოთხ კედელს შორის ყოფნა მოგბეზრდათ? დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფე, სადაც ბავშვთან ერთად კომფორტულად წახვალთ, და თავი გაიხალისეთ.'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'ხმაურის კონტროლი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. გარემოში ხმაურის დონე ხმაურის საზომით შეამოწმეთ და მოერიდეთ მოულოდნელ ხმაურს.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'სწრაფი პედიატრი 🤖', 'გაწუხებთ თქვენი 18 თვის ბავშვის მეტყველების განვითარება? ჰკითხეთ Anacan AI-ს და გაიგეთ, რომელი სიტყვების ცოდნაა ამ ასაკისთვის ნორმალური.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'მარტივ მითითებებს ასრულებს 🧸', 'როდესაც ეუბნებით, რომ ფეხსაცმელი მოიტანოს, ნამდვილად მიდის და მოაქვს? მისი ლექსიკური მარაგი და გაგების უნარი განვითარების პიკზეა! უფრო ხშირად ჩართეთ თამაშებში.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'დააფასეთ საკუთარი თავი 👏', 'ოთახის არეულობას კი ნუ შეხედავთ, არამედ იმას, თუ როგორი ბედნიერი იყო თქვენი ბავშვი დღეს. თქვენ ისეთი შესანიშნავი დედა ხართ, როგორად ყოფნასაც ვერცერთი წიგნი ვერ გასწავლით.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'ძილის ანალიზი ტაიმერით ⏱️', 'დღის ძილი ხანმოკლე გახდა? ჩართეთ ძილის ტაიმერი, გააანალიზეთ ამ კვირის განრიგი და საღამოს დაძინების დრო ხელახლა დაარეგულირეთ.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'მხარი დაუჭირეთ ერთმანეთს! 💖', 'რთული დღის შემდეგ პარტნიორთან პირისპირ დაჯექით და ერთმანეთს გულწრფელად ესაუბრეთ. ურთიერთმხარდაჭერა ტვირთს ანახევრებს.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'შუადღის მადა 🥣', 'მიიღო თუ არა ბავშვმა დღეს საკმარისი ცილა? დაამატეთ საკვები კვების მონიტორინგის ხელსაწყოში და დარწმუნდით, რომ დღიური ნორმა შეავსეთ.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'გონებრივი განვითარების ნახტომი 🧠', 'რა ხდება თქვენი ბავშვის ტვინში? ბლოგების განყოფილებაში წაიკითხეთ უახლესი სტატია 17-18 თვის ბავშვების კოგნიტიური განვითარების შესახებ.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'ძილის განრიგი ⏱️', 'გაღვიძების დრო შეიცვალა? ძილის ტაიმერის სტატისტიკის დახმარებით დეტალურად გააანალიზეთ ბალანსი დღის და ღამის ძილს შორის.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'დილის ანგარიში 💩', 'ჯანმრთელობის ერთ-ერთი პირველი მაჩვენებელი საჭმლის მომნელებელი სისტემაა. საფენის გამოცვლისას დაამატეთ აპლიკაციაში მონაცემები განავლის შესახებ და დღის განმავლობაში ცვლილებებს დააკვირდით.'),
  ('e59af63b-a407-459e-a6f1-a0263d9f74f5', 'პატარა ვარსკვლავი 🌟', 'არ გამოგრჩეთ ეს საყვარელი ღიმილი! ბავშვის ფოტოსესიის ხელსაწყოში წარმოდგენილი საინტერესო თემებით უკვდავყავით მისი დღევანდელი განწყობა.'),
  ('f71b2bf0-976d-4844-8538-db17781ce999', 'დრო საკუთარ თავსაც დაუთმეთ 🍵', 'ბავშვს ჩაეძინა, ახლა თქვენი სხეულის აღდგენის დროა. ჯანსაღი რეცეპტებიდან შეარჩიეთ და მოამზადეთ დამამშვიდებელი მცენარეული ჩაი.'),
  ('91d67474-6689-4302-b69e-a9b260aedef7', 'სწორად შერჩეული სათამაშო 🧩', 'ეძებთ სათამაშოს, რომელიც ბავშვს ლოგიკურ აზროვნებას განუვითარებს? რეკომენდებული პროდუქტების განყოფილებაში აღმოაჩინეთ ასაკის შესაბამისი და სასარგებლო ფაზლები.'),
  ('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2', 'ძილის წინა რუტინა 🌙', 'ყოველდღე ერთსა და იმავე დროს დაძინება ბავშვს ჩვევას უყალიბებს. ჩართეთ ძილის ტაიმერი, შეამოწმეთ ძილის ნორმა და დატკბით მშვიდად დაძინებით.'),
  ('e8b020dc-c4fe-4f5b-946a-28ae84382a39', 'ჯანსაღად ვიზრდებით 📈', '18 თვის შესრულებამდე ცოტა დარჩა! გააანალიზეთ ბავშვის ზრდის ტემპი წონის მონიტორინგის ხელსაწყოში და შეამოწმეთ, შეესაბამება თუ არა მისი სიმაღლე და წონა ნორმას.'),
  ('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17', 'შესანიშნავი დღის დასასრული 🖼️', 'ბავშვის ალბომში დაამატეთ თქვენი ყველაზე მხიარული და თბილი ერთობლივი ფოტო და სამუდამოდ შემოინახეთ ეს განსაკუთრებული დღე (540 დღე!).'),
  ('c1dc4453-41a2-40e6-812c-73fb934ccc70', 'თქვენ გმირი ხართ! ✨', 'დედობის გზის 540-ე დღე! მისწერეთ Anacan AI-ს თქვენი დღევანდელი მიღწევის შესახებ და მიიღეთ განსაკუთრებული სამოტივაციო გზავნილი, რომელიც დღეს გაგილამაზებთ.'),
  ('fa1d5820-5e14-435d-81d1-df116bd7de6f', 'ოჯახური სუფრა 🍲', 'ბავშვს უკვე შეუძლია, იგივე კერძები მიირთვას, რასაც თქვენ მიირთმევთ. კვების მონიტორინგის ხელსაწყოთი მარტივად გამოთვალეთ თქვენი საერთო კერძების კვებითი ღირებულება.'),
  ('4f770f32-235d-4481-acc9-8a3353f11910', 'რა გაწუხებთ? 🤔', 'უეცრად უარს ამბობს ჭამაზე? დედობასთან დაკავშირებული ნებისმიერი კითხვა დაუსვით Anacan AI-ს და მყისიერად მიიღეთ ექსპერტული სიზუსტის პასუხი.'),
  ('996b9423-cc50-4ec2-bbf6-02866083bb10', 'მარტივად ჩაძინება 🎶', 'აქტიური აღმოჩენებით სავსე დღის შემდეგ ვერ იძინებს? თეთრი ხმებიდან იავნანა აირჩიეთ და ოთახში ჯადოსნური სიმშვიდე შექმენით.'),
  ('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b', 'ბუნების აღმოჩენა 🍂', 'სუფთა ჰაერი ორივეს კარგად მოგიხდებათ. დედებისთვის მეგობრულ სივრცეებში განსხვავებული პარკი იპოვეთ და ბავშვს თავისუფლად სირბილისა და ენერგიის დახარჯვის საშუალება მიეცით.'),
  ('19f1aa58-50a6-4acf-b375-1d03850cfcb6', 'თქვენი შინაგანი ხმა 💖', 'არ ხართ ვალდებული, იდეალური დედა იყოთ — მისთვის თქვენ საუკეთესო ხართ. დღევანდელი გრძნობები განწყობის დღიურში ჩაწერეთ და შვება იგრძენით.'),
  ('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98', 'დამოუკიდებლად ჭამის ცდა ⏱️', 'ცდილობს, თავად ჭამოს? არეულობაზე თვალი დახუჭეთ! ჩართეთ კვების ტაიმერი და გააანალიზეთ, რამდენ დროს უთმობს ბავშვი დამოუკიდებლად ჭამას.'),
  ('f869363f-52a1-4240-a759-b2b999d347e4', 'ჯანსაღი ტკბილეული 🍪', 'მაღაზიის ტკბილეული საჭირო არ არის. რეცეპტებიდან მოამზადეთ მარტივი, უშაქრო და გემრიელი ორცხობილა ბავშვებისთვის, რომლებმაც დამატებითი კვება დაიწყეს.'),
  ('ae531928-8e01-4e71-961a-63a517eaee5a', 'ღრმა ძილში გადასვლა 🌙', 'ჩართეთ ძილის ტაიმერი. თუ ღამით გაღვიძებები გახშირდა, თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ, რათა ბავშვის ნერვული სისტემა დამშვიდდეს.'),
  ('bacdcc71-8211-4dd5-b3af-c5af34fb468a', 'დილის სიურპრიზი 💩', 'დღის პირველი საფენის გამოცვლისას მონაცემები ჩაინიშნეთ! ეს საუკეთესო გზაა მზარდი ბავშვის საჭმლის მომნელებელი სისტემისა და მიღებული სითხის რაოდენობის გასაკონტროლებლად.'),
  ('e207d666-c361-4203-8076-7ba835d4f015', 'კოვზს ხელიდან არ უშვებს? 🥄', 'ჩართეთ კვების ტაიმერი. გააანალიზეთ, რამდენ ხანს გრძელდება დამოუკიდებლად ჭამის მცდელობები და შეამოწმეთ კვების დღიური ნორმა.'),
  ('35587de2-b62b-435c-aca4-01e72314423a', 'გულზე მოეშვით 📝', 'ყველა დღე იდეალური არ არის და ეს ნორმალურია. განწყობის დღიურში ჩაწერეთ, რას გრძნობთ დღეს, გათავისუფლდით სტრესისგან და მშვიდად დაისვენეთ.'),
  ('6dca6700-52a0-4818-812b-80dcc5c42de9', 'უკვე ოფიციალურად 1.5 წლისაა! 🎈', 'ამ თვეებში თქვენი ბავშვი სწრაფად იზრდება. განვითარების მონიტორში შეიყვანეთ უახლესი მონაცემები და სიამაყით გადახედეთ განვითარების გრაფიკს.'),
  ('da88924f-9b7a-4cc5-9b9e-429e9d903edd', 'დააჯილდოეთ საკუთარი თავი ☕', '18-თვიანი დედობა სულაც არ არის მარტივი! დედებისთვის მეგობრული ადგილების რუკაზე იპოვეთ მყუდრო კაფე და საკუთარ თავს ცხელი ყავით გაუმასპინძლდით.'),
  ('6b77a02d-8882-4aed-be91-5f8ce3841671', 'სირბილისთვის მზად ხართ? 👟', 'პირველი თავდაჯერებული ნაბიჯებით სირბილისთვის სწორი ფეხსაცმელი აუცილებელია! რეკომენდებულ პროდუქტებში აღმოაჩინეთ დედების მიერ ყველაზე მეტად მოწონებული ორთოპედიული მოდელები.'),
  ('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e', 'ტკბილი კადრები 📸', 'სირბილისას წაიქცა და გაეცინა? ეს საყვარელი მომენტი დაუყოვნებლივ დაამატეთ ბავშვის ალბომში და მომავალისთვის ფერად, დაუვიწყარ მოგონებად აქციეთ.'),
  ('e2aefd08-9263-41a3-87d4-c2d0378c7526', 'როგორია რკინის მარაგი? 🥩', 'კვების კონტროლის ინსტრუმენტით შეამოწმეთ, მიიღო თუ არა ბავშვმა დღეს საკმარისი რაოდენობის რკინა. თუ დეფიციტია, გაეცანით ბავშვის რეცეპტებს.'),
  ('48983c78-1769-4320-a7cf-ba470eef1415', 'განსაკუთრებული ზღაპარი 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ისტორია, რომლის მთავარი გმირიც თქვენი ბავშვია: 1.5 წლის პატარა მკვლევრის თავგადასავლები.'),
  ('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0', 'ზრდა გრძელდება! 🌟', 'ის უკვე 18 თვეზე მეტისაა! იწყება ახალი ეტაპი ბავშვთან ერთად, რომელიც დამოუკიდებლად დადის, ემოციებს გამოხატავს, ჯიუტია, თუმცა სიყვარულით სავსე!'),
  ('cdca9fee-71e1-4e46-aea7-41734d6fa68a', 'ძილის რეგრესია 18 თვის ასაკში? 🥱', 'დაძინებას ეწინააღმდეგება ან ღამით იღვიძებს? ეს ამ პერიოდისთვის დამახასიათებელი ცნობილი ძილის რეგრესიაა. მიიღეთ Anacan AI-სგან სამეცნიერო ინფორმაცია ამ ბიოლოგიური პროცესის შესახებ.'),
  ('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03', '„მე თვითონ!“ — სიჯიუტე 🛑', 'ყველაფრის, საშიში ნივთებისაც კი, თავად აღება სურს. როცა ხელიდან გამოართმევთ, მოსალოდნელი ქარიშხლისთვის მოემზადეთ. აკრძალვის ნაცვლად, სცადეთ მისი ყურადღება უფრო საინტერესო რამეზე გადაიტანოთ.'),
  ('d6508b29-e914-4995-93c3-58c73e271159', 'მასაჟი და სიმშვიდე 💆‍♀️', 'მთელი დღე სირბილისგან წელი გტკივათ? ბავშვის დაძინების შემდეგ პარტნიორს სთხოვეთ, მხრებზე 10-წუთიანი მასაჟი გაგიკეთოთ. თქვენ ამას იმსახურებთ!'),
  ('dd068a2e-5d54-49f1-be6d-02db7c690974', 'სარბენ ბილიკზე ხართ 🏃‍♂️', 'ოთახიდან ოთახში სწრაფად დარბის და ვერ ჩერდება? ამ პერიოდში ფეხზე დგომისას წონასწორობის უნარი სრულად უყალიბდება. სახლში წვრილმანი საფრთხეები მოაშორეთ და ამ ენერგიულ მომენტებს გვერდიდან დააკვირდით.'),
  ('d14775e1-8a41-4689-87c3-351bcaa01c87', 'მამის მოედანი 👨‍👧', 'მოთმინება გეწურებათ? ოთახის კარი დახურეთ და ბავშვი მამასთან მარტო დატოვეთ. დაე, ამ საღამოს სახლის სათამაშო მოედანს ის ხელმძღვანელობდეს.'),
  ('e1121d1f-a680-4fb9-9a1f-6792cb16e172', 'ხილთან მტრობა 🍎', 'ვაშლს, რომელიც გუშინ უყვარდა, დღეს იატაკზე აგდებს? საკვებისადმი პრეტენზიულობა ამ ასაკისთვის ერთ-ერთი ყველაზე ტიპური პრობლემაა. ინტერნეტში ძიების ნაცვლად, ჯანსაღ რეცეპტებში ხილის სახალისოდ გაფორმების იდეები ნახეთ.'),
  ('ef76ecee-5471-407a-a72c-9593be1406af', 'საუბარი დიდხანს გრძელდება 🗣️', 'დილით გაღვიძებისთანავე თავის ენაზე დიდხანს გელაპარაკებათ? მისი მეტყველების ცენტრი ინტენსიურად ვითარდება. სერიოზული სახით მოუსმინეთ და უპასუხეთ: „მართლა?“, „შემდეგ რა მოხდა?“'),
  ('1bf2c33f-3711-4208-8da6-0a931502b566', 'სრული სიბნელე აუცილებელია 🌙', 'დაძინებას ეწინააღმდეგება? ოთახში უმცირესი სინათლეც კი ყურადღებას უფანტავს. გამორთეთ ეკრანები და ოთახი სრულად დააბნელეთ, რათა მელატონინის გამომუშავება დააჩქაროთ.'),
  ('5f000b16-6031-438b-92a6-3ea1d69ae68b', 'მეხსიერებამ ისევ გიმტყუნათ? 🛒', 'ბავშვის საფენები გათავდა თუ იოგურტი? თავს ნუ დაიღლით, მაშინვე დაამატეთ საყიდლების სიაში, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას იყიდოს.'),
  ('8593e3b3-5794-49a0-a5ef-d04af1bd53a7', 'დეტალები წიგნებში 📖', 'წიგნს ფურცლავს და სურათზე უმცირეს დეტალზე (მაგალითად, პატარა ჩიტზე) თითით მიგანიშნებთ? განვითარების ტრეკერში მონიშნეთ ეს კოგნიტიური ყურადღება. მხედველობითი მეხსიერება შესანიშნავად მუშაობს!'),
  ('5df90283-8938-4f2c-bc5d-95fad0d0249f', 'შევამოწმოთ ძილის რეჟიმი ⏱️', 'საღამოს დაძინება არ სურს? გააანალიზეთ ძილის ტაიმერის გრაფიკი. იქნებ დღის ძილი ცოტათი უნდა შეამციროთ.'),
  ('eb685812-a20b-4dfa-8dcd-a8c0865f1a25', 'დედის ენერგია 🔋', 'საკუთარი თავი არ დაგავიწყდეთ! რეცეპტებიდან დილისთვის სწრაფად მოსამზადებელი, ცილებით მდიდარი გემრიელი ულუფა შეარჩიეთ.'),
  ('f80fa225-e7f6-4b7d-a7da-b651f5688ba0', '„არა!“ კრიზისები 🛑', 'ყველაფერს ეწინააღმდეგება? 1.5 წლის ასაკისთვის დამახასიათებელი სიჯიუტის შესახებ რჩევა ჰკითხეთ ჩვენს Anacan AI ასისტენტს, მიიღეთ ფსიქოლოგიური მხარდაჭერა და იპოვეთ გამოსავალი.'),
  ('bd224607-0812-4b81-8b5d-af59d7d7cc10', 'ვიტამინების ბომბი 🥗', 'დედას ენერგია არ უნდა გამოელიოს! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ გემრიელი სმუზი, რომელიც მყისიერად შეგმატებთ ენერგიას.'),
  ('c9435c7a-e56d-449f-9eb8-fae0dc263176', 'ძილისთვის მომზადების რიტუალი 🌙', 'ჩართეთ ძილის ტაიმერი და დააბნელეთ ოთახი. გრაფიკის გაანალიზებით მარტივად ჩამოუყალიბეთ ბავშვს ყოველ საღამოს ერთსა და იმავე დროს დაძინების ჩვევა.'),
  ('ffe1377d-426e-4c3f-a06d-3551b2ee446b', 'განმავითარებელი სათამაშოები 🧩', '18 თვე ლოგიკური თამაშებისთვის იდეალური ასაკია. რეკომენდებულ პროდუქტებში აღმოაჩინეთ ასაკის შესაბამისი ფაზლები და კუბიკები და ხელი შეუწყვეთ ბავშვის აზროვნების განვითარებას.'),
  ('10d89b1a-052c-42d7-9604-a8aa080e3159', 'ოჯახური სუფრის მადლი 🍲', 'ახლა მას უკვე შეუძლია თქვენთან ერთად სრულფასოვნად ჭამა! დამატებით კვებაზე გადასული ბავშვებისთვის განკუთვნილი რეცეპტებიდან შეარჩიეთ საერთო და ჯანსაღი ვახშამი.'),
  ('25077620-39e7-49c9-abd7-7ee3d4c9f4a5', 'ნაწლავების მუშაობის შემოწმება ⏱️', 'საფენის ტრეკერში დღის განმავლობაში მომხდარი ცვლილებების აღნიშვნით მარტივად გააანალიზეთ, იღებს თუ არა ბავშვი საკმარისი რაოდენობის სითხესა და ბოჭკოს.'),
  ('94fb4891-ca2e-4e41-b663-ea23a832df89', 'წვიმის ხმის სიმშვიდე 🌧️', 'აქტიურმა დღემ შეიძლება ტვინი გადაღალოს. თეთრი ხმებიდან ჩართეთ წვიმის ხმა და ოთახში შექმენით დამამშვიდებელი, ძილის მომგვრელი იდეალური ფონი.'),
  ('02d8aef9-6d63-4748-9f41-c063ee842eb2', 'თქვენ ამას შეძლებთ! 💖', 'როდესაც იგრძნობთ, რომ დაიღალეთ, გახსენით განწყობის დღიური. უბრალოდ დაწერეთ იქ: მე ყველაფერს ვუმკლავდები — და დაისვენეთ.'),
  ('04fca8dd-97bb-4af2-93b5-030f318cd3da', 'ბუნების აღმოჩენა 🌳', 'სახლის კედლები უკვე ვიწრო ეჩვენება? დედებისთვის მეგობრულ ადგილებში იპოვეთ ფართო და უსაფრთხო პარკი და დაეხმარეთ ბავშვს ენერგიის დახარჯვაში.'),
  ('7306940e-101e-4de4-af72-da4ab6736ad8', 'კვების ტაიმერი ⏱️', 'საჭმლით ზედმეტად ბევრს თამაშობს? ჩართეთ კვების ტაიმერი და გააანალიზეთ, შეესაბამება თუ არა სუფრასთან გატარებული დრო ნორმას, ასევე შეაფასეთ ბავშვის მადა.'),
  ('07b5d33a-c674-4dcc-a023-81e3746cb054', 'ლოგიკური თამაშები 🧱', '4-5 კუბს ერთმანეთზე აწყობს და კოშკს აშენებს? განვითარების მონიტორში აღნიშნეთ მოტორული უნარების ეს მიღწევა! არ დაგავიწყდეთ, შეაქოთ მისი პატარა საინჟინრო მცდელობები.'),
  ('be5acfb3-03f0-4bea-9e14-40b38bca8262', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებებს მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს. ამაღამ ბავშვის დამშვიდება მისი ჯერია.'),
  ('fa9c7680-afc6-4095-9ec3-d56ad432d989', 'პარკი თუ სახლი? ⛅', 'გარეთ გასვლა გსურთ, მაგრამ ამინდი ცვალებადია. ამინდისა და ტანსაცმლის დამხმარე არა მხოლოდ ტემპერატურას გეტყვით, არამედ იმასაც, რა ჩააცვათ ბავშვს ქარისგან დასაცავად.'),
  ('22efa7bf-186e-41c7-b46c-b75ce17b0a09', 'დილის ჰიგიენა 💧', 'დღის პირველი საფენი გამოუცვალეთ? აპლიკაციაში გამონაყოფის შესახებ მონაცემები შეიყვანეთ და მარტივად აკონტროლეთ, იღებს თუ არა ბავშვი საკმარის სითხეს.'),
  ('37e7b0b1-141f-488d-99c8-a87bde73955f', 'მენიუს კრიზისები 🥣', 'ჭამაზე უარს ამბობს? ძალით კვების ნაცვლად, თეფშზე სხვადასხვა ფერის ბოსტნეული დაუდეთ და მისი ინტერესი გააღვივეთ. ახალი იდეებისთვის ჯანსაღ რეცეპტებს გაეცანით.'),
  ('5ae1647c-ec81-4db7-838c-66f57619dd06', 'ხმის კონტროლი 🤫', 'ძილისთვის მომზადებისას ოთახში ხმის დონე ხმის საზომით აკონტროლეთ. ღამით წყვეტილი ძილი უარყოფითად მოქმედებს როგორც ბავშვის განვითარებაზე, ისე თქვენს დილის განწყობაზე.'),
  ('2e177a88-e995-4df3-ae19-8a1044979006', 'მუსიკალური საღამოები 🎶', 'საღამოს დაწყებული ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზაა, ჩართოთ მისი საყვარელი სიმღერა, ჩაიხუტოთ და ერთად იცეკვოთ.'),
  ('82b5cb21-ea7e-4957-9166-81471c0b098a', 'რატომ იქცევა ასე? 🤖', 'უმიზეზო ბრაზის შეტევები (ტანტრუმი) დაეწყო? დაუყოვნებლივ გაიარეთ კონსულტაცია Anacan AI-სთან და გაეცანით ექსპერტების მიერ რეკომენდებულ ფსიქოლოგიურ მიდგომებს.'),
  ('8aa141ab-420e-4a45-9eba-7dddd2430cb1', 'ენერგია შაქრის გარეშე 🍌', 'შუადღისას ტკბილეული მოუნდა? ბავშვის რეცეპტებში ბანანისა და შვრიის ჯანსაღი წასახემსებლებით დაბალანსებული კვება შეუნარჩუნეთ.'),
  ('2d802010-e9c4-4370-b595-862f19214f3d', 'კალციუმის მარაგი 🧀', 'კბილებისა და ძვლებისთვის კალციუმი აუცილებელია. კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღეთ თუ არა დღეს რძის პროდუქტების რეკომენდებული რაოდენობა.'),
  ('739069ab-a4c7-4cc9-ae84-572e67836bd2', 'დღის ყველაზე საყვარელი მომენტი 🖼️', 'გახსოვთ, დღეს რომელმა საქციელმა გაგაცინათ ყველაზე მეტად? ახლავე ატვირთეთ ის ბავშვის ალბომში და შემოუნახეთ მომავალს.'),
  ('faac9718-e68e-455d-90e4-e34b7b38a24e', 'ინტელექტის განვითარება 🧠', 'ბლოგების განყოფილებაში აუცილებლად წაიკითხეთ ახალი სტატია იმ საოცარი პროცესების შესახებ, რომლებიც 1.5 წლის ბავშვების ტვინში მიმდინარეობს.'),
  ('2155f722-dd8c-49ec-a515-ecee85476474', 'დილის ბალანსი 🧻', 'დღის პირველი საფენი აპლიკაციაში აღრიცხეთ? გამონაყოფის ფერი და კონსისტენცია ზუსტად მიანიშნებს, იღებს თუ არა ბავშვი საკმარის სითხეს.'),
  ('67ef78f2-7b35-47be-a6f4-6368c3a37a84', 'გამოცდა სასადილო მაგიდასთან ⏱️', 'ბავშვი დიდხანს ზის მაგიდასთან და საკვებით თამაშობს? ჩართეთ კვების ტაიმერი და დაიწყეთ უმადობის მიზეზების გაანალიზება.'),
  ('d9b69a33-09da-4d7d-98e9-ac3acd553715', 'ძილის რეგრესია? 🤖', 'ბავშვი ღამით ხშირად იღვიძებს? მისწერეთ Anacan-ის AI ექსპერტს და დაუყოვნებლივ გაიგეთ, უკავშირდება თუ არა ეს ზრდის ნახტომს.'),
  ('283507fe-ca12-4764-a828-61d9a9f30424', 'თქვენ გმირი ხართ 💖', 'არ ხართ ვალდებული, იდეალური იყოთ. განწყობის დღიურში უბრალოდ დაწერეთ მე ყველაფერს გავუმკლავდები და დაისვენეთ.'),
  ('290e0f59-3a24-4f74-9a01-c478f55efce5', 'სუფთა ჰაერზე თავგადასავალი 🌳', 'სახლის კედლები მისთვის უკვე ვიწროა. დედებისთვის მეგობრულ სივრცეებში იპოვეთ ფართო და უსაფრთხო პარკი და დაეხმარეთ, ენერგია დახარჯოს.'),
  ('d9528425-30f7-4a4a-ac0d-053206658d00', 'ნუ გამოგელევათ ენერგია 🔋', 'აქეთ-იქით სირბილით ძალა გამოგელიათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან შეარჩიეთ გემრიელი საუზმე, რომელიც მყისიერად შეგმატებთ ენერგიას.'),
  ('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b', 'დღის ძილი ⏱️', 'გაააქტიურეთ ძილის ტაიმერი. დღის ძილის საათების დაზუსტებით მარტივად დაარეგულირეთ საღამოს ძილზე გადასვლა.'),
  ('1b9ea296-6f6b-4447-9f45-4c6548d5e543', 'ოჯახური სუფრა 🍲', 'მას უკვე შეუძლია, იგივე საკვები მიირთვას, რასაც თქვენ. კვების კონტროლის ხელსაწყოს მეშვეობით მარტივად გამოთვალეთ თქვენი საერთო კერძების კვებითი ღირებულება.'),
  ('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0', 'დამამშვიდებელი ტალღები 🌊', 'აქტიური აღმოჩენებით სავსე დღის შემდეგ ვერ იძინებს? თეთრი ხმებიდან აირჩიეთ ოკეანის ტალღების ხმა და ოთახში ჯადოსნური სიმშვიდე შექმენით.'),
  ('b62665c0-5b12-4c5d-adfa-7b34000204cf', 'სიცილის ხმა 📸', 'გაიხსენეთ დღევანდელი ტკბილი წამი, რომელმაც ყველაზე მეტად გაგაცინათ, და აუცილებლად დაამატეთ ის ბავშვის ალბომში პატარა ვიდეოს ან ფოტოს სახით.'),
  ('e16b58bb-af8f-43a3-bf1f-c1d132a221a5', 'ნუ შეშინდებით 🤖', 'თქვენი ბავშვის უცნაური ქცევა შენიშნეთ? ღამემდე ნუ დაელოდებით — დაუყოვნებლივ მისწერეთ Anacan AI-ს და გაიქარწყლეთ შფოთვა.'),
  ('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4', 'კალციუმის საჭიროება 🦷', 'კვების კონტროლის ხელსაწყოს დახმარებით გამოთვალეთ, რამდენი კალციუმი მიიღეთ დღეს. ძვლებისა და კბილების ჯანმრთელობისთვის ყურადღება მიაქციეთ რძის პროდუქტების რეკომენდებულ რაოდენობას.'),
  ('284e490f-ef18-407e-b320-432395edf56f', 'საჭირო ნივთების სია არ ილევა 🛒', 'შამპუნი, ბავშვის საფენები ან შვრია გაგითავდათ? ნუ შეინახავთ გონებაში — ჩაწერეთ საყიდლების სიაში და გაუზიარეთ პარტნიორს სინქრონიზაციის ფუნქციით.'),
  ('72bb2391-6fc4-4ef8-9352-3ae963d61f5b', 'ახლა თქვენი ჯერია 🥗', 'თუ ბავშვმა დაიძინა, სამზარეულოში გადით! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან აღმოაჩინეთ ცილებით მდიდარი სალათი, რომელიც ენერგიას მყისიერად შეგმატებთ.'),
  ('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd', 'სახლიდან გასვლის დროა ☕', 'რუტინამ დაგღალათ? „დედების მეგობარ სივრცეებში“ იპოვეთ კაფე საბავშვო კუთხით და მიირთვით ფინჯანი ცხელი ყავა.'),
  ('7c893844-8335-47b4-baf7-b21329be4554', 'გულზე მოგეშვებათ 📝', 'ძალიან ხმაურიანი დღე გქონდათ? განწყობის დღიურში თქვენი გრძნობების ჩაწერა გონებრივ დატვირთვას შეგიმსუბუქებთ.'),
  ('ee049a04-c690-49d6-a1c7-d2c603be49d5', 'ზღაპრით დაძინება 🪄', '„ჭკვიან ზღაპრებში“ შექმენით განსაკუთრებული ზღაპარი.  წაუკითხეთ ის თქვენს შვილს.'),
  ('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a', 'ტანსაცმელი ისევ დაპატარავდა? 📏', '18 თვის შემდეგ ზრდის ნახტომია მოსალოდნელი. წონის ტრეკერში ახალი მონაცემები შეიყვანეთ და სიამაყით გადახედეთ განვითარების მრუდს.'),
  ('46fbf80f-0604-494d-b68e-60f85488090d', 'თავად ჭამს! 🥣', 'კოვზს ხელიდან არ უშვებს? ჩართეთ კვების ტაიმერი, აკონტროლეთ პროცესის ხანგრძლივობა და შეამოწმეთ, შეესაბამება თუ არა ნორმას.'),
  ('5174db8a-22d1-41db-af86-5a575522337a', 'პირველი ნახატები 🖍️', 'უკვე დაიწყო ჯღაბნა? უსაფრთხო და ადვილად ჩამოსარეცხი საღებავების შესარჩევად გადახედეთ საუკეთესო ვარიანტებს რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b', 'პატარა მხატვარი 📸', 'თავიდან ფეხებამდე საღებავშია? გაბრაზების ნაცვლად, უკვდავყავით ეს სახალისო მომენტი ბავშვის ფოტოსესიის მხიარული ჩარჩოებით.'),
  ('0671a41f-8a24-4dff-87f0-008aa3abfc3d', 'როგორ მუშაობს საჭმლის მომნელებელი სისტემა? 💩', 'საფენის გამოცვლისას განავლის შესახებ მონაცემები აპლიკაციაში დაამატეთ. მარტივად აკონტროლეთ, როგორ მოქმედებს ბოჭკოვანი საკვები საჭმლის მონელებაზე დღის განმავლობაში.'),
  ('d414aad6-2d3e-4a62-a555-9241874e68b3', 'ძილის გრაფიკი ⏱️', 'ძილის დროა! ჩართეთ ძილის ტაიმერი და გააანალიზეთ ბავშვის რეჟიმი, რათა დარწმუნდეთ, რომ მას ყოველდღიურად საკმარისად სძინავს.'),
  ('fbbb1355-d1ac-4efe-b9c7-1746b97b1656', 'არ სურს გაზიარება? 🤖', 'პარკში სათამაშოს არავის უზიარებს და ყვირის? Anacan AI-ის დახმარებით გაიგეთ, როგორ მოიქცეთ ასეთ სიტუაციაში, და მიღებული რჩევები პრაქტიკაში გამოიყენეთ.'),
  ('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e', 'დილის სიურპრიზი 💩', 'დღის პირველი საფენი გამოუცვალეთ? განავლის შესახებ მონაცემები აპლიკაციაში შეიყვანეთ და ყურადღებით აკონტროლეთ ბავშვის კუჭ-ნაწლავის სისტემის მუშაობა და სითხის მიღება.'),
  ('b32e8863-be99-483a-aff4-94fc82f554bc', 'ძილის ტაიმერი ჩაირთო! ⏱️', 'საღამოს რუტინა იწყება. ჩართეთ ტაიმერი და მარტივად გააანალიზეთ, როგორ ცვლის აქტიური დღე ჩაძინებისთვის საჭირო დროს.'),
  ('f0fc96ac-776c-4e66-bacf-461eff128cbc', 'ფერადი თეფშები 🥦', 'ბოსტნეულს არ ჭამს? თუ ბავშვმა დამატებითი კვება უკვე დაიწყო, რეცეპტებში მოცემული სახალისო გაფორმების იდეებით კვების კონტროლის ინსტრუმენტში ნორმა ხალისიანად შეავსეთ.'),
  ('4673b81e-675b-4232-a5ca-c06aa26d504d', 'დედის ენერგია 🔋', 'ყოველდღიურმა ფუსფუსმა ძალა გამოგაცალათ? საკუთარ თავსაც ნუ დაივიწყებთ! ჯანსაღი რეცეპტებიდან მოამზადეთ ცილებით მდიდარი სმუზი, რომელიც ენერგიით მყისიერად აგავსებთ.'),
  ('7a2ab463-526e-46c6-a246-3494b6c46fa9', 'რთული დილა? 🌪️', 'სიჯიუტის შეტევები დამღლელია. ღრმად ჩაისუნთქეთ და დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ მოიქცეთ ამ სიტუაციაში.'),
  ('c995af30-30f9-4eaf-a66c-3d0d65fc825b', 'მოუსმინეთ შინაგან ხმას 📝', 'ბავშვმა დაიძინა. ახლა გახსენით განწყობის დღიური, დღევანდელი გრძნობები იმ სტრიქონებს გაანდეთ, რომლებსაც ვერავინ წაიკითხავს, და შვება იგრძენით.'),
  ('0aa2cefc-f18c-4c10-98d6-e4dfda22198e', 'დამამშვიდებელი ხმა 🌧️', 'ახალი აღმოჩენებით სავსე დღის შემდეგ ვერ იძინებს? თეთრი ხმებიდან წვიმის ხმა ჩართეთ და მისი ნერვული სისტემა ბუნებრივად დაამშვიდეთ.'),
  ('a57c041d-751b-4413-a98e-ee1564a86127', 'სუფთა ჰაერი, ბევრი ენერგია 🌳', 'სახლის კედლები გთრგუნავთ? დედებისთვის მოსახერხებელი ადგილების სიაში იპოვეთ ახალი პარკი მრავალფეროვანი სათამაშო მოწყობილობებით და დაეხმარეთ ბავშვს ენერგიის დახარჯვაში.'),
  ('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc', 'გონებრივი განვითარების ნახტომი 🧠', 'რა ხდება 18.5 თვის ბავშვის ტვინში? წაიკითხეთ ბლოგების განყოფილებაში გამოქვეყნებული უახლესი სტატია და გაეცანით განვითარების პროცესებს.'),
  ('108adc32-ab84-4dcd-be8c-e7597e84aa99', 'სუფრასთან დიდხანს ზის? ⏱️', 'საჭმლით თამაშის პერიოდი დაიწყო. ჩართეთ კვების ტაიმერი და უმადობის თავიდან ასაცილებლად კვების ხანგრძლივობა გააანალიზეთ.'),
  ('36ae8436-7cda-46ec-b16d-44295bf2f7bc', 'ტანსაცმელი ისევ დაუპატარავდა? 📏', 'გრძნობთ, რომ ბავშვი უეცრად გაიზარდა? განვითარების მონიტორში შეიყვანეთ ახალი მონაცემები და სიამაყით დააკვირდით განვითარების გრაფიკის აღმასვლას.'),
  ('909b1a9f-36d9-4ba3-a481-ae0e711ea145', 'საყვარელი კადრები 📸', 'ხტომას ან ცეკვას ცდილობს? გააფორმეთ ეს წამი ბავშვის ფოტოსესიის მხიარული ჩარჩოებით და შექმენით მოგონება მთელი სიცოცხლისთვის.'),
  ('049ab226-ff27-4f2f-a64f-85d2b588c035', 'შეიძლება კბილი სტკიოდეს? 🤖', 'უმიზეზოდ დაკარგა მადა ან ტირის? სთხოვეთ Anacan AI-ს ექსპერტული მოსაზრება საღეჭი კბილების ამოჭრის ნიშნების შესახებ.'),
  ('0e73fb38-1702-4d44-8a47-bf821e795ce5', 'უსაფრთხო ნაბიჯები 👟', 'სულ უფრო სწრაფად დარბის! პირველი თავდაჯერებული ნაბიჯებისთვის გაეცანით რეკომენდებული პროდუქტების განყოფილებაში წარმოდგენილ საუკეთესო ორთოპედიულ ფეხსაცმელს.'),
  ('2606521b-da76-4e40-8b9b-74eaed8f4900', 'მემკვიდრეობა მომავლისთვის 🖼️', 'დაამატეთ ბავშვის ალბომში ის საქციელი, რომელმაც დღეს ყველაზე მეტად გაგაცინათ? ტელეფონის მეხსიერება რომც გაივსოს, თქვენი მოგონებები ყოველთვის საიმედოდ იქნება დაცული.'),
  ('1e433a5c-ee68-4089-bf86-5ce74fde7136', 'ლოგიკური სათამაშოები 🧩', '18.5 თვის ასაკი იდეალური დროა ლოგიკური თამაშებისთვის. რეკომენდებულ პროდუქტებში აღმოაჩინეთ ასაკის შესაბამისი ფაზლები და კუბიკები.'),
  ('9d69d283-cfae-47a2-a874-8fabcc20a7f1', 'ზრდის ტემპი 📈', 'გააანალიზეთ განვითარების ტემპი განვითარების მონიტორინგის ხელსაწყოში. გრაფიკის საშუალებით თვალყური ადევნეთ, შეესაბამება თუ არა ბავშვის სიმაღლე და წონა ნორმას.'),
  ('a242b14e-b434-493a-ab87-b2064aedfc9e', 'ნამდვილი თავგადასავლების მოყვარული 📸', 'ცოცვისას ან სირბილით თამაშისას გადაღებული ყველაზე სახალისო ფოტო ბავშვის ალბომში დაამატეთ და დაუვიწყარ მოგონებად აქციეთ.'),
  ('58a79bee-96dd-429b-a570-14dc6d97d91a', 'დამამშვიდებელი ტალღები 🌊', 'ზედმეტად სტიმულირებულ ტვინს დამშვიდება სჭირდება. ოთახში თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ და ბავშვი დაამშვიდეთ.'),
  ('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1', 'ეტაპი „ეს რა არის?“ 🤖', 'ბავშვის დაუსრულებელი კითხვები და აღმოჩენებისადმი ინტერესი გაოცებთ? ამ შემეცნებითი ნახტომის შესახებ ინფორმაცია ჩვენი Anacan AI ასისტენტისგან მიიღეთ.'),
  ('f8ad5a51-f4c3-4fc4-8170-0775df79fe84', 'თავად სურს ჭამა 🥣', 'კოვზს ხელიდან არ უშვებს? ჩართეთ კვების ტაიმერი, აკონტროლეთ პროცესის ხანგრძლივობა და ბავშვის რეცეპტებიდან ადვილად დასაჭერი საკვები შეარჩიეთ.'),
  ('995604f6-97b2-4fe5-91ea-98f2248c1b28', 'ცილის მარაგი 🥚', 'აქტიური პატარას კუნთებისთვის ცილა აუცილებელია! კვების კონტროლის ხელსაწყოთი შეაფასეთ მისი ყოველდღიური კვების ბალანსი და შეავსეთ დეფიციტი.'),
  ('ec6ff433-9523-4a66-a427-b2548807345b', 'ყურადღება და მეხსიერება 🧠', 'როგორ სწავლობს თქვენი ბავშვი? ჩვენი აპლიკაციის ბლოგების განყოფილებაში წაიკითხეთ სტატია 1.5 წლის შემდეგ ყურადღებისა და მეხსიერების განვითარების შესახებ.'),
  ('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855', 'დღის დასასრული 🌙', 'ძილის დროა! ჩართეთ ძილის ტაიმერი, აღრიცხეთ ბავშვის რეჟიმი, რათა დარწმუნდეთ, რომ ძილის დღიურ ნორმას იცავს, და დაისვენეთ.'),
  ('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7', 'ძილის რეგრესია? ⏱️', 'ღამით ხშირად იღვიძებს? გადახედეთ ძილის ტაიმერის გრაფიკს. თუ დღის ძილი ძალიან ხანგრძლივია, შესაძლოა, მისი ოდნავ შემცირების დრო მოვიდა.'),
  ('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9', 'კალციუმის მარაგი 🧀', 'კალციუმი აუცილებელია კბილებისა და ძვლებისთვის. კვების კონტროლის ხელსაწყოს მეშვეობით შეამოწმეთ, მიიღეთ თუ არა დღეს რძის პროდუქტების დღიური ნორმა.'),
  ('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11', 'ყოველდღიური ბალანსი 💧', 'შუადღისას საფენის გამოცვლისას ჩანიშვნა არ დაგავიწყდეთ! გამოყოფის სიხშირე ბავშვის აქტივობასთან დაკავშირებულ სითხის საჭიროებასა და საჭმლის მონელებაზე მიგანიშნებთ.'),
  ('44008632-a96c-4f5e-a936-9b65273a2264', 'ახლა თქვენი ჯერია 🥗', 'ბავშვმა დღისით დაიძინა? სამზარეულოში შეიხედეთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან თქვენთვის გემრიელი ულუფა მოამზადეთ.'),
  ('868f8ace-292a-4cf1-9abe-4b2da08aca3f', 'ყავის შესვენება ☕', 'საოჯახო საქმეებმა და ყოველდღიურმა რუტინამ დაგღალათ? დედებისთვის მეგობრულ სივრცეებს შორის იპოვეთ კაფე, სადაც საბავშვო კუთხეა. ფინჯანი ცხელი ყავის მირთმევა თქვენი სრულიად ბუნებრივი უფლებაა.'),
  ('f7b08a7d-5067-40df-81d3-421be952c00e', 'იდეალური დედა არ არსებობს 💖', 'თუ დღეს ყველაფერი გეგმის მიხედვით არ წარიმართა, თავს ნუ დაიდანაშაულებთ. განწყობის დღიურში ჩაწერეთ, რაც გაწუხებთ, და შვებით ამოისუნთქეთ.'),
  ('465d0258-9df5-4a0a-9902-79a09218dcc5', 'ზუსტად 19 თვე! 🎂', 'გილოცავთ! მშობიარობიდან ზუსტად 19 თვე გავიდა! ახლავე აირჩიეთ სპეციალური სტიკერი ბავშვის ფოტოსესიიდან და ეს სიხარული Anacan-ის საზოგადოებას გაუზიარეთ!'),
  ('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4', 'სიცილის ჟღერადობა 📸', 'ბავშვის ალბომში დაამატეთ ყველაზე მხიარული ფოტო, რომელიც ცოცვისას ან სირბილით თამაშისას გადაუღეთ, და დღის დაღლილობა ღიმილად აქციეთ.'),
  ('ccbbf1c0-789d-4a84-96bd-cdb04c618d13', 'თვალი მივადევნოთ ზრდას 📈', 'ფიზიკური აქტივობა გაიზარდა. მაგრამ წონის მატება ნორმის ფარგლებშია? გააანალიზეთ ზრდის ტემპი წონის მონიტორინგის ხელსაწყოში და გაიქარწყლეთ ეჭვები.'),
  ('44418a3d-932e-44e2-832c-c9fdeea34df1', 'დარტყმა და კბენა? 🛑', 'ემოციები, რომელთა გამოხატვაც ბავშვს არ შეუძლია, ზოგჯერ აგრესიაში გადაიზრდება. ჰკითხეთ Anacan AI-ს, როგორ უნდა მოიქცეთ ამ ასაკში კბენისა და დარტყმის შემთხვევებზე.'),
  ('4a287257-0f36-49cd-93f7-28a1154386a6', 'როგორ ყალიბდება წიგნების სიყვარული? 📖', 'ძილის წინ კითხულობთ? ბლოგების განყოფილებაში გაეცანით ოქროს წესებს, რომლებიც დაგეხმარებათ, ბავშვს წიგნები შეაყვაროთ და მისი ყურადღება გვერდებზე შეინარჩუნოთ.'),
  ('f9f77164-bd35-4d6c-83ca-1991fcf7701a', 'ახალი აღმოჩენები, ახალი საფრთხეები ⚠️', 'ის უკვე ყველგან აძვრება! სახლის უსაფრთხოების გასაზრდელად აუცილებლად დაათვალიერეთ ავეჯის კუთხეების რბილი დამცავები რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('66297752-072e-4e90-afa0-bfdfc587176c', 'როგორია რკინის მარაგი? 🥩', 'იმისთვის, რომ აქტიურ პატარას ანემია არ განუვითარდეს და ენერგია შეუნარჩუნდეს, კვების კონტროლის ხელსაწყოში შეამოწმეთ, რამდენი რკინა მიიღო დღეს და შეავსეთ დანაკლისი.'),
  ('802d0f46-e525-43d0-8f5c-440b82228035', 'ქვიშისა და ფოთლების თერაპია 🍂', 'გადით სახლის ოთხი კედლიდან! დედებისთვის მეგობრული ადგილების განყოფილებაში იპოვეთ პარკი ქვიშის მოედნით ან ფართო გამწვანებული სივრცით და ხელი შეუწყვეთ ბავშვის სენსორულ განვითარებას.'),
  ('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618', 'უარი თქვით სრულყოფილების ძიებაზე ✨', 'დღეს ბავშვს ხმას აუწიეთ? თავს ნუ დაიდანაშაულებთ. განწყობის დღიურში ჩაწერეთ თქვენი შინაგანი განცდები, აპატიეთ საკუთარ თავს და მოემზადეთ ხვალინდელი ახალი დღისთვის.'),
  ('0bcc42e9-f88e-427d-8d6d-562c3e7e7138', 'ოპერაცია „ბროკოლი“! 🥦', 'ბოსტნეულზე უარს ამბობს? არ ინერვიულოთ. ბავშვის რეცეპტებში აღმოაჩინეთ, როგორ დამალოთ ბროკოლი გემრიელ ბლინებში.'),
  ('2e502c2f-240e-4506-a102-a80013f7742b', 'გამოუტყდით საკუთარ თავს 🛋️', 'დღეს ძალიან დაიღალეთ და ყველაფრის მიტოვება მოგინდათ? ეს ნორმალურია! გახსენით განწყობის დღიური, ჩაწერეთ „დასვენება მჭირდება“ და ეს საღამო მხოლოდ საკუთარ თავს დაუთმეთ.'),
  ('530196ff-adb2-4ae9-a06d-67bb4bfd998f', 'მშრალი საფენები გახშირდა? 🧻', 'დილით საფენი შეამოწმეთ. თუ ის 2 საათზე მეტხანს მშრალი რჩება, ეს შეიძლება ტუალეტზე მიჩვევისთვის მზადყოფნის პირველი ნიშანი იყოს! შეიტანეთ ჩანაწერები საფენების ტრეკერში და შეამოწმეთ სტატისტიკა.'),
  ('057998e1-6566-4f75-aa40-70a38d334aee', 'დედის წყლის ბალანსი 💧', 'ბავშვის დევნაში წყლის დალევა დაგავიწყდათ? შესაძლოა, თავის ტკივილის მიზეზი სწორედ ეს იყოს. ჯანსაღი რეცეპტებით მოამზადეთ დეტოქს-წყლები და აღიდგინეთ ენერგია.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('29452fba-ed37-4bde-8e72-45e1f9c46d4d'::uuid, 'დაძინებამდე 10 წუთი... ⏱️', 'ჩართეთ ძილის ტაიმერი და ჩააბნელეთ ოთახი. თეთრი ხმებიდან ტყის შრიალი ჩართეთ და დაძინების პროცესი ჯადოსნურ გამოცდილებად აქციეთ — როგორც ბავშვისთვის, ისე საკუთარი თავისთვის.'),
  ('fa637a9e-0a58-4301-a5dd-89fb27cdb46b', 'მაკარონის მონსტრი! 🍝', 'დამოუკიდებლად ჭამისას ტანსაცმელი და თმაც კი მოითხუპნა? არ გამოტოვოთ ეს სახალისო მომენტი! გააფორმეთ ბავშვის ფოტოსესიის მხიარული ჩარჩოებით და დაამატეთ ალბომში.'),
  ('031932e3-d91b-494c-9f35-dc03d53026b4', 'ფეხსაცმელი უჭერს? 👟', 'ბოლო დროს სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! წონის მონიტორინგში შეიყვანეთ ფეხსაცმლის ახალი ზომა და სიმაღლის მონაცემები და გააანალიზეთ ზრდის ტემპი.'),
  ('db0a30ff-e18a-4830-abdc-881dc8827a75', 'საკვები ტვინისთვის: ომეგა-3 🐟', 'თევზი მნიშვნელოვანია გონებრივი განვითარებისთვის. ბავშვებისთვის, რომლებმაც დამატებითი კვება დაიწყეს, რეცეპტების განყოფილებიდან მოამზადეთ ღუმელში გამომცხვარი, უძვლო და გემრიელი თევზის კატლეტი.'),
  ('eb71840a-d8fc-43f9-897d-715c008b72b7', 'შენელების დროა! 🌙', 'აქტიური დღე დასასრულს უახლოვდება. ჩართეთ ძილის ტაიმერი, შეწყვიტეთ სირბილი და ხმაურიანი თამაში და გადადით დამამშვიდებელ აქტივობებზე (მაგალითად, ფაზლის აწყობაზე).'),
  ('36d9b82f-d63f-40d9-bafa-df3b3dc844b9', '5-წუთიანი გემრიელობა! 🥗', 'შუადღისას სახელდახელოდ მიირთმევთ რამეს? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ავოკადოსა და კვერცხის ტოსტი, რომელიც დაგანაყრებთ და ენერგიით აგავსებთ.'),
  ('5db92d40-f36e-4671-8f65-a3cb3f1c91ed', 'ფიზიკის აღმოჩენები აბაზანაში 🛁', 'ბავშვის ალბომში დაამატეთ მისი სერიოზული და ყურადღებიანი გამომეტყველება, როცა წყალს ერთი პლასტმასის ჭიქიდან მეორეში ასხამს — აღმოჩენების ეს პატარა მომენტები დაუვიწყარია!'),
  ('e18f3a19-4a7e-44e4-9703-5c88f6dda037', 'ეკრანთან მეტისმეტ დროს ატარებს? 📱', 'ტელეფონის ჩამორთმევა დიდ ისტერიკას იწვევს? Anacan AI-სგან შეიტყვეთ, როგორ შეზღუდოთ ეკრანთან გატარებული დრო სტრესის გარეშე და დააწესოთ ჯანსაღი საზღვრები.'),
  ('2c1e9be8-ccf0-412a-a942-30cea5075e5b', 'სოციალიზაციის დროა! 👶', 'მას უკვე ძალიან უნდა სხვა ბავშვებთან ერთად ყოფნა. დედებისთვის მეგობრულ ადგილებს შორის მოძებნეთ სივრცე, სადაც საბავშვო სათამაშო ცენტრიც არის, და გაახარეთ ბავშვი.'),
  ('cb4b4d68-2b36-4d3f-aa77-92d10314464f', 'ახალი საკვები, ახალი რეაქცია 💩', 'გუშინ რაიმე უჩვეულო ან ალერგიის გამომწვევი ხომ არ ჭამა? დილით საფენის გამოცვლისას დააკვირდით განავალს, ფერისა და კონსისტენციის ცვლილებები კი აპლიკაციაში მონიშნეთ, რათა მდგომარეობა აკონტროლოთ.'),
  ('fec1f9db-8b95-410a-b753-aded5a7dc606', 'სიბნელის ეშინია? 🌌', 'ოთახში შუქის ჩაქრობისას ტირის ან შფოთავს? თეთრი ხმებიდან ჩაურთეთ საშვილოსნოში მოსმენილი ხმა (გულისცემა), რათა კვლავ აგრძნობინოთ ნაცნობი, თბილი და უსაფრთხო გარემო.'),
  ('5c635a69-e5ff-42eb-9277-29e39d9986fa', 'კბილების გახეხვა სახალისოა! 🪥', 'ჯაგრისს პირთან ახლოს არ იკარებს? რეკომენდებულ პროდუქტებში დაათვალიერეთ თითზე ჩამოსაცმელი ჯაგრისები ან განათებიანი და მუსიკალური მოდელები და ჰიგიენის ეს პროცესი თამაშად აქციეთ.'),
  ('f2a19104-ece3-4a8f-9966-8cad392a68af', 'ღამის სიმშვიდე 🍵', 'ბავშვმა დაიძინა, ტაიმერი გაჩერდა. ახლა სირბილის კი არა, დასვენების დროა. ჯანსაღი რეცეპტებიდან გვირილის ჩაი მოამზადეთ და სრული სიმშვიდით დატკბით.'),
  ('f524b282-4173-4386-b8dd-255261b77d1d', 'მე თვითონ ჩავიცვამ! 👕', 'დილაობით ჩაცმისას დიდი ალიაქოთი იწყება? ბლოგების განყოფილებაში წაიკითხეთ, როგორ მოაგვაროთ ჩაცმასთან დაკავშირებული კრიზისები პრაქტიკული გზებით — ბავშვს არჩევანის საშუალება მიეცით.'),
  ('46919051-4727-4a43-8ba3-d5a1f5451c16', 'დიდი ისტერიკა მაღაზიაში? 🛒', 'საზოგადოებრივ ადგილას სასურველი რომ ვერ მიიღო, იატაკზე წვება და ყვირის? გარშემომყოფთა მზერას ყურადღებას ნუ მიაქცევთ — იმ მომენტში სიმშვიდის შესანარჩუნებლად გაესაუბრეთ Anacan AI-ს და მიიღეთ მხარდაჭერა.'),
  ('874df706-e26e-4b72-a02c-7f8309fc95d5', 'ორსიტყვიანი წინადადებები! 🗣️', 'დღეს ახალი ფრაზა თქვა, მაგალითად, დედა, მოდი ან ბურთი გადააგდე? ენის განვითარების ეს შესანიშნავი ეტაპი ვიდეოზე ხმით გადაიღეთ და დაუყოვნებლივ შეინახეთ ბავშვის ალბომში სამახსოვროდ.'),
  ('af368cd3-f751-4611-9e47-9c8fda037ebd', 'თითების მოტორიკა მოქმედებაშია! 🧩', 'მიეცით საშუალება, დამოუკიდებლად ჭამოს ბარდა, სიმინდი ან დაჭრილი ხილი. ეს წვრილ მოტორიკას ავითარებს. კვების კონტროლის საშუალებით აკონტროლეთ ულუფა.'),
  ('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323', 'იმუნიტეტის მხარდაჭერა! 🍊', 'ამინდი იცვლება? კვების კონტროლის ხელსაწყოთი გამოთვალეთ, რამდენი Vitamin C მიიღო დღეს ბავშვმა და მენიუს ციტრუსები, კივი ან ფერადი ბულგარული წიწაკა დაამატეთ.'),
  ('28cf8172-0a76-4afd-b2de-765879c7939a', 'მადლობა გადაუხადეთ საკუთარ თავს! 💖', 'თქვენ ისეთი თავდადებული და შესანიშნავი დედა ხართ! გახსენით განწყობის დღიური, ჩაინიშნეთ თუნდაც ყველაზე პატარა რამ, რაც დღეს თქვენი შვილისთვის გააკეთეთ, და იამაყეთ საკუთარი თავით.'),
  ('f00a5e44-ed12-4c77-9249-e4246b2b108d', 'ქოთანთან პირველი გაცნობა 🚽', 'მართალია, ჯერ ადრეა, მაგრამ ქოთნის სააბაზანოში დადგმა ბავშვს ვიზუალურად შეაჩვევს მას. რეკომენდებულ პროდუქტებში დაათვალიერეთ კომფორტული და საინტერესო მოდელები, რომლებიც მის ყურადღებას მიიქცევს.'),
  ('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee', 'პატარა დიზაინერი საქმეშია! 👗', 'სურს, თავად შეარჩიოს ტანსაცმელი და შეუხამებელ ფერებს იცვამს? გააფორმეთ ეს სასაცილო კომბინაცია ბავშვის ფოტოსესიის მხიარული სტიკერებით და აქციეთ ალბომის ყველაზე სახალისო კადრად.'),
  ('f830cd97-a8bb-4789-bdc5-7806bcd89cfe', 'გადაჭარბებული აღგზნებულობა 🎇', 'დღის განმავლობაში ზედმეტად აქტიური ტვინი ღამით დამშვიდებას ვერ ახერხებს. „თეთრი ხმების“ განყოფილებაში ჩართეთ ფენის ან ვენტილატორის ხმა და ნახეთ, როგორ ამშვიდებს ბავშვს მონოტონური ხმაური.'),
  ('f8565841-4602-47d5-af45-99f7dea5b129', 'ცაციაა თუ მემარჯვენე? 🤚', 'რომელი ხელით უჭირავს კოვზი? აუცილებლად გაეცანით ბლოგების განყოფილებაში გამოქვეყნებულ ჩვენს ახალ სამეცნიერო სტატიას იმის შესახებ, როგორ და როდის ყალიბდება წამყვანი ხელი.'),
  ('1915583e-53f5-46af-8212-835dfd587e22', 'თმის ცვენა გრძელდება? 💇‍♀️', 'თქვენი ორგანიზმი ჯერ კიდევ აღდგენის პროცესშია. დღეს იზრუნეთ საკუთარ თავზე და ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან შეარჩიეთ თუთიითა და ბიოტინით მდიდარი საუზმის მენიუ.'),
  ('cfbeabf3-def0-4cbe-a106-fd34987dd776', 'მუსიკალური ინსტრუმენტების დროა 🥁', 'უყვარს ხის კოვზებით ქვაბებზე დაკვრა? რეკომენდებულ პროდუქტებში დაათვალიერეთ ქსილოფონები და დოლები, რომელთა ხმის დონეც ბავშვის სმენისთვის უსაფრთხოა.'),
  ('daa6a0d6-25d4-401e-ba81-8a8ca5108695', 'ცხოველების პირველი ხმები 🐮', 'ძაღლის ან კატის დანახვისას ცდილობს მათი ხმის მიბაძვას? გადაიღეთ ამ შესანიშნავი შემეცნებითი განვითარების ამსახველი მოკლე ვიდეო, დაამატეთ ბავშვის ალბომში და სამუდამოდ შემოინახეთ ეს მოგონება.'),
  ('2ed7fd17-90ba-451d-9c88-a1f94a180fe0', 'მადა შემცირდა, წონა კი? 📉', 'ამ თვეებში ბავშვები საკვების მიმართ უფრო პრეტენზიულები ხდებიან. შეიყვანეთ მიმდინარე მონაცემები წონის მონიტორინგის ფუნქციაში, დარწმუნდით, რომ განვითარება სინამდვილეში სრულიად ნორმალურად მიმდინარეობს და მაშინვე დამშვიდდით.'),
  ('50209dd4-d2d7-4719-bf4e-21df8c72686a', 'ძილისთვის მომზადების რიტუალები 🧸', 'ყოველ საღამოს ერთი და იგივე თანმიმდევრობა დაიცავით! ჩართეთ ძილის ტაიმერი, ბავშვს საყვარელი დათუნიასთვის ღამე მშვიდობისა ათქმევინეთ და დააკვირდით, როგორ ამარტივებს ეს სტაბილურობა ჩაძინებას.'),
  ('cc01349a-6eef-4c61-aa08-b3f505c2eb5f', '„მე თვითონ შევჭამ!“ — ბრძოლა 🥣', 'თუ ნებას დართავთ, საჭმელი ყველგან მიმოიფანტება, ხოლო თუ არ დართავთ — ყვირილს იწყებს. Anacan AI-ის ფსიქოლოგიური რჩევებით ახლავე გაიგეთ, როგორ მართოთ ეს კრიზისი სტრესის გარეშე.'),
  ('3abde512-ebd4-4cf1-986e-fb1953695f78', 'იმუნიტეტის ფერადი ფარი 🛡️', 'კვების მონიტორინგის ფუნქციით შეამოწმეთ, მიიღო თუ არა ბავშვმა დღეს საკმარისი C ვიტამინი. ნარინჯისფერი და წითელი ბოსტნეულის კერძების მოსამზადებლად გაეცანით ბავშვის რეცეპტებს.'),
  ('56129e04-2f90-42b1-b51e-b835940e284e', 'გათავისუფლდით გონებრივი დატვირთვისგან 🧘‍♀️', 'ესეც უნდა გავაკეთო, ისიც უნდა მოვამზადო — თქვენი გონება არ ისვენებს? განწყობის დღიურში ჩაიწერეთ ყველა თქვენი გეგმა და შიში. სიის შედგენა სტრესს მაშინვე ამცირებს.'),
  ('deb6cbd4-3a89-4915-9bdf-626d87829918', 'წყლისა და ტალახის სიყვარული 💦', 'ნუ შეგეშინდებათ, თუ ბავშვი ტანსაცმელს დაისვრის! დედებისთვის მეგობრულ სივრცეებში მოძებნეთ ადგილი ღია ცის ქვეშ და მიეცით ბავშვს საშუალება, ბუნებასთან შეხებით სენსორული განვითარების პიკი განიცადოს.'),
  ('1576f605-27d8-4159-b3bd-3dd9e63c91dd', 'მეტი სითხე, მარტივი მონელება 💧', 'მყარ საკვებზე სრულად გადასვლა ზოგჯერ მონელებას ართულებს. საფენების ტრეკერში ჩანაწერების გაკეთებით მარტივად განსაზღვრეთ, საჭიროა თუ არა მიღებული წყლის რაოდენობის გაზრდა.'),
  ('93141c59-a17f-414d-9f6c-c865a0650eeb', 'ჩრდილების თეატრი იწყება! 🐰', 'ოთახში შუქი ჩააქრეთ და ფანრით კედელზე ჩრდილის ფიგურები შექმენით. აუცილებლად გადაიღეთ ბავშვის ალბომისთვის მისი საყვარელი, გაოცებული სახე, როცა ამ ჯადოსნობას უყურებს.'),
  ('a14c30d1-ff1f-46da-8b1e-98116e38ee0d', 'გვერდების დახევა უყვარს? 📖', 'წიგნების წაკითხვის ნაცვლად მათი დახევა სურს? ბლოგების განყოფილებაში გაეცანით ახალ რჩევებს, თუ რატომ არის ამ ასაკში მნიშვნელოვანი მუყაოს და ტაქტილური წიგნები.'),
  ('8e7d531f-d445-43eb-a4d5-05ffff377c4f', 'ხმაურიდან სიჩუმემდე 🎶', 'ტელევიზორის ან სათამაშოების ხმებიდან უეცარ სიჩუმეზე გადასვლამ შეიძლება ბავშვი შეაშინოს. ოთახში თეთრი ხმებიდან მატარებლის ხმა ჩართეთ და ძილის გარემოზე რბილი გადასვლა შექმენით.'),
  ('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf', 'გაზიარების პრობლემა 🧸', 'პარკში სხვა ბავშვების სათამაშოებისკენ გარბის, მაგრამ საკუთარს არავის აძლევს? Anacan AI-სგან შეიტყვეთ, როგორ ასწავლოთ 1.5 წლის ბავშვს რიგრიგობით თამაში.'),
  ('ca671510-91c4-4377-9f69-b4bd47b292a2', 'ერთი ფინჯანი შესვენება ☕', 'თქვენი ენერგიის მარაგი როგორ არის? შეაჩერეთ საოჯახო საქმეები. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ენერგიული კექსი არაქისის კარაქით და უბრალოდ მშვიდად მიირთვით ყავა.'),
  ('38141003-a43c-4589-a477-21da541a08db', 'კინეტიკური ქვიშის ჯადოსნობა 🏖️', 'მოდით, სახლში პატარა სანაპირო მოვაწყოთ! გაეცანით რეკომენდებულ პროდუქტებში წარმოდგენილ კინეტიკური ქვიშის ნაკრებებს, რომლებიც თითების კუნთებს აძლიერებს და ადვილად იწმინდება.'),
  ('75f9f2e1-a04a-4711-9125-3d8c610326d9', 'უკვე საკუთარ სხეულს ცნობს! 👃', 'როცა ეკითხებით: „ცხვირი სად გაქვს?“, ამაყად მიგითითებთ? ბავშვის ფოტოსესიისთვის ოთახში პატარა გადაღება მოაწყვეთ და ეს საყვარელი პოზა მაშინვე შეინახეთ ალბომში.'),
  ('ae036003-f237-47e6-8031-7feeb47126cc', 'როგორ გავიგოთ, რომ დანაყრდა? ⏱️', 'თუ საკვების გადაყრა ან გადმოფურთხება დაიწყო, ეს ნიშნავს, რომ უკვე დანაყრდა. გააჩერეთ კვების ტაიმერი, მონიშნეთ, რომ ნორმა შესრულებულია და გააანალიზეთ მისი მადა.'),
  ('05bc3cfd-c566-4963-b6b2-87889d369e27', 'თქვენც გჭირდებათ ურთიერთობა 💬', 'სხვა დედებთან ურთიერთობა თქვენც სასიკეთოდ წაგადგებათ! დედებისთვის მეგობრული ადგილებიდან შეარჩიეთ ცენტრი, სადაც სათამაშო ჯგუფებია, და ორივეს აჩუქეთ სოციალიზაციის შესაძლებლობა.'),
  ('5b6366a9-6eb4-4593-8335-c41fd3447da1', 'რა არის თქვენი დღევანდელი გამარჯვება? 🏆', 'ბავშვის ტირილის გარეშე დაძინება? თუ მისთვის მთელი ჯამის საკვების შეჭმევინება? თქვენი უმცირესი წარმატებაც კი ჩაწერეთ განწყობის დღიურში და საკუთარ თავს დამსახურებული ტაში დაუკარით.'),
  ('98a39354-24f3-4f3c-9cfb-1e084764a56b', 'ზრდა ფეხსაცმლიდან იწყება 📏', 'თუ ბავშვს ფეხსაცმლის ჩაცმა აღარ სურს, შესაძლოა, ის უკვე უჭერს! შეამოწმეთ ზომების ცხრილი წონის მონიტორინგის ხელსაწყოში და თვალი ადევნეთ მის ფიზიკურ განვითარებას.'),
  ('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1', 'თმისა და კანისთვის 🥑', 'იზრუნეთ ყოველდღიური რუტინით დაღლილ სხეულზე. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ანტიოქსიდანტებით მდიდარი ახალგაზრდობის სალათი ავოკადოთი და ნიგვზით.'),
  ('a832a387-bccf-4a1a-823c-3930e73e4c07', 'წყალი მომეცი, დედა მოდი 🗣️', 'უკვე ცდილობს ორი სიტყვის გაერთიანებას და პატარა წინადადებების შედგენას? ეს მეტყველების განვითარებაში საოცარი წინსვლაა! ყოველთვის წაახალისეთ მისი მცდელობები და ხშირად ესაუბრეთ.'),
  ('d1f9f7f1-6831-4583-9dbd-fab805703b8d', 'ულევი ენერგია 🔋', 'სირბილით არ იღლება? ჩართეთ ძილის ტაიმერი და ოთახში განათება ჩააქრეთ. თეთრი ხმებიდან ტყის შრიალი შეარჩიეთ და თანდათან ძილისთვის განაწყეთ.'),
  ('34104368-1e25-46df-8c68-910d16cd40b1', 'როგორ მუშაობს საჭმლის მომნელებელი სისტემა? 🚽', 'შეკრულობა აწუხებს? დილით, საფენის გამოცვლისას, მონიშნეთ ეს და კვების კონტროლის ხელსაწყოს დახმარებით მის მენიუში აუცილებლად დაამატეთ ბოჭკოვანი საკვები (მსხალი, შვრია).'),
  ('79b083b6-1c72-4250-a120-ca8846206ce5', 'როგორ გრძნობთ თავს? 🧘‍♀️', 'დღეს ბევრჯერ თქვით „არა!“? თავს დამნაშავედ ნუ იგრძნობთ. განწყობის დღიურში გადმოიტანეთ თქვენი შინაგანი ხმა და გაიხსენეთ, რამდენად თავდადებული დედა ხართ.'),
  ('bfb35c45-0163-48f3-be24-eff4697cb9e8', 'ბუნების ხელოვანები 🍂', 'ფოთლები, ქვები და ტოტები საუკეთესო სათამაშოებია! დედებისთვის მეგობრულ ადგილებში მოძებნეთ გამწვანებული პარკი და ღია ცის ქვეშ ნამდვილ აღმოჩენებზე გაემართეთ.'),
  ('01861a89-1cc1-4443-8c58-c79d90402305', 'კაპრიზები მაღაზიაში 🛒', 'მაღაზიაში სასურველი ნივთი არ უყიდეთ და ბავშვი იატაკზე გაწვა? ნუ აჰყვებით პანიკას. გარშემომყოფთა მზერას ყურადღებას ნუ მიაქცევთ, მშვიდად დაიხარეთ ბავშვის თვალების დონემდე.'),
  ('32e724db-ca0f-4d6b-9d07-716443a9dcdd', 'განიტვირთეთ ემოციური ტვირთისგან 📝', 'რთული დღე გქონდათ? დღევანდელი სტრესის შესახებ განწყობის დღიურში დაწერეთ და გული მოიოხეთ. ყველა დედა გადის ამ გზას — თქვენ მარტო არ ხართ.'),
  ('a0570819-b575-49b5-bbf4-bc21cf5fc939', 'ორივე ფეხით ხტუნვა 🦘', 'ცდილობს, ადგილიდან ორივე ფეხით ერთდროულად ახტეს? ძალიან სახალისოდ გამოიყურება, არა? ეს მომენტი აუცილებლად უკვდავყავით ბავშვის ფოტოსესიით.'),
  ('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d', 'ძილზე უარს ამბობს? 🥱', 'დღისით დაძინება არ უნდა და წინააღმდეგობას გიწევთ? ჰკითხეთ Anacan AI-ს ზუსტი ინფორმაცია 20 თვის ბავშვების ძილის ფანჯრების შესახებ და სთხოვეთ, ძილის რეჟიმის განრიგი შეგიდგინოთ.'),
  ('2edb626b-eafe-49c0-a743-e6dae9f9eddd', 'მუსიკალური სიმშვიდე 🎶', 'საღამოს დაწყებული ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზა მისი საყვარელი მელოდიის ჩართვა, ბავშვთან ჩახუტება და ნელა ცეკვაა.'),
  ('b174df30-8e63-488e-ae9b-4d227f3136f1', 'ნადიმი დედისთვის 🥑', 'ბავშვის დასანაყრებლად ყველაფერს აკეთებთ. თავად თქვენზე რას იტყვით? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინით მდიდარი სადილი, რომელიც ენერგიას შეგმატებთ, მშვიდად დაჯექით და მიირთვით.'),
  ('5d951093-5ada-49f6-9750-d303bcf8d918', 'დიდი საღეჭი კბილები? 🦷', 'უმიზეზოდ ყველაფერს ღრღნის და ტირის? შესაძლოა, ყველაზე უკანა საღეჭი კბილები ამოსდის. მონიშნეთ პროცესი კბილების ამოსვლის ტრეკერში და მოამზადეთ ცივი კბილების მოსაფხანი სათამაშოები.'),
  ('9fe66081-4fad-49c8-891d-2ca85484f87d', 'ზღაპრის გმირი 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ შექმენით განსაკუთრებული ამბავი, რომლის გმირიც თქვენი შვილი იქნება: მამაცი პატარა, რომელსაც კბილების გახეხვა უყვარს.'),
  ('c638741f-2af1-4bf3-a4de-09ffcb406144', 'გარეთ გასვლის გამბედაობა ⛅', 'უჩვეულო ამინდის გამო სახლში დარჩით? ამინდისა და ჩაცმულობის ხელსაწყო მყისიერად გიჩვენებთ ქარის სიჩქარეს, რომელიც ფანჯრიდან არ ჩანს, და სამოსის სწორ კომბინაციას შეგირჩევთ — თქვენ კი თამამად გაემართეთ პარკისკენ.'),
  ('3d75b744-8440-4e62-83c6-4a08b865c0f7', 'იოგურტის ნიღაბი! 🥣', 'საჭმელი სახესა და თმაზე წაისვა? გაბრაზების ნაცვლად, დაამატეთ ხელოვნების ეს გენიალური ნიმუში ბავშვის ალბომში, გააფორმეთ სახალისო სტიკერებით და სამუდამოდ შემოინახეთ მოგონებად.'),
  ('69c1e419-f8f2-4b2f-90e3-9b51e78ff197', 'ტაიმერი გაჩერდა, თქვენ კი დაისვენეთ 🍵', 'ძილის ტაიმერი გააჩერეთ და ოთახიდან გამოხვედით. ახლა საოჯახო საქმეებს ხელი არ ახლოთ! მოიმზადეთ გვირილის ჩაი და დღის დაღლილობა თბილ ორთქლს გაატანეთ.'),
  ('934796d5-42af-4c49-9cb9-67f18b657e36', 'კბილები ექავება? 🦷', 'შესაძლოა, ბოლო საღეჭი კბილები ამოსდის. ღრძილების ქავილის შესამსუბუქებლად ბავშვის რეცეპტებიდან მოამზადეთ გრილი, უშაქრო და სასარგებლო ხილის ყინული (პოპსიკლები).'),
  ('06d75280-127a-43d4-a7f0-42d2871b24c5', 'დამოუკიდებელი შეფმზარეული! 👨‍🍳', 'არ სურს, კოვზი მოგცეთ? ბავშვის რეცეპტებიდან მოამზადეთ ხელით ადვილად ასაღები კატლეტები. კვების ტაიმერის საშუალებით გააანალიზეთ, რამდენ ხანს ჭამს დამოუკიდებლად და თვალი ადევნეთ მის მადას.'),
  ('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb', 'სასაცილო მიმიკები 🤪', 'სარკის წინ სასაცილო სახეებს იღებს? არ გამოტოვოთ ეს მხიარული მომენტი! გააფორმეთ ბავშვის ფოტოსესიის სახალისო სტიკერებით და აქციეთ ალბომის ყველაზე მხიარულ კადრად.'),
  ('739af07d-8466-4c3f-a164-5e408385ca93', 'ყველაფერზე ძვრება? 🧗‍♀️', 'დივანი, მაგიდა, კარადა... ნამდვილი ალპინისტია! ბლოგების განყოფილებაში წაიკითხეთ, როგორ დააკმაყოფილოთ სახლში უსაფრთხოდ მისი ეს სახიფათო, თუმცა მოტორული განვითარებისთვის აუცილებელი მოთხოვნილება.'),
  ('8ac7016a-7613-48aa-a952-59cc5f8a6354', 'შარვლის ტოტები დაუმოკლდა? 👖', 'ზრდის ნახტომი სრული ტემპით გრძელდება! შეიყვანეთ მისი ამჟამინდელი სიმაღლე და წონა წონის ტრეკერში და სიამაყით დააკვირდით, როგორ მიიწევს ზემოთ განვითარების გრაფიკი.'),
  ('db467018-0ec9-41a9-a3a3-3ef1c48cda53', 'განმავითარებელი სათამაშოს ძიებაში 🧩', 'საჭიროა სათამაშოები, რომლებიც მხოლოდ ხმას კი არ გამოსცემს, არამედ აზროვნებასაც ავითარებს. აუცილებლად გადახედეთ რეკომენდებულ პროდუქტებში 1.5 წლის ზემოთ ბავშვებისთვის განკუთვნილ ლოგიკურ და ფორმების თავსატეხებს (puzzle).'),
  ('df8f7402-1277-45bd-a743-5c24bdaf48e1', 'გაბრაზებისას კბენა? 🦖', 'გაბრაზებისას ურტყამს ან კბენს? ასე გამოხატავს გრძნობებს, რომელთა სიტყვებით გადმოცემაც ჯერ არ შეუძლია. Anacan AI-ისგან გაიგეთ, როგორ შეცვალოთ ეს ქცევა რბილი მიდგომით.'),
  ('348430a9-4730-49e1-90ac-91076b5c5d7c', 'გავარჩიოთ ფერები! 🔴🔵', 'წითელი სათამაშოები ერთ მხარეს, ლურჯები კი — მეორე მხარეს. ბლოგების განყოფილებაში გაეცანით 19.5 თვის ბავშვებისთვის განკუთვნილ, ყურადღებისა და ლოგიკური აზროვნების განმავითარებელ სახლის თამაშებს და სცადეთ ისინი.'),
  ('907f2a4d-a45c-43e1-8024-d6c91a18d072', 'ხმამაღალი ისტერიკა მაღაზიაში? 🛒', 'საჯარო ადგილას იატაკზე დაეცა და ატირდა? სხვების მზერას ყურადღებას ნუ მიაქცევთ. Anacan AI-ს გაუზიარეთ თქვენი განცდები და ისწავლეთ, როგორ მართოთ ასეთი კრიზისები სიმშვიდის შენარჩუნებით.'),
  ('e6ec7f70-00dc-438b-af17-5f764a9d8216', 'დღის ძილი ხანმოკლე გახდა? ⏱️', 'შუადღისას დაძინება აღარ სურს? თვალი ადევნეთ ძილის ტაიმერის სტატისტიკას. შესაძლოა, უკვე სრულად უნდა გადახვიდეთ დღის განმავლობაში ერთხელ ძილის რეჟიმზე და საღამოს უფრო ადრე დააძინოთ.'),
  ('46ef9700-c667-4312-ac63-98bd03625249', 'ფეხსაცმელზე გაჯიუტდა 👟', 'გარეთ გასვლისას ზაფხულშიც მაინცდამაინც ზამთრის ფეხსაცმლის ჩაცმა სურს? ზოგჯერ არჩევანის უფლება მიეცით — ეს მის ნებისყოფას აძლიერებს.'),
  ('5541587a-ad73-4e1d-9174-d4fe1c028c3e', 'დაძინებას ეწინააღმდეგება? 🛌', 'დასაძინებლად არ მიდის, რადგან თამაში უფრო საინტერესოა! ჩართეთ ძილის ტაიმერი და თეთრი ხმებიდან ოკეანის ტალღების ხმა გამოიყენეთ, რათა თანდათან დამშვიდდეს და ძილისთვის განეწყოს.'),
  ('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'ტუალეტით დაინტერესდა? 🚽', 'თქვენთან ერთად სააბაზანოში შემოსვლა სურს? ეს ვიზუალური მომზადების ეტაპია. ბლოგების განყოფილებაში წაიკითხეთ, როდის და როგორ უნდა დაიწყოთ ქოთნის გამოყენების სწავლება, რათა მზად იყოთ.'),
  ('45af46ac-18bf-499b-a5c7-56bbe71e4564', 'სიმშვიდეზე გადასვლა 🎶', 'პატარა ფეხებს, რომლებიც მთელი დღე დარბოდნენ, დასვენების დრო დაუდგათ. თეთრი ხმებიდან ავტომობილის სალონის ხმა ჩართეთ და ერთფეროვანი ჟღერადობით ძილისთვის იდეალური გარემო შექმენით.'),
  ('47b68bdb-a1fd-4da7-9316-dcca5fdae94f', 'თქვენც გჭირდებათ მეგობრები 👯‍♀️', 'სანამ ბავშვი პარკში თამაშობს, თქვენც გსურთ სხვა დედებთან საუბარი? დედებისთვის მეგობრულ ადგილებში აღმოაჩინეთ ცენტრები, სადაც სათამაშო ჯგუფებია, და გაიცანით ახალი ადამიანები.'),
  ('49af58d4-c188-43d7-a0b2-43f4cd255337', 'დილის ყავა საკმარისი არ არის! ☕', 'უზმოზე ყავით დღის დაწყება ენერგიას სწრაფად გამოგაცლით. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან აირჩიეთ ენერგიით სავსე შვრიის კექსი, რომელიც 5 წუთში მზადდება.'),
  ('869af623-de96-421f-808b-d64172a8f765', 'ყოჩაღ! 👏', 'დღეს სახლი მოუწესრიგებელი დარჩა? ამაზე საერთოდ არ ინერვიულოთ! ბავშვთან ერთად გატარებული სიცილით სავსე წუთები ბევრად უფრო ძვირფასია. განწყობის დღიურში საკუთარი თავი აუცილებლად შეაქეთ.'),
  ('aaf473f6-79bc-44cf-97f4-687dfa4eb293', 'წყლის დალევა არ უყვარს? 💧', 'დილით საფენი ზედმეტად მშრალი იყო? საჭიროა სითხის მიღების გაზრდა. ჩაინიშნეთ ეს საფენების ტრეკერში და აპში ხილის წყლის რეცეპტებსა და სხვადასხვა მოდელის საბავშვო ჭიქებს გაეცანით.'),
  ('ff614b36-4091-473e-b7fa-91411bd4e2a9', 'ძვლები მტკიცდება! 🦴', 'კვების კონტროლის ხელსაწყოთი გამოთვალეთ, მიიღო თუ არა ბავშვმა დღეს საკმარისი კალციუმი და D ვიტამინი. სწრაფი ფიზიკური განვითარებისთვის ეს ორი ელემენტი აუცილებელია.'),
  ('6d72635f-ba12-4c8b-b7ef-f626dd634dce', 'დილის ენერგია სულ სხვაგვარია! ⚡', 'შვრიის ფაფაზე უარს ამბობს? ბავშვის რეცეპტებში აღმოაჩინეთ ხილისა და არაქისის კარაქის სმუზი და კვების კონტროლის ხელსაწყოში კალორიების სამიზნე მაჩვენებელს მარტივად მიაღწიეთ.'),
  ('0a81bd63-014b-4d25-b347-1808455aea49', 'ოთხი კედლიდან გაქცევა 🏃‍♀️', 'სახლში დაგროვილი ენერგიის დახარჯვა რთულია. დედებისთვის მეგობრულ სივრცეებში იპოვეთ უსაფრთხო სათამაშო ცენტრი, სადაც თქვენ ყავას დალევთ, ბავშვი კი ირბენს.'),
  ('657f4585-c7bb-41c0-9574-51e8f943398b', 'არეული, მაგრამ დამოუკიდებელი! 🥣', 'დაჟინებით ითხოვს, რომ თავად ჭამოს? ჩართეთ კვების ტაიმერი, აკონტროლეთ პროცესის ხანგრძლივობა და აღნიშნეთ, როგორ უწყობს ხელს ეს დამოუკიდებლობა მისი ნატიფი მოტორიკის განვითარებას.'),
  ('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4', 'ღამით გაღვიძებები დაბრუნდა? ⏱️', 'ეს შეიძლება 20 თვის ასაკისთვის დამახასიათებელი ძილის რეგრესია იყოს. გადახედეთ ძილის ტაიმერის გრაფიკს და შეამოწმეთ, ხომ არ დადგა დღის ძილის 15 წუთით შემცირების დრო.'),
  ('385a8205-8e28-4c23-94fa-a2a8fe32e28c', 'თავს ნუ დაიდანაშაულებთ 📝', 'დღეს ხმას ოდნავ აუწიეთ? თავს ნუ გაკიცხავთ. განწყობის დღიურში გადმოიტანეთ თქვენი შინაგანი განცდები და გახსოვდეთ, რომ თქვენზე უკეთესი დედა არ არსებობს.'),
  ('49b18c8f-b30b-4368-9445-6af88b1d8115', '2-სიტყვიანი წინადადებები! 🗣️', '„დედა, მოდი“, „ბურთი მომეცი“ — მისი ლექსიკა სწრაფად იზრდება. საუბრის ეს საყვარელი მცდელობები დაუყოვნებლივ დაამატეთ ბავშვის ალბომში ვიდეოს სახით და სამუდამო მოგონებად აქციეთ.'),
  ('5d516faa-7c77-4db9-b201-49bff969e3d8', 'კალციუმი ძვლებისთვის 🦴', 'აქტიური პატარას ძვლები ძლიერი უნდა იყოს. კვების კონტროლის ხელსაწყოში შეამოწმეთ დღეს მიღებული კალციუმის (ყველი, იოგურტი) რაოდენობა და შეავსეთ დღიური ნორმა.'),
  ('3b603489-95c3-4a32-b0e0-5191fc844b75', 'თავად ჩაცმისთვის ბრძოლა 👕', 'დაიწყო ჯიუტობა: „ეს მაისური არ მინდა!“? ჰკითხეთ Anacan AI-ს, როგორ შეამციროთ დილის ჩაცმასთან დაკავშირებული კრიზისები და მისცეთ ბავშვს თავისუფალი არჩევანის უფლება.'),
  ('89933e6a-484e-4f2e-bf20-8262f6a74c72', 'ომეგა-3-ის მარაგი 🐟', 'ტვინის განვითარება არ ჩერდება. კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა ბავშვმა ამ კვირაში საკმარისი რაოდენობის თევზი ან ნიგოზი და დეფიციტის შემთხვევაში აუცილებლად მონიშნეთ.'),
  ('fa46cf0a-85f0-484c-8aa5-b60eb52b320b', 'როგორ დავხარჯოთ ენერგია სახლში? 🏃‍♂️', 'გარეთ გასვლას ვერ ახერხებთ? რეკომენდებულ პროდუქტებში დაათვალიერეთ დახურული სივრცისთვის განკუთვნილი მინი ბატუტები ან სასრიალოები და ბავშვის ენერგია მიზანმიმართულ აქტივობაზე მიმართეთ.'),
  ('00691751-d785-4fc6-8036-d313adccdad6', 'დილის სიურპრიზის შემოწმება 🧻', 'მშრალი საფენების რაოდენობა იზრდება თუ მონელება შენელდა? დილით საფენის გამოცვლის მონაცემები საფენების ტრეკერში შეიტანეთ და მაშინვე გააანალიზეთ პატარას სითხისა და ბოჭკოს საჭიროება.'),
  ('0bde6683-6d18-4d98-bc39-b122396c0b17', 'ახლა დასვენების დროა 🍵', 'სირბილი და დევნა დასრულდა! ჯანსაღი რეცეპტებიდან სასმელი მოამზადეთ, დივანზე წამოწექით და უბრალოდ სიჩუმით დატკბით.'),
  ('0eecf770-9ba2-463c-9b39-bbe24d01b4e1', '„ჩემია!“ — ყვირილი 🧸', 'პარკში სხვას სათამაშოს ართმევს? ჰკითხეთ Anacan AI-ს და შეიტყვეთ ყველაზე ეფექტური ფსიქოლოგიური მიდგომები ამ ასაკისთვის დამახასიათებელი ეგოცენტრული კრიზისების სამართავად.'),
  ('9867089b-80a4-4895-985d-1e1d5fa3df95', 'თვალები გეხუჭებათ? 😴', 'როცა ბავშვს სძინავს, თქვენც წამოწექით. თუ ვერ იძინებთ, ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ანტიოქსიდანტებით მდიდარი მწვანე ჩაი და ენერგია აღიდგინეთ.'),
  ('a5fedf21-2dca-46ed-9476-0b415ced68a5', 'დაძინებას ეწინააღმდეგება? 🛌', 'მე-19 თვე ძილის რეგრესიით არის ცნობილი. ჩართეთ ძილის ტაიმერი და გადაამოწმეთ განრიგი — შესაძლოა, სწორედ ახლა იყოს დღის ძილის ხანგრძლივობის შემცირების დრო!'),
  ('39db43fc-07a0-417e-90da-c0bbbd5f14a4', 'მუცლის ტკივილზე ეჭვი გაქვთ? 💩', 'დილით საფენის გამოცვლისას შეიყვანეთ განავლის მონაცემები. თუ ყაბზობის რისკია, ჰკითხეთ Anacan AI-ს, რა ბუნებრივი საშუალებებისა და მასაჟის ტექნიკების გამოყენება შეგიძლიათ დაუყოვნებლივ, და გამოიყენეთ ისინი.'),
  ('613cd9e2-958a-41bd-b191-0de3ff8ec07f', 'რამდენჯერ გაიგონეთ „არა“? 🙉', 'ჯიუტ პატარასთან გამკლავებას მოთმინება სჭირდება. განწყობის დღიურში ჩაიწერეთ თქვენი შინაგანი დაძაბულობის შესახებ და საკუთარ თავს განსჯის გარეშე მიეცით ემოციების გამოხატვის საშუალება.'),
  ('68ef19de-c144-4be9-8878-9cc1b34a6483', 'რამდენი დრო სჭირდება ჩაძინებას? ⏱️', 'საწოლში ბევრს ტრიალებს? გაააქტიურეთ ძილის ტაიმერი და ჩაინიშნეთ, რამდენი დრო სჭირდება ჩაძინებას. იქნებ საღამოს თამაშების უფრო ადრე დასრულებაა საჭირო.'),
  ('70a3e410-6335-466b-99bc-28ac0c3d913f', 'რატომ იწყებს უეცრად ტირილს? 🤖', 'ღამით ყვირილით იღვიძებს და ვერ მშვიდდება? ღამის ტერორთან დაკავშირებული ეჭვების შესახებ დაუყოვნებლივ მისწერეთ Anacan AI ექსპერტს და გაიგეთ, როგორ მოიქცეთ სწორად.'),
  ('80e71246-05ae-4bc6-857d-5ce3af704b5e', 'დედის ენერგიის წყარო 🥗', 'ბავშვის დევნაში ძალა გამოგელიათ? ტკბილეულის ნაცვლად ცილა აირჩიეთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ არაქისის კარაქის სმუზი, რომელიც მყისიერად შეგმატებთ ენერგიას.'),
  ('145211fa-74d2-4e28-8a64-c14921db5185', 'შეაქეთ საკუთარი თავი! 🌟', 'დღეს მისი გამოკვება ისე შეძელით, რომ არ უტირია? განწყობის დღიურში თქვენი უმცირესი წარმატებაც კი ჩაიწერეთ და დედობრივი უნარებისთვის საკუთარ თავს ფეხზე წამომდგარმა დაუკარით ტაში.'),
  ('4f60f5e8-df5e-4892-aa2e-dcffda8f877b', 'წყლის ბალანსი სასიცოცხლოდ მნიშვნელოვანია 💧', 'აქტიური სირბილი ორგანიზმს აუწყლოებს. საფენების ტრეკერში დილის მონაცემები ჩაინიშნეთ, ხოლო რეკომენდებულ პროდუქტებში დაათვალიერეთ სპორტული წყლის ბოთლები, რომელთა გახსნასაც ბავშვი მარტივად შეძლებს.'),
  ('edd993f1-ac76-4300-8ed0-6009d7897f2b', 'საუბარი სხვა დედებთან ☕', 'მხოლოდ ბავშვთან საუბარმა დაგღალათ? დედებისთვის მეგობრულ ადგილებში იპოვეთ საბავშვო კაფეები, სადაც ბევრი დედა იკრიბება, და საკუთარ თავსაც აჩუქეთ ურთიერთობის შესაძლებლობა.'),
  ('e893b0aa-e3fc-4f78-a970-b681a0ed0450', 'ცოცვის ჩემპიონი! 🧗', 'სახლში ავეჯი აღარ ჰყოფნის? დედებისთვის მეგობრულ სივრცეებში იპოვეთ დახურული გასართობი ცენტრი რბილი დაბრკოლებების ბილიკებით და უსაფრთხოდ დაუკმაყოფილეთ ეს სურვილი.'),
  ('6f516c4d-5db5-4d3e-8fca-8c461e614752', 'რკინის მარაგი შევსებულია? 🥩', 'იმისთვის, რომ თქვენს აქტიურ პატარას ანემია არ განუვითარდეს, კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი რკინა (ხორცი, პარკოსნები), და მენიუ შესაბამისად შეასწორეთ.'),
  ('b003834c-8ce3-4da4-a17e-0b837c04f7f7', 'შევამოწმოთ კალციუმის მარაგი 🧀', 'სწრაფად მზარდ ძვლებს კალციუმი სჭირდება! კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა ბავშვმა დღეს საკმარისი ყველი და იოგურტი, და დანაკლისი შეავსეთ.'),
  ('b5cae897-2c37-4223-8c5a-201bd9d0229a', 'ტყის იდუმალი ხმები 🍃', 'დღე ხმაურიანი და ჭირვეულობით სავსე იყო? თეთრი ხმებიდან ფოთლების შრიალი ჩართეთ და დაამშვიდეთ როგორც მისი, ისე თქვენი ნერვული სისტემა.'),
  ('20cf6725-2fdc-45bb-965b-09069424fe0a', 'უშაქრო წასახემსებელი 🍪', 'მაღაზიის ორცხობილა საჭირო არ არის. ბავშვების რეცეპტებში აღმოაჩინეთ ფინიკისა და შვრიის ჯანსაღი ტკბილეული, რომელსაც სახლში სულ რაღაც 10 წუთში მოამზადებთ.'),
  ('9a0a29d7-d513-4158-b204-99c831639c23', 'ერთად, მაგრამ ცალ-ცალკე 👶', 'პარკში ბავშვებთან არ თამაშობს და მხოლოდ შორიდან აკვირდება? ეს პარალელური თამაშია! ჰკითხეთ Anacan AI-ს საინტერესო ფაქტები სოციალიზაციის ამ ეტაპის შესახებ.'),
  ('f527de5c-afa8-4884-a173-da37070a2826', 'პატარა დამხმარე სახლში 🧹', 'სანამ თქვენ იატაკს გვით, ის მაგიდას ტილოთი წმენდს? დაუყოვნებლივ გადაიღეთ პასუხისმგებლობის ეს საყვარელი მომენტი და ბავშვის ალბომის ყველაზე საამაყო კადრად აქციეთ.'),
  ('18518788-d8e2-4971-93f7-6fbf0592ca33', 'დარტყმა ან ხელის კვრა 🛑', 'გაბრაზებისას მოულოდნელად ხელს გირტყამთ? მიმართეთ Anacan AI-ს, რათა გაიგოთ, როგორ გაუმკლავდეთ თამაშების დახმარებით 20-ე თვისთვის დამახასიათებელ ამ ქცევას.'),
  ('a6200253-33e2-4142-a4a9-811aa67d4feb', 'დღის გმირი თქვენ ხართ 🧘‍♀️', 'ბავშვს ჩაეძინა. შეწყვიტეთ ყველა საოჯახო საქმე. ჩაწერეთ თქვენი გრძნობები განწყობის დღიურში, ჩართეთ მშვიდი მუსიკა და ეს საღამო მხოლოდ საკუთარ თავს დაუთმეთ.'),
  ('eefd67fd-3835-4f65-abf3-9ced6b705e30', 'მოთმინების გამოცდა სასადილო მაგიდასთან ⏱️', 'ერთ კოვზს 5 წუთის განმავლობაში ჭამს? ჩართეთ კვების ტაიმერი, გამოიჩინეთ მოთმინება და აპლიკაციაში მოცემული ანგარიშის დახმარებით ზუსტად გააანალიზეთ მადის ცვლილებები.'),
  ('070b2f75-0440-4e85-b828-292900301f9e', 'წარმოსახვითი თამაშები დაიწყო 🧸', 'დათუნიას წყალს ასმევს ან თქვენ გკურნალობთ? შეინახეთ თანაგრძნობის ეს შესანიშნავი მომენტები მომავლისთვის — დაამატეთ ისინი ბავშვის ალბომში ხმიანი ვიდეოს ფორმატით.'),
  ('388f83f4-0bb5-4306-abf6-b75f9dc65017', 'რკინის მარაგის შემოწმება 🥩', 'აქტიური კუნთებისა და ჯანსაღი განვითარებისთვის აუცილებელია ანემიის თავიდან აცილება. კვების კონტროლის ხელსაწყოთი შეამოწმეთ დღეს მიღებული რკინის რაოდენობა (ხორცი, პარკოსნები) და დანაკლისი დაუყოვნებლივ შეავსეთ.'),
  ('9cb7efe6-c6c0-4032-89de-12eeec5119ee', 'ხმაურიდან სიჩუმეზე გადასვლა 🎶', 'ტელევიზორისა და სათამაშოების ხმების შემდეგ მოულოდნელი სიჩუმე მას აშინებს. ოთახში თეთრი ხმებიდან ჩართეთ თმის საშრობის ხმა და ნახეთ, როგორ უწყობს ხელს მონოტონური ხმა ძილისთვის ხელსაყრელი გარემოს შექმნას.'),
  ('847e9a71-981a-4920-b6be-a1986674dd92', 'დაუსრულებელი შოუ სუფრასთან ⏱️', 'საჭმლით თამაშობს, იატაკზე ყრის, მაგრამ არ ჭამს. ჩართეთ კვების ტაიმერი, გამოიჩინეთ მოთმინება და დამოუკიდებლობის ამ პერიოდში მადის ცვლილებები აპში მოცემული გრაფიკის საშუალებით ზუსტად გააანალიზეთ.'),
  ('890ee8d7-3315-4b7a-994a-c41900d8c960', 'ჭკვიანი სათამაშოს ძიება 🧩', 'უკვე ოსტატურად ათავსებს ფიგურებს შესაბამის ღიობებში? რეკომენდებული პროდუქტების განყოფილებაში ახლავე აღმოაჩინეთ ასაკის შესაბამისი ფაზლები, რომლებიც მის გონებრივ შესაძლებლობებს კიდევ უფრო განავითარებს.'),
  ('8ad462c4-33b5-4c76-be29-aa192feb14a1', 'ფეხსაცმელი უჭერს? 📏', 'ბოლო დროს სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! შეიყვანეთ მიმდინარე სიმაღლე და ზომები განვითარების მონიტორინგის განყოფილებაში და თვალი ადევნეთ მის ფიზიკურ განვითარებას.'),
  ('2e662854-2d0b-4e0d-be84-f71f33b1ed5b', 'რატომ იწყებს მოულოდნელად ტირილს? 🤖', 'მშვიდად თამაშობდა, მაგრამ უცებ ხასიათი შეეცვალა და ტირილი დაიწყო? ემოციური ცვალებადობის მიზეზის გასარკვევად მისწერეთ ჩვენს ექსპერტ AI ასისტენტს — Anacan AI-ს.'),
  ('b30cbe06-794a-4924-bc78-63ebe289b716', 'გონებრივი განვითარება არ ჩერდება 🧠', 'მას ყველაფრის დახარისხება უყვარს! აუცილებლად წაიკითხეთ ბლოგების განყოფილებაში სტატია სახლის თამაშების შესახებ, რომლებიც 20-21 თვის ბავშვებს ფერებისა და ფორმების აღქმას უვითარებს.'),
  ('dcfe0150-6b59-46be-be17-cba289272768', '5-წუთიანი ენერგია 🔋', 'უზმოზე ყავის დალევის შემთხვევაში ენერგია შუადღისთვის გამოგელევათ. ჯანსაღი რეცეპტებიდან შეარჩიეთ გემრიელი და ნოყიერი შვრიის კექსი, რომელიც სწრაფად მზადდება.'),
  ('41523bc6-ac22-4b48-a7b5-8663ed9c74c3', 'ქვიშის თერაპია 🏖️', 'ნუ შეგეშინდებათ დასვრის! დედებისთვის მეგობრულ ადგილებს შორის მოძებნეთ სივრცე, სადაც ქვიშის აუზია. ქვიშასთან შეხება სენსორული განვითარებისთვის ძვირადღირებულ სათამაშოებზე მეტად სასარგებლოა.'),
  ('863859ae-c920-41fe-b876-915ee50bba17', 'საღებავებში ამოსვრილი ხელოვანი! 📸', 'საკუთარი თავი და კედელიც მოხატა? გაბრაზების ნაცვლად, ეს სახალისო ჯღაბნის მომენტი ბავშვის ალბომში ატვირთეთ და მხიარული სტიკერები დაამატეთ.'),
  ('af623bf2-6a45-452d-a9c0-bd16d67bf74d', 'ბლინების მონსტრი 🥞', 'საუზმეზე უარს ამბობს? ბავშვის რეცეპტებში უშაქრო ბანანის ბლინების რეცეპტი ნახეთ. ბავშვი მათ ხელში დაიჭერს და დამოუკიდებლად შეჭამს, თან მადაც გაეხსნება.'),
  ('a7786d73-a362-4a32-a77f-3c09e4ab2ffb', 'ფიზიკის გაკვეთილი წყლით 🛁', 'აბაზანაში წყლის ერთი ჭიქიდან მეორეში გადასხმა არ ბეზრდება? ამ სახალისო და დამამშვიდებელი წყლის სათამაშოების სანახავად რეკომენდებულ პროდუქტებს გადახედეთ.'),
  ('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793', 'კალციუმის ფარი 🦴', 'კბილებისა და ძვლებისთვის კალციუმი აუცილებელია. კვების კონტროლის ხელსაწყოს საშუალებით გადაამოწმეთ, მიიღო თუ არა ბავშვმა დღეს იოგურტისა და ყველის საჭირო რაოდენობა.'),
  ('e8d46282-de1c-4981-9242-f0dff7014b1d', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს ფხიზლად ყოფნის დრო ზედმეტად გახანგრძლივდა? ჩართეთ ძილის ტაიმერი და განრიგს დააკვირდით. შესაძლოა, სწორედ ახლაა დრო, დღის ძილი 15 წუთით შეამციროთ.'),
  ('527e5a17-444d-47c4-8578-4ebb1ee870b1', 'ტკბილი ძილი თუ ომი? 🛌', 'თუ დაძინება დიდ კრიზისად იქცა, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს 21 თვის ბავშვებისთვის განკუთვნილი ძილისწინა რიტუალებისა და ფსიქოლოგიური ხრიკების შესახებ.'),
  ('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6', 'როგორ ჩაიარა ღამემ? 🌙', 'თუ დილით საფენი ძალიან მძიმეა, შესაძლოა, ღამით სითხის მიღების დარეგულირება გახდეს საჭირო. მონიშნეთ ეს საფენების ტრეკერში და შეამოწმეთ დღის განმავლობაში მიღებული სითხის ბალანსი.'),
  ('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4', 'თითების მოტორიკა 🧩', 'ბავშვი უკვე ოსტატურად ათავსებს ფიგურებს შესაბამის ადგილებზე. ახლავე აღმოაჩინეთ რეკომენდებული პროდუქტების განყოფილებაში მისი ასაკისთვის შესაფერისი ფაზლები, რომლებიც გონებრივ განვითარებას კიდევ უფრო შეუწყობს ხელს.'),
  ('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60', 'განტვირთვის დროა 🎶', 'აქტიურმა დღემ შეიძლება ტვინი გადაღალოს. ჩართეთ ტყის შრიალი „თეთრი ხმებიდან“ და ოთახში მშვიდი, ძილის მომგვრელი იდეალური ფონი შექმენით.'),
  ('d93eedfc-78de-4d26-810d-89c2b8c71690', 'გაუმასპინძლდით საკუთარ თავს ყავით ☕', 'მთელი დღე სირბილმა ძალა გამოგაცალათ! დედებისთვის მეგობრული ადგილების რუკაზე იპოვეთ კაფე საბავშვო სათამაშო სივრცით და საკუთარ თავს მცირე სიამოვნება აჩუქეთ.'),
  ('fcfa5044-061e-4832-8787-ddd94f46ab93', 'ახალი სიტყვის აღმოჩენა 🗣️', 'დღეს რომელი ახალი სიტყვა თქვა?'),
  ('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f', 'კუჭ-ნაწლავის სიგნალები 💩', 'მყარ საკვებზე სრულად გადასვლამ შეიძლება საჭმლის მონელება გაართულოს. დილით საფენის ტრეკერში ჩანაწერი გააკეთეთ და მარტივად შეამოწმეთ, საჭიროა თუ არა სითხისა და ბოჭკოს ბალანსის კორექტირება.'),
  ('c4d895de-4842-4a9b-ae46-1557c6e3d2cc', 'ბუნებრივი დამამშვიდებელი 🍃', 'რთული და ხმაურიანი დღე გქონდათ? „თეთრ ხმებში“ ფოთლების შრიალი ჩართეთ და დაამშვიდეთ როგორც ბავშვის, ისე თქვენი ნერვული სისტემა.'),
  ('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3', 'ჩაცმის ომი 👗', '„ეს მაისური არ მინდა!“ — ჭირვეულობა არ მთავრდება? დილით ჩაცმისას კონფლიქტების შესამცირებლად პროცესი თამაშად აქციეთ და უთხარით, რომ ბავშვის ფოტოსესიაზე სურათებს გადაუღებთ.'),
  ('0daafb47-5c27-4a37-935b-b3612abf5506', 'დღის გმირი 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღე ითვისებს, თქვენი შრომის შედეგია. გახსენით განწყობის დღიური, ჩაიწერეთ თუნდაც ყველაზე პატარა სიკეთე, რომელიც დღეს მისთვის გააკეთეთ, და იამაყეთ საკუთარი თავით!'),
  ('3b1eb831-8b25-40be-89a6-b50384eeb49b', 'ლაპარაკი სურს, მაგრამ... 🗣️', 'მისი პასიური ლექსიკა აქტიურზე უფრო დიდია? სიტყვებს სწორად ჯერაც რომ ვერ წარმოთქვამდეს, ბლოგების განყოფილებაში წაიკითხეთ, როგორ შეუწყოთ ხელი ენობრივი განვითარების ამ საოცარ ნახტომს.'),
  ('a4477b67-ebfc-489b-b2e5-165c0ebb273f', 'დამოუკიდებლობის ძიება 🥣', 'კოვზს არ გაძლევთ? ჩართეთ კვების ტაიმერი და გააანალიზეთ, რამდენ ხანს გრძელდება დამოუკიდებლობის ეს გამოცდა. დაყრილ საკვებს კი უბრალოდ ღიმილით შეხედეთ.'),
  ('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94', 'ზრდის ნახტომი! 📏', 'ამჩნევთ, რომ თქვენი ბავშვი უეცრად გაიზარდა? შეიყვანეთ ახალი მონაცემები განვითარების მონიტორში და სიამაყით დააკვირდით ჯანსაღი ზრდის გრაფიკს.'),
  ('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677', 'ენერგიის აღდგენის დროა 🔋', 'ნუ დაივიწყებთ საკუთარ თავს! ჯანსაღი რეცეპტებიდან შეარჩიეთ სწრაფად მოსამზადებელი, ცილებით მდიდარი გემრიელი სმუზი საუზმისთვის და აღიდგინეთ ენერგია.'),
  ('e61cda6e-e7ca-46f3-a40c-42185a9f8216', 'ენერგია 5 წუთში ⚡', 'როცა ბავშვი შუადღით დაიძინებს, სახლის საქმეებს ნუ მიაწყდებით. ჯანსაღი რეცეპტებიდან მოამზადეთ ანტიოქსიდანტებით მდიდარი სმუზი და აღიდგინეთ ძალები.'),
  ('733a062a-9528-4b89-8399-8894cdcd37ab', 'ერთად წიგნის კითხვა 📖', 'თავად სურს წიგნის ფურცლების გადაფურცვლა? ბლოგების განყოფილებაში წაიკითხეთ შესანიშნავი სტატია იმის შესახებ, თუ როგორ შეაყვაროთ ამ ასაკში კითხვა თამაშის საშუალებით.'),
  ('840a48c0-60b0-4169-a7a4-bfd97c049d9d', 'ბუნების აღმოჩენა 🌳', 'სახლის კედლებში ყოფნა მობეზრდა? დედებისთვის მოსახერხებელი ადგილების სიაში იპოვეთ ფართო და უსაფრთხო პარკი და დაეხმარეთ, ენერგია ბუნებაში დახარჯოს.'),
  ('fc70b034-70d7-48ac-b093-b541c3d08e54', 'დილის შემოწმება და ანალიზი 💧', 'დღის პირველი საფენი გამოუცვალეთ? გამონაყოფის მონაცემები აპში შეიყვანეთ და მარტივად აკონტროლეთ, იღებს თუ არა ბავშვი საკმარის სითხეს და გამართულად მუშაობს თუ არა მისი საჭმლის მომნელებელი სისტემა.'),
  ('8139b24d-f8c3-4b60-b4f1-38bd25e609a6', 'კოვზს ხელიდან არ უშვებს? 🥄', 'ჩართეთ კვების ტაიმერი. გააანალიზეთ, რამდენ ხანს გრძელდება დამოუკიდებლად ჭამის მცდელობები და აპში შეამოწმეთ კვების დღიური ნორმა.'),
  ('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91', 'ქვიშით თერაპია 🏖️', 'ნუ შეგეშინდებათ დასვრის! კინეტიკური ქვიშისა და სენსორული თამაშებისთვის საუკეთესო საშუალებები ახლავე აღმოაჩინეთ რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('f71cc78c-d1eb-4694-b94a-1843f80e2db1', 'დამამშვიდებელი ტალღები 🌊', 'აქტიური აღმოჩენებით სავსე დღის შემდეგ ვერ იძინებს? თეთრი ხმებიდან აირჩიეთ ოკეანის ტალღების ხმა, ოთახში ჯადოსნური სიმშვიდე შექმენით და ბავშვი ძილისთვის განაწყვეთ.'),
  ('3787f491-d618-4351-acd6-86ff87689c17', 'დარტყმა და ხელის კვრა 🛑', 'გაბრაზებისას მოულოდნელად ხელს ურტყამს ან კბენს? ჰკითხეთ Anacan AI-ს, როგორ გაუმკლავდეთ სიყვარულით 21-ე თვისთვის დამახასიათებელ ამ ქცევას.'),
  ('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce', 'როგორია ცილის მარაგი? 🍗', 'ბავშვის ზრდისთვის ცილა აუცილებელია! კვების კონტროლის ხელსაწყოთი შეაფასეთ მისი ყოველდღიური კვების ბალანსი და შეავსეთ დანაკლისი.'),
  ('e90a6ec1-ff62-4f86-8635-bb93512c7c35', 'ძილის ანალიზი ტაიმერით ⏱️', 'დაძინების დროა! ჩართეთ ძილის ტაიმერი, გააანალიზეთ ბავშვის რეჟიმი, რათა დარწმუნდეთ, რომ ძილის დღიურ ნორმას იცავს, და დაისვენეთ.'),
  ('ad033330-a436-4b30-84e7-2df370198c16', 'გონების განმავითარებელი სათამაშოს ძიება 🧩', 'უყვარს ფიგურების შესაბამის ჭრილებში ჩასმა? აღმოაჩინეთ ასაკის შესაბამისი ხის თავსატეხები (ფაზლები), რომლებიც მის გონებრივ უნარებს კიდევ უფრო განავითარებს, რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('0ac93f21-93e2-449d-b93b-ae00befc33f7', 'სიბნელის ეშინია? 🌌', 'ოთახში შუქის ჩაქრობისას შფოთავს? „თეთრ ხმებში“ ჩაურთეთ დედის საშვილოსნოს ხმა (გულისცემა) და სითბოსა და სიმშვიდის განცდა აჩუქეთ.'),
  ('5831d6e0-9735-485f-be90-56915bc7047f', 'ახლა თქვენი ჯერია 🥗', 'ბავშვს ჩაეძინა? სამზარეულოში გადაინაცვლეთ! ქალებისთვის განკუთვნილ ჯანსაღ რეცეპტებში აღმოაჩინეთ ცილებით მდიდარი სალათი ან დეტოქს-წყალი, რომელიც მყისიერად შეგმატებთ ენერგიას.'),
  ('5c1e8139-b38e-4666-8558-f6706af826d7', 'პატარა მხატვარი მუშაობს 🖍️', 'ჯღაბნა უყვარს? ტანსაცმელი საღებავით რომც დაესვაროს, ნუ გაბრაზდებით! ეს შემოქმედებითი წამი დაუყოვნებლივ დაამატეთ ბავშვის ალბომში და სამუდამო მოგონებად აქციეთ.'),
  ('04f3e5a5-25b9-471b-9c8e-e6c96050313b', 'იმუნიტეტის ფერადი ფარი 🛡️', 'კვების კონტროლის ხელსაწყოთი შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი C ვიტამინი. ფერადი ბოსტნეულის კერძების მოსამზადებლად ბავშვის რეცეპტებს მიმართეთ.'),
  ('41231bd2-e2dd-4432-bc31-3952982f012e', 'კბილები გაიხეხა? 🪥', 'კბილის ჯაგრისის დანახვისთანავე გარბის? რეკომენდებულ პროდუქტებში მოძებნეთ მუსიკალური ან თითზე ჩამოსაცმელი ჯაგრისები და ჰიგიენის ეს მნიშვნელოვანი პროცესი სახალისო თამაშად აქციეთ.'),
  ('9603c325-693c-472c-b02b-2c75bd255571', 'დღის გმირი თქვენ ხართ! 🌟', 'ყველა ჭირვეულობისა და დაღლილობის მიუხედავად, შესანიშნავი ხართ! გახსენით განწყობის დღიური და დღეს ისეთი ჩანაწერი გააკეთეთ, რომლისთვისაც საკუთარ თავს ფეხზე წამოუდგებით და ტაშს დაუკრავთ.'),
  ('d22a5573-d857-4918-90d2-9def6a084f6f', 'ტვინის დამშვიდების ხელოვნება 🎶', 'ზედმეტად ბევრი სტიმულის მიმღებ ბავშვს ღამით დაძინება უჭირს. ჩააბნელეთ ოთახი, თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ და ნელ-ნელა მოამზადეთ ბავშვი ღრმა ძილისთვის.'),
  ('fb035079-cf24-4146-9049-8d721e68f53f', 'საღებავებში ამოსვრილი ხელოვანი! 🎨', 'ხატვისას ტანსაცმელი საღებავებით დაისვარა? გაბრაზების ნაცვლად, გააფორმეთ ეს სახალისო მომენტი ბავშვის ფოტოსესიის მხიარული სტიკერებით და ატვირთეთ ალბომში.'),
  ('0b2c56b1-a7a8-4553-8880-13254eeb155b', 'ტანსაცმელი დაუმოკლდა? 📏', 'თუ შარვლის ტოტები დაუმოკლდა, ესე იგი, ბავშვს ზრდის ნახტომი აქვს! შეიყვანეთ მიმდინარე მონაცემები წონის ტრეკერში და სიამაყით ადევნეთ თვალი განვითარების გრაფიკის აღმასვლას.'),
  ('03d03133-0370-4630-9d2e-153f9459d86d', 'ყვირილით იღვიძებს?', 'ოთახში შუქის აუნთებლად, თეთრი ხმებიდან საშვილოსნოს ხმა ჩაურთეთ, რათა თავი უსაფრთხოდ იგრძნოს და კვლავ დაიძინოს.'),
  ('8ed6f8ef-f210-4aaa-96f8-4667b80d657e', 'ყველაფერზე „არა“! 🛑', 'თქვენს ყველა შეთავაზებას ეწინააღმდეგება? სიჯიუტესთან ბრძოლის ნაცვლად, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ შესთავაზოთ ბავშვს არჩევანი სწორად.'),
  ('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c', 'ღამით სითხის მიღება 🚰', 'თუ დილით საფენი ძალიან მძიმეა, შესაძლოა საღამოს წყლის მიღების დარეგულირება იყოს საჭირო. ჩაინიშნეთ საფენების ტრეკერში და გადახედეთ ყოველდღიურ სტატისტიკას.'),
  ('0b3896bc-de1d-4dd2-b68d-bd0aa3890750', 'დღის ძილი დიდხანს გრძელდება? ⏱️', 'საღამოს დაძინებას ეწინააღმდეგება? ჩართეთ ძილის ტაიმერი და თვალყური ადევნეთ განრიგს. იქნებ დღის ძილიდან ძალიან გვიან იღვიძებს?'),
  ('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d', 'კალციუმი და ძვლები 🦴', 'სწრაფი ფიზიკური განვითარება კალციუმს მოითხოვს. კვების მონიტორინგის ხელსაწყოთი გამოთვალეთ ყველისა და იოგურტის საჭირო რაოდენობა, ხოლო თუ საკმარისი არ არის, გაეცანით ბავშვის რეცეპტებს.'),
  ('c7f42861-81dc-4ed2-b93f-7c30709d92ed', 'თავს გამოფიტულად გრძნობთ? 🔋', 'ენერგია გამოგელიათ? ტკბილეულს ნუ მიეძალებით. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებით მოამზადეთ უშაქრო ენერგეტიკული ბურთულები, რომლებიც სწრაფად შეგმატებთ ძალას და ენერგიით დაგმუხტავთ.'),
  ('9f2ceaa6-0d99-46a0-884c-3460db78351b', 'ესმის თქვენი, მაგრამ არ ლაპარაკობს? 🧠', 'პასიური ლექსიკა აქტიურზე უფრო სწრაფად ვითარდება. ბლოგების განყოფილებაში აუცილებლად წაიკითხეთ სტატია სახლის თამაშების შესახებ, რომლებიც 20 თვის ბავშვის მეტყველების განვითარებას უწყობს ხელს.'),
  ('f641f443-9a8d-4060-a2b5-fe5d5562fa9d', 'საიდუმლო ვიტამინების ოპერაცია 🥕', 'მწვანილსა და ბოსტნეულს გვერდზე სწევს? ბავშვის რეცეპტებში შეიტყვეთ, როგორ ოსტატურად დამალოთ ისპანახი და სტაფილო გემრიელ ბლინებში.'),
  ('2ecfbac7-2e44-4661-8705-95fe2f59e9a9', 'თავი დაანებეთ სრულყოფილებისკენ სწრაფვას 🧘‍♀️', 'სახლი არეულია? არა უშავს! ჩაწერეთ თქვენი გრძნობები განწყობის დღიურში. გახსოვდეთ, ბედნიერი დედა იდეალურად მოწესრიგებულ სახლზე მნიშვნელოვანია.'),
  ('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1', 'თქვენც გჭირდებათ შესვენება ☕', 'გადით სახლიდან და ცოტა სუფთა ჰაერი ჩაისუნთქეთ! დედებისთვის მეგობრულ სივრცეებში იპოვეთ ახლომდებარე კაფე საბავშვო კუთხით და მშვიდად მიირთვით ცხელი ყავა.'),
  ('f9b61a4f-eba1-4cee-bf4a-958278a9300c', 'სახლის პატარა შეფ-მზარეული 👩‍🍳', 'სამზარეულოში გეხმარებათ და ქვაბებში ურევს? ფქვილში ამოსვრილი ამ სახალისო მომენტის ფოტო ბავშვის ფოტოსესიის შეფ-მზარეულის სტიკერებით გააფორმეთ.'),
  ('2c0cd78a-df37-49ab-8eae-44063551c7d9', 'ფაზლების ოსტატი 🧩', 'ფიგურების შესაბამის ადგილებზე მოთავსებას უკვე ოსტატურად ახერხებს? გონებრივი უნარების გასავითარებლად რეკომენდებულ პროდუქტებში აღმოაჩინეთ 21 თვის ბავშვებისთვის განკუთვნილი გეომეტრიული თავსატეხები.'),
  ('eeefba30-2a67-4d29-87df-2dbd7f03271f', 'წიგნების დახევის სურვილი 📖', 'კითხვის ნაცვლად წიგნის გვერდებს ხევს? ბლოგების განყოფილებაში ახლავე წაიკითხეთ, როგორ გაუმკლავდეთ ამ პრობლემას ისე, რომ ბავშვს კითხვისადმი ინტერესი არ დაუკარგოთ.'),
  ('f7f548f7-29ae-4098-8eb1-12f16f94c4b9', 'საკვებით თამაშის ეტაპი 🥣', 'კოვზს გვერდზე აგდებს და საკვებს ხელით ეხება? ჩართეთ კვების ტაიმერი, გააანალიზეთ მადის ცვლილებები და მოთმინებით მოეკიდეთ სენსორული განვითარების ამ ეტაპს.'),
  ('3512adbc-96b2-42e9-8a54-b673dc404876', 'საღამოს კისკისი 📸', 'არ გამოგრჩეთ ის სასაცილო მოძრაობა, რომელსაც ძილის წინ აკეთებს! მაშინვე გადაიღეთ ვიდეო, დაამატეთ ბავშვის ალბომში და დღის დაღლილობა ღიმილად აქციეთ.'),
  ('42cda594-bd4d-4a45-a1f6-1f894ad11fe7', 'ახალი სიტყვები მალე გაიჟღერებს! 🗣️', 'ბევრ ბგერას გამოსცემს, მაგრამ ჯერ სრულ სიტყვებს არ ამბობს? Anacan AI-სგან შეიტყვეთ ყველაზე ეფექტური სახლის თამაშებისა და მარცვლების სავარჯიშოების შესახებ, რომლებიც პასიური ლექსიკის გააქტიურებაში დაეხმარება.'),
  ('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54', 'ფეხსაცმელი დაუპატარავდა? 👟', 'ბოლო დროს სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! შეიყვანეთ მიმდინარე ზომები განვითარების ტრეკერში და თვალი ადევნეთ მის ზრდას.'),
  ('8ae66558-ee37-4cd1-9102-46bab1a97b21', '5-წუთიანი გემრიელობა! 🥗', 'შუადღისას სახელდახელოდ მიირთმევთ რამეს? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ავოკადოს ტოსტი, რომელიც დიდხანს დაგანაყრებთ და მყისიერად შეგმატებთ ენერგიას.'),
  ('a3eb6f02-e9da-422e-a243-1f395cf4661e', 'ძილის დრო იცვლება? ⏱️', 'საღამოს სიფხიზლის პერიოდი გახანგრძლივდა? ჩართეთ ძილის ტაიმერი, გააანალიზეთ გრაფიკი და ხელახლა გამოთვალეთ ძილის ფანჯრები.'),
  ('aac102d8-edd5-4708-bab2-8cf3fcc9802c', 'საჭმლის მონელება შენელდა? 🚽', 'დილით საფენის გამოცვლისას დააკვირდით ბავშვის განავალს. თუ ყაბზობა აქვს, არ დაგავიწყდეთ ამის აპში აღნიშვნა და მენიუში ბოჭკოვანი საკვების (მსხალი, შვრია) დამატება.'),
  ('4bdcd931-fb36-41ca-9759-7a92226d97f9', 'როგორ მივხვდეთ, რომ დანაყრდა? ⏱️', 'თუ საკვების გადაყრას ან გადმოფურთხებას იწყებს, ეს ნიშნავს, რომ დანაყრდა. გააჩერეთ კვების ტაიმერი, მონიშნეთ, რომ ნორმა შესრულებულია და გააანალიზეთ მისი მადა.'),
  ('be36c558-6f81-4ee5-9a59-f79497bbff2d', 'კბილების გახეხვის ომი 🪥', 'კბილის ჯაგრისის დანახვისთანავე გარბის? რეკომენდებული პროდუქტების განყოფილებაში შეარჩიეთ მუსიკალური ან თითზე ჩამოსაცმელი ჯაგრისი და ეს მნიშვნელოვანი ჰიგიენური პროცესი სახალისო თამაშად აქციეთ.'),
  ('cd9296b3-74e7-4229-8871-9f5ee4fe977a', 'დედის წყლის ბალანსი 💧', 'თავი გტკივათ? შესაძლოა, ბავშვის დევნაში წყლის დალევა დაგავიწყდათ. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებით მოამზადეთ დეტოქს-წყალი და ორგანიზმი გამოაცოცხლეთ.'),
  ('2fbfd933-5095-452a-808e-4209aab75b80', 'თქვენც გჭირდებათ ურთიერთობა 👯‍♀️', 'მხოლოდ ბავშვთან საუბრით დაიღალეთ? „დედების მეგობრულ სივრცეებში“ იპოვეთ ცენტრები, სადაც სათამაშო ჯგუფებია, და სხვა დედები გაიცანით.'),
  ('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc', 'პატარა მიმბაძველი 📱', 'თქვენსავით საუბრობს ტელეფონზე და თქვენს ჟესტებს იმეორებს? ბავშვები ჩვენი ყველაზე დიდი სარკეები არიან!'),
  ('bf157f3f-185f-45b5-aae0-091b2cf00653', 'ერთად, მაგრამ ცალ-ცალკე 👶', 'პარკში სხვა ბავშვებთან არ თამაშობს და მხოლოდ აკვირდება? ეს პარალელური თამაშია! ბლოგების განყოფილებაში გაეცანით საინტერესო ფაქტებს სოციალიზაციის ამ ეტაპის შესახებ.'),
  ('205f33e0-59b6-4cce-bdf2-72feb1805167', 'ჯანსაღი ტკბილეულის ძიებაში 🍪', 'უშაქრო, მაგრამ გემრიელი წასახემსებელი გჭირდებათ? ბავშვების რეცეპტებში აღმოაჩინეთ ბანანისა და ფინიკის ორცხობილები, რომლებიც სულ რაღაც 10 წუთში მზადდება.'),
  ('db60a4c8-3ab7-4727-9545-2ff3fea13946', 'ჯიუტი „არა“! 🛑', 'ყველაფერს აპროტესტებს და ყვირის? გაესაუბრეთ ჩვენს Anacan AI ასისტენტს 21-ე თვისთვის დამახასიათებელი სიჯიუტის შესახებ და ისწავლეთ ემოციური აფეთქებების მართვა.'),
  ('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36', 'მოდით, ძილის რეჟიმი შევამოწმოთ ⏱️', 'ღამით ხშირად იღვიძებს? გააანალიზეთ ძილის ტაიმერის გრაფიკი. შესაძლოა, დღის ძილი ოდნავ შეამციროთ, რათა საღამოსთვის უფრო დაღლილი იყოს.'),
  ('87662f03-ab51-47a9-bb0d-dc1172cdf859', 'ვიტამინების მარაგი 🥗', 'კვების კონტროლის ხელსაწყოს მეშვეობით გამოთვალეთ ვიტამინების დღევანდელი საჭიროება და დაგეგმეთ მენიუ. აუცილებლად შეამოწმეთ ომეგა-3-ისა და D ვიტამინის ბალანსი.'),
  ('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7', 'ლოგიკური სათამაშოები 🧩', 'ეს ასაკი ლოგიკური თამაშებისთვის იდეალური პერიოდია. რეკომენდებულ პროდუქტებში აღმოაჩინეთ ასაკის შესაბამისი ფაზლები და ფორმების დასახარისხებელი სათამაშოები და დაეხმარეთ ბავშვს აზროვნების განვითარებაში.'),
  ('b4b68202-2497-420c-9cf0-d0f43130a249', 'გული გადაშალეთ 📝', 'ყველა დღე იდეალური ვერ იქნება და ეს ნორმალურია. განწყობის დღიურში დაწერეთ, რა გაწუხებთ დღეს, გათავისუფლდით სტრესისგან და მშვიდად დაისვენეთ.'),
  ('6b045729-7aac-44f1-99aa-a2dbeb7985f2', 'სია სიცოცხლეს გიხსნით 🛒', 'მეხსიერებამ ისევ გიღალატათ? ნუ ეცდებით, გონებაში დაიმახსოვროთ სახლში გათავებული ყველა წვრილმანი — მაშინვე დაამატეთ საყიდლების სიაში და დანარჩენი თქვენს პარტნიორს მიანდეთ.'),
  ('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba', 'ბურთზე დარტყმა ⚽', 'ცდილობს, იატაკზე დაგორებულ ბურთს ფეხი დაარტყას? მისი წონასწორობა და ფეხების კოორდინაცია უმჯობესდება. ეთამაშეთ მარტივი პასების თამაში.'),
  ('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1', 'ჯადოსნური ფონი ძილისთვის 🪄', 'დაძინება უჭირს? ჭკვიან ზღაპრებში შექმენით ორიგინალური ზღაპარი და წაუკითხეთ.'),
  ('51155148-f9ec-40a7-99a1-3f09cffe59c1', 'მამის სათამაშო მოედანი 👨‍👧', 'მოთმინება ამოგეწურათ? ოთახის კარი დახურეთ და ბავშვი მამასთან მარტო დატოვეთ. დაე, ამ საღამოს ის იყოს სახლის სათამაშო მოედნის ხელმძღვანელი.'),
  ('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739', 'ტანსაცმლის არჩევის სიჯიუტე 👗', 'ზაფხულში სქელი სვიტერის, ზამთარში კი საზაფხულო მაისურის ჩაცმა სურს? მისი ნებისყოფა ყალიბდება. ორი შესაფერისი სამოსი დაუდეთ წინ და ჰკითხეთ: „რომელი გინდა?“ — არჩევანი მას მიანდეთ.'),
  ('c6ce4007-ba3b-4772-8fba-7c4797ad17dd', 'სუფთა ჰაერი წამალია 🌳', 'ბავშვი ძალიან მოუსვენარია და სახლში ვერ ჩერდება? შეამოწმეთ ამინდი, სათანადოდ ჩააცვით და დაუყოვნებლივ პარკისკენ გაეშურეთ. ბუნება მისთვის ყველაზე სწრაფი დამამშვიდებელი საშუალებაა.'),
  ('5bf406ee-d6c9-4691-8b5e-2df617ed2939', 'ბუნების აღმოჩენა 🌳', 'სახლის კედლებში ყოფნა მობეზრდა? „დედებისთვის მეგობრულ სივრცეებში“ იპოვეთ უსაფრთხო პარკი დიდი ქვიშის მოედნითა და საქანელებით და სუფთა ჰაერზე გაისეირნეთ.'),
  ('ad873c49-3118-429c-a9cf-3328699e514f', 'მაკარონის რბოლა! 🍝', 'არ სურს სასადილო მაგიდასთან ჯდომა? ბავშვების რეცეპტებში ფერადი, ბოსტნეულიანი მაკარონის იდეები დაათვალიერეთ და მისი ყურადღება კვლავ თეფშისკენ მიმართეთ.'),
  ('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42', 'ერთფეროვნების ძალა 🌬️', 'სიჩუმე აშინებს? ოთახში „თეთრი ხმებიდან“ ჩართეთ ფენის ან ვენტილატორის ხმა და ნახეთ, როგორ ქმნის ის ძილის გარემოში უსაფრთხოების განცდას.'),
  ('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5', 'შეაქეთ საკუთარი თავი! 🌟', 'დღეს შეძელით მისი ჩაცმა ისე, რომ არ ატირებულიყო? განწყობის დღიურში თქვენი უმცირესი წარმატებაც კი ჩაწერეთ და საკუთარ დედობრივ უნარებს ფეხზე წამოდგომით ტაში დაუკარით.'),
  ('5d85dda7-f62e-4490-8b4e-2ca037fd60ac', 'იმუნური ფარი 🛡️', 'მზად ხართ სეზონის ცვლილებისთვის? კვების კონტროლის ხელსაწყოთი შეამოწმეთ, მიიღეთ თუ არა დღეს საკმარისი C ვიტამინი, და განაახლეთ მენიუ.'),
  ('680f971c-231a-40e8-a772-413975915698', 'დარტყმა და ხელის კვრა 🛑', 'უეცრად გაბრაზებისას ხელს გირტყამთ ან ხელს გკრავთ? ჰკითხეთ Anacan AI-ს, როგორ გაუმკლავდეთ 21.5 თვის ასაკისთვის დამახასიათებელ ამ რთულ ქცევას თამაშის საშუალებით.'),
  ('9faf82e4-78ff-4782-a4bb-0d745a808c97', 'მწვანე ფერზე უარი 🥦', 'ბოსტნეულზე უარს ამბობს? დამატებითი კვების დაწყების ეტაპზე მყოფი ბავშვებისთვის განკუთვნილ რეცეპტებში აღმოაჩინეთ, როგორ დამალოთ ბოსტნეული გემრიელ ბლინებში.'),
  ('c2142ff9-9553-4737-9602-95ee907b4599', 'არ დანებდეთ დაღლილობას 🛋️', 'დღეს ყველაფრისთვის თავის დანებება მოგინდათ? ეს ნორმალურია! გახსენით განწყობის დღიური, დაწერეთ, რა გაწუხებთ და ეს საღამო მხოლოდ საკუთარ თავს დაუთმეთ.'),
  ('cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'საფენი მშრალი რჩება? 🧻', 'დილის შემოწმება! თუ საფენი დიდხანს მშრალი რჩება, ქოთანზე მიჩვევის დრო ახლოვდება. მონიშნეთ ეს საფენების ტრეკერში და შეამოწმეთ სტატისტიკა.'),
  ('53a89401-1ea0-43b5-9469-65a0d422f72c', 'დაუსრულებელი შოუ სუფრასთან 🥣', 'საჭმლით თამაშობს, იატაკზე ყრის, მაგრამ არ ჭამს. ჩართეთ კვების ტაიმერი და აპლიკაციაში მოცემული გრაფიკის დახმარებით ზუსტად გააანალიზეთ მადის ცვლილება.'),
  ('86da0f7a-f021-4c65-aed2-e8e15433a92d', 'ტრიალის სიყვარული 🌀', 'ბორბლებს ან თავსახურებს განუწყვეტლივ ატრიალებს? ბლოგებში წაიკითხეთ ამ სპეციფიკური მოტორული მოთხოვნილებისა და ბავშვის კოგნიტიურ განვითარებაში მისი როლის შესახებ.'),
  ('9ea6bc21-5003-4afe-8fca-e2eebb549250', 'ქვიშით თერაპია 🏖️', 'ნუ შეგეშინდებათ დასვრის! დედებისთვის მეგობრულ სივრცეებში იპოვეთ ადგილი, სადაც ქვიშის აუზია. ქვიშასთან შეხება შესანიშნავია სენსორული განვითარებისთვის.'),
  ('081299bb-b5c9-4af5-8361-9fa39bbdf0bf', 'შეკრულობის პრობლემა აქვს? 🚽', 'დილით საფენის გამოცვლისას დააკვირდით განავალს. თუ ბავშვს შეკრულობა აქვს, მონიშნეთ ეს აპლიკაციაში და დამატებითი კვების დაწყების შემდეგ რეცეპტებიდან შეარჩიეთ ბოჭკოვანი პროდუქტები (მსხალი, შვრია).'),
  ('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb', 'პატარა მხატვარი მუშაობს 🎨', 'ხატვისას საკუთარ თავსაც აფერადებს? უვნებელი, ადვილად ჩამოსარეცხი საღებავების შესარჩევად რეკომენდებულ პროდუქტებში ნახეთ, რას ირჩევენ დედები ყველაზე ხშირად.'),
  ('f9d59314-c8fe-45fa-9d77-efb82ec57626', 'საღამოს კისკისი 📸', 'არ გამოგრჩეთ ის სასაცილო მოძრაობა, რომელსაც ძილის წინ აკეთებს!'),
  ('3e9ffaf8-f631-4e99-946e-651b683eab7f', '„დედა, მოდი!“ წინადადებები 🗣️', 'უკვე ცდილობს ორი სიტყვის გაერთიანებას და წინადადების შედგენას? ეს მეტყველების განვითარებაში დიდი ნახტომია! განვითარების ტრეკერში სამახსოვროდ ჩაინიშნეთ მისი პირველი პატარა წინადადებები.'),
  ('473def83-9d3b-4698-becd-a16f81aed11d', 'ისტერიკა მაღაზიაში 🛒', 'იმიტომ, რომ მაღაზიაში სასურველი ნივთი არ უყიდეთ, ბავშვი იატაკზე გაწვა და ისტერიკა მოაწყო? ნუ აჰყვებით პანიკას. გარშემომყოფთა მზერას ყურადღებას ნუ მიაქცევთ, მშვიდად ჩაიმუხლეთ, რომ ბავშვის თვალების დონეზე აღმოჩნდეთ.'),
  ('fdbb311e-3b42-4723-986f-c65a632fb53e', 'მოიხსენით ემოციური ტვირთი 📝', 'რთული დღე გქონდათ? განიტვირთეთ და დღევანდელი სტრესის შესახებ ემოციების დღიურში დაწერეთ. ყველა დედა გადის ასეთ ემოციურ კრიზისებს — თქვენ მარტო არ ხართ.'),
  ('34d9fbb9-7747-4964-9067-399afa7f0a7c', 'ბუნებრივი დამამშვიდებელი 🍃', 'ბავშვს ჩაეძინა. დაივიწყეთ საოჯახო საქმეები! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მელისას ჩაი მოამზადეთ, დივანზე წამოწექით და უბრალოდ სიჩუმით დატკბით.'),
  ('e79393de-a250-4c25-b9a8-93a1bc3692aa', 'C ვიტამინის ფარი 🍊', 'იმუნიტეტი ძლიერი უნდა იყოს. კვების კონტროლის ხელსაწყოთი გამოთვალეთ, მიიღეთ თუ არა დღეს საკმარისი C ვიტამინი, და მენიუ გაამრავალფეროვნეთ.'),
  ('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7', 'ჩაცმის ომი 👗', '„ეს მაისური არ მინდა!“ — სიჯიუტე დაიწყო? დილის ჩაცმის კრიზისების შემცირებისა და ბავშვისთვის არჩევანის თავისუფლების მინიჭების გზები Anacan AI-სგან შეიტყვეთ.'),
  ('2a640acf-5bf6-44d4-b56f-00e902c2ddd2', 'დამოუკიდებლობის ძიება 🥣', 'კოვზს არ გაძლევთ? ჩართეთ კვების ტაიმერი და გააანალიზეთ, რამდენ ხანს გრძელდება დამოუკიდებლობის ეს გამოცდა. დაყრილ საკვებს კი უბრალოდ ღიმილით შეხედეთ.'),
  ('cb94164a-0ea2-471c-9c17-a09778ea707c', 'განშორების შიში? 🌌', 'ოთახიდან გასვლისთანავე თქვენს კვალდაკვალ ტირის? თეთრი ხმებიდან ჩაურთეთ საშვილოსნოში მოსმენილი ხმა (გულისცემა) და ძველი, თბილი უსაფრთხოების განცდა დაუბრუნეთ.'),
  ('d3ae908a-552f-4504-a171-436173eaeceb', 'კბილების გახეხვის ომი 🪥', 'ჯაგრისის დანახვისთანავე პირს მაგრად კეტავს? რეკომენდებულ პროდუქტებში შეარჩიეთ მუსიკალური ან თითზე ჩამოსაცმელი ჯაგრისი და ჰიგიენის ეს რუტინა სახალისო თამაშად აქციეთ.'),
  ('4932b8a8-d024-498c-ba06-d790b59bc198', 'იყავით საკუთარი თავის მიმართ კეთილი 🧘‍♀️', 'დღეს ყველაფერი უკუღმა წავიდა? განწყობის დღიურში ჩაწერეთ თქვენი შინაგანი ხმა, აპატიეთ საკუთარ თავს, ღრმად ჩაისუნთქეთ და დაისვენეთ.'),
  ('ed014436-2469-48a6-b579-7bce93de1ae7', 'სიტყვების მარაგი იზრდება 🗣️', 'უფრო ხშირად იყენებს ორსიტყვიან წინადადებებს? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ შეუწყოთ ხელი მის ამ შესანიშნავ ენობრივ განვითარებას და როგორ წარმართოთ დიალოგი.'),
  ('ed579060-f78c-4890-b8e4-2bb0c7729792', 'განავლის ფერი 💩', 'ჩაინიშნეთ საფენის გამოცვლისას! სითხისა და ბოჭკოს ბალანსის კონტროლით შეკრულობის თავიდან ასაცილებლად გამოიყენეთ კვების მონიტორინგის ხელსაწყო.'),
  ('15f9bb81-a16f-4753-a3f5-a2b604b16a46', 'ძილი სუფთა ჰაერზე 🌳', 'სახლში ვერ იძინებს? დედებისთვის მეგობრულ ადგილებს შორის იპოვეთ მშვიდი, ხეებით დაფარული პარკი. სუფთა ჰაერი მას მადასაც გაუუმჯობესებს და ძილსაც.'),
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031', 'ღამით გაღვიძება ⏱️', 'ჩართეთ ძილის ტაიმერი! ტაიმერის სტატისტიკური გრაფიკის საშუალებით სწრაფად გააანალიზეთ, ხომ არ აქვს ბავშვს ღამის ტერორი ან ძილის რეგრესია.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'რკინის საჭიროება 🥩', 'მიაწოდეთ ენერგია მის აქტიურ კუნთებს! კვების მონიტორინგის ხელსაწყოთი შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი რკინა, და შესაბამისად შეუცვალეთ მენიუ.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'სიცილის ხმა 📸', 'სახეს ჭმუხნის თუ გიყურებთ და ხმამაღლა იცინის? გააფორმეთ ეს ტკბილი წამი ბავშვის ფოტოსესიის სტიკერებით და დაამატეთ ალბომში სამუდამო მოგონებად.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'ერთფეროვანი ხმის ძალა 🎶', 'ხმაურიანი დღის შემდეგ მოულოდნელი სიჩუმე ბავშვს აშინებს. ჩართეთ ფენის ხმა „თეთრი ხმების“ განყოფილებიდან და ძილის გარემოში უსაფრთხოების განცდა შეუქმენით.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'დედის ელემენტი 🔋', 'ენერგია გამოგელიათ? ტკბილეულს ნუ მიეძალებით! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ცილებით მდიდარი, არაქისის კარაქიანი სმუზი, რომელიც სწრაფად შეგმატებთ ძალას.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'ტანსაცმელი ისევ უვიწროვდება? 📏', 'ბავშვს ფიზიკური ზრდის ნახტომი აქვს! შეიყვანეთ მისი ამჟამინდელი სიმაღლე და ფეხსაცმლის ზომა განვითარების მონიტორინგის განყოფილებაში და სიამაყით დააკვირდით, როგორ მიიწევს ზრდის მრუდი ზემოთ.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'ლოგიკის ძიებაში 🧩', 'ერთნაირი სათამაშოები მობეზრდა? რეკომენდებული პროდუქტების განყოფილებაში აღმოაჩინეთ ბავშვის ასაკის შესაბამისი, უსაფრთხო ფაზლები, რომლებიც მის აზროვნებას განავითარებს.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'მოულოდნელად დარტყმა და კბენა 🦖', 'გაბრაზებისას აგრესიული ხდება? Anacan AI-ის დახმარებით გაიგეთ, როგორ აქციოთ ეს ქცევა თამაშად და ნაზად შეცვალოთ.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'ბოსტნეულთან დამალობანა 🥕', 'სტაფილოსა და ისპანახზე უარს ამბობს? ბავშვის რეცეპტებში აღმოაჩინეთ, როგორ შეიძლება ამ ვიტამინების გემრიელ ბლინებში ოსტატურად დამალვა.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'თავს ნუ დაიდანაშაულებთ 💖', 'დღეს ხმას აუწიეთ? თავს ნუ გაკიცხავთ. ჩაწერეთ თქვენი გრძნობები განწყობის დღიურში — თქვენ მისთვის მაინც საუკეთესო დედა ხართ.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'დაუსრულებელი სანახაობა სუფრასთან ⏱️', 'საჭმლით თამაშობს, მაგრამ არ ჭამს? ჩართეთ კვების ტაიმერი, აკონტროლეთ პროცესის ხანგრძლივობა და ზუსტად გააანალიზეთ მადის ცვლილებები.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'დღის გმირი თქვენ ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ის ყოველდღიურად სწავლობს, თქვენი შრომის შედეგია. გახსენით განწყობის დღიური და დღეს საკუთარი თავისთვის მქუხარე აპლოდისმენტების ღირსი ჩანაწერი გააკეთეთ!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'ერთად, მაგრამ ცალ-ცალკე 👶', 'პარკში სხვა ბავშვებთან არ თამაშობს და მხოლოდ აკვირდება? ეს პარალელური თამაშია! ბლოგების განყოფილებაში წაიკითხეთ სოციალიზაციის ამ ჯანსაღი ეტაპის შესახებ.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'უშაქრო წასახემსებელი 🍪', 'მაღაზიის ორცხობილები საჭირო არ არის. ბავშვის რეცეპტებში აღმოაჩინეთ ფინიკისა და ვაშლის სასარგებლო ტკბილეული, რომელიც სახლში სულ რაღაც 10 წუთში მზადდება.'),
  ('02902252-366d-405a-a62b-9c6f129b4a84', 'როგორ ვითარდება ინტელექტი? 🧠', 'ბლოგების განყოფილებაში აუცილებლად წაიკითხეთ სტატია სახლის თამაშების შესახებ, რომლებიც 21.5 თვის ბავშვებს ფერებისა და ფორმების აღქმას უვითარებს და ტვინის მუშაობას ასტიმულირებს.'),
  ('08bbbba1-9e53-4379-a09e-82d1079f7df6', 'რკინის მარაგის შემოწმება 🥩', 'აქტიური კუნთებისთვის ანემია დაუშვებელია. კვების კონტროლის ხელსაწყოთი შეამოწმეთ, მიიღეთ თუ არა დღეს საკმარისი რკინა, და დანაკლისი დაუყოვნებლივ შეავსეთ.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'ღამით საფენი ივსება? 🧻', 'თუ დილით საფენი ძალიან მძიმეა, ამან შესაძლოა ღამის ძილი დაარღვიოს. საფენების ტრეკერში მონიშნეთ გამონაყოფი და გააანალიზეთ სტატისტიკა, რათა საღამოს სითხის მიღება დაარეგულიროთ.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'პატარა მკვლევარი სამზარეულოში 🥦', 'მასაც სურს თქვენთან ერთად მომზადება? თუ ბავშვმა დამატებითი კვება უკვე დაიწყო, რეცეპტებში აღმოაჩინეთ მარტივი, ბოსტნეულიანი და გემრიელი კექსების რეცეპტები, რომელთა მომზადებაც ერთად შეგიძლიათ.'),
  ('e02612f3-415f-450d-9411-e60c3bd32d09', 'სიჩუმის ხმა 🌧️', 'ზედმეტად აქტიური დღის შემდეგ ტვინს განტვირთვა სჭირდება. ოთახში თეთრი ხმებიდან წვიმის ხმა ჩართეთ და ძილისთვის ბუნებრივად მშვიდი გარემო შექმენით.'),
  ('3dca59c4-0add-4ccb-919d-3806c0dfdbf4', 'ბუნებრივი დამამშვიდებელი 🍃', 'ჭირვეულობითა და ხმაურით სავსე დღე გქონდათ? თეთრი ხმებიდან ფოთლების შრიალი ჩართეთ და როგორც ბავშვის, ისე თქვენი ნერვული სისტემა დაამშვიდეთ.'),
  ('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8', '5-წუთიანი ენერგია ⚡', 'დილითვე ნუ გადაეშვებით საოჯახო საქმეებში. ჯანსაღი რეცეპტებიდან მოამზადეთ ანტიოქსიდანტებით მდიდარი შვრიის ფაფა კენკრით და ორგანიზმი ენერგიით შეავსეთ.'),
  ('e5117ef0-d242-45f1-b114-50b3bfca72d9', 'თქვენც გჭირდებათ საზოგადოება ☕', 'მხოლოდ ბავშვთან საუბრით დაიღალეთ? დედებისთვის მეგობრულ ადგილებში იპოვეთ საბავშვო კაფეები, სადაც ბევრი დედა იკრიბება, და ახალი ნაცნობები გაიჩინეთ.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('cd9b8bec-56d4-42a3-a245-f71b148a61ef'::uuid, 'ხმიდან სიჩუმეზე გადასვლა 🎶', 'ხმაურიანი თამაშების შემდეგ უეცარი სიჩუმე ბავშვს აშინებს. ოთახში „თეთრი ხმებიდან“ ფენის ხმა ჩართეთ და ნახეთ, როგორ დადებითად მოქმედებს მონოტონური ხმა ძილზე.'),
  ('54f26234-4c50-45b3-9088-6a5b0c08fcd2', 'დედის წყლის ბალანსი 💧', 'თავი გტკივათ? ბავშვზე ზრუნვაში შეიძლება წყლის დალევა დაგავიწყდათ და გაუწყლოება დაგეწყოთ. მოამზადეთ დეტოქს-წყლები ჯანსაღი რეცეპტებით და ორგანიზმი გამოაცოცხლეთ.'),
  ('a27861d3-4efc-4b58-bec5-f3117fe589e3', 'დახარისხების თამაშები 🔴🔵', 'უყვარს წითელი ნივთების ერთ მხარეს, ლურჯების კი მეორე მხარეს შეგროვება? ლოგიკური აზროვნების განვითარება კიდევ უფრო სახალისო რომ გახადოთ, თამაშების იდეები Anacan AI-ს ჰკითხეთ.'),
  ('622216cc-100d-4e85-95dc-7d70e41c5761', 'თავად ჭამა სურს 🥣', 'კოვზს არ გაძლევთ? ჩართეთ კვების ტაიმერი და გააანალიზეთ, რამდენი დრო სჭირდება დამოუკიდებლად ჭამის ამ მცდელობას. დაყრილ საკვებს კი უბრალოდ ღიმილით შეხედეთ.'),
  ('9387504c-dde1-4fdb-977d-53c3dfbb83a2', 'უსაფრთხო აღმოჩენები ⚠️', 'კარადები, უჯრები... პატარა მკვლევრისთვის სახიფათოა! რეკომენდებულ პროდუქტებში ავეჯის დამცავებსა და უსაფრთხოების საკეტებს გაეცანით.'),
  ('bdef77ef-7476-4b14-a4a3-51d31635951f', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს სიფხიზლის პერიოდი ზედმეტად გახანგრძლივდა? ჩართეთ ძილის ტაიმერი. შესაძლოა, სწორედ ახლაა დრო, დღის ძილი 15 წუთით შეამციროთ.'),
  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'დედის წელის ტკივილი 🧘‍♀️', 'ბავშვის ხელში აყვანისგან წელი გტკივათ? იზრუნეთ საკუთარ სხეულზე — ჯანსაღი რეცეპტებიდან მოამზადეთ ანთების საწინააღმდეგო და აღმდგენი მწვანე ჩაი ჯანჯაფილით.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'არასწორი ჭიქის გამო ჩხუბი? 🥤', 'იმიტომ ატყდა ერთი ამბავი, რომ წყალი წითელი ჭიქის ნაცვლად ლურჯით მიაწოდეთ? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ გაუმკლავდეთ სიმშვიდით ამ ერთი შეხედვით აბსურდულ კრიზისებს.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'გულიდან გადმოიღეთ 📝', 'დღეს ბავშვი გაუჩერებლად ტიროდა და თქვენ ძალიან დაიღალეთ. თავს ნუ დაიდანაშაულებთ. მთელი თქვენი დაღლილობის შესახებ განწყობის დღიურში დაწერეთ, გონება განიტვირთეთ და დაისვენეთ.'),
  ('d5617275-bfe2-4829-8f3f-d3b94dc34cfe', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს ფხიზლად ყოფნის პერიოდი ზედმეტად ხომ არ გახანგრძლივდა? ჩართეთ ძილის ტაიმერი და დააკვირდით გრაფიკს. შესაძლოა, სწორედ ახლაა დღის ძილის 15 წუთით შემცირების დრო.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'ზღაპარი თავად მოყვეს 📖', 'წიგნში სურათებს უყურებს და თავის ენაზე რაღაცებს ჰყვება? ეს საოცარი წარმოსახვის მომენტი დაუყოვნებლივ ხმიან ვიდეოდ დაამატეთ ბავშვის ალბომში და მომავლისთვის შეინახეთ.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'ოთხ კედელს გაექეცით 🌳', 'სახლში ენერგიას ვერ ხარჯავს და ყველაფერს თავდაყირა აყენებს? გახსენით დედებისთვის მეგობრული ადგილების რუკა, იპოვეთ პარკი, სადაც უსაფრთხოდ სირბილს შეძლებს, და სუფთა ჰაერზე გაიყვანეთ.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'გაზიარება არ სურს? 🧸', 'პარკში სათამაშოს არავის აძლევს? ბლოგების განყოფილებაში აუცილებლად წაიკითხეთ პრაქტიკული სტატია, რომელიც გასწავლით, როგორ აუხსნათ 22 თვის ბავშვს რიგრიგობით თამაში.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'კალციუმის ფარი 🦴', 'კალციუმი აუცილებელია ძვლებისა და კბილებისთვის. კვების კონტროლის ხელსაწყოთი გადაამოწმეთ, მიიღო თუ არა ბავშვმა დღეს იოგურტისა და ყველის საჭირო ულუფა.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'ფეხსაცმელი უჭერს? 📏', 'ბოლო დროს სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! წონის ტრეკერში შეიყვანეთ მიმდინარე სიმაღლე და ზომები, რათა მის ფიზიკურ განვითარებას თვალყური ადევნოთ.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'საჭმელს იატაკზე ყრის? 🥣', 'თუ კოვზისა და საჭმლის მაგიდიდან გადაყრა დაიწყო, შესაძლოა დანაყრდა ან მოიწყინა. გააჩერეთ კვების ტაიმერი, გრაფიკის მეშვეობით გააანალიზეთ მადის ცვლილება და კვება დაასრულეთ.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'უსაფრთხოების განცდა 🌌', 'ოთახში შუქის ჩაქრობისას ეშინია? თეთრი ხმებიდან ჩართეთ დედის საშვილოსნოში გაგონილი ხმა (გულისცემა), რათა ბავშვს ძველი, თბილი უსაფრთხოების განცდა დაუბრუნოთ და დასაძინებლად განაწყოთ.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'თქვენც გჭირდებათ ურთიერთობა ☕', 'მხოლოდ ბავშვთან საუბრით დაიღალეთ? „დედების მეგობრული სივრცეების“ მეშვეობით იპოვეთ საბავშვო კაფეები, სადაც ბევრი დედა იკრიბება, და თქვენთვისაც შექმენით ახალი გარემო.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'დარტყმა ან ხელის კვრა 🛑', 'გაბრაზებისას მოულოდნელად ხელს ურტყამს? მიმართეთ Anacan AI-ს და გაიგეთ, როგორ გარდაქმნათ ამ ასაკისთვის დამახასიათებელი აგრესიული ემოციები თამაშად და ნაზად შეცვალოთ ბავშვის ქცევა.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'ლოგიკური ნახტომი 🧩', 'ბავშვი მიზეზშედეგობრივი კავშირების დამყარებას იწყებს. ბლოგების განყოფილებაში გაეცანით და გამოსცადეთ საუკეთესო საშინაო თამაშები, რომლებიც 22 თვის ბავშვების კოგნიტიურ განვითარებას აჩქარებს.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს ფხიზლად ყოფნის დრო ზედმეტად გახანგრძლივდა? ჩართეთ ძილის ტაიმერი და დააკვირდით განრიგს. შესაძლოა, სწორედ ახლაა დღის ძილის 15 წუთით შემცირების დრო.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'რკინის მარაგის შემოწმება 🥩', 'კუნთების აქტიური მუშაობისთვის მნიშვნელოვანია, ბავშვს ანემია არ ჰქონდეს. კვების კონტროლის ხელსაწყოთი შეამოწმეთ, რამდენი რკინა მიიღო დღეს, და დანაკლისი დაუყოვნებლივ შეავსეთ.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'უშაქრო წასახემსებელი 🍪', 'მაღაზიის ორცხობილები აღარ დაგჭირდებათ. ბავშვის რეცეპტებში აღმოაჩინეთ ფინიკისა და ვაშლის ჯანსაღი ტკბილეული, რომელსაც სახლში სულ რაღაც 10 წუთში მოამზადებთ, და ბავშვს მადა გაუღვიძეთ.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'ზრდის ნახტომი! 📏', 'პერანგების სახელოები ისევ დაუმოკლდა? ფიზიკური განვითარება ჩქარდება. განვითარების ტრეკერში შეიყვანეთ მიმდინარე მონაცემები და სიამაყით გადახედეთ ზრდის გრაფიკს.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'ახალი სიტყვები მოდის! 🗣️', 'ბევრ ბგერას გამოსცემს, მაგრამ ჯერ სრულ სიტყვებს ვერ ამბობს? პასიური ლექსიკის გასააქტიურებლად ბავშვის ალბომში აუდიოჩანაწერის სახით დაამატეთ და თვალი ადევნეთ მის სახალისო მცდელობებს, წარმოთქვას მარცვლები.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'პატარა დამხმარე 🧹', 'მას უკვე სურს საოჯახო საქმეებში მონაწილეობა. ბლოგების განყოფილებაში წაიკითხეთ, როგორ განუვითაროთ 22.5 თვის ბავშვს პასუხისმგებლობის გრძნობა თამაშის მეშვეობით, და რჩევები პრაქტიკაში გამოიყენეთ.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'ფანტაზიას საზღვრები არ აქვს 🧸', 'დათუნიას აჭმევს თუ თქვენ გკურნალობთ? ბავშვის ალბომში მოკლე ვიდეოს სახით დაამატეთ ემპათიის განვითარების ეს მომენტი და სამუდამო მოგონებად აქციეთ.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'უსაფრთხო აღმოჩენები ⚠️', 'კარადები, უჯრები... პატარა მკვლევრისთვის ისინი სახიფათოა! რეკომენდებული პროდუქტების განყოფილებაში აუცილებლად გაეცანით ავეჯის დამცავებსა და უსაფრთხოების საკეტებს.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'ხელოვნების ნიმუში კედელზე 🎨', 'ფანქარი აიღო და კედელი მოხატა? ნუ გაბრაზდებით! ეს საყვარელი ცელქობა ბავშვის ფოტოსესიის სახალისო ჩარჩოებით ალბომში დაამატეთ და უბრალოდ გაიღიმეთ.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'უეცარი გამოღვიძებები დაბრუნდა? ⏱️', 'შუაღამისას ტირილით იღვიძებს? გადახედეთ ძილის ტაიმერის გრაფიკს. თუ დღის ძილი ძალიან გვიან სრულდება, საღამოს ღრმა ძილში გადასვლა რთულდება.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'დედის ყავის შესვენება ☕', 'საკუთარი თავი არ დაგავიწყდეთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ენერგიის მომცემი შვრიის წასახემსებელი და მიირთვით ყავა სიამოვნებით.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'როგორ ავირჩიოთ სწორი ქოთანი 🚽', 'დაიწყეთ ტუალეტის ჩვევის გამომუშავებისთვის ვიზუალური მომზადება! აუცილებლად გადახედეთ რეკომენდებულ პროდუქტებში დედების მიერ გამოცდილი ყველაზე კომფორტული და მიმზიდველი ქოთნების მოდელებს.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'როგორია ომეგა-3-ის მარაგი? 🐟', 'ტვინის სწრაფი განვითარებისთვის თევზი ან ნიგოზი აუცილებელია! კვების კონტროლის ხელსაწყოთი შეამოწმეთ ამ კვირაში მიღებული ომეგა-3-ის რაოდენობა და მენიუ დაუყოვნებლივ განაახლეთ.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'სრულყოფილება აუცილებელი არ არის 💖', 'დღეს სახლში არეულობაა და საჭმლის მომზადებაც დაგაგვიანდათ? არა უშავს! ჩაწერეთ თქვენი შინაგანი ხმა განწყობის დღიურში და გახსოვდეთ, რომ თქვენს შვილს ყველანაირი უყვარხართ.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'ბევრი წყალი, მარტივი მონელება 💧', 'როგორ მუშაობს აქტიური ბავშვის ნაწლავები? საფენის გამოცვლისას შეიტანეთ ჩანაწერები. თუ ყაბზობის რისკია, აპში გაეცანით ბუნებრივი ბოჭკოთი მდიდარი საკვების რეკომენდაციებს.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'საჭმელთან ბრძოლა დასრულდა ⏱️', 'მაგიდასთან კოვზს გვერდზე აგდებს? შეაჩერეთ კვების ტაიმერი — ბავშვი დანაყრდა. მადის გრაფიკის გაანალიზებით, თავიდან აიცილეთ ძალით კვება.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'სხვა დედების გაცნობა 👯‍♀️', 'ბავშვმაც ითამაშოს და თქვენც ისაუბროთ! დედებისთვის მეგობრული ადგილების რუკაზე იპოვეთ ცენტრი, სადაც სათამაშო ჯგუფებია, და გადით სახლიდან.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'კბილები გაიხეხა? 🪥', 'ჯაგრისის დანახვისთანავე პირს მჭიდროდ კეტავს? Anacan AI-სგან მიიღეთ პრაქტიკული რჩევები, რათა გაიგოთ, როგორ აქციოთ ეს ჰიგიენური რუტინა სახალისო თამაშად.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'ბუნებრივი დამამშვიდებელი 🍃', 'ძალიან ხმაურიანი დღე იყო? ტაიმერი გაჩერდა. დაივიწყეთ საოჯახო საქმეები, ჯანსაღი რეცეპტებიდან მოამზადეთ მელისას ჩაი და უბრალოდ დატკბით სიმშვიდით.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'ჯანსაღი ტკბილეულის ძიება 🍎', 'მაღაზიის ორცხობილებს დაემშვიდობეთ! ბავშვის რეცეპტებში აღმოაჩინეთ ფინიკისა და ვაშლის სასარგებლო ორცხობილები, რომლებიც სახლში 10 წუთში მზადდება, და ბავშვს მადა გაუღვიძეთ.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'განშორების შიში ბრუნდება? 🌌', 'ოთახიდან გასვლისთანავე უკან მოგყვებათ და ტირის? „თეთრი ხმების“ ფუნქციაში გულისცემის ხმა ჩართეთ, რათა ბავშვს უსაფრთხოების განცდა შეუქმნათ და ძილისთვის განაწყოთ.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'შარვლები ისევ დაუმოკლდა! 📏', 'პერანგების სახელოებიც დაუმოკლდა? ბავშვს ფიზიკური ზრდის ნახტომი აქვს. შეიყვანეთ მიმდინარე მონაცემები წონის მონიტორში და სიამაყით გადახედეთ ზრდის გრაფიკს.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'სასაცილო გამოთქმები 🗣️', 'ზოგიერთ სიტყვას ისე ტკბილად და არასწორად წარმოთქვამს! არ გამოტოვოთ ეს ძვირფასი მომენტები. ატვირთეთ ისინი ბავშვის ალბომში ხმიან ვიდეოებად, რათა მომავალში ერთად იცინოთ.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'ცილის მარაგი როგორია? 🍗', 'აქტიური კუნთებისთვის ცილა აუცილებელია. კვების კონტროლის ხელსაწყოთი შეაფასეთ ბავშვის ყოველდღიური კვების ბალანსი და გაამდიდრეთ მისი მენიუ.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'ამას მე თვითონ გავაკეთებ! 👕', 'დილაობით ჩაცმა დიდ კრიზისად იქცევა? სიჯიუტესთან გამკლავებისა და ბავშვისთვის არჩევანის უფლების მიცემის საიდუმლოებები ახლავე შეიტყვეთ Anacan AI-ისგან.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'წიგნი წასაკითხადაა და არა დასახევად 📖', 'საღამოს ზღაპრის კითხვისას ფურცლებს ხევს? ბლოგების განყოფილებაში ახლავე წაიკითხეთ, როგორ მოაგვაროთ ეს პრობლემა ისე, რომ კითხვის ჩვევის ჩამოყალიბებას ხელი არ შეუშალოთ.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს სიფხიზლის პერიოდი ძალიან ხომ არ გახანგრძლივდა? ჩართეთ ძილის ტაიმერი და დააკვირდით განრიგს. იქნებ სწორედ ახლაა დღის ძილის 15 წუთით შემცირების დრო.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'ქვიშისა და ტალახის თერაპია 🏖️', 'დასვრის ნუ შეგეშინდებათ! კინეტიკური ქვიშისა და სენსორული თამაშებისთვის საუკეთესო საშუალებები ახლავე აღმოაჩინეთ რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'ეს თქვენი შრომის შედეგია 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღე ითვისებს, და ყოველი თავდაჯერებული ნაბიჯი თქვენი შრომის შედეგია. გახსენით განწყობის დღიური და დღეს ჩაწერეთ, რატომ ამაყობთ საკუთარი თავით!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'დღეს რამდენჯერ თქვით „არა“? 💆‍♀️', 'ძალიან დაიღალეთ, არა? ღრმად ჩაისუნთქეთ. განწყობის დღიურში გადმოიტანეთ ყველა თქვენი გრძნობა, დანაშაულის განცდა გვერდზე გადადეთ და უბრალოდ დაისვენეთ.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'მშრალი საფენით გაიღვიძა? 🩲', 'დილით საფენის გამოცვლისას შენიშნეთ, რომ ის მშრალი იყო? ქოთანზე მიჩვევის დასაწყებად საუკეთესო დროისა და ფსიქოლოგიური მეთოდების შესახებ ახლავე ჰკითხეთ Anacan AI-ს.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'კექსის სიყვარული 🧁', 'ტკბილეული მოუნდა? მაღაზიაში ნუ გაიქცევით. ბავშვის რეცეპტებში მოამზადეთ უშაქრო, ბანანისა და შვრიის 10-წუთიანი შინაური კექსი და კვების კონტროლის ხელსაწყოში ჯანმრთელობის ქულა შეინარჩუნეთ.'),
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182', '5-წუთიანი ენერგია ⚡', 'დილითვე ნუ შეუდგებით სახლის საქმეებს. მოამზადეთ კენკროვანი შვრიის ფაფა — ანტიოქსიდანტებით მდიდარი კერძი ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან — და ორგანიზმი ენერგიით შეივსეთ.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'ჩაცმის ომი! 👗', 'დილაობით ჩაცმა დიდ კრიზისად იქცევა? შესთავაზეთ ორი სხვადასხვა მაისური და არჩევანის თავისუფლება მიეცით.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'თვალებს იფშვნეტს? 🥱', 'ძილის ნიშნები გამოჩნდა! ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან ტყის შრიალი შეარჩიეთ, მშვიდად განაწყვეთ ბავშვი დასაძინებლად და თვალი ადევნეთ განრიგს.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'დედის ყავის დრო ☕', 'ახლა შესვენების დროა. სანამ ბავშვი დამოუკიდებლად თამაშობს, ენერგია აღიდგინეთ ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან ანტიოქსიდანტებით მდიდარი მწვანე ჩაით ან მსუბუქი ყავით.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'სახლში კედლებზე აძვრება? 🧗', 'მას ენერგიის დახარჯვა სჭირდება! გახსენით დედებისთვის მოსახერხებელი ადგილების რუკა, აღმოაჩინეთ ახალი პარკი უსაფრთხო სარბენი სივრცითა და სასრიალოთი და მიეცით ბავშვს თავისუფლად თამაშის საშუალება.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'სუფრიდან გარბის! 🏃‍♂️', 'ჭამას შუაში ტოვებს და გარბის? გააჩერეთ კვების ტაიმერი. იძულებით კვების ნაცვლად, ბლოგების განყოფილებაში წაიკითხეთ, როგორ გაუღვივოთ ბავშვს მადა ბუნებრივი გზით.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'ფეხსაცმელი რატომ უჭერს? 👟', 'სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! შეიყვანეთ მიმდინარე ზომები განვითარების ტრეკერში, დაუყოვნებლივ შეამოწმეთ ზრდის ნახტომი და გააანალიზეთ ბავშვის ზრდა.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'ღამით გაღვიძებები ⏱️', 'ჩართეთ ძილის ტაიმერი! ტაიმერის სტატისტიკური გრაფიკის დახმარებით ზუსტად გააანალიზეთ, ღამის ტერორთან გაქვთ საქმე თუ ძილის რეგრესიასთან, და რეჟიმი შესაბამისად მოარგეთ.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'გონებრივი განვითარება არ ჩერდება 🧠', 'მას ყველაფრის დახარისხება უყვარს! რეკომენდებულ პროდუქტებში ახლავე აღმოაჩინეთ გეომეტრიული თავსატეხები (ფაზლები), რომლებიც ფერისა და ფორმის აღქმას აუმჯობესებს და ტვინის მუშაობას ასტიმულირებს.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'დღის გმირი თქვენ ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღე ითვისებს, თქვენი შრომის შედეგია. გახსენით განწყობის დღიური და დღეს ჩაწერეთ ისეთი რამ, რის გამოც საკუთარ თავს ფეხზე წამოდგომით ტაშს დაუკრავთ!'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'ფიგურებს სწორად არჩევს? 🧩', 'ლოგიკური აზროვნების განვითარების ხელშესაწყობად, ასაკის შესაბამისი გეომეტრიული ფაზლები და შემეცნებითი ხის სათამაშოები ახლავე მოძებნეთ რეკომენდებულ პროდუქტებში.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'ცილების მარაგი როგორია? 🥚', 'სწრაფად მზარდი კუნთებისთვის ცილა აუცილებელია. კვების კონტროლის ხელსაწყოთი გამოთვალეთ დღევანდელი ნორმა და დეფიციტის შემთხვევაში მენიუ შეასწორეთ.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'პირველი სერიოზული საუბრები 🗣️', 'თავის ენაზე დიდხანს გესაუბრებათ და რაღაცებს განიხილავს? ეს სახალისო და ძვირფასი მომენტი ხმიანი ვიდეოს სახით ბავშვის ალბომში შეინახეთ.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'უეცარი ყვირილი! 🛑', 'როცა სასურველს ვერ იღებს, იატაკზე ეცემა? ჰკითხეთ ჩვენს ექსპერტ დამხმარეს, Anacan AI-ს, როგორ აქციოთ თამაშად ეს ემოციური აფეთქებები, რომლებიც 23-ე თვისკენ ხშირდება.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'წყლის დალევა არ დაავიწყდეს 💧', 'როგორ მუშაობს აქტიური პატარას ნაწლავები? საფენის გამოცვლისას გამონაყოფი აღრიცხეთ. თუ ყაბზობის რისკი არსებობს, აუცილებლად გაეცანით აპლიკაციაში ბოჭკოთი ბუნებრივად მდიდარი საკვების რეკომენდაციებს.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'სიბნელის ეშინია? 🌌', 'ოთახში შუქის ჩაქრობისას ტირის? თეთრი ხმებიდან ჩაურთეთ დედის საშვილოსნოს ხმა (გულისცემა) და კვლავ აგრძნობინეთ მისთვის ნაცნობი, სრულყოფილი უსაფრთხოება.'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'პატარა ხელოვანი საღებავებში! 📸', 'საკუთარი თავიც შეღება და კედელიც? გაბრაზების ნაცვლად, ეს სახალისო ჯღაბნის მომენტი ბავშვის ფოტოსესიის მხიარული სტიკერებით გააფორმეთ და სამუდამო მოგონებად ალბომში ატვირთეთ.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'მოიშორეთ დღის დაღლილობა 🛋️', 'მისდევდით და ძალა აღარ დაგრჩათ. ბავშვმა დაიძინა, ახლა განწყობის დღიურში მთელი თქვენი სტრესი გადმოიტანეთ და საკუთარ თავს ერთი ჭიქა მცენარეული ჩაი დაუსხით.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'შეკრულობა აწუხებს? 💩', 'დილით საფენის გამოცვლისას დააკვირდით განავალს. თუ ბავშვს შეკრულობა აქვს, მონიშნეთ აპლიკაციაში და კვების კონტროლის ხელსაწყოს დახმარებით მის მენიუში აუცილებლად დაამატეთ ბოჭკოვანი საკვები.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'ქოთნისთვის მზადყოფნის ნიშნები? 🚽', 'დილით საფენი სრულიად მშრალია? შესაძლოა, ქოთანზე მიჩვევის დასაწყებად იდეალური დრო იყოს. მონიშნეთ ეს საფენების ტრეკერში და გაეცანით აპლიკაციაში მოცემულ სტატიებს ქოთნისთვის მზადყოფნის შესახებ.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'შეინარჩუნეთ დილის ენერგია ⚡', 'არ დაიწყოთ დღე უზმოზე! იზრუნეთ საკუთარ თავზე და ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან შეარჩიეთ ნოყიერი და გემრიელი შვრიის კექსი, რომელიც 5 წუთში მზადდება.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'თქვენც გჭირდებათ მეგობრები 👯‍♀️', 'დაიღალეთ მხოლოდ ბავშვთან საუბრით? დედებისთვის მეგობრულ სივრცეებში იპოვეთ ცენტრები, სადაც სათამაშო ჯგუფებია, გაიცანით სხვა დედები და გაუზიარეთ ერთმანეთს გამოცდილება.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'დღის ძილი ხანმოკლე ხდება? ⏱️', 'ღამით ჩაძინებას დიდი დრო დასჭირდა? ჩართეთ ძილის ტაიმერი და თვალი ადევნეთ განრიგს. შესაძლოა, სწორედ ახლაა დრო, დღის ძილი 15-20 წუთით შეამციროთ.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'დღის გმირი თქვენ ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღე სწავლობს, და ყოველი თავდაჯერებული ნაბიჯი თქვენი შრომის შედეგია. გახსენით განწყობის დღიური და დღეს დაწერეთ ჩანაწერი, რომელიც საკუთარი თავით სიამაყეს გაგრძნობინებთ!'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'მწვანილის დანახვისას გარბის? 🥦', 'ფერების მიხედვით საკვების არჩევა დაიწყო? ბავშვებისთვის განკუთვნილ რეცეპტებში აღმოაჩინეთ, როგორ ოსტატურად დამალოთ ისპანახი და სტაფილო გემრიელ ბლინებში და გაუღვიძოთ ბავშვს მადა.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'პატარა მხატვარი მუშაობს 🎨', 'მაშინაც კი, თუ ტანსაცმელი საღებავით დაესვარა, ნუ გაბრაზდებით! გააფორმეთ ეს შემოქმედებითი წამი ბავშვის ფოტოსესიის მხიარული სტიკერებით, დაამატეთ ალბომში და გაიღიმეთ.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'ხორცის ჭამა არ სურს? 🥩', 'ცილა სჭირდება, მაგრამ ხორცს თავს არიდებს? ბავშვის რეცეპტებში იპოვეთ ადვილად დასაღეჭი, გემრიელი ქათმის ხორცის ბურთულები და კვების კონტროლის ხელსაწყოში შეავსეთ საჭირო ნორმა.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'საწოლიდან გაქცევის გეგმა 🏃‍♂️', 'როგორც კი ძილის დრო დგება, ოთახიდან გარბის? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან ტყის შრიალი აირჩიეთ და ოთახი მშვიდ გამოქვაბულად აქციეთ.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'დილის სიჯიუტე 🛑', '„ამას არ ჩავიცვამ, ამას არ შევჭამ!“ — ასეთი კრიზისები დილას გირთულებთ? დაუყოვნებლივ მისწერეთ Anacan AI-ს და გაიგეთ, როგორ მართოთ ამ ასაკისთვის დამახასიათებელი საზღვრების გამოცდა.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'კედლიდან კედელზე ხტუნვა! 🧗‍♂️', 'ის ნამდვილი კასკადიორია! სახლში დაგროვილი ენერგიის დასახარჯად, დედებისთვის მეგობრულ სივრცეებში მოძებნეთ ცენტრები ფართო სათამაშო დარბაზებით და მიეცით ბავშვს თავისუფლად თამაშის საშუალება.'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'გაბრაზებული კბენა 🦖', 'გაბრაზებისას მეგობრებს ან თქვენ გკბენთ? დაუყოვნებლივ ჰკითხეთ ჩვენს Anacan AI ექსპერტ-ასისტენტს, როგორ გაუმკლავდეთ ამ რთულ ქცევას სიყვარულით.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'მხოლოდ პურს ჭამს? 🍞', 'ცილებსა და ბოსტნეულს გვერდზე სწევს და მხოლოდ ნახშირწყლები სურს? კვების კონტროლის ხელსაწყოთი გამოთვალეთ, რამდენი სასარგებლო საკვები მიიღო დღეს და დაარეგულირეთ ნორმა.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'გვერდების დახევის სურვილი 📖', 'საღამოს ზღაპრის კითხვისას წიგნის გვერდების დახევა სურს? ბლოგების განყოფილებაში წაიკითხეთ, როგორ მოაგვაროთ ეს პრობლემა ისე, რომ კითხვის ჩვევას ზიანი არ მიადგეს.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'ხელოვნების ნიმუში კედელზე 🎨', 'ფანქარი აიღო და კედელი მოხატა? ნუ გაბრაზდებით! ეს საყვარელი ცელქობა ბავშვის ფოტოსესიის სახალისო ჩარჩოებით ალბომში დაამატეთ და უბრალოდ გაიღიმეთ.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'წელი გტკივათ? 🧘‍♀️', '12+ kq პატარას გამუდმებით აწევა ადვილი არ არის. ჯანსაღი რეცეპტების განყოფილებიდან მოამზადეთ კუნთების მომადუნებელი და ანთების საწინააღმდეგო ჯანჯაფილის ჩაი და დაისვენეთ.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'საწოლიდან გაქცევის გეგმა 🏃‍♂️', 'ძილის დრო რომ მოდის, საწოლიდან გადმოძვრება? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან მატარებლის მონოტონური ხმა აარჩიეთ და მშვიდად განაწყეთ ძილისთვის.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'მხოლოდ პურს ჭამს? 🍞', 'ცილოვან საკვებსა და ბოსტნეულს გვერდზე სწევს და მხოლოდ ნახშირწყლები უნდა? კვების კონტროლის ხელსაწყოს მეშვეობით გამოთვალეთ, რამდენი სასარგებლო საკვები მიიღო დღეს და დაარეგულირეთ ნორმა.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'გვერდების დახევის სურვილი 📖', 'საღამოს ზღაპრის კითხვისას წიგნის გვერდების დახევა უნდა? ბლოგების განყოფილებაში წაიკითხეთ, როგორ მოაგვაროთ ეს პრობლემა ისე, რომ კითხვის ჩვევას ზიანი არ მიადგეს.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'გაბრაზებული კბენა 🦖', 'როცა ბრაზდება, მეგობრებს ან თქვენ გკბენთ? დაუყოვნებლივ ჰკითხეთ ჩვენს Anacan AI ექსპერტ-ასისტენტს, როგორ გაუმკლავდეთ ამ რთულ ქცევას სიყვარულით.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'წელი გტკივათ? 🧘‍♀️', '12+ kq პატარას განუწყვეტლივ აყვანა ადვილი არ არის. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ კუნთების მომადუნებელი და ანთების საწინააღმდეგო ჯანჯაფილის ჩაი და დაისვენეთ.'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'ხელოვნების ნიმუში კედელზე 🎨', 'ფანქარი აიღო და კედელი მოხატა? ნუ გაბრაზდებით! ბავშვის ფოტოსესიის სახალისო ჩარჩოებით ეს საყვარელი ცელქობა ალბომში დაამატეთ და უბრალოდ გაიღიმეთ.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'საწოლიდან გაქცევის გეგმა 🏃‍♂️', 'როცა ძილის დრო დგება, საწოლიდან გადმოძვრება? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან მატარებლის მონოტონური ხმა გაუშვით და მშვიდად განაწყვეთ დასაძინებლად.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'ქოთნისთვის მზადყოფნის ნიშნები? 🚽', 'დილით საფენი სრულიად მშრალია? შესაძლოა, ტუალეტის ჩვევის გამომუშავების დასაწყებად იდეალური დრო იყოს. მონიშნეთ ეს საფენის ტრეკერში და რეკომენდებულ პროდუქტებში ერგონომიული ქოთნები დაათვალიერეთ.'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'მარტო თამაში სურს? 👶', 'პარკში სხვა ბავშვებს არ უერთდება და შორიდან აკვირდება? ჯანსაღი პარალელური თამაშის შესახებ ყველაზე საინტერესო და მეცნიერული ფაქტები ბლოგების განყოფილებაში აღმოაჩინეთ.'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'სრულყოფილი დედის ძიებაში 💖', 'დღეს ოდნავ ხმას აუწიეთ? თავს ნუ დაიდანაშაულებთ. ჩაწერეთ თქვენი გრძნობები განწყობის დღიურში — თქვენ მისთვის ისედაც საუკეთესო ხართ.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს სიფხიზლის პერიოდი მეტისმეტად გახანგრძლივდა? ჩართეთ ძილის ტაიმერი და დააკვირდით განრიგს. შესაძლოა, სწორედ ახლაა დღის ძილის 15 წუთით შემცირების დრო.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'ქვიშისა და ტალახის თერაპია 🏖️', 'დასვრის ნუ შეგეშინდებათ! სენსორული განვითარებისთვის დედებისთვის მეგობრულ სივრცეებში იპოვეთ უსაფრთხო პარკი ქვიშის მოედნით და ბავშვს ბუნებასთან თავისუფლად ურთიერთობის საშუალება მიეცით.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'რკინის საუკეთესო მეგობარი 🥩', 'ორგანიზმში რკინის შესაწოვად C ვიტამინი აუცილებელია! კვების კონტროლის ხელსაწყოთი შეამოწმეთ დღევანდელი მენიუ და ხორცთან ერთად უხვად ლიმონმოსხმული სალათიც დაამატეთ.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'ორივე ფეხით ხტომა 🦘', 'ადგილზე დგომისას ორივე ფეხით ერთდროულად ახტომას ცდილობს? ძალიან სასაცილოდ გამოიყურება, არა? აუცილებლად აღბეჭდეთ ეს მომენტი.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'მუსიკალური სიმშვიდე 🎶', 'საღამოს დაწყებული ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზაა, ჩართოთ მისი საყვარელი მელოდია, ჩაიხუტოთ და ნელა იცეკვოთ მასთან ერთად.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'უარს ამბობს ძილზე? 🥱', 'არ სურს დღისით დაძინება და წინააღმდეგობას გიწევთ? სთხოვეთ Anacan AI-ს ზუსტი ინფორმაცია ორი წლის ასაკთან მიახლოებული ბავშვის ძილის ფანჯრების შესახებ და ძილის რეჟიმის განრიგი.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'ჯანსაღი ტკბილეულის ძიებაში 🍎', 'დაემშვიდობეთ მაღაზიის ორცხობილებს! ბავშვების რეცეპტებში აღმოაჩინეთ ფინიკისა და ვაშლის ჯანსაღი ტკბილეული, რომლის მომზადებაც სახლში 10 წუთში შეგიძლიათ, და გაუღვივეთ ბავშვს მადა.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'კბილის გახეხვის ბრძოლა 🪥', 'ჯაგრისის დანახვისთანავე პირს მჭიდროდ კეტავს? მიიღეთ პრაქტიკული რჩევები Anacan AI-სგან, რათა გაიგოთ, როგორ აქციოთ ეს მნიშვნელოვანი ჰიგიენური პროცედურა სახალისო თამაშად.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'სასაცილო გამოთქმები 🗣️', 'ზოგიერთ სიტყვას ისე საყვარლად და არასწორად წარმოთქვამს! არ გამოტოვოთ ეს ოქროს წუთები. ატვირთეთ ბავშვის ალბომში ვიდეო ხმით და მომავალში ერთად იცინეთ.'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'უცნაური ამინდის გამო სახლში დარჩით?', 'ამინდისა და ტანსაცმლის ხელსაწყო მყისიერად გეტყვით ქარის სიჩქარეს და როგორ ჩაიცვათ სწორად — თამამად გაემართეთ პარკისკენ.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'ბოლო ძირითადი კბილები? 🦷', 'უმიზეზოდ ყველაფერს ღრღნის და გაღიზიანებულია? შესაძლოა, ყველაზე უკანა ძირითადი კბილები ამოსდიოდეს. მონიშნეთ ეს პროცესი კბილების ამოსვლის ტრეკერში და მოამზადეთ გაცივებული კბილის საღეჭები.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'ზღაპრის გმირი 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ შექმენით განსაკუთრებული ამბავი, რომლის გმირიც თქვენი ბავშვი იქნება: მამაცი პატარა, რომელსაც კბილების გახეხვა უყვარს.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'დრო საკუთარ თავსაც დაუთმეთ 🛋️', 'მის დევნაში ძალა გამოგელიათ. ბავშვს ჩაეძინა — ახლა განწყობის დღიურში მთელი სტრესი აღწერეთ და თქვენთვის ერთი ფინჯანი ბარამბოს ჩაი დაისხით.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'შია თუ სწყურია? 💧', 'ზოგჯერ წყურვილი უმადობაში ერევათ. საფენების ტრეკერში გამოყოფის ჩანაწერების შემოწმებით მყისიერად დარწმუნდით, რომ ბავშვი საკმარის სითხეს იღებს.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'პატარა მომღერალი 🎤', 'ერთსა და იმავე სიმღერას გაუჩერებლად მღერის? ეს რიტმის შეგრძნებისა და მეტყველების განვითარებას უწყობს ხელს.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'წიგნების სიყვარული 📖', 'მოაქვს თავისი საყვარელი ზღაპრების წიგნი და კალთაში გიჯდებათ? ეს ნიშნავს, რომ მისი ყურადღების ხანგრძლივობა იზრდება. ერთად წაიკითხეთ და სურათებზე გამოსახულ საგნებს სახელები დაარქვით.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'შიშები იწყება? 👻', 'ახლა ეშინია მტვერსასრუტის, რომლისაც ადრე არ ეშინოდა? წარმოსახვის განვითარებასთან ერთად შესაძლოა უსაფუძვლო შიშები გაჩნდეს. ჩაეხუტეთ და უთხარით, რომ უსაფრთხოდ არის.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'სუფთა ჰაერი სჭირდება 🌳', 'ბავშვი ძალიან მოუსვენარია და სახლში ვერ ჩერდება? შეამოწმეთ ამინდი, შეურჩიეთ შესაბამისი ტანსაცმელი და დაუყოვნებლივ პარკისკენ გაემართეთ. ბუნება მისთვის ყველაზე სწრაფი დამამშვიდებელი საშუალებაა.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'თქვენც გჭირდებათ მეგობრები 👯‍♀️', 'დაიღალეთ მხოლოდ ბავშვთან საუბრით? დედებისთვის მეგობრულ სივრცეებში იპოვეთ ცენტრები, სადაც სათამაშო ჯგუფებია, გაიცანით სხვა დედები და გაუზიარეთ ერთმანეთს გამოცდილება.'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'პატარა დამხმარე 🧹', 'მას უკვე სურს საოჯახო საქმეებში მონაწილეობა. ბლოგების განყოფილებაში წაიკითხეთ, როგორ განუვითაროთ დაახლოებით 2 წლის ბავშვს პასუხისმგებლობის გრძნობა თამაშით, და მიღებული რჩევები პრაქტიკაში გამოიყენეთ.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'იამაყეთ საკუთარი თავით! 🌟', 'ყოველი ახალი უნარი, რომელსაც ყოველდღე ითვისებს, და ყოველი თავდაჯერებული ნაბიჯი თქვენი შრომის შედეგია. გახსენით განწყობის დღიური და დღეს ჩაწერეთ ისეთი რამ, რის გამოც საკუთარი თავით იამაყებთ!'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'დარტყმა ან ხელის კვრა 🦖', 'გაბრაზებისას მოულოდნელად ხელს ურტყამს ან მეგობრებს ხელს კრავს? გაიგეთ Anacan AI-სგან, როგორ შეცვალოთ რბილად ამ ასაკისთვის დამახასიათებელი აგრესიული ემოციური რეაქციები.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'ძვლები მტკიცდება 🦴', 'სწრაფი განვითარებისთვის კალციუმია საჭირო. კვების კონტროლის ხელსაწყოს დახმარებით შეამოწმეთ, მიიღეთ თუ არა დღეს ყველისა და იოგურტის საჭირო რაოდენობა და შეავსეთ დანაკლისი.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'ბუნებრივი დამამშვიდებელი 🍃', 'ძალიან ხმაურიანი დღე იყო? ტაიმერი დასრულდა. დაივიწყეთ საოჯახო საქმეები, „თეთრი ხმებიდან“ ნაკადულის ჩუხჩუხი ჩართეთ და დასასვენებლად დივანზე წამოწექით.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'წიგნი დასახევად კი არა, წასაკითხადაა 📖', 'საღამოს ზღაპრის კითხვისას ბავშვი გვერდებს ხევს? ბლოგების განყოფილებაში ახლავე წაიკითხეთ, როგორ მოაგვაროთ ეს პრობლემა ისე, რომ კითხვის ჩვევას ზიანი არ მიაყენოთ.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'დაუსრულებელი შოუ საწოლში 🛌', 'ძილის ნაცვლად საწოლზე ხტუნავს? ჩართეთ ძილის ტაიმერი და თვალყური ადევნეთ გრაფიკს. გააანალიზეთ, ბოლომდე ვერ დახარჯა ენერგია თუ ზედმეტად გადაიღალა.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'კბილების გახეხვის ბრძოლა 🪥', 'ჯაგრისის დანახვისთანავე პირს მაგრად კეტავს? რეკომენდებულ პროდუქტებში მუსიკალური ან თითზე წამოსაცმელი ჯაგრისები დაათვალიერეთ და აღმოაჩინეთ, როგორ აქციოთ ეს მნიშვნელოვანი რუტინა სახალისო თამაშად.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'ფანტაზიას საზღვრები არ აქვს 🧸', 'თავის დათუნიას აჭმევს თუ თქვენ გიმკურნალებთ? გაეცანით რეკომენდებულ პროდუქტებს და შეარჩიეთ ექიმის ან სამზარეულოს ნაკრები, რომელიც თანაგრძნობის საოცარ განვითარებას შეუწყობს ხელს.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'განშორების შიში ბრუნდება? 🌌', 'როგორც კი ოთახიდან გახვალთ, თქვენს კვალდაკვალ ტირის? თეთრი ხმებიდან გულისცემის ხმა ჩაურთეთ, რათა თავი უსაფრთხოდ იგრძნოს და ძილისთვის განეწყოს.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'შარვლები ისევ დაუმოკლდა! 📏', 'პერანგების სახელოები უკვე ვიწროა? თქვენს ბავშვს ფიზიკური ზრდის ნახტომი აქვს. შეიყვანეთ მიმდინარე მონაცემები განვითარების ტრეკერში და სიამაყით გადახედეთ ზრდის გრაფიკს.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'დედის ცილების მარაგი ⚡', 'მოუსვენარი პატარას უკან სირბილი ადვილი არ არის. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ცილებითა და ხილით მდიდარი ენერგეტიკული სმუზი და ენერგიით დაიმუხტეთ.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'ამას მე თვითონ გავაკეთებ! 👕', 'დილაობით ჩაცმა დიდ კრიზისად იქცევა? ახლავე გაიგეთ Anacan AI-სგან, როგორ გაუმკლავდეთ სიჯიუტეს და მისცეთ ბავშვს არჩევანის უფლება.'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'ბოსტნეულის საიდუმლო ოპერაცია 🥦', 'ბროკოლის დანახვისთანავე თეფშს გვერდზე სწევს? ბავშვებისთვის განკუთვნილ რეცეპტებში აღმოაჩინეთ, როგორ ოსტატურად დამალოთ ეს ვიტამინები გემრიელ ბლინებში და ბავშვს მადა გაუღვიძოთ.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'თამაში არ მთავრდება ⏱️', 'დასაძინებლად წასვლის ნაცვლად გარბის და იმალება? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან კი ოკეანის ტალღების ხმა დააყენეთ და ოთახი მშვიდ ძილის გამოქვაბულად აქციეთ.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'როგორ გავიგოთ, რომ დანაყრდა? ⏱️', 'თუ საკვების გადაგდებას ან გადმოფურთხებას იწყებს, ეს ნიშნავს, რომ დანაყრდა. გააჩერეთ კვების ტაიმერი, მონიშნეთ, რომ ნორმა შესრულებულია და გააანალიზეთ მადა.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'დილით ძალიან ადრე იღვიძებს? 🌅', 'მზის ამოსვლამდე იღვიძებს და ენერგიით არის სავსე? დაუყოვნებლივ ჰკითხეთ ჩვენს Anacan AI ექსპერტ-ასისტენტს რჩევები, რათა გაიგოთ, როგორ გადაიტანოთ ძილის ეს რეჟიმი უფრო მისაღებ საათებზე.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'ლოგიკური თამაშები 🧩', 'ბავშვი სათამაშოებს ყუთში ყრის და შემდეგ ყველაფერს იქიდან იღებს? ასე მას უყალიბდება შიგნით და გარეთ ცნებების გაგება. განვითარების ტრეკერში მონიშნეთ ეს კოგნიტიური უნარი.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'ფეხსაცმელზე გაჯიუტება 👟', 'გარეთ გასვლისას აუცილებლად ზამთრის ფეხსაცმლის ზაფხულში ჩაცმა სურს? ზოგჯერ მიეცით საშუალება, თავად გააკეთოს არჩევანი — ეს მის ნებისყოფას აძლიერებს.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'კითხვა გაქვთ? 🤖', '2 წლის ასაკის კრიზისებზე წაკითხული გაშინებთ? ნუ დაიკარგებით ინტერნეტში — პირდაპირ მისწერეთ Anacan AI-ს და გაიგეთ, როგორ გადალახოთ ეს პერიოდი უფრო მარტივად.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'სიტყვებიდან წინადადებებამდე 🗣️', 'უკვე დაიწყო 3-სიტყვიანი სახალისო წინადადებების შედგენა? ეს შესანიშნავი ენობრივი ნახტომი და მისი საყვარელი გამოთქმა ვიდეოზე ხმით ჩაწერეთ და სამომავლოდ შეინახეთ.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'გვერდები ცოცხლდება 📖', 'ზღაპრის კითხვისას წიგნში გამოსახული ცხოველების ხმებს ბაძავს? აუცილებლად გაეცანით ბლოგების განყოფილებაში მოცემულ ინტერაქტიული კითხვის მეთოდებს, რომლებიც წარმოსახვის განვითარებას უწყობს ხელს.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'ენერგიის მოზღვავება 💥', 'სახლის ოთხი კედელი მის სირბილს ვეღარ იტევს. გახსენით დედებისთვის მეგობრული ადგილების რუკა, იპოვეთ უსაფრთხო პარკი რბილი საფარითა და დიდი სასრიალოთი და მიეცით ბავშვს თავისუფლად თამაშის საშუალება.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'კბილებს მე თვითონ გავიხეხავ! 🪥', 'კბილის ჯაგრისს გართმევთ და თავად სურს კბილების გახეხვა, მაგრამ სინამდვილეში ვერ იხეხავს? რეკომენდებულ პროდუქტებში ახლავე მოძებნეთ მუსიკალური და ერგონომიული მოდელები, რომლებიც ამ პროცესს გაამარტივებს.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'სითხის მიღება და შეკრულობა 💧', 'ბევრს დარბის და ცოტა წყალს სვამს? საფენის გამოცვლისას დააკვირდით განავალს. თუ შეკრულობის რისკია, მონიშნეთ ეს აპში და კვების კონტროლის ხელსაწყოს საშუალებით რაციონს დაუყოვნებლივ დაამატეთ ბოჭკოვანი საკვები.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'მოთმინების გამოცდა სუფრასთან 🥣', 'საკვებით თამაშობს და ირგვლივ ყველაფერს სვრის? ჩართეთ კვების ტაიმერი, გრაფიკის საშუალებით გააანალიზეთ მადის ცვლილება და ზუსტად აკონტროლეთ, რამდენ ხანს გრძელდება პროცესი.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'ღამის რიტუალები 🧸', 'ყოველ საღამოს ერთსა და იმავე სათამაშოს ეხუტება და ისე იძინებს? ეს საყვარელი, სიმშვიდის მომგვრელი მომენტი დაუვიწყარი გახადეთ — ფოტოს გარეშე, მხოლოდ აღწერის სახით ჩაწერეთ ბავშვის ალბომის შენიშვნების განყოფილებაში.'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'მეგობრობის პირველი მცდელობები 👶', 'პარკში სხვა ბავშვის სათამაშოთი ინტერესდება ან სხვადასხვა ხმას გამოსცემს? დედებისთვის მეგობრულ სივრცეებში სხვა დედებთან საუბრისას გაიგეთ, როგორ შეუწყოთ ხელი სოციალიზაციის ამ ეტაპს.'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'პატარა ექიმი საქმეშია 🩺', 'დათუნიას ნემსს უკეთებს ან მუცელს უსმენს? წარმოსახვითი თამაშები პიკშია! ბლოგების განყოფილებაში წაიკითხეთ, რა საოცარ გავლენას ახდენს როლური თამაშები გონებრივ განვითარებაზე.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'საფენი სრულიად მშრალია გაღვიძებისას? 🩲', 'დილით საფენის გამოცვლისას შენიშნეთ, რომ ის მშრალია? ეს ქოთნისთვის ფიზიკური მზაობის ერთ-ერთი მთავარი ნიშანია! ჩაინიშნეთ საფენების ტრეკერში და ყურადღებით დააკვირდით სტატისტიკას.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'უშაქრო, მაგრამ ტკბილი 🍪', 'შუადღის წასახემსებელი უნდა? მაღაზიის ორცხობილა საჭირო არ არის. ბავშვის რეცეპტებში აღმოაჩინეთ ფინიკისა და შვრიის სასარგებლო ტკბილეული, რომელიც 10 წუთში მზადდება.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'სრულად გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს ჩაძინებას 40 წუთი დასჭირდა? გადახედეთ ძილის ტაიმერის გრაფიკს. იქნებ სწორედ ახლაა დრო, დღის ძილი 20 წუთით შეამციროთ და საღამოს დაძინების დრო გადმოსწიოთ.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'ყველაფრის იატაკზე დაყრის სურვილი 🛑', 'როცა ბრაზდება ან მოწყენილია, ხელში რაც უჭირავს, ისვრის? ჰკითხეთ Anacan AI-ს, როგორ წარმართოთ ეს ემოციური რეაქციები რბილად.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'ტანსაცმელი უმოკლდება! 📏', 'ჩაცმისას შენიშნეთ, რომ სახელოები დაუმოკლდა? 2 წლის ასაკის მოახლოებასთან ერთად ბავშვს ფიზიკური ზრდის ნახტომი აქვს! შეიყვანეთ მისი ამჟამინდელი სიმაღლე განვითარების მონიტორინგის ხელსაწყოში და სიამაყით გადახედეთ ზრდის მრუდს.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'ცხელი ჩაი და სიჩუმე 🍵', 'ტაიმერი გაჩერდა, ბავშვს კი ჩაეძინა. ნუ იჩქარებთ საოჯახო საქმეების კეთებას! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მელისას ჩაი მოამზადეთ და განწყობის დღიურში დღევანდელი პატარა წარმატებები ჩაინიშნეთ.'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'რკინის ძალა 🥩', 'იმისთვის, რომ თქვენს აქტიურ პატარას ანემია არ განუვითარდეს და ენერგიული დარჩეს, კვების კონტროლის ხელსაწყოში შეამოწმეთ დღეს მიღებული რკინის რაოდენობა და დეფიციტის შემთხვევაში მენიუ დაარეგულირეთ.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'ერთფეროვანი ბგერების მაგია 🌬️', 'ტელევიზორის გამორთვის შემდეგ მოულოდნელი სიჩუმე ბავშვს აწუხებს. ოთახში თეთრი ხმაურის განყოფილებიდან ჩართეთ ვენტილატორის ან ფენის ხმა და ნახეთ, როგორ უქმნის ეს მას ძილის დროს უსაფრთხოების განცდას.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'ფერადი ხელების ხელოვნება 🎨', 'ფერებით თამაშისას მთელი სახე მოისვარა? გაბრაზების ნაცვლად, დაუყოვნებლივ გადაიღეთ ეს სახალისო და შემოქმედებითი მომენტი და ალბომში ყველაზე ფერად მოგონებად დაამატეთ.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'ზღაპარი თავად მოყვეს 📖', 'წიგნში მოცემულ სურათებს უყურებს და თავის ენაზე რაღაცებს ჰყვება? წარმოსახვის ეს საოცარი მომენტი დაუყოვნებლივ დაამატეთ ბავშვის ალბომში ხმოვანი ვიდეოს სახით და მომავლისთვის შეინახეთ.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'უსაფრთხო სივრცე სირბილისთვის 🏃‍♀️', 'სახლში ენერგიას ვერ ხარჯავს და ყველაფერს თავდაყირა აყენებს? გახსენით დედებისთვის მეგობრული ადგილების რუკა, იპოვეთ პარკი უსაფრთხო სარბენი სივრცით და სუფთა ჰაერზე გაისეირნეთ.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'არასწორი ჭიქის გამო კამათი? 🥤', 'იმიტომ ატყდა ამბავი, რომ წყალი წითელი ჭიქის ნაცვლად ლურჯში მიეცით? Anacan AI-სგან შეიტყვეთ, როგორ გაუმკლავდეთ სიმშვიდის შენარჩუნებით ამ ერთი შეხედვით აბსურდულ კრიზისებს.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'ღამით გაღვიძებები ⏱️', 'ჩართეთ ძილის ტაიმერი! ტაიმერის სტატისტიკური გრაფიკის დახმარებით ზუსტად გააანალიზეთ, ღამის შიშებთან თუ ძილის რეგრესიასთან გაქვთ საქმე, და რეჟიმი შესაბამისად დაარეგულირეთ.'),
  ('91af8067-4bf1-4cab-af7f-58a96c7e04b3', 'თქვენც გჭირდებათ შესვენება ☕', 'გადით სახლიდან და ცოტა ამოისუნთქეთ! დედებისთვის მეგობრულ ადგილებში იპოვეთ ახლომდებარე კაფე საბავშვო კუთხით და მშვიდად მიირთვით ცხელი ყავა.'),
  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'შეკრულობა აწუხებს? 🚽', 'დილით საფენის გამოცვლისას განავალს დააკვირდით. თუ ბავშვს შეკრულობა აქვს, მონიშნეთ ეს აპლიკაციაში და კვების კონტროლის ხელსაწყოს დახმარებით რაციონს დაუყოვნებლივ დაამატეთ ბოჭკოვანი საკვები ბალანსის შესანარჩუნებლად.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'დილის კრიზისები 👗', '„ეს ფეხსაცმელი არ მინდა!“ — ეს სიჯიუტე დილას გირთულებთ? Anacan AI-სგან გაიგეთ, როგორ შესთავაზოთ ბავშვს ალტერნატივები და მისცეთ არჩევანის თავისუფლება ყველაზე ეფექტური ფსიქოლოგიური მეთოდებით.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'დედის ცილების მარაგი ⚡', 'მოუსვენარი პატარას დევნა მარტივი არ არის. ნუ გამოიფიტებით! ჯანსაღი რეცეპტებიდან მოამზადეთ ცილებითა და ხილით მდიდარი ენერგეტიკული სმუზი და აღიდგინეთ ენერგია.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'ბუნებრივი დამამშვიდებელი 🍃', 'ძალიან ხმაურიანი და დატვირთული დღე გქონდათ? ტაიმერი გაჩერდა. ჩააბნელეთ ოთახი, თეთრი ხმებიდან ნაკადულის ჩხრიალი ჩართეთ და თქვენსა და ბავშვის გონებას დასვენების საშუალება მიეცით.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'ბრძოლა დამოუკიდებლობისთვის! 👕', 'თავად სურს ჩაცმა და თქვენს დახმარებაზე უარს ამბობს? დაუყოვნებლივ ჰკითხეთ ჩვენს ექსპერტ დამხმარეს, Anacan AI-ს, როგორ აქციოთ ეს სიჯიუტე ჯანსაღი განვითარების ნაწილად.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'რკინის მარაგის შემოწმება 🥩', 'იმისთვის, რომ აქტიურ პატარას ანემია არ განუვითარდეს, კვების კონტროლის ხელსაწყოში შეამოწმეთ დღეს მიღებული რკინის რაოდენობა (ხორცი, პარკოსნები) და განაახლეთ მენიუ.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'ღამით ტემპის შენელება 🎶', 'სირბილით არ იღლება და დასაძინებლად არ მიდის? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან ოკეანის ტალღების ხმა შეარჩიეთ და ოთახში სიმშვიდისა და ძილისთვის ხელსაყრელი გარემო შექმენით.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'კრიზისი ეკრანთან 📱', 'ტელეფონს რომ ართმევთ, იატაკზე ვარდება და ჭირვეულობს? Anacan AI-სგან გაიგეთ, როგორ შეზღუდოთ ეკრანთან გატარებული დრო სტრესის გარეშე და დააწესოთ ჯანსაღი საზღვრები.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'დღის გმირი თქვენ ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღიურად იძენს, თქვენი შრომის შედეგია. გახსენით განწყობის დღიური და დღეს დაწერეთ ჩანაწერი, რომლისთვისაც საკუთარ თავს ფეხზე წამომდგარი ტაშს დაუკრავთ!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'კბილების გახეხვის ბრძოლა 🪥', 'ჯაგრისის დანახვისთანავე გარბის? რეკომენდებულ პროდუქტებში მუსიკალური ან მბრუნავი საბავშვო ჯაგრისები დაათვალიერეთ და ჰიგიენის ეს მნიშვნელოვანი პროცესი სახალისო თამაშად აქციეთ.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'ბუნებრივი დამამშვიდებელი 🍃', 'დღე მეტისმეტად ხმაურიანი და ქაოსური იყო? ტაიმერი გაჩერდა. ჩააბნელეთ ოთახი, თეთრი ხმებიდან ჩართეთ ნაკადულის ჩუხჩუხი და ბავშვისა და თქვენს გონებასაც დასვენების საშუალება მიეცით.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'ლოგიკური ნახტომი 🧩', 'ბავშვი მიზეზშედეგობრივი კავშირების დამყარებას იწყებს. ბლოგების განყოფილებაში გაეცანით და სცადეთ საუკეთესო სახლის თამაშები, რომლებიც დაახლოებით 2 წლის ბავშვების შემეცნებით განვითარებას აჩქარებს.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'კალციუმის ფარი 🦴', 'კალციუმი აუცილებელია კბილებისა და ძვლებისთვის. კვების კონტროლის ხელსაწყოთი გადაამოწმეთ, მიიღო თუ არა ბავშვმა დღეს იოგურტისა და ყველის საჭირო რაოდენობა.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'დივნის ალპინისტი! 🧗', 'ავეჯზე ძრომიალი მისი ყველაზე დიდი გატაცებაა? გააფორმეთ მისი ეს გაბედული და სახალისო მოტორული უნარების შოუ ბავშვის ფოტოსესიის მხიარული სტიკერებით და ატვირთეთ ალბომში.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'ფანქეიქების მონსტრი 🥞', 'საუზმეზე უარს ამბობს? ბავშვის რეცეპტებში უშაქრო ბანანის ფანქეიქის რეცეპტი სცადეთ. ბავშვი მას ხელში დაიჭერს, დამოუკიდებლად შეჭამს და მადაც გაეხსნება.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'მოთმინების გამოცდა სუფრასთან 🥣', 'საჭმლით თამაშობს და ირგვლივ ყველაფერს სვრის? ჩართეთ კვების ტაიმერი, გრაფიკზე გააანალიზეთ მადის დინამიკა და ზუსტად აკონტროლეთ, რამდენ ხანს გრძელდება პროცესი.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'ქვიშისა და ტალახის თერაპია 🏖️', 'ნუ შეგეშინდებათ დასვრის! კინეტიკური ქვიშისა და სენსორული თამაშებისთვის საუკეთესო საშუალებები ახლავე აღმოაჩინეთ რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'ენერგიის დახარჯვის ხელოვნება 🧗', 'სახლის სივრცე მისთვის საკმარისი აღარ არის. გახსენით დედებისთვის მეგობრული ადგილების რუკა და იპოვეთ ადგილი უსაფრთხო სათამაშო ზონითა და რბილი იატაკით, სადაც ბავშვი თავისუფლად იხტუნავებს და ირბენს.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'ჭირვეული მადა 🥦', 'მხოლოდ მაკარონი ან პური უნდა? კვების კონტროლის ხელსაწყოთი გააანალიზეთ მენიუ და ვიტამინების ნაკლებობა ბავშვის რეცეპტებში მოცემული საინტერესო ულუფებით შეავსეთ.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა მკვეთრი განათება და ეკრანი გამორთეთ. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'დედის ენერგია იწურება? 🔋', 'შუადღისას ფეხზე მდგომსაც კი გეძინებათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ცილებით მდიდარი სმუზი არაქისის კარაქით, რომელიც კოფეინის გარეშე მყისიერად შეგმატებთ ენერგიას.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'დღეს ყველაფერი რთული იყო? 💆‍♀️', 'განუწყვეტლივ ყვირილი და ტირილი გესმოდათ? ღრმად ჩაისუნთქეთ, შეწყვიტეთ საკუთარი თავის განსჯა — თქვენ შესანიშნავი ხართ!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'სამზარეულოში ყველა ქვაბი იატაკზეა?', 'უსაფრთხო ნივთებით თამაში ბავშვის ლოგიკურ აზროვნებას ავითარებს. მიეცით საშუალება, თავისუფლად გამოიკვლიოს თავისი საგანძური.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'ჭკვიანი სათამაშოები 🧩', '2 წლის ბავშვის გონებრივი განვითარებისთვის საჭიროა არა მხოლოდ ხმოვანი, არამედ განმავითარებელი სათამაშოები. რეკომენდებულ პროდუქტებში აღმოაჩინეთ ხის ფაზლები, რომლებიც ლოგიკურ აზროვნებას ავითარებს.'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'უშაქრო ტორტის მომზადება 🎂', 'ხვალინდელი განსაკუთრებული დღისთვის ჯანსაღი ტორტია საჭირო! ბავშვის რეცეპტებში აღმოაჩინეთ ხილის ტორტების რეცეპტები რაფინირებული შაქრის გარეშე, რომლებიც სრულად არის მორგებული ბავშვებზე.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'დედის ენერგიის წყარო 🥗', 'არ დაგავიწყდეთ საკუთარი ენერგიის აღდგენა! ჯანსაღი რეცეპტებიდან მოამზადეთ არაქისის კარაქიანი, ცილებით მდიდარი სმუზი, რომელიც მყისიერად აგავსებთ ენერგიით.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'ოფიციალურად 2 წლისაა! 🎈', '2 წელი უწყვეტი შრომის, სიყვარულისა და უძილო ღამეების. განწყობის დღიურში ჩაწერეთ სიამაყე, რომელსაც ამ 730 დღის გამო გრძნობთ. თქვენ მართლაც შესანიშნავი დედა ხართ!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'თქვენ ეს შეძელით 🥂', 'ორი წელი თავდადებისა! თუ ბავშვს სძინავს, სახლის საქმეები გვერდზე გადადეთ. გახსენით განწყობის დღიური, საკუთარ თავს მადლობა გადაუხადეთ და უბრალოდ დაისვენეთ.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', '2 წლის ასაკის კრიზისი? 🌪️', '„არას“ თქმა და ყვირილი გახშირდა? ამ ცნობილი პერიოდის მშვიდად გასავლელად ახლავე მიიღეთ Anacan AI-სგან ემოციური აფეთქებების მართვის ტაქტიკები.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'სიჩუმის საჭიროება 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმის საზომით შეამოწმეთ გარემოში ხმაურის დონე დეციბელებში და მოერიდეთ უეცარ ხმაურს.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'სუფრასთან ჯდომა არ უნდა 🥣', 'ჭამა მალე ბეზრდება და გარბის? ჩართეთ კვების ტაიმერი, მონიშნეთ პროცესის ხანგრძლივობა და სრულად მოერიდეთ ძალით კვებას.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'სიმშვიდის საჭიროება 🤫', 'გუშინდელი ხმაურის შემდეგ ოთახში სიმშვიდე ხმის საზომით შეინარჩუნეთ. ღამით შეწყვეტილი ძილი მის განწყობასაც აფუჭებს და თქვენსასაც.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'დაბადების დღის შემდგომი ქაოსი 🌪️', 'გუშინდელი წვეულების შემდეგ სახლში სრული არეულობაა? დალაგებას ნუ იჩქარებთ. ეს დღე თქვენს ახლად 2 წლის პატარასთან ერთად უბრალოდ დასვენებას დაუთმეთ.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'ბუნების ხელოვანი 🍂', 'გადით სახლიდან! პარკში ფოთლები და ქვები საუკეთესო სენსორული მასალაა. დედებისთვის მეგობრულ ადგილებში იპოვეთ სივრცე დიდი გამწვანებული ტერიტორიით.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'ბევრი წყალი, მარტივი მონელება 💧', 'სირბილში წყლის დალევა ავიწყდება? საფენის ტრეკერში დილის მონაცემი შეიტანეთ და შეკრულობის რისკის შესამცირებლად სითხისა და ბოჭკოს ბალანსი დაუყოვნებლივ გააანალიზეთ.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'საღამოს ზღაპრის ჩვევა 📖', 'თქვენ მიერ წაკითხულ ზღაპარს საკუთარი სიტყვებით იმეორებს? ენის განვითარების ეს საოცარი ნახტომი დაუყოვნებლივ დაამატეთ ბავშვის ალბომში ხმიან ვიდეოდ და მომავალს შემოუნახეთ.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'სრულყოფილების ილუზია 🛋️', 'სოციალურ ქსელებში მუდამ მხიარული დედების ყურებისას თავს ნუ დაიდანაშაულებთ. თქვენი დაღლილობაც და არეული ოთახიც სრულიად ბუნებრივი რეალობაა.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', '„ჩემია!“ პერიოდი 🧸', 'პარკში სათამაშოს არავის უზიარებს და ყვირის? Anacan AI-სგან გაიგეთ, როგორ მართოთ 2 წლის ბავშვის ეგოცენტრიზმი ჯანსაღად, რომ ის აგრესიაში არ გადაიზარდოს.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'ანთების საწინააღმდეგო ძალა 🍵', 'ბავშვის ხელში აყვანისგან ზურგი და მკლავები გტკივათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ჯანჯაფილისა და ლიმონის ჩაი და ორგანიზმს აღდგენაში დაეხმარეთ.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს სიფხიზლის პერიოდი მეტისმეტად გახანგრძლივდა? ჩართეთ ძილის ტაიმერი და დააკვირდით განრიგს. იქნებ დროა, დღის ძილი 20 წუთით შეამციროთ!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'კვლავ ყველაფერს გბაძავთ 🦜', 'როცა ტელეფონზე საუბრობთ, ისიც იღებს პულტს და ყურთან მიაქვს? 100%-ით გბაძავთ! ეცადეთ, მისთვის კარგი მაგალითი იყოთ.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', 'სიტყვა „არას“ ძალა 🛑', 'როცა რამეს სთავაზობთ, თავს აქნევს და ამბობს „არა“! ეს სიჯიუტე კი არა, საკუთარი აზრის გამოხატვაა. შესთავაზეთ არჩევანი, რათა დამშვიდებაში დაეხმაროთ.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'მამიკოს სახალისო ოინები 🤡', 'ბავშვის გასაცინებლად საუკეთესო ხერხი მამიკოს მიერ უცნაური ხმების გამოცემაა. ამ საღამოს ბავშვთან ერთად დატკბით მხიარული წუთებით.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'საწოლიდან გაქცევის გეგმა 🏃‍♂️', 'როცა ძილის დრო მოდის, გარბის და იმალება? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან ტყის შრიალი შეარჩიეთ და ოთახი მშვიდ გამოქვაბულად გადააქციეთ.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'პარალელური თამაშიდან ერთობლივ თამაშამდე 👶', 'სხვა ბავშვებთან ერთად ერთ სივრცეში თამაშისადმი მისი ინტერესი იზრდება. ბლოგების განყოფილებაში გაეცანით 2 წლის ბავშვების სოციალიზაციის საიდუმლოებებსა და სათამაშო მოედნის ფსიქოლოგიას.'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'ჩაცმისას გაჯიუტება 👗', 'ტირის და ამბობს: „ეს შარვალი არ მინდა!“? დილის ჩაცმასთან დაკავშირებული კრიზისების შემცირებისა და მისთვის არჩევანის თავისუფლების მიცემის გზები Anacan AI-სგან შეიტყვეთ.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'პატარა მზარეული საქმეშია 👨‍🍳', 'სამზარეულოში გეხმარებათ და ცომს ზელს? ფქვილში ამოსვრილი ბავშვის ეს სახალისო მომენტი ხმის მქონე ვიდეოდ გადაიღეთ და სამუდამო მოგონებად აქციეთ.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'ყვირილი სუპერმარკეტში 🛒', 'საჯარო ადგილას სასურველი ნივთი რომ ვერ მიიღო, იატაკზე გაწვა და ისტერიკა მოაწყო? დაივიწყეთ გარშემომყოფთა მზერა და Anacan AI-ს გაუზიარეთ თქვენი დარდი, რათა 2 წლის ასაკის ეს კრიზისები სიმშვიდით მართოთ.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'ღამე უძილოდ გაატარეთ? ☕', 'ღამით გაღვიძებამ ენერგია გამოგაცალათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ცილებით მდიდარი სმუზი არაქისის კარაქით, რომელიც კოფეინის გარეშე სწრაფად შეგმატებთ ძალას და გამოგაცოცხლებთ.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'უშაქრო, მაგრამ გემრიელი 🥞', 'ტკბილეული მოუნდა? მაღაზიაში წასვლა არ დაგჭირდებათ. ბავშვის რეცეპტებში ნახეთ ბანანისა და ვაშლის ფანქეიქები, რომლებიც სულ რაღაც 10 წუთში მზადდება, და გაუღვიძეთ მადა.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'ბრძოლა კბილის ჯაგრისთან 🪥', 'კბილების გახეხვა დიდ ბრძოლად იქცევა? რეკომენდებულ პროდუქტებში შეარჩიეთ მუსიკალური ან საყვარელი მულტფილმის გმირით გაფორმებული ჯაგრისი და ეს პროცესი მყისიერად თამაშად აქციეთ.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'ბუნებრივი დამამშვიდებელი 🍃', 'დღემ ხმაურსა და სირბილში ჩაიარა? ტაიმერი გაჩერდა. ჩააბნელეთ ოთახი, თეთრი ხმებიდან ჩართეთ ნაკადულის ჩუხჩუხი და თქვენს გონებასაც დასვენების საშუალება მიეცით.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'რკინის ფარი 🥩', 'ენერგია გამოელია თუ უბრალოდ დაიღალა? კვების კონტროლის ხელსაწყოთი შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი რკინა (ხორცი, პარკოსნები), და დანაკლისი დროულად შეავსეთ.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'ექიმობანას თამაში დაიწყო 🩺', 'დათუნიას ნემსს უკეთებს? წარმოსახვითი თამაშები პიკშია. აღბეჭდეთ ეს საყვარელი მომენტი ბავშვის ფოტოსესიით და ყველაზე დასამახსოვრებელ მოგონებად შეინახეთ.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'თქვენც გჭირდებათ შესვენება ☕', 'ცოტა ხნით ბავშვს მოშორდით და ამოისუნთქეთ! დედებისთვის მეგობრულ სივრცეებში იპოვეთ კაფე საბავშვო კუთხით და მშვიდად მიირთვით ცხელი ყავა.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'მასაჟის დროა 💆‍♂️', 'ბავშვის დაძინების შემდეგ, დღის სტრესის მოსახსნელად, თქვენ და თქვენმა პარტნიორმა ერთმანეთს მხრები დაუზილეთ. თქვენ ერთი გუნდი ხართ!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'წარმოსახვითი მანქანის მართვა 🚗', 'იღებს ცარიელ ყუთს ან სათამაშოს, საჭესავით ატრიალებს და ხმებს გამოსცემს? ეს ნიშნავს, რომ სიმბოლური თამაში (pretend play) აქტიურად ვითარდება!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'დედების გულახდილი საუბრები 💬', 'ფიქრი „ჩემი ბავშვი რატომ იქცევა ასე?“ მოსვენებას არ გაძლევთ? შეუერთდით Anacan-ის საზოგადოებას და წაიკითხეთ სხვა დედების მსგავსი ისტორიები.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'კალციუმის მარაგი 🦴', 'კალციუმი აუცილებელია კბილებისა და ძვლებისთვის. კვების მონიტორინგის ხელსაწყოთი შეამოწმეთ, მიიღეთ თუ არა დღეს იოგურტისა და ყველის საჭირო რაოდენობა, და შეავსეთ დანაკლისი.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', '„მე თვითონ შევჭამ!“ 🥦', 'ბავშვს სურს, კოვზი ხელიდან გამოგართვათ. მიეცით ამის საშუალება. ტანსაცმელი დაესვრება, მაგრამ დამოუკიდებლობის ეს განცდა მისთვის ძალიან მნიშვნელოვანია.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'დღის გმირი თქვენ ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღიურად სწავლობს, და ყოველი დამოუკიდებელი ნაბიჯი თქვენი შრომის შედეგია.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'ჭკვიანი სათამაშოები 🧩', '2 წლის ბავშვის გონებრივი განვითარებისთვის საჭიროა არა უბრალოდ ხმოვანი, არამედ შემეცნებითი სათამაშოები. რეკომენდებულ პროდუქტებში აღმოაჩინეთ ხის ფაზლები და ფორმების ასაწყობი სათამაშოები, რომლებიც ლოგიკურ აზროვნებას ავითარებს.'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'შეკრულობის პრობლემა აქვს? 🚽', 'თამაშსა და სირბილში წყლის დალევა ავიწყდება? საფენის გამოცვლისას დააკვირდით განავალს. თუ შეკრულობის რისკი არსებობს, მონიშნეთ ეს აპში და კვების კონტროლის ხელსაწყოს გამოყენებით რაციონს დაუყოვნებლივ დაამატეთ ბოჭკოვანი საკვები.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს დაძინებას 40 წუთი დასჭირდა? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, სწორედ ახლაა დრო, დღის ძილი 20 წუთით შეამციროთ და საღამოს დაძინების დრო გადმოწიოთ.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'უშაქრო, მაგრამ ტკბილი 🍪', 'შუადღის წახემსება უნდა? მაღაზიაში ნაყიდი ორცხობილა საჭირო არ არის. ბავშვის რეცეპტებში მოამზადეთ ფინიკისა და შვრიის სასარგებლო ტკბილეული, რომელსაც მხოლოდ 10 წუთი სჭირდება.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'სასაცილო მიმიკები 🤪', 'სარკის წინ სასაცილო სახეებს იღებს? არ გამოტოვოთ ეს სახალისო მომენტი! ბავშვის ფოტოსესიის სასაცილო ჩარჩოებით გააფორმეთ და დაუყოვნებლივ დაამატეთ ალბომში.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'თქვენც გჭირდებათ შესვენება ☕', 'გადით სახლიდან და ცოტა ამოისუნთქეთ! დედებისთვის მეგობრულ ადგილებში იპოვეთ ახლომდებარე კაფე საბავშვო კუთხით, მშვიდად მიირთვით ცხელი ყავა და გაიცანით სხვა დედები.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'არასწორი ფერის თეფში! 🎨', 'იმის გამო ატყდა ჭირვეულობა, რომ საჭმელი მწვანე თეფშის ნაცვლად წითელზე მიართვით? ამ ასაკისთვის დამახასიათებელი ალოგიკური სიჯიუტის მართვის შესახებ რჩევები ბლოგების განყოფილებაში წაიკითხეთ.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'დედის წელის ტკივილი 🧘‍♀️', '13+ kq პატარას აწევისგან წელი გტკივათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან კუნთების მომადუნებელი ჯანჯაფილის ჩაი მოამზადეთ და საკუთარ თავზე იზრუნეთ.'),
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696', 'ფარული მიმბაძველი 📸', 'თქვენსავით საუბრობს ტელეფონზე ან იმავე მოძრაობებს იმეორებს? ეს სახალისო მომენტი ბავშვის ფოტოსესიის მხიარული სტიკერებით გააფორმეთ და ალბომში დაამატეთ.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'ყველაფრის იატაკზე დაყრის სურვილი 🛑', 'როცა ბრაზდება ან მოწყენილია, ხელში რაც უჭირავს, მოიქნევს და ისვრის? ბლოგების განყოფილების სტატიებში წაიკითხეთ, როგორ მისცეთ ამ ემოციურ რეაქციებს სწორი მიმართულება რბილი მიდგომით.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'შეღებილი ხელების ხელოვნება 🎨', 'ფერებით თამაშისას მთელი სახე მოითხუპნა? გაბრაზების ნაცვლად დაუყოვნებლივ გადაუღეთ ფოტო ამ სახალისო და შემოქმედებით მომენტს და ბავშვის ალბომში ყველაზე ფერად მოგონებად დაამატეთ.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'ბუნებრივი დამამშვიდებელი 🍃', 'ტაიმერი გაჩერდა. ბავშვს ჩაეძინა. ახლა საკუთარი თავი დააფასეთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მელისას ჩაი მოამზადეთ, დივანზე წამოწექით და ამ დამღლელი დღის შემდეგ სიჩუმეში ჩაიძირეთ.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', 'მე თვითონ დავიბან! 🧽', 'აბაზანაში ჯაგრისს ან ღრუბელს ხელიდან გართმევთ? დამოუკიდებლობისკენ მისწრაფების მხარდასაჭერად, ბავშვისთვის უსაფრთხო სააბაზანო ნივთები რეკომენდებულ პროდუქტებში მოძებნეთ.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', 'ენერგია 5 წუთში ⚡', 'სირბილმა ძალა გამოგაცალათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ენერგიის სწრაფად აღმდგენი, ცილებით მდიდარი არაქისის კარაქის სმუზი და ძალები აღიდგინეთ.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'ძილის რეჟიმის ანალიზი ⏱️', 'საღამოს საწოლში დიდხანს ტრიალებს? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, სწორედ ახლაა დრო, დღის ძილი 20 წუთით შეამციროთ და საღამოს დაძინების დრო გადმოსწიოთ.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'სიმშვიდის ჯადოსნური ფონი 🌊', 'ჭირვეული და ხმაურიანი დღე გქონდათ? თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ და როგორც ბავშვის, ისე თქვენი ნერვული სისტემა დაამშვიდეთ.'),
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2', 'თამაში ბოსტნეულით 🥦', 'ისპანახზე უარს ამბობს? ბავშვის რეცეპტებში აღმოაჩინეთ, როგორ დამალოთ ეს ვიტამინები გემრიელ ბლინებში და ბავშვს მადა გაუღვიძოთ.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'სიმაღლეში ნახტომი! 📏', 'შარვლები ისევ დაუმოკლდა? 25-ე თვის მოახლოებასთან ერთად ფიზიკური განვითარება ჩქარდება. შეიყვანეთ მიმდინარე მონაცემები განვითარების მონიტორში და სიამაყით გადახედეთ განვითარების გრაფიკს.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'სუფთა ჰაერზე თავგადასავალი 🌳', 'სახლის კედლებში ყოფნა უკვე ბეზრდება. დედებისთვის მეგობრულ ადგილებში იპოვეთ ფართო და უსაფრთხო პარკი, სადაც თავისუფლად ირბენს და ენერგიას დახარჯავს.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'მოთმინების გამოცდა სუფრასთან ⏱️', 'საჭმლით თამაშობს, მაგრამ არ ჭამს? ჩართეთ კვების ტაიმერი, აკონტროლეთ პროცესის ხანგრძლივობა და მადის ცვლილება აპლიკაციაში მოცემული გრაფიკის საშუალებით გააანალიზეთ.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'რატომ იწყებს მოულოდნელად დარტყმას? 🛑', 'გაბრაზებისას ხელს ურტყამს? Anacan AI-ის ექსპერტისგან გაიგეთ, როგორ მიმართოთ ამ ასაკისთვის დამახასიათებელი აგრესიული ემოციები თამაშისკენ და ნაზად შეცვალოთ ეს ქცევა.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'ყავის შესვენება ☕', 'სახლის საქმეები და ბავშვზე ზრუნვა... ახლა შესვენების დროა! დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფე საბავშვო კუთხით და მშვიდად მიირთვით ცხელი ყავა.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'დღის გმირი თქვენ ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღიურად იძენს, თქვენი შრომის შედეგია.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'C ვიტამინის ბალანსი 🍊', 'იმუნიტეტი ძლიერი უნდა იყოს. კვების კონტროლის ხელსაწყოთი გამოთვალეთ, მიიღო თუ არა ბავშვმა დღეს საკმარისი C ვიტამინი, და განაახლეთ მენიუ.'),
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45', 'დაუსრულებელი „რატომ?“ პერიოდი 🤔', '„ეს რა არის?“, „რატომ არის ასე?“... ის უკვე სამყაროს შესახებ კითხვებს სვამს! მოთმინებით უპასუხეთ, რადგან სწორედ ამ დროს მის ტვინში ნეირონები ზეიმობენ.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'გაწყვიტეთ სრულყოფილების ჯაჭვი 🛑', 'ბავშვს დღეს შუადღისას არ დაუძინია და სახლიც თავდაყირაა? არა უშავს! ღრმად ჩაისუნთქეთ — ყველაფერს ერთდროულად ვერ გააკონტროლებთ. ცოტა მოეშვით.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'მოთმინება გეწურებათ?', 'ოთახის კარი დახურეთ და ბავშვი მამასთან მარტო დატოვეთ. დაე, ამ საღამოს სახლში მოწყობილი სათამაშო მოედნის უფროსი მამა იყოს.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'გეჩვენებათ, რომ სახლის კედლები გიახლოვდებათ?', 'დედებისთვის მეგობრულ სივრცეებში იპოვეთ კაფე, რომელსაც საბავშვო სათამაშო კუთხე აქვს. ბავშვმა ითამაშოს, თქვენ კი ყავით დატკბით.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'მე თვითონ ჩავიცვამ 👕', 'თუნდაც შარვლის თავზე ჩამოცმას ცდილობდეს, ჩაცმის მცდელობაში ხელს ნუ შეუშლით. დამოუკიდებლობის სურვილი პიკს აღწევს! მონიშნეთ ეს პატარა გამარჯვება განვითარების ტრეკერში.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'მუსიკალური სიმშვიდე 🎶', 'საღამოს დაწყებული ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზაა, ჩართოთ მისი საყვარელი მელოდია, ჩაეხუტოთ და მასთან ერთად ნელა იცეკვოთ.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df'::uuid, 'მყუდრო გამოქვაბულის სიმშვიდე 🌌', 'სირბილით არ იღლება და დასაძინებლად არ მიდის? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან ტყის შრიალი შეარჩიეთ და ოთახი მშვიდ, ძილისთვის მყუდრო გამოქვაბულად აქციეთ.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'ხტუნვის დროა 🦘', 'სახლში დივნებზე ხტუნავს? დედებისთვის მეგობრულ ადგილებში იპოვეთ გასართობი ცენტრი ბატუტითა და რბილი იატაკით, რათა ბავშვმა ენერგია უსაფრთხოდ დახარჯოს.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'ძალიან ადრე იღვიძებს! 🌅', 'მზის ამოსვლამდე უკვე ფეხზეა? იმის გასაგებად, თუ როგორ დაარეგულიროთ ძილის ეს რეჟიმი, ახლავე მიიღეთ პრაქტიკული რჩევები ჩვენი Anacan AI ექსპერტი ასისტენტისგან.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'ახალი სიტყვების აღმოჩენა 🗣️', 'დღეს რა სასაცილო სიტყვა მოიგონა? ენის განვითარების ეს შესანიშნავი მომენტი ბავშვის ალბომში ხმოვან ვიდეოდ შეინახეთ — წლების შემდეგ ნახავთ და ბევრს იცინებთ.'),
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40', 'შუადღისას ფეხზე მდგარს გეძინებათ?', 'ჯანსაღი რეცეპტებიდან მოამზადეთ არაქისის კარაქის სმუზი, რომელიც კოფეინის გარეშე მყისიერად შეგმატებთ ენერგიას.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'დაუსრულებელი შოუ საწოლში 🛌', 'ძილის ნაცვლად საწოლში ხტუნავს? თვალი ადევნეთ ძილის ტაიმერის გრაფიკს და სწრაფად გაარკვიეთ, ენერგია ბოლომდე ვერ დახარჯა თუ ზედმეტად გადაიღალა.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'თბილი ჩაი და სიჩუმე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. ნუ იჩქარებთ საოჯახო საქმეების კეთებას! მოიმზადეთ მელისას ჩაი და უბრალოდ დატკბით სიჩუმით.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'კალციუმის ფარი 🦴', 'კალციუმი აუცილებელია კბილებისა და ძვლებისთვის. კვების კონტროლის ხელსაწყოთი შეამოწმეთ, მიიღეთ თუ არა დღეს იოგურტისა და ყველის საჭირო რაოდენობა, და შეავსეთ დანაკლისი.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'პატარა ექიმი მუშაობს 🩺', 'დათუნიას ნემსს უკეთებს თუ მუცელს უსმენს? წარმოსახვითი თამაშების საუკეთესო პერიოდია! ეს საყვარელი მომენტი დაუყოვნებლივ გადაიღეთ ბავშვის ფოტოსესიის საშუალებით და დაუვიწყარ მოგონებად აქციეთ.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'სიჩუმის საჭიროება 🤫', 'ოთახში სიმშვიდე ხმის საზომით შეინარჩუნეთ. ღამით შეწყვეტილი ძილი ზიანს აყენებს როგორც ბავშვის განვითარებას, ისე თქვენს დილის განწყობას.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'ბოლო საღეჭი კბილები? 🦷', 'უმიზეზოდ ყველაფერს ღრღნის და ხელები პირში აქვს? შესაძლოა, ყველაზე უკანა საღეჭი კბილები (მეორე მოლარები) ამოსვლას იწყებდეს. აუცილებლად შეამოწმეთ კბილების ამოსვლის ტრეკერი.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'საოჯახო საქმეებს შეუძლიათ მოიცადონ 🛑', 'იატაკი არ მოგიწმენდიათ? ნუ იდარდებთ. დასვრილი სახლის დალაგება შეიძლება, მაგრამ გადაღლილი დედის ძალების აღდგენას დიდი დრო სჭირდება. წამოწექით დივანზე და უბრალოდ დატკბით სიმშვიდით.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'ხილისადმი მტრობა 🍎', 'გუშინ საყვარელ ხილს დღეს იატაკზე აგდებს? საკვების შერჩევითობა ამ ასაკისთვის დამახასიათებელი პრობლემაა. გაეცანით ჯანსაღ რეცეპტებსა და საკვების სახალისოდ და განსხვავებულად წარდგენის იდეებს.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'წარმოსახვითი თამაშები ღრმავდება 🧸', 'სათამაშოებს აჭმევს და აძინებს? წარმოსახვის განვითარების პიკური პერიოდია! განვითარების მონიტორინგის განყოფილებაში ემპათიის გამოვლენის ეს მცდელობები აღნიშნეთ.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'ძალა ერთობაშია🥂', 'ბავშვის დაძინების შემდეგ, დღის სტრესის მოსახსნელად, პარტნიორთან ერთად ჩაი დაისხით და უთხარით ერთმანეთს: „ჩვენ შესანიშნავი გუნდი ვართ“ — ასე გამოხატეთ ერთმანეთის მიმართ მადლიერება.'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს დაძინებას 40 წუთი დასჭირდა? გადახედეთ ძილის ტაიმერის გრაფიკს. იქნებ სწორედ ახლაა დრო, დღის ძილი 20 წუთით შეამციროთ და საღამოს დაძინების დრო გადმოწიოთ.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'ყვირილი საზოგადოებრივ ადგილას 🛒', 'მაღაზიაში სასურველი ნივთი არ უყიდეთ და ბავშვი იატაკზე დაეცა? დაივიწყეთ გარშემომყოფთა მზერა და Anacan AI-ს გაუზიარეთ თქვენი წუხილი, რათა ასეთი კრიზისების მშვიდად მართვა შეძლოთ.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'ნუ შეგეშინდებათ დასვრის!', 'კინეტიკური ქვიშისა თუ სენსორული თამაშებისთვის საუკეთესო საშუალებები ახლავე აღმოაჩინეთ „რეკომენდებული პროდუქტების“ განყოფილებაში და სახლში გამოიწერეთ.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'უეცარი გაღვიძებები 🌌', 'შუაღამისას ტირილით იღვიძებს და ვერ მშვიდდება? ღამის შიშსა და კოშმარს შორის განსხვავების გასაგებად და სათანადო რეაგირებისთვის მისწერეთ Anacan AI ექსპერტს.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'კბილის ჯაგრისზე ბრძოლა დასრულდა 🪥', 'კბილის ჯაგრისის დანახვისთანავე პირს მჭიდროდ კეტავს? რეკომენდებულ პროდუქტებში ახლავე მოძებნეთ მუსიკალური და ერგონომიული მოდელები, რომლებიც ამ პროცესს გაამარტივებს და ყოველდღიურ რუტინას თამაშად აქცევს.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'რკინის ფარი 🥩', 'იმისთვის, რომ თქვენს აქტიურ პატარას ანემია არ განუვითარდეს და ენერგიული დარჩეს, ბავშვთა რეცეპტებში აღმოაჩინეთ ადვილად დასაღეჭი, გემრიელი ხორცისა და ბოსტნეულის გუფთები და გაუღვიძეთ მადა.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'გვერდების დახევის სურვილი 📖', 'კითხვის ნაცვლად წიგნის გვერდებს ხევს? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ მოაგვაროთ ეს პრობლემა კითხვის ჩვევის დაზიანების გარეშე.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'დედის ენერგეტიკული ბომბი ⚡', 'ამდენი სირბილისგან თვალები გეხუჭებათ? ტკბილეულის ნაცვლად ცილას მიაშურეთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან 5 წუთში მოსამზადებელი არაქისის კარაქის სმუზით ენერგია აღიდგინეთ.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'ჩრდილების ეშინია? 🌌', 'ოთახის ჩაბნელებისას კედელზე გაჩენილი ჩრდილები ბავშვს აშფოთებს? წარმოსახვის განვითარებამ შესაძლოა შიშები გამოიწვიოს. თეთრი ხმებიდან ჩართეთ დედის საშვილოსნოს ხმა და ოთახში უსაფრთხოების განცდა შექმენით.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'პირველი ნაბიჯი ტუალეტისკენ? 🧻', 'დილით საფენი სრულიად მშრალია და ბავშვი მოუსვენრადაა? ეს შესანიშნავი ნიშანია. მონიშნეთ ეს საფენების ტრეკერში და ბლოგების განყოფილებაში ქოთანზე მიჩვევისთვის მომზადების ეტაპების კითხვა დაიწყეთ.'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', '„არა!“ ქარიშხალი 🛑', 'თქვენს ყოველ შეთავაზებას ყვირილით აპროტესტებს? 2 წლის ასაკის კრიზისის ამ რთულ მომენტებში სიმშვიდის შესანარჩუნებლად და კრიზისული სიტუაციების თამაშად გადასაქცევად დაუყოვნებლივ მიიღეთ რჩევები ჩვენი Anacan AI ექსპერტისგან.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'ლოგიკის ძიებაში 🧩', 'მარტივი სათამაშოები უკვე მალე ბეზრდება. რეკომენდებული პროდუქტების განყოფილებაში აღმოაჩინეთ ხის ფაზლები და გეომეტრიული თამაშები, რომლებიც გონებას გაუვარჯიშებს და ყურადღების კონცენტრირებაში დაეხმარება.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'დაუსრულებელი სირბილი 🏃‍♂️', 'დაძინების ნაცვლად დივნებზე დახტის? ჩართეთ ძილის ტაიმერი, ჩაინიშნეთ პროცესის ხანგრძლივობა და გრაფიკის მიხედვით, შესაძლოა, საღამოს რუტინა უფრო ადრე დაიწყოთ.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', '5-წუთიანი ენერგია ⚡', 'შუადღისას ფეხზე მდგომსაც კი გეძინებათ? მოამზადეთ ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან კენკრიანი შვრია — ანტიოქსიდანტების ნამდვილი წყარო, რომელიც მყისიერად შეგმატებთ ძალას და ორგანიზმს გამოგიცოცხლებთ.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'სიტყვებიდან წინადადებებამდე 🗣️', 'უკვე დაიწყო 3-4-სიტყვიანი სახალისო წინადადებების შედგენა? ბლოგების განყოფილებაში გაეცანით საუკეთესო სახლის თამაშებსა და მარცვლების სავარჯიშოებს, რომლებიც ენის განვითარების ამ შესანიშნავ ნახტომს ხელს უწყობს.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'სასაცილო წინადადებები 🗣️', 'მისი საყვარელი შეცდომებით აწყობილი 3-4-სიტყვიანი წინადადებები ოქროს ფასია! არ გამოტოვოთ განვითარების ეს შესანიშნავი ეტაპი — დაუყოვნებლივ დაამატეთ ბავშვის ალბომში ხმოვანი ვიდეოს სახით და სამუდამოდ შეინახეთ ეს მოგონება.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'ენერგიას ვერ ხარჯავს და ყველაფერს ანადგურებს?', 'გახსენით დედებისთვის მეგობრული ადგილების რუკა, იპოვეთ უსაფრთხო პარკი რბილი საფარითა და სასრიალოთი და მიეცით ბავშვს თავისუფლად თამაშის საშუალება.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'ცილის მარაგის შემოწმება 🥚', 'სწრაფად მზარდი კუნთებისთვის ცილა აუცილებელია. კვების მონიტორინგის ხელსაწყოთი გამოთვალეთ დღევანდელი ნორმა (კვერცხი, ხორცი, პარკოსნები) და დეფიციტის შემთხვევაში მენიუ დაარეგულირეთ.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'თითებით ხატვის ხელოვნება! 🎨', 'ფერებით თამაშისას სახე მთლიანად მოითხვარა? გაბრაზების ნაცვლად, ეს მხიარული და შემოქმედებითი მომენტი ბავშვის ფოტოსესიის სახალისო სტიკერებით გააფორმეთ და ალბომში ატვირთეთ.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'ღამით გაღვიძებები დაბრუნდა? ⏱️', 'შუაღამისას ტირილით იღვიძებს და ჩაძინება უჭირს? გააანალიზეთ ძილის ტაიმერის სტატისტიკა. იქნებ დღის ძილი ზედმეტად გახანგრძლივდა და საღამოს რეჟიმს არღვევს?'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'კითხვა კი არა, მოყოლა 📖', 'საღამოს ზღაპრის დროს ბავშვი სურათების მიხედვით გიყვებათ ამბავს? ჩაიწერეთ ეს საოცარი წარმოსახვის მომენტი აუდიოდ.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'ძვლები მტკიცდება 🦴', 'სწრაფი განვითარებისთვის კალციუმია საჭირო. კვების კონტროლის ხელსაწყოთი გადაამოწმეთ, მიიღო თუ არა ბავშვმა დღეს საკმარისი ყველი და იოგურტი, და შეავსეთ დანაკლისი.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'გაზიარება არ სურს? 🧸', 'პარკში სხვა ბავშვების სათამაშოებისკენ გარბის, საკუთარს კი არავის აძლევს? ბლოგების განყოფილებაში გაიგეთ, როგორ ასწავლოთ 2 წლის ბავშვს მორიგეობით თამაში.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'სრულად გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს დაძინებას 40 წუთი დასჭირდა? გადახედეთ ძილის ტაიმერის გრაფიკს. იქნებ სწორედ ახლაა დრო, დღის ძილი 20 წუთით შეამციროთ და საღამოს დაძინების დრო გადმოწიოთ.'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'თქვენი პატარა ასლი 📸', 'როცა ოთახს გვით, ისიც ტილოთი წმენდს, ან თქვენნაირად დადის? მიბაძვის უნარი პიკზეა!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'უშაქრო, მაგრამ ტკბილი 🍪', 'დაემშვიდობეთ მაღაზიის ორცხობილებს! ბავშვების რეცეპტებში აღმოაჩინეთ ფინიკითა და ვაშლით მომზადებული სასარგებლო ტკბილეული, რომლის სახლში მომზადებასაც 10 წუთი სჭირდება, და გაახარეთ ბავშვი.'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'უეცარი აგრესია 🛑', 'გაბრაზებისას მეგობრებს ხელს ჰკრავს ან თქვენზე ხელს აღმართავს? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ შეგიძლიათ ამ ასაკისთვის დამახასიათებელი მძაფრი ემოციები მშვიდად და სწორად წარმართოთ.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'წელი გტკივათ? 🧘‍♀️', '13+ kq-იანი პატარას აწევისგან წელი გტკივათ? იზრუნეთ საკუთარ თავზე — ჯანსაღი რეცეპტებიდან მოამზადეთ კუნთების მომადუნებელი და ანთების საწინააღმდეგო ჯანჯაფილის ჩაი.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'სიჩუმე აშინებს?', 'ოთახში თეთრი ხმებიდან ჩართეთ ვენტილატორის ან თმის საშრობის ხმა და ნახეთ, როგორ უქმნის ის ბავშვს ძილისას სრულ უსაფრთხოების განცდას.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'გონების დაბინდვა 🌫️', 'ძალიან დაიღალეთ და ყველაფერი გავიწყდებათ? ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ომეგა-3-ით მდიდარი ნიგვზის წასახემსებელი და განიტვირთეთ განწყობის დღიურში თქვენი ფიქრების ჩაწერით.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'ქოთანზე უარს ამბობს? 🚽', 'ტუალეტში წასვლა არ სურს და ტირის? დაუყოვნებლივ ჰკითხეთ ჩვენს ექსპერტ ასისტენტს, Anacan AI-ს, საჭიროა თუ არა სწავლების დროებით შეჩერება ან სხვა მეთოდის მოსინჯვა.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'მხოლოდ ხილს ჭამს? 🍎', 'ცილოვან საკვებს ან ბოსტნეულს უარყოფს? კვების კონტროლის ხელსაწყოთი გამოთვალეთ, რამდენი სასარგებლო საკვები მიიღო დღეს და შექმენით გემრიელი კომბინაციები, მაგალითად, ხილიანი იოგურტი.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'დედის წყლის ბალანსი 💧', 'ბავშვის დევნაში წყლის დალევა დაგავიწყდათ? შესაძლოა, თავის ტკივილის მიზეზი სწორედ ეს იყოს. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ პიტნისა და ლიმონის დეტოქს წყალი და გამოცოცხლდით.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'დილის მონელების შემოწმება 💩', 'საფენის გამოცვლისას განავალს დააკვირდით. მყარი საკვების რაოდენობის მატებასთან ერთად ყაბზობის რისკიც იზრდება. ჩაინიშნეთ აპში და კვების კონტროლის ხელსაწყოს დახმარებით რაციონს დაუყოვნებლივ დაამატეთ ბოჭკოვანი საკვები (მსხალი, შვრია).'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'უეცარი ხმების შიში 🌪️', 'მტვერსასრუტის ან ბლენდერის ხმის ეშინია? ოთახში თეთრი ხმებიდან ჩართეთ თმის საშრობის ხმა — ასე შიშსაც შეუმცირებთ და ნელ-ნელა ძილისთვისაც მოამზადებთ.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'ფერების დახარისხება 🔴🔵', 'ლოგიკური აზროვნების განვითარების ხელშესაწყობად რეკომენდებულ პროდუქტებში მოძებნეთ ასაკის შესაბამისი გეომეტრიული თავსატეხები (puzzle) და ფერადი ხის სათამაშოები, რათა ბავშვის გონებრივი უნარები განავითაროთ.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'კბენა და დარტყმა 🦖', 'გაბრაზებისას უეცრად ხელს გარტყამთ ან გკბენთ? ბლოგების განყოფილებაში წაიკითხეთ ფსიქოლოგიური სტატიები იმის შესახებ, თუ როგორ შეცვალოთ რბილი მიდგომით ამ ასაკისთვის დამახასიათებელი აგრესიული ქცევა.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'ფეხსაცმელი უეცრად მოუჭირა? 👟', 'სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! წონის მონიტორინგის ხელსაწყოში შეიყვანეთ მისი ამჟამინდელი სიმაღლე და ფეხსაცმლის ზომა, რათა ფიზიკურ განვითარებას თვალი ადევნოთ.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'კუჭ-ნაწლავის სიგნალები 💩', 'საფენის გამოცვლისას შეიტანეთ ჩანაწერები. თუ შეკრულობის რისკი არსებობს, აუცილებლად გაეცანით აპში მოცემულ ბუნებრივი ბოჭკოთი მდიდარი საკვების რეკომენდაციებსა და ხილის წყლის რეცეპტებს.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'განშორების შიში? 🌌', 'როგორც კი ოთახიდან გახვალთ, თქვენს კვალდაკვალ ტირის? თეთრი ხმებიდან ჩაურთეთ დედის საშვილოსნოში არსებული ხმები, რათა ძველი, თბილი უსაფრთხოების განცდა დაუბრუნოთ და ძილისთვის განაწყოთ.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'ძვლები მტკიცდება 🦴', 'სწრაფი განვითარება კალციუმს მოითხოვს. კვების კონტროლის ხელსაწყოთი შეამოწმეთ, მიიღეთ თუ არა დღეს ყველისა და იოგურტის საჭირო რაოდენობა და დანაკლისი დაუყოვნებლივ შეავსეთ.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'თქვენ ისედაც შესანიშნავი ხართ 🌟', 'დღეს მთელი დღე მისდევდით და დაიღალეთ. გახსენით განწყობის დღიური, ჩაიწერეთ თუნდაც ყველაზე პატარა სიკეთე, რაც დღეს მისთვის გააკეთეთ, და საკუთარ თავს ფეხზე წამომდგარმა დაუკარით ტაში!'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'დაჟინებით ცდილობს, თვითონ ჭამოს 🥄', 'კოვზს გართმევთ და ირგვლივ ყველაფერს სვრის? ჩართეთ კვების ტაიმერი და გააანალიზეთ, რამდენ ხანს გრძელდება დამოუკიდებლობის ეს გამოცდა. დაყრილ საკვებს კი უბრალოდ ღიმილით შეხედეთ.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'ეს შარვალი არ მინდა! 👗', '„მე თვითონ ჩავიცვამ!“ — ასეთი სიჯიუტე უკვე დაიწყო? Anacan AI-სგან შეიტყვეთ, როგორ შეამციროთ დილის ჩაცმასთან დაკავშირებული კრიზისები და მისცეთ ბავშვს დამოუკიდებლად არჩევის უფლება.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'თქვენც გჭირდებათ მეგობრები 👯‍♀️', 'დაიღალეთ მხოლოდ ბავშვთან საუბრით? დედებისთვის მეგობრული სივრცეების დახმარებით იპოვეთ ცენტრები, სადაც სათამაშო ჯგუფებია, გაიცანით სხვა დედები და გაუზიარეთ ერთმანეთს გამოცდილება.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'წიგნი წასაკითხადაა და არა დასახევად 📖', 'საღამოს ზღაპრის დროს გვერდებს ხევს ან წაკითხვის საშუალებას არ გაძლევთ? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ მოაგვაროთ ეს პრობლემა ისე, რომ ბავშვს კითხვის ჩვევა არ დაუკარგოთ.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'უშაქრო, მაგრამ ტკბილი 🍪', 'დაემშვიდობეთ მაღაზიის ორცხობილებს! ბავშვების რეცეპტებში აღმოაჩინეთ ფინიკისა და შვრიის ჯანსაღი ტკბილეული, რომლის მომზადებასაც სახლში სულ 10 წუთი სჭირდება.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'მოდი, რეჟიმი სრულად გავაანალიზოთ ⏱️', 'საღამოს დაძინებას 40 წუთი დასჭირდა? გადახედეთ ძილის ტაიმერის გრაფიკს. იქნებ სწორედ ახლაა დრო, დღის ძილი 20 წუთით შეამციროთ და საღამოს დაძინების დრო გადმოსწიოთ.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'დაუსრულებელი კითხვები „რატომ?“ 🤔', 'კითხვების დასმა არ ბეზრდება? „ეს რა არის? რატომ?“ — ეს ეტაპი ოფიციალურად დაიწყო! ბლოგებიდან შეიტყვეთ, როგორ უპასუხოთ მოთმინებით ბავშვის ამ ცნობისმოყვარეობას.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'უშაქრო, მაგრამ ტკბილი 🍪', 'მაღაზიის ორცხობილებს დაემშვიდობეთ! ბავშვის რეცეპტებში აღმოაჩინეთ სასარგებლო ტკბილეული, რომლის მომზადებაც სახლში 10 წუთში შეგიძლიათ, და გაახარეთ პატარა.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'ცხელი ჩაი და სიმშვიდე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. ნუ იჩქარებთ სახლის საქმეების კეთებას! ჯანსაღი რეცეპტების მიხედვით მოამზადეთ განსაკუთრებული ყავა, წამოწექით დივანზე და უბრალოდ სიმშვიდით დატკბით.'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'დასუფთავების პატარა დამხმარე 🧹', 'როცა ოთახს გვით, ბავშვიც ტილოთი წმენდს თუ მტვერსასრუტს უტევს? ეს სახალისო მიბაძვა დაუყოვნებლივ გააფორმეთ ბავშვის ფოტოსესიის სტიკერებით და ალბომში ატვირთეთ.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'რკინის მარაგის შემოწმება 🥩', 'იმისთვის, რომ აქტიურ პატარას ანემია არ განუვითარდეს, კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა მან დღეს საკმარისი რკინა (ხორცი, პარკოსნები), და განაახლეთ მენიუ.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', '„არა!“ — თქმის ხელოვნება 🛑', 'ყველაფერზე „არას“ ამბობს? ეს თქვენთვის წინააღმდეგობის გაწევა კი არა, საკუთარი ინდივიდუალურობის აღმოჩენაა. დაუსვით არა დახურული კითხვები, არამედ შესთავაზეთ არჩევანი ორ ვარიანტს შორის — ასე მის სიჯიუტეს შეარბილებთ.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'ისევ დაგავიწყდათ?', 'სახლში გამოლეული ყველა წვრილმანის დამახსოვრებას ნუ ეცდებით — მაშინვე დაამატეთ საყიდლების სიაში და თქვენს პარტნიორს მიანდეთ.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'ხტუნვის ხელოვნება 🦘', 'დივნები უკვე აღარ ჰყოფნის! იპოვეთ უსაფრთხო დახურული გასართობი ცენტრი, სადაც ბატუტია, და დაეხმარეთ ენერგიის დახარჯვაში.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'პატარა მხატვარი მუშაობის პროცესშია 🎨', 'ფერებით თამაშისას მთელი სახე მოისვარა? გაბრაზების ნაცვლად დატკბით ამ სახალისო და შემოქმედებითი მომენტით.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'ღამით გაღვიძებები დაბრუნდა? ⏱️', 'შუაღამისას ტირილით იღვიძებს და ძლივს იძინებს? გააანალიზეთ ძილის ტაიმერის სტატისტიკა. მიზეზი შესაძლოა 2 წლის ასაკისთვის დამახასიათებელი ძილის რეგრესია ან კბილების ამოჭრა იყოს.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'ბუნებრივი დამამშვიდებელი 🍃', 'დღე ძალიან ხმაურიანი და აქტიური იყო? ჩააბნელეთ ოთახი, თეთრი ხმებიდან ჩართეთ ნაკადულის ჩუხჩუხი და გონება მასაც და საკუთარ თავსაც დაასვენებინეთ.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'როგორ არის ცილის მარაგი? 🍗', 'აქტიური კუნთებისთვის ცილა აუცილებელია. კვების კონტროლის ხელსაწყოთი შეაფასეთ მისი ყოველდღიური კვების ბალანსი და გაამდიდრეთ მენიუ.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'საყვარელი სიმღერები 🎤', 'ერთსა და იმავე სიმღერას განუწყვეტლივ მღერის ან ღიღინებს? აღბეჭდეთ რიტმის ეს შეგრძნება და მეტყველების განვითარება — ბავშვის ფოტოსესიის მუსიკალური სტიკერებით ალბომში დაამატეთ.'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'დღის ძილის წინააღმდეგ ამბოხი! 🛌', 'შუადღისას დაძინება არ სურს და გარბის? ჰკითხეთ Anacan AI-ს 2 წლის ბავშვების ძილის საჭიროებებისა და მშვიდი დროის (quiet time) მოწყობის საიდუმლოებების შესახებ.'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'გახდის სპეციალისტი! 🧦', 'ცდილობს, წინდები ან შარვალი დამოუკიდებლად გაიხადოს? ეს მოტორული უნარების შესანიშნავი განვითარებაა.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'ჯანჯაფილის ძალა 🫖', 'მთელი დღის განმავლობაში სირბილისგან წელი და ფეხები გტკივათ? ჯანსაღი რეცეპტებიდან მოამზადეთ კუნთების მომადუნებელი ჩაი და დაისვენეთ.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'ვაკვირდებით ფრინველებს 🕊️', 'სახლში ძალიან მოიწყინა? იპოვეთ გამწვანებული პარკი, ფრინველებს მარცვლეული დაუყარეთ და ბუნებისადმი მისი თანაგრძნობა გააძლიერეთ.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'ამბის მოფიქრების დროა 📖', 'წიგნების კითხვა მოგბეზრდათ? ჩააქრეთ შუქი, თეთრი ხმებიდან წვიმის ხმა ჩართეთ, სიბნელეში ერთად მოიგონეთ ზღაპრები და დაიძინეთ.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'ისევ პიურე? 🥣', 'მყარი საკვების ღეჭვა ეზარება და ისევ პიურეს ითხოვს? ბავშვების რეცეპტებში გაეცანით ადვილად დასაღეჭი, მაგრამ არა პიურეს კონსისტენციის მქონე საინტერესო კატლეტების რეცეპტებს.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'შუაღამისას ყვირილით იღვიძებს და არ ჩუმდება?', '2 წლის ასაკის კრიზისი ძილზეც მოქმედებს. ხმა ტირილის ანალიზს მოასმენინეთ და ზუსტად გაარკვიეთ, რა არის პრობლემა.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'მე თვითონ ჩამოვასხამ! 🥛', 'სურს, წყალი ჭიქაში თავად ჩამოასხას და ირგვლივ ყველაფერს ასველებს? ამ პრაქტიკული უნარის გასავითარებლად იხილეთ დაღვრისგან დაცული ჭკვიანი ჭიქები რეკომენდებულ პროდუქტებში.'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'კარს აჯახუნებს? 🚪', 'გაბრაზებისას კარს აჯახუნებს და ტირის? ასეთი ძლიერი ემოციური აფეთქებების სამართავად დაუყოვნებლივ დაუკავშირდით ჩვენს Anacan AI ექსპერტს და გაეცანით საჭირო სტრატეგიებს.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'ფეხზე დგომისას ნუ წაიხემსებთ 🍎', 'დააფასეთ საკუთარი თავი! ჯანსაღი რეცეპტებიდან მოამზადეთ ანტიოქსიდანტებით მდიდარი კენკრის სალათი.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'ტუალეტის ქაღალდის სიყვარული 🧻', 'სააბაზანოში ტუალეტის ქაღალდს რულონიდან შლის და ეთამაშება? ეს ინტერესი შესაძლებლობად აქციეთ — ახლავე დაიწყეთ ბლოგებში სტატიის კითხვა, თუ როგორ გადავიდეთ თამაშით ქოთნის გამოყენების სწავლებაზე.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'ერთი, ორი, სამი... 🔢', 'კიბეზე ასვლისას სხვადასხვა რამის დათვლას ცდილობს? ეს მათემატიკური განვითარების პირველი ნაპერწკლებია.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'ყველა კბილი ამოუვიდა? 🦷', 'ბოლო ძირითადი კბილები ამოსდის? კალციუმის საჭიროების დასაკმაყოფილებლად კვების კონტროლის ხელსაწყოს მეშვეობით აუცილებლად შეამოწმეთ, რამდენი იოგურტი და ყველი მიიღო დღეს.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'საძინებელში ძალიან ცხელა? 🌡️', 'საწოლში ბევრს ტრიალებს და ოფლიანობს? შეამოწმეთ ოთახის ტემპერატურა, ჩართეთ ძილის ტაიმერი და თეთრი ხმებიდან ვენტილატორის ხმით ოთახში სიგრილის შეგრძნება შექმენით.'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'თქვენს კვალდაკვალ ტირის? 🚪', 'ოთახიდან გასვლისასაც კი მოგყვებათ და ყვირის? Anacan AI-ს ჰკითხეთ, როგორ გაუმკლავდეთ განშორების შფოთვის ამ ახალ ტალღას რბილად.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'ლოგიკა მოქმედებაშია 🧩', 'გეომეტრიული ფიგურების შეხამებაში უკვე დაოსტატდა? აღმოაჩინეთ რეკომენდებული პროდუქტების განყოფილება უფრო რთული თამაშებისთვის, რომლებიც მის გონებას კიდევ უფრო მეტ გამოწვევას შესთავაზებს.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'კბილის პასტის არჩევა 🪥', 'უკვე იწყებს წყლის გადმოფურთხების სწავლას? აუცილებლად წაიკითხეთ ბლოგების განყოფილებაში ჩვენი სამეცნიერო სტატია ფტორიანი და ფტორის გარეშე კბილის პასტის არჩევის შესახებ.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'ტალახის ნამცხვრები! 🧁', 'ეზოში მიწით თამაში სურს? მიეცით დასვრის უფლება! ბავშვის ფოტოსესიით უკვდავყავით ეს შესანიშნავი მომენტები, რომლებიც სენსორულ განვითარებას უწყობს ხელს.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'გონება გადატვირთეთ 🧘‍♀️', 'გრძნობთ, რომ ყველაფერი ერთდროულად დაგატყდათ თავს? გახსენით განწყობის დღიური და 3 წუთის განმავლობაში შეუჩერებლად წერეთ, რას გრძნობთ. წერა სტრესს დაუყოვნებლივ ამცირებს.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'გრავიტაციის ტესტი! 🍎', 'საჭმლის ან სათამაშოების მაღლიდან ძირს გადაყრა უყვარს? ამ ფიზიკური აღმოჩენების შეჩერების ნაცვლად, Anacan AI-სგან გაიგეთ, როგორ მიმართოთ ისინი სხვა მიმართულებით.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'ბოჭკოს ნაკლებობა? 💩', 'განავალი გამაგრდა და ყაბზობა აწუხებს? ჩაინიშნეთ საფენის ტრეკერში და კვების კონტროლის ხელსაწყოს მეშვეობით მენიუს დაუყოვნებლივ დაამატეთ შავი ქლიავი ან შვრია.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'პირველი მეგობარი თამაშისთვის 👯‍♂️', 'პარკში სხვა ბავშვთან თამაშს გამუდმებით ცდილობს? დედებისთვის მეგობრულ სივრცეებში მოძებნეთ საბავშვო კაფეები, რომლებიც სოციალიზაციის ამ ახალ ეტაპს ხელს უწყობს.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'ძილის ტაიმერის ანალიზი ⏱️', 'საღამოობით ძალიან გვიან იძინებს? გადახედეთ ძილის ტაიმერის გრაფიკს. დღის ძილის შემცირებისა და საღამოს დაძინების დროის გადმოწევის დრო ახლოვდება.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'ფეხსაცმელი მოულოდნელად მოუჭირა? 👟', 'სირბილისას ხშირად ბორძიკობს? შესაძლოა, ფეხი გაეზარდა! განვითარების ტრეკერში შეიყვანეთ მისი ამჟამინდელი სიმაღლე და ფეხსაცმლის ზომა, რათა ფიზიკურ განვითარებას თვალი ადევნოთ.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'ყავა თუ წყალი? 💧', 'ნუ ეცდებით დაღლილობის კოფეინით შენიღბვას! ქალებისთვის განკუთვნილ ჯანსაღ რეცეპტებში აღმოაჩინეთ ენერგიის მომცემი ცილოვანი და ხილის დეტოქს-სასმელები.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'პატარა მზარეული სამზარეულოში 👩‍🍳', 'ბავშვის რეცეპტებიდან უშაქრო ორცხობილის ცომი ერთად მოზილეთ. ასე მისი მოტორული უნარებიც განვითარდება და საკუთარი ხელით მომზადებულსაც მადიანად შეჭამს.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'პატარა ალპინისტი 🧗', 'ავეჯზე აძრომა უკვე ჰობად იქცა? სახლის მაქსიმალური უსაფრთხოებისთვის გადახედეთ სპეციალურ დამცავ საშუალებებს რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'მოჩუხჩუხე წყალი 🌊', 'ძალიან მოუსვენარი და სირბილით სავსე დღე იყო? ჩააქრეთ მკვეთრი განათება, თეთრი ხმებიდან მდინარის ჩუხჩუხი ჩართეთ და უბრალოდ ორივენი სიმშვიდეში ჩაიძირეთ.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'ტაში დაუკარით საკუთარ თავს 🌟', 'დღის კრიზისების გარეშე დასრულება შეძელით? თქვენ გარეშე ასეთი განვითარება შეუძლებელი იქნებოდა. გახსენით განწყობის დღიური და თავდადებისთვის საკუთარ თავს დიდი მადლობა გადაუხადეთ!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'სათამაშოებისადმი მზრუნველობა 🧸', 'დათუნიას იავნანას უმღერის ან საბანს აფარებს? ეს ძლიერი ემპათიის განვითარების ნიშანია. ბავშვის ალბომში ხმოვან ვიდეოდ დაამატეთ და მისი მზრუნველობა აღბეჭდეთ.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'სიტყვების მარაგის სწრაფი ზრდა 🗣️', 'როგორია მისი სიტყვების მარაგი? ბლოგების განყოფილებაში გაეცანით ამ თვისთვის შესაბამის მეტყველების განვითარების ნორმებს და აღმოაჩინეთ განვითარების ხელშემწყობი თამაშები სახლისთვის.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'საკვები ფორმებს იძენს ⭐️', 'ჩვეულებრივ დაჭრილ ხილს არ ჭამს? ბავშვების რეცეპტებში ნახეთ ვარსკვლავის ან ცხოველის ფორმის სახალისო გაფორმებები და კვება ვიზუალურ თამაშად აქციეთ.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'იმალება, როცა კუჭში გადის? 🙈', 'ფარდის უკან ან კუთხეში განმარტოვდება, როცა კუჭში გადის? ეს ქოთნისთვის მზადყოფნის ერთ-ერთი ყველაზე მნიშვნელოვანი ფსიქოლოგიური ნიშანია! მონიშნეთ ეს საფენის ტრეკერში და ბლოგებში წაიკითხეთ ქოთნის მიჩვევის შესახებ სტატიები.'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'წელი გტკივათ? 🧘‍♀️', 'ბავშვის სიმძიმის მატებასთან ერთად მისი ხელში აყვანისგან კუნთები დაგეძაბათ. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ანთების საწინააღმდეგო ჯანჯაფილის ჩაი, წამოწექით და საკუთარ თავს დრო დაუთმეთ.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', '„მე თვითონ ჩავიცვამ“ ხელოვნება 👕', 'ცდილობს, შარვალი თავზე ჩამოიცვას, მაისური კი — ფეხებზე? დამოუკიდებლობის მოპოვების ეს სასაცილო მცდელობა არ გამოტოვოთ! მაშინვე გააფორმეთ ბავშვის ფოტოსესიის მხიარული სტიკერებით და ალბომში ატვირთეთ.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'გუბეების აღმოჩენა 🌧️', 'წვიმის შემდეგ სახლში ჯდომა არ შეიძლება! დედებისთვის მეგობრულ ადგილებში იპოვეთ ახლომდებარე პარკი, ჩააცვით რეზინის ჩექმები და მიეცით ტალახში ხტუნვის უფლება.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'ძილის დრო იცვლება ⏱️', 'დღისით დაძინებაზე უარი თქვა? ჩართეთ ძილის ტაიმერი და საღამოს რუტინა 30 წუთით ადრე დაიწყეთ, რათა ზედმეტად არ გადაიღალოს და ემოციური კრიზისი არ ჰქონდეს.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'ნატიფი მოტორიკის განვითარება 🧩', 'მან მარტივი ფაზლები უკვე ზეპირად იცის. რეკომენდებული პროდუქტების განყოფილებაში აღმოაჩინეთ უფრო რთული, მრავალნაწილიანი ხის თავსატეხები, რომლებიც მის გონებრივ შესაძლებლობებს მეტად განავითარებს.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'იატაკზე გაწოლით ტირილის შეტევა 🛑', 'საჯარო ადგილას იატაკზე წვება და ყვირის? გარშემომყოფთა მზერას ნუ მიაქცევთ ყურადღებას! Anacan AI-ს გაუზიარეთ თქვენი წუხილი და ისწავლეთ, როგორ მართოთ მშვიდად ასეთი ძლიერი ემოციური აფეთქებები.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'წიგნი წასაკითხადაა და არა დასახევად 📖', 'საღამოს ზღაპრის დროს ფურცლებს ხევს? ბლოგების განყოფილებაში წაიკითხეთ, როგორ მიაპყროთ მისი ყურადღება ზღაპარს ისე, რომ კითხვის ჩვევის ჩამოყალიბებას ხელი არ შეუშალოთ.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'კალციუმის წყარო მხოლოდ რძე არ არის 🧀', 'რძის დალევაზე უარს ამბობს? კალციუმი ძვლებისთვის აუცილებელია. კვების კონტროლის ხელსაწყოთი გამოთვალეთ, რამდენი ყველი, იოგურტი ან ბროკოლი მიიღო დღეს და შეავსეთ დანაკლისი.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'ტანსაცმლის დაკეცვის თამაში 🧺', 'როცა ტანსაცმელს ალაგებთ, მასაც სურს დახმარება? წინდების დაწყვილება მიანდეთ! ბლოგებში წაიკითხეთ, როგორ განუვითაროთ პასუხისმგებლობის გრძნობა თამაშით.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'ბნელი ოთახის შიში 🌌', 'შუქის ჩაქრობისას ტირის? წარმოსახვის განვითარებასთან ერთად შიშებიც იმატებს. თეთრი ხმების განყოფილებაში ჩაურთეთ დედის საშვილოსნოში მოსმენილი ხმა და დაუბრუნეთ ნაცნობი უსაფრთხოების განცდა.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'როგორ ჩნდება წიგნებისადმი ინტერესი? 📖', 'კითხვის ნაცვლად გვერდების დახევა სურს? ჰკითხეთ Anacan AI-ს პრაქტიკული რჩევები, როგორ დააინტერესოთ ზღაპრით ისე, რომ კითხვის ჩვევის ჩამოყალიბებას ხელი არ შეუშალოთ.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'რკინის საიდუმლო: ვიტამინი C 🍋', 'ორგანიზმში რკინის უკეთ შესათვისებლად გადახედეთ კვების კონტროლის ხელსაწყოში მოცემულ დღევანდელ მენიუს. ხორციან კერძს აუცილებლად დაუმატეთ უხვად ლიმონიანი ან პომიდვრიანი სალათი.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'დედიკოს ყავის დრო ☕', 'საშინაო საქმეები გვერდზე გადადეთ და ამოისუნთქეთ! დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფე საბავშვო სათამაშო კუთხით, მშვიდად მიირთვით ცხელი ყავა და გაიცანით სხვა დედები.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'ღამის ხმა: მატარებელი 🚂', 'დღის ხმაურის შემდეგ მოულოდნელი სიჩუმე ბავშვს აწუხებს? სახლში სხვა ხმების დასაფარად თეთრი ხმებიდან ჩართეთ მატარებლის მონოტონური ხმა და ბავშვი ძილისთვის განაწყვეთ.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'ფეხსაცმელი უცებ დაუპატარავდა? 👟', 'სირბილისას ებორძიკება ან ფეხსაცმლის გახდა სურს? შესაძლოა, ფეხი გაეზარდა! განვითარების მონიტორში შეიყვანეთ მიმდინარე ზომები და დაუყოვნებლივ გადაამოწმეთ ფიზიკური განვითარების დინამიკა.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'უშაქრო ენერგეტიკული ბურთულები 🍪', 'მაღაზიის ტკბილეულს დაემშვიდობეთ! ბავშვის რეცეპტებში აღმოაჩინეთ ფინიკისა და შვრიის სასარგებლო, გემრიელი წასახემსებელი, რომელიც სულ რაღაც 10 წუთში მზადდება, და გაახარეთ ბავშვი.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'უეცარი აგრესია 🦖', 'გაბრაზებისას მეგობრებს ხელს ჰკრავს ან თქვენზე ხელს აღმართავს? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ მართოთ ამ ასაკისთვის დამახასიათებელი აგრესიული ემოციები რბილად და სწორად.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'ნუ დაივიწყებთ საკუთარ თავს ⚡', 'შუადღისას ძალა გეცლებათ? ტკბილეულს ნუ მიეძალებით! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ენერგიის სწრაფად აღმდგენი, ცილებით მდიდარი არაქისის კარაქის სმუზი და ძალები აღიდგინეთ.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'ძილის ანალიზი ტაიმერით ⏱️', 'საღამოს ჩაძინებას ძალიან დიდი დრო დასჭირდა? ჩართეთ ძილის ტაიმერი და თვალყური ადევნეთ გრაფიკს. გააანალიზეთ, ბავშვმა საკმარისი ენერგია ვერ დახარჯა თუ ზედმეტად გადაიღალა.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'ცხელი ჩაი და სიჩუმე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. ახლა საოჯახო საქმეებს ხელი არ ახლოთ! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მელისის ჩაი მოამზადეთ და დღის დაღლილობა თბილ ორთქლს გაატანეთ.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'როგორია ცილის მარაგი? 🍗', 'კუნთებს, რომლებიც გამუდმებით დარბიან და ხტუნავენ, ცილა აუცილებლად სჭირდებათ. კვების კონტროლის ხელსაწყოთი შეაფასეთ ბავშვის ყოველდღიური კვების ბალანსი და გაამდიდრეთ მისი მენიუ.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'დაუსრულებელი „რატომ?“ კითხვები 🤔', 'ეს რა არის? რატომ არის ასე? ეს ეტაპი ოფიციალურად დაიწყო! ბლოგებიდან შეიტყვეთ, როგორ უპასუხოთ მოთმინებითა და ბავშვის განვითარებისთვის სასარგებლოდ მის უსასრულო ცნობისმოყვარეობას.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'ძველი ხმის ჩანაწერები 🎤', 'როცა ბავშვი დაიძინებს, გახსენით ბავშვის ალბომი და მოუსმინეთ იმ საყვარელ ხმებს, რომლებსაც ის რამდენიმე თვის წინ გამოსცემდა. იამაყეთ იმით, თუ რამდენად სწრაფად იზრდება!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', '„ჩემია!“ ეტაპი 🧸', 'პარკში სათამაშოს არავის აძლევს? ჰკითხეთ Anacan AI-ს და გაიგეთ, როგორ ასწავლოთ 2.5 წლის ასაკს მიახლოებულ ბავშვს მორიგეობით თამაში.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'შოუ სარკის წინ 🤪', 'მანჭავს სახეს, საკუთარ თავს უყურებს და ხმამაღლა იცინის? საკუთარი თავის აღმოჩენის ეს სახალისო მომენტი მაშინვე ვიდეოდ დაამატეთ ბავშვის ალბომში და დღის სტრესი მოიხსენით.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'თქვენც გჭირდებათ შესვენება ☕', 'გადით სახლიდან და ცოტა ამოისუნთქეთ! დედებისთვის მეგობრულ სივრცეებში იპოვეთ ახლომდებარე კაფე საბავშვო კუთხით, მშვიდად მიირთვით ცხელი ყავა და გაიცანით სხვა დედები.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'იამაყეთ საკუთარი თავით 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღე სწავლობს, და ყოველი თავდაჯერებული ნაბიჯი თქვენი თავდადების შედეგია. გახსენით განწყობის დღიური და დღეს ისეთი ჩანაწერი გააკეთეთ, რომლისთვისაც საკუთარ თავს ფეხზე წამოუდგებით და ტაშს დაუკრავთ!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'საჭმელს ატრიალებს და ისვრის? 🥣', 'მაგიდასთან ჯდომა მობეზრდა და კოვზს ისვრის? ჩართეთ კვების ტაიმერი, პროცესის ხანგრძლივობა გრაფიკის დახმარებით გააანალიზეთ და საკვების ძალით მიცემას სრულად მოერიდეთ.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'მხოლოდ ერთი ფერის საკვები? 🟡', 'მხოლოდ ყვითელი ფერის საკვებს (კარტოფილს, მაკარონს, ბანანს) ითხოვს? კვების კონტროლის ხელსაწყოთი გააანალიზეთ მისი მენიუ და ბავშვის რეცეპტებში აღმოაჩინეთ ფერადი ალტერნატივები დამალული ბოსტნეულით.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', 'განსხვავება „მე“-სა და „შენ“-ს შორის 🗣️', 'უკვე აღარ საუბრობს საკუთარ თავზე მესამე პირში და ამბობს „მე“? ამ მნიშვნელოვანი შემეცნებითი ნახტომის მხარდასაჭერად დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ წარმართოთ დიალოგი სწორად.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'კიდევ ერთი ზღაპარი! 📚', 'დასაძინებლად წასვლის თავიდან ასაცილებლად გამუდმებით ახალ მიზეზებს იგონებს? ჩართეთ ძილის ტაიმერი, დაიცავით საზღვრები და თეთრი ხმებიდან ოკეანის ტალღების ხმა ჩართეთ, რათა ოთახში სიმშვიდე დაისადგუროს.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'ხტომის ხელოვნება 🦘', 'კიბიდან ან დივნიდან გადმოხტომას ცდილობს? მოტორული უნარების განვითარებისთვის უსაფრთხო სივრცე სჭირდება. დედებისთვის მეგობრულ ადგილებში იპოვეთ დახურული გასართობი ცენტრი ბატუტით და მისი ენერგია სასარგებლოდ მიმართეთ.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'თქვენც გაქვთ ელემენტი 🔋', 'მთელი დღე „არას“ თქმითა და ბავშვის დევნით დაიღალეთ? განწყობის დღიურში გადმოიტანეთ ყველაფერი, რაც გულს გიმძიმებთ. გახსოვდეთ, საკუთარი თავისთვის დროის დათმობა ფუფუნება კი არა, საჭიროებაა.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'ფეხსაცმელები უკუღმა აცვია! 👟', 'მარჯვენა ფეხსაცმელი მარცხენა ფეხზე ჩაიცვა, მარცხენა კი — მარჯვენაზე და გახდაც არ სურს? დამოუკიდებლობის ეს სახალისო მცდელობა ბავშვის ფოტოსესიის მხიარული სტიკერებით გააფორმეთ და ალბომის ყველაზე სასაცილო კადრად აქციეთ.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'მაკარონის სიყვარული 🍝', 'ბავშვი უკვე რამდენიმე დღეა ერთსა და იმავე კერძს ითხოვს? საკვების არჩევითობა პიკს აღწევს. ჯანსაღ რეცეპტებში მოძებნეთ სახალისო სოუსები, რომლებშიც ბოსტნეულის დამალვას შეძლებთ.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'სიჩუმის გემო 🤫', 'ოთახში როგორც იქნა სიჩუმემ დაისადგურა. საქმეებს თავი დაანებეთ და სიბნელეში ჩამოჯექით. ჩართეთ ხმის საზომი, გაზომეთ ამ სიჩუმის დონე და გონება დაასვენეთ.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', '800 შევასრულეთ!🚀', 'ახლა მეტი კითხვის, მეტი მოძრაობისა და მეტი ინდივიდუალურობის დროა. ეს ახალი და ამაღელვებელი ეტაპი ღრმად ჩასუნთქვით დაიწყეთ.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'მითები იდეალური დედის შესახებ 🛑', 'თავს იდანაშაულებთ, რადგან დღეს ბავშვმა ეკრანთან დიდი დრო გაატარა? დაივიწყეთ ინტერნეტში ნანახი იდეალური დედები. თქვენ თქვენს რეალობაში სრულყოფილი ხართ.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'მამის სათამაშო მოედანი 👨‍👧', 'მოთმინება გეწურებათ? ოთახის კარი დახურეთ და ბავშვი მამასთან მარტო დატოვეთ. დაე, ამ საღამოს სახლში თამაშებს მამა გაუძღვეს.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', '„რატომ?“ პერიოდი 🤔', 'ყველაფერზე გეკითხებათ: „ეს რატომ არის ასე?“ მისი ტვინი ღრუბელივით ისრუტავს ინფორმაციას. მოიკრიბეთ მოთმინება და მოკლე, ლოგიკური პასუხები გაეცით.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'ბანანი თუ ტელეფონი? 🍌', 'ბანანი ან პულტი ყურთან მიაქვს და წარმოსახვით საუბრებს მართავს? ეს წარმოსახვითი თამაშების მწვერვალია! ეს ოქროს წამი ხმოვანი ვიდეოს სახით დაუყოვნებლივ დაამატეთ ბავშვის ალბომში და სამუდამოდ შეინახეთ მოგონებებში.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'ბნელი ოთახის შიში 🌌', 'შუქის ჩაქრობისას ოთახში არსებულ ნივთებს ურჩხულებად აღიქვამს? წარმოსახვის განვითარებასთან ერთად შიშებიც ჩნდება. თეთრი ხმების განყოფილებიდან ჩაურთეთ დედის საშვილოსნოში მოსმენილი ხმა და დაუბრუნეთ მისთვის ნაცნობი, სრულყოფილი უსაფრთხოების განცდა.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'რკინისა და ენერგიის საიდუმლო 🥩', 'აქტიურ პატარას ანემია რომ არ განუვითარდეს, კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი რკინა (ხორცი, ოსპი, ისპანახი) და მენიუ C ვიტამინითაც გაამდიდრეთ.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'სითხის მიღება და ყაბზობა 💧', 'ბევრს დარბის, მაგრამ ცოტა წყალს სვამს? საფენის გამოცვლისას დააკვირდით განავალს. თუ ყაბზობის რისკი არსებობს, მონიშნეთ ეს აპში და კვების კონტროლის ხელსაწყოს დახმარებით დაუყოვნებლივ დაამატეთ ბოჭკოვანი საკვები (მსხალი, შვრია).'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'ფერებისა და ფორმების ოსტატი 🔴🟩', 'რგოლებს, ღილაკებს ან სათამაშოებს ფერების მიხედვით აჯგუფებს? რეკომენდებული პროდუქტების განყოფილებაში ახლავე აღმოაჩინეთ ლოგიკური აზროვნების განმავითარებელი ხის ფაზლები, რომლებიც მის გონებას კიდევ უფრო ავარჯიშებს.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'ღამის შიში თუ კოშმარი? 🤖', 'შუაღამისას ტირილით იღვიძებს და ვერ მშვიდდება? მათ შორის განსხვავების გასაგებად და სწორი ფსიქოლოგიური მიდგომის შესარჩევად გაეცანით ჩვენს სამეცნიერო სტატიებს ბლოგების განყოფილებაში.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'რთული დღე იყო? 📝', 'დღევანდელი სტრესის შესახებ განწყობის დღიურში დაწერეთ და გული მოიოხეთ. ყველა დედა გადის ასეთ რთულ მომენტებს — თქვენ მარტო არ ხართ.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'წარმოსახვითი თამაშები 🧸', 'მანქანებს ალაპარაკებს, სათამაშო დათუნიას აჭმევს? მისი წარმოსახვა სწრაფად ვითარდება. განვითარების ტრეკერში აღნიშნეთ ეს კოგნიტიური ნახტომი და თამაშში ჩაერთეთ.'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'სახლში მოიწყინეთ?', 'დედებისთვის მეგობრულ ადგილებში აღმოაჩინეთ კაფე, რომელსაც საბავშვო სათამაშო კუთხე აქვს. ბავშვმა ითამაშოს, თქვენ კი ყავა ჯერ კიდევ ცხელი მიირთვით.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'მუსიკალური სიმშვიდე 🎶', 'საღამოს ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზაა, ჩართოთ მისი საყვარელი მელოდია, გულში ჩაიკრათ და ერთად ნელა იცეკვოთ.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'უცნაური ამინდის გამო სახლში დარჩით?', 'ამინდისა და ჩაცმის ინსტრუმენტი მყისიერად გაჩვენებთ ტემპერატურას, რომელსაც ფანჯრიდან ვერ შეამჩნევთ — მოემზადეთ და პარკში გაისეირნეთ.'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'მე თვითონ ჩავიცვამ 👕', 'შარვალი თავზეც რომ ჩამოიცვას, ჩაცმის მცდელობაში ხელს ნუ შეუშლით. დამოუკიდებლობის სურვილი პიკს აღწევს! მიეცით დრო და საშუალება, თავად სცადოს.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'თვითონ დავისხამ! 🥛', 'სურს, წყალი ჭიქაში თვითონ დაისხას და ყველაფერს ასველებს? რეკომენდებულ პროდუქტებში მოძებნეთ ჭკვიანი საბავშვო ჭიქები, რომლებიც პრაქტიკული ცხოვრებისეული უნარების განვითარებას უწყობს ხელს და სითხეც არ იღვრება — ასე საქმეს გაიმარტივებთ.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'პატარა მზარეული სამზარეულოში 👩‍🍳', 'საბავშვო რეცეპტებიდან შეარჩიეთ უშაქრო ბანანის ორცხობილა და ცომი ერთად მოზილეთ. ასე ბავშვს მოტორული უნარებიც განუვითარდება, გაერთობა კიდეც და საკუთარი ხელით მომზადებულსაც მადიანად მიირთმევს.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'ცხელი ჩაი და სიმშვიდე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. ნუ იჩქარებთ საოჯახო საქმეების კეთებას! ჯანსაღი რეცეპტებიდან შეარჩიეთ მელისას ან გვირილის ჩაი, მოადუღეთ, დივანზე წამოწექით და უბრალოდ სიმშვიდით დატკბით.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'შენიც ჩემია! 🧸', 'პარკში სხვისი სათამაშოს დაბრუნება არ სურს? ეს ეგოცენტრიზმის პერიოდია. გაზიარება იძულებით კი არა, რიგრიგობით თამაშით ასწავლეთ.'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'წიგნის ჭია 📖', 'მოაქვს საყვარელი ზღაპრების წიგნი და ერთსა და იმავე გვერდს მრავალჯერ გაკითხებთ? გამეორება მისთვის სწავლის საშუალებაა. მოთმინებით წაუკითხეთ კიდევ ერთხელ.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'საოჯახო საქმეები მოიცდის 🛑', 'იატაკი არ მოგიწმენდიათ? იყოს ასე. ჭუჭყიანი სახლის დალაგება შეიძლება, მაგრამ გადაღლილი დედის ძალების აღდგენას დიდი დრო სჭირდება. დივანზე წამოწექით და სიმშვიდეს მოუსმინეთ.'),
  ('04312503-34be-494a-8896-38312d406a86', 'წარმოსახვითი ჩაის სერვიზი 🫖', 'წარმოსახვითი ჭიქებით ჩაის დალევას გაიძულებთ თქვენ ან თავის სათამაშოებს? როლური თამაშები გონებრივი განვითარების მწვერვალია!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'დედის კისრის ტკივილი 🧘‍♀️', 'იატაკზე თამაშისა და ბავშვის ხელში აყვანისგან კისერი და წელი დაგეჭიმათ? დაისვენეთ და ჯანსაღი რეცეპტებიდან მოამზადეთ ჯანჯაფილიანი მწვანე ჩაი, რომელიც კუნთებს ადუნებს და ანთების საწინააღმდეგო მოქმედება აქვს.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'ურჩხული საწოლის ქვეშ? 👾', 'წარმოსახვის განვითარებასთან ერთად შიშებიც რეალური ხდება. თუ ბავშვს ჩრდილების ეშინია, ჩააქრეთ მკვეთრი განათება და თეთრი ხმებიდან ჩაურთეთ დედის საშვილოსნოს ხმა (გულისცემა), რათა მისთვის ნაცნობი, სრული უსაფრთხოების განცდა დაუბრუნოთ.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'რიგისთვის დავა სასრიალოზე 🛑', 'პარკში სხვა ბავშვებისთვის რიგის დათმობა არ სურს? აუცილებლად წაიკითხეთ ბლოგების განყოფილებაში სოციალიზაციის შესახებ სტატიები, რათა გაიგოთ, როგორ ჩამოუყალიბოთ რიგისა და მოთმინების ცნებები 2.5 წლის ასაკისთვის.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'თავს ნუ დაიდანაშაულებთ 💖', 'დღეს ბავშვის სიჯიუტემ მოთმინება დაგაკარგვინათ და ხმას აუწიეთ? თქვენი შინაგანი განცდები განწყობის დღიურს გაუზიარეთ. თქვენ რობოტი არ ხართ და არც ვალდებული ხართ, სრულყოფილი იყოთ!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'უკუღმა ჩაცმის მოდა! 👕', 'შარვალი უკუღმა ჩაიცვა, ფეხსაცმელი არასწორ ფეხებზე მოირგო და გახდა არ სურს? ნუ ჩაერევით დამოუკიდებლობის მოპოვების ამ სახალისო მცდელობაში!'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'დღის ძილის წინააღმდეგ ამბოხი! ⏱️', 'შუადღის ძილზე უარი თქვა და ახლა ზედმეტად გადაღლილია? გადახედეთ ძილის ტაიმერის გრაფიკს და საღამოს რუტინა სულ მცირე 40 წუთით ადრე დაიწყეთ, რათა ღამის შიშები თავიდან აიცილოთ.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'განავალს იკავებს? 💩', 'ქოთანზე მიჩვევის პერიოდში ფეხზე დგება და კუჭში გასვლას იკავებს? ამან შესაძლოა ფსიქოლოგიური შეკრულობა გამოიწვიოს. მონიშნეთ ეს საფენის ტრეკერში და მენიუში დაუყოვნებლივ დაამატეთ გარგარი ან შვრია.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'ოთხ კედელში ყოფნა მობეზრდა 🌳', 'სახლში ენერგიას ვერ ხარჯავს და ყველაფერს აქეთ-იქით ისვრის? გახსენით დედებისთვის მეგობრული ადგილების რუკა, იპოვეთ უსაფრთხო პარკი რბილი საფარითა და სასრიალოთი და მიეცით ბავშვს სუფთა ჰაერზე თავისუფლად თამაშის საშუალება.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'სიმაღლისა და წონის ნახტომი! 📏', 'ჩაცმისას შენიშნეთ, რომ მაისურები დაუპატარავდა ან ფეხსაცმელი უჭერს? წონის ტრეკერში შეიყვანეთ მიმდინარე სიმაღლე და ზომები და სიამაყით დააკვირდით, როგორ მიიწევს ზემოთ განვითარების მრუდი.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'შეამოწმეთ რკინის მარაგი 🥩', 'ფერმკრთალია ან სწრაფად იღლება? კვების კონტროლის ხელსაწყოში შეამოწმეთ დღეს მიღებული რკინის რაოდენობა და შეწოვის გასაუმჯობესებლად ხორცთან ერთად აუცილებლად მიეცით C ვიტამინის შემცველი საკვები (ლიმონი, პომიდორი).'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'თქვენც გჭირდებათ მეგობარი 👯‍♀️', 'მთელი დღე მხოლოდ ბავშვურ ენაზე ლაპარაკმა დაგღალათ? დედებისთვის მეგობრულ ადგილებში იპოვეთ საბავშვო კაფეები, სადაც ბევრი დედა იკრიბება, და საკუთარ თავსაც შეუქმენით სოციალიზაციის შესაძლებლობა.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'სასწრაფოდ საყიდლები 🛒', 'შამპუნი, ბავშვის საფენები ან შვრია გაგითავდათ? ნუ დაიმახსოვრებთ — ჩაწერეთ საყიდლების სიაში და თქვენს პარტნიორს გაუზიარეთ.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'როცა სასურველს ვერ იღებს, იატაკზე წვება და ყვირის?', 'პატარების ემოციური აფეთქებები გრძელდება. მშვიდად დარჩით მის გვერდით და როცა დამშვიდდება, ჩაეხუტეთ.'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'ზღაპრის გმირი 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი ბავშვი იქნება: ღამის მოყვარული მამაცი პატარა.'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', '„მიყვარხარ“ ჩახუტება 🫂', 'უეცრად მოდის, კისერზე გეხვევათ ან სახეზე გეფერებათ? ის უკვე ფიზიკურად გამოხატავს თავის სიყვარულს. დატკბით ამ მომენტით.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'ნივთების თავის ადგილზე მოთავსება 🧸', 'სათამაშოს ყუთში აგდებს და ისევ იღებს? მასში „შიგნით“ და „გარეთ“ ცნებების გაგება ყალიბდება. აუცილებლად მონიშნეთ ეს შემეცნებითი უნარი განვითარების ტრეკერში.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'კითხვა გაქვთ? 🤖', 'როგორი უნდა იყოს ბავშვის მეტყველება 2 წლის შემდეგ? ნუ დაიკარგებით ინტერნეტში — პირდაპირ მისწერეთ Anacan AI-ს და მიიღეთ მეცნიერულ მტკიცებულებებზე დაფუძნებული პასუხი.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'გრძელი წინადადებები იწყება! 🗣️', 'უკვე 4-5 სიტყვას აერთიანებს და სახალისო ამბავს ჰყვება? ეს ლექსიკური მარაგის ნამდვილი აფეთქებაა! არ გამოტოვოთ ეს ძვირფასი მომენტი — დაუყოვნებლივ შეინახეთ ხმოვანი ჩანაწერი ბავშვის ალბომში და დააფიქსირეთ მისი განვითარება.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'ლოგიკის ძიებაში 🧩', 'მარტივ, ორ-სამნაწილიან ფაზლებს უკვე ადვილად აწყობს. რეკომენდებული პროდუქტების განყოფილებაში იპოვეთ უფრო რთული ხის სათამაშოები, რომლებიც მის გონებრივ შესაძლებლობებს გამოცდის და მიზეზშედეგობრივი კავშირების გააზრებაში დაეხმარება.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'ქარიშხალი აბაზანაში 🛁', 'წყლიდან ამოსვლა არ სურს და ტირის? ჰკითხეთ Anacan AI-ს ყურადღების გადასატანი სათამაშოებისა და პრაქტიკული მეთოდების შესახებ, რომლებიც ბანაობის რუტინის სტრესის გარეშე დასრულებაში დაგეხმარებათ.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'სასრიალოზე რიგისთვის ბრძოლა 🛑', 'პარკში სხვა ბავშვების მოცდა არ სურს? ბლოგების განყოფილებაში აუცილებლად წაიკითხეთ სოციალიზაციის შესახებ სტატიები, რათა გაიგოთ, როგორ ასწავლოთ 2.5 წლის ასაკისთვის რიგის დაცვა და გაზიარება.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'გვერდები ცოცხლდება 📖', 'ზღაპრის კითხვისას ამბის დასასრულს თავად იგონებს? Anacan AI-ის დახმარებით აღმოაჩინეთ ინტერაქციული კითხვის მეთოდები, რომლებიც ფანტაზიის ამ შესანიშნავ გამოვლინებას შეუწყობს ხელს.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'სითხის მიღება და ყაბზობა 💩', 'ბევრს დარბის, მაგრამ ცოტა წყალს სვამს? საფენის გამოცვლისას (ან ქოთნის გამოყენებისას) განავალს დააკვირდით. თუ ყაბზობის რისკი არსებობს, ჩაინიშნეთ ეს აპში და კვების კონტროლის ხელსაწყოს მეშვეობით მენიუს დაუყოვნებლივ დაამატეთ ქლიავის ჩირი ან შვრია.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'საჭმლით თამაშობს 🥦', 'მაკარონს ჭამის ნაცვლად ჭყლეტს და აქეთ-იქით ყრის? ამ ასაკში საკვები მისთვის სათამაშოცაა. კვების გეგმაში მონიშნეთ, რამდენად კარგად ჭამს და აკონტროლეთ კვირის კვებითი ბალანსი.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'დილის ფიასკო 🧦', 'ამ დილით წინდის ხელზე ჩაცმა მოინდომა? ნუ გაბრაზდებით სიჯიუტით სავსე აღმოჩენების ასეთ მომენტებზე. მიეცით საშუალება, ცოტა ხანს ასე იაროს — ეს დამოუკიდებლობის გამოცდაა.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'წყლის ჯადოსნური ძალა 🛀', 'მთელი დღე სირბილმა ისიც დაღალა და თქვენც. თბილი აბაზანა მხოლოდ დაბანის საშუალება კი არა, მისი ნერვული სისტემის დამამშვიდებელი საუკეთესო თერაპიაცაა.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'ეგოიზმი პარკში 🧸', 'ქვიშაში თამაშისას თავის სათამაშო ჭურჭელს არავის აძლევს? 27 თვის ასაკში გაზიარების ცნება ჯერ კიდევ სუსტად აქვს განვითარებული. ნუ დაადანაშაულებთ ეგოიზმში, უბრალოდ აუხსენით, რომ სათამაშო რიგრიგობით უნდა გამოიყენონ.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'მამის ხმის ტონი 📖', 'ამ საღამოს ოთახში განსხვავებული ატმოსფერო შევქმნათ. წიგნის წაკითხვა ან ზღაპრის მოყოლა მამის დაბალ და დამაჯერებელ ხმას მიანდეთ, თავად კი გვერდით დაისვენეთ.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'შესანიშნავი მეხსიერება 🧠', 'გუშინ დამალული სათამაშო ამ დილით ზუსტად იპოვა? მისი ხანგრძლივი მეხსიერება საოცრად კარგად განვითარდა.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'სირბილის მარათონი 🏃‍♂️', 'სიარული მისთვის უკვე მოსაწყენია — მხოლოდ დარბის! ოთახის შუაგულიდან პატარა დაბრკოლებები აიღეთ და ღიმილით ადევნეთ თვალი ამ დაუშრეტელ ენერგიას.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'თამაშები სიბნელეში 🐰', 'დაძინება არ სურს და სიბნელის ეშინია? ოთახი მთლიანად დააბნელეთ და კედელზე ხელებით ჩრდილების თეატრი მოაწყვეთ. შიში გართობად აქციეთ.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'დედის ოფლაინ საათი ☕', 'როცა ბავშვი თავის სამყაროშია ჩაფლული და თოჯინებს ესაუბრება, მაშინვე ჭურჭლის სარეცხ მანქანასთან ნუ გაიქცევით. ფინჯანი ყავა დაისხით, ტელეფონიც 15 წუთით გვერდზე გადადეთ და სრულიად ოფლაინ იყავით.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'პირველი გრძელი წინადადებები 🗣️', 'დედა, მანქანა იქ წავიდა! ბავშვი უკვე სიტყვებს ერთმანეთთან აკავშირებს და აზრიან წინადადებებს აყალიბებს. მოუსმინეთ ამ ისტორიულ მომენტებს და აუცილებლად ჩაწერეთ განვითარების ტრეკერში სამახსოვროდ.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'ბლოგის შესვენება 📱', 'ახლა ქოთანზე მიჩვევის დასაწყებად შესაფერისი დროა? თუ ყოყმანობთ, შედით Anacan აპის ბლოგების განყოფილებაში და წაიკითხეთ სპეციალისტების მიერ დაწერილი, პედიატრების მიერ დამტკიცებული სტატიები.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'დღის ანალიზი 📝', 'რთული დღე იყო? განწყობის დღიურში დღევანდელი სტრესის შესახებ დაწერეთ და გული მოიოხეთ. ყველა დედა გადის ასეთ მძიმე კრიზისებს — თქვენ მარტო არ ხართ.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'წყალზე უარი 💧', 'წყლის ნაცვლად სულ ტკბილ წვენებს ითხოვს? გამოთვალეთ მისი ყოველდღიური წყლის საჭიროება და წყალი ფერად, საინტერესო ჭიქებში შესთავაზეთ.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'გამოგონილი ამბები 🎭', 'სათამაშო დათუნიას ალაპარაკებს და გამოგონილ ამბებს უყვება? ფანტაზია ფრთებს შლის! გვერდიდან დააკვირდით და საერთოდ არ ჩაერიოთ.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'ზღაპრის გარეშე არ ვიძინებთ 🪄', 'კლასიკური ზღაპრები მის ყურადღებას აღარ იპყრობს? ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ზღაპარი, რომლის მთავარი გმირიც თავად იქნება.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'არეულობა მშვენიერია 🌪️', 'დაიღალეთ ყოველდღე ერთი და იმავე სათამაშოების ყუთში ჩალაგებით? დღეს ნუ დაალაგებთ! სახლში არეულობა სამყაროს დასასრული არ არის — თქვენი ფსიქოლოგიური სიმშვიდე უფრო მნიშვნელოვანია.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', '10 წუთი მარტო 🛀', 'ოთახში სიჩუმემ დაისადგურა. სთხოვეთ თქვენს პარტნიორს, სახლში ყველაფერს მან მიხედოს. თქვენ კი თბილი შხაპი მიიღეთ და 10 წუთით მხოლოდ საკუთარ თავთან დარჩით.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'კალციუმი მხოლოდ რძე არ არის 🧀', 'რძის დალევაზე უარს ამბობს? ძვლებისთვის კალციუმი აუცილებელია. კვების კონტროლის ხელსაწყოს მეშვეობით დღეს მიღებული ყველის, იოგურტის ან ბროკოლის რაოდენობა გამოთვალეთ და დანაკლისი შეავსეთ.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'სოლიდარობის კლუბი 💬', 'ძალიან დაიღალეთ და გგონიათ, რომ თქვენი არავის ესმის? დაუყოვნებლივ მისწერეთ Anacan-ის საზოგადოებას. იქ ათასობით დედა, რომელსაც თქვენნაირად არ სძინავს, მხარს დაგიჭერთ.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'უმიზეზო სიჯიუტე 🛑', 'ამ დილით იმიტომ ატყდა ერთი ამბავი, რომ წყალი ლურჯის ნაცვლად წითელ ჭიქაში მიეცით? ეს ჭირვეულობა არ არის — ბავშვი უბრალოდ ამოწმებს, შეუძლია თუ არა სამყაროს მართვა. მოთმინება გამოიჩინეთ.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'ვიტამინების წყარო 🥗', 'ყველაფერს აკეთებთ, რომ ბავშვი დანაყრდეს. თქვენზე კი ვინ იზრუნებს? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინითა და კალციუმით მდიდარი სადილი, რომელიც 10 წუთში მზადდება, და ენერგია აღიდგინეთ.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'სარკის წინ 👀', 'სარკის წინ დგას, სხვადასხვა სახეს იღებს და საკუთარ თავზე იცინის? ეს შესანიშნავი თვითშემეცნების ნიშანია. ჩუმად დააკვირდით და დატკბით ამ სახალისო მომენტებით.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'ძილის გაპროტესტება 🥱', 'შუადღის ძილი არ სურს და წინააღმდეგობას გიწევთ? ზოგი ბავშვი ამ ასაკში დღისით ძილს თავს ანებებს. კამათის ნაცვლად, გამოაცხადეთ სიმშვიდის საათი და საწოლში ერთად დაათვალიერეთ წიგნი.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'ოთახის აკუსტიკა 🤫', 'როგორც კი დაიძინებს, უმცირეს ხმაურზეც კი შეკრთება? ხმის საზომით შეამოწმეთ ოთახის აკუსტიკა და ფანჯრიდან შემოსული ხმების გასანეიტრალებლად თეთრი ხმაური ჩართეთ.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'ჭირვეულობის შეტევები 🛑', 'მაღაზიაში ან პარკში ბავშვის ჭირვეულობის შეტევები უხერხულ მდგომარეობაში გაყენებთ? გახსოვდეთ, მნიშვნელოვანია არა ის, თუ რას ფიქრობენ გარშემომყოფები, არამედ ის, თუ რას გრძნობს თქვენი ბავშვი იმ მომენტში. დაამყარეთ მასთან თვალით კონტაქტი და დაამშვიდეთ.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'ხტომის მცდელობები 🤸‍♂️', 'დივნიდან იატაკზე ან ადგილიდან ჰაერში ახტომას ცდილობს? მისი მსხვილი მოტორული უნარები იხვეწება! წაახალისეთ.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'სრულად გავაანალიზოთ რეჟიმი ⏱️', 'საღამოს დაძინებას 40 წუთი დასჭირდა? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, უკვე დროა, დღის ძილი კიდევ უფრო შეამციროთ და საღამოს დაძინების დრო გადმოწიოთ.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'ბუნების აღმოჩენა ⛅', 'ოთხ კედელში ყოფნა უკვე გაწუხებთ. გახსენით ამინდისა და ტანსაცმლის ინსტრუმენტი, ამინდის შესაბამისად ჩააცვით ბავშვს და მაშინვე წაიყვანეთ პარკში. მიეცით საშუალება, ფოთლები და ქვები შეისწავლოს.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'დატკბით სიმშვიდით 🤫', 'როგორც იქნა, დაიძინა. ახლა სახლში უმცირესი ხმაურიც კი გაღიზიანებთ. გაიკეთეთ ყურსასმენები, არაფერი ჩართოთ და უბრალოდ სიჩუმით დატკბით.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'ფერების აღმოჩენა 🎨', 'როცა წითელი ბურთი უნდა, სწორედ წითელზე მიგითითებთ? ის უკვე იწყებს ფერების გარჩევას. განვითარების ტრეკერში აღრიცხეთ აღქმის ეს ახალი ეტაპი.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', '„მე უკვე დავნაყრდი“ — საბაბი 🥣', 'ორ კოვზს შეჭამს, ამბობს, რომ დანაყრდა და გარბის? ნუ დააძალებთ. სცადეთ, მცირე ულუფები უფრო ხშირად შესთავაზოთ.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'სხეულის ნაწილების ამოცნობა 👀', 'როცა ეკითხებით: „სად გაქვს მხრები?“, თითით ეხება და გაჩვენებთ? მისი გონებრივი აღქმა პიკზეა! განაგრძეთ თამაში სხეულის უფრო რთულად ამოსაცნობი ნაწილებით.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'პიჟამის ორთაბრძოლა 👕', 'საღამოს ჩაცმა დიდ ომად იქცევა? არჩევანი მას დაუტოვეთ: „თეთრი პიჟამა გინდა თუ ლურჯი?“ ეს ხრიკი ხშირად ამართლებს.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'სხვისი სათამაშო 🧸', 'სტუმრად მოსულ ბავშვს საკუთარ სათამაშოს არ აძლევს? ეს ეგოიზმი კი არა, პირადი საზღვრების დაცვაა. გაზიარება იძულებით კი არა, საკუთარი მაგალითით ასწავლეთ.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'სიტყვების წარმოთქმა 🗣️', 'ზოგიერთ სიტყვას არასრულად ან ძალიან სასაცილოდ წარმოთქვამს? ნუ გაიცინებთ — უბრალოდ სწორად, სათანადო მახვილით გაუმეორეთ, რათა მისმა ტვინმა სწორი ფორმა დაიმახსოვროს.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'ღამის შიშის ეჭვი 😭', 'შუაღამისას დახუჭული თვალებით ტირის და ვერ მშვიდდება? მისი ხმა დაუყოვნებლივ მოასმენინეთ ტირილის ანალიზის ფუნქციას. ზოგჯერ მიზეზი მხოლოდ აირები კი არა, ღამის შიშია.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'დილის ჭირვეულობა ☁️', 'თვალის გახელისთანავე ყველაფერზე ტირის და არაფერი მოსწონს? შესაძლოა, სწორედ ზრდის ნახტომის შუა ეტაპზე იყოს. უბრალოდ ხშირად ჩაეხუტეთ და თავი უსაფრთხოდ აგრძნობინეთ.'),
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8', 'მიეცით დასვრის უფლება 🏖️', 'პარკში ტალახით ან ქვიშით თამაში სურს? მიეცით უფლება, დასვრას ნუ შეუშლით! ამ აქტივობისთვის, რომელიც სენსორულ განვითარებას უწყობს ხელს, საუკეთესო დედებისთვის მეგობრული ადგილები აპში იპოვეთ.'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'გუნდური სულისკვეთება 🥂', 'რთული დღე უკან მოიტოვეთ. ბავშვის დაძინების შემდეგ პარტნიორთან ერთად ჩაი დაისხით, უთხარით ერთმანეთს: „ჩვენ ამას ნამდვილად ვუმკლავდებით“ და ერთმანეთის ძალისხმევა დააფასეთ.'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'თავს როგორ გრძნობთ? 🩸', 'ენერგია უეცრად დაგიქვეითდათ თუ განწყობა ხშირად გეცვლებათ? აპში მენსტრუაციის ტრეკერს გადახედეთ. ციკლზე თვალყურის დევნებით უკეთ გაიგეთ თქვენი სხეულის საჭიროებები.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'გამოგონილი ზღაპრები 📖', 'წიგნების კითხვა მოგბეზრდათ? ჩააქრეთ შუქი, თეთრი ხმებიდან წვიმის ხმა ჩართეთ, სიბნელეში ერთად მოიგონეთ ზღაპრები და მშვიდად დაიძინეთ.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'ხილის აღმოჩენები 🍏', 'ცილოვან საკვებზე ან ბოსტნეულზე უარს ამბობს? კვების კონტროლის ხელსაწყოთი დღევანდელი ნორმა გამოთვალეთ და ბავშვის რეცეპტებში ხილის იოგურტის მსგავსი გემრიელი კომბინაციები შექმენით.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'თითებზე თვლა 🔢', 'კიბეზე ასვლისას ან მანქანების მწკრივად დალაგებისას ცდილობს თქვას: ერთი, ორი, სამი? ასე მათემატიკური აზროვნების საფუძველი ეყრება. მასთან ერთად ყველაფერი ხმამაღლა დაითვალეთ.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'ღრმად ჩაისუნთქეთ 🧘‍♀️', 'მთელი დღე კითხვებზე პასუხის გაცემით ყელი გაგიშრათ. როგორც კი ოთახში სიჩუმე დაისადგურებს, ეკრანს ნუ შეხედავთ — უბრალოდ ღრმად ისუნთქეთ და დაისვენეთ.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'თბილი ჩაი და სიჩუმე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. ნუ იჩქარებთ საოჯახო საქმეების კეთებას! ჯანსაღი რეცეპტებიდან შეარჩიეთ მელისის ან გვირილის ჩაი, მოამზადეთ, დივანზე წამოწექით და უბრალოდ სიჩუმით დატკბით.'),
  ('37bdad79-de07-4752-a75a-2761546b1523', 'გაზიარება რთულია 🧸', 'თავის და-ძმას ან პარკში მყოფ ბავშვს უხეშად ექცევა? გაზიარება მისთვის ჯერ კიდევ აბსტრაქტული ცნებაა. ნუ დასჯით — აჩვენეთ, რომ მისი გრძნობები გესმით.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'წარმოსახვითი ჩაის სუფრა 🍵', 'წარმოსახვით თამაშებში თქვენც გრთავთ და გთხოვთ, ცარიელი ფინჯნიდან ჩაი დალიოთ? გახდით მისი წარმოსახვის ნაწილი. ასეთი თამაშები მის სოციალურ ინტელექტს ავითარებს.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'მამის ზღაპარი 📖', 'ამ საღამოს ხმას დასვენების საშუალება მიეცით. დაე, ბავშვის საყვარელი წიგნების სხვადასხვა ხმითა და სახალისოდ წაკითხვის მოვალეობა მამამ შეასრულოს.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'დაცემისას არ ტირის 🧗‍♂️', 'მსუბუქად დაცემისას მაშინვე არ ტირის, ჯერ თქვენს რეაქციას აკვირდება და შემდეგ წყვეტს, იტიროს თუ არა? ნუ შეშინდებით, გაუღიმეთ და უთხარით: „არაფერი მომხდარა, შენ ძლიერი ხარ“.'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'სიბნელის ეშინია?  🌙', 'მის საწოლთან პატარა, თბილი ფერის ღამის სანათი დადგით. დანარჩენი ოთახი კი მელატონინის გამომუშავებისთვის სრულ სიბნელეში დატოვეთ.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'ბოსტნეულთან მტრობა 🥦', 'წვნიანიდან ყველა ბოსტნეულს გვერდზე დებს? კვების გეგმაში მისთვის განსხვავებული ალტერნატივები მოძებნეთ. ბოსტნეულის კატლეტში დამალვა დედების უძველესი ხრიკია.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'იდეალური დედა არ არსებობს 💬', 'თავს ცუდად გრძნობთ, რადგან ყველაფრის ერთდროულად გაკეთებას ვერ ახერხებთ? ახლავე შეუერთდით Anacan-ის საზოგადოებას. იქ მყოფი დედების გულწრფელი აღიარებები ძალას შეგმატებთ.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'ჯღაბნის სურვილი 🖍️', 'ფანქრის დაჭერის მანერას ცვლის და ქაღალდზე მიზანმიმართულ ხაზებს ავლებს. განვითარების მაჩვენებლების ტრეკერში აუცილებლად მონიშნეთ ნატიფი მოტორიკის ეს შესანიშნავი წინსვლა.'),
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf', 'ყავის მუხტი ☕', 'დღის სირბილმა ძალა გამოგაცალათ. ბავშვი 15 წუთით უსაფრთხო აქტივობით (მაგალითად, გაფერადებით) დააკავეთ და აუცილებლად შეივსეთ ენერგია ფინჯანი ყავით.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'ზუსტი სროლები ⚾', 'უკვე ცდილობს, თქვენ მიერ მისთვის გადაგდებული დიდი ბურთი ხელებით დაიჭიროს და უკანაც კი გადმოგიგდოთ? თვალისა და ხელის კოორდინაცია სწრაფად ვითარდება. ერთად ითამაშეთ ბურთით დერეფანში.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'მუსიკალური გადასვლა 🛀', 'საღამოს რუტინა გართულდა? თბილი აბაზანის მიღებისას ფონად მშვიდი კლასიკური მუსიკა ჩართეთ. წყლისა და მუსიკის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ამშვიდებს.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'დღის ძილზე უარი 🥱', 'ისევ ვერ დაიძინა? ნუ შეებრძოლებით და ნუ დაღლით არც მას და არც საკუთარ თავს. ოთახში ჩუმად წიგნის ფურცვლაც კი ტვინისთვის დასვენების ერთ-ერთი ფორმაა.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'გრძნობების გამოხატვა 📝', 'დღეს ძალიან დაიღალეთ, ან მან რაღაც ძალიან საყვარელი თქვა? ორივე შემთხვევაში გახსენით განწყობის დღიური და ეს მომენტი მომავლისთვის ჩაინიშნეთ.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'ბრძოლა კბილების გახეხვისას 🦷', 'არ გაძლევთ ჯაგრისის პირთან მიტანის უფლებას? ეს იძულებად კი არა, თამაშად აქციეთ. ჯერ მას მიეცით საშუალება, თქვენი კბილები გახეხოს, შემდეგ კი თქვენი ჯერი იქნება.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('7022b1d9-81c4-428f-be96-d38885bd2971'::uuid, 'დამოუკიდებელი თამაში 🧸', 'არ ხართ ვალდებული, ყოველ წუთს გაართოთ. მოწყენა ბავშვებისთვის შემოქმედებითობის დასაწყისია. მიეცით საშუალება, ოთახში დამოუკიდებლად აღმოაჩინოს რამე.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც რაიმე ნივთი გჭირდებათ, არც წიგნი და არც ზღაპარი. ამ საღამოს უბრალოდ გულში ჩაიკარით, მისი სურნელი ღრმად შეისუნთქეთ და სიბნელეში ჩუმად უთხარით, როგორ გიყვართ.'),
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4', 'მტკიცე „არა“ 🛑', 'როცა ვინმეს მისი კოცნა სურს, ბავშვი თავს არიდებს და უარს ამბობს? პატივი ეცით მისი სხეულის საზღვრებს და სხვებისგანაც იგივე მოითხოვეთ. თავდაჯერებულობა სწორედ აქედან იწყება.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'გადახედეთ ბლოგებს 📱', '2 წლის ბავშვის ტანტრუმებთან გამკლავება გიჭირთ? წაიკითხეთ ფსიქოლოგიური ბლოგები Anacan აპლიკაციაში. თუ გაიგებთ, რა ხდება ბავშვის ტვინში ასეთი კრიზისის დროს, მასთან გამკლავება გაგიადვილდებათ.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'ჭკვიანი ზღაპრის დრო 🪄', 'ამ საღამოს ჭკვიანი ზღაპრების მეშვეობით მისთვის განსაკუთრებული თავგადასავალი შექმენით: უშიშარი, მამაცი კურდღლის ამბავი. დაეხმარეთ ბავშვს შიშების დაძლევაში ზღაპრების საშუალებით.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'ქაოსი სახლში 🌪️', 'ოთახი, რომელსაც ყოველდღე ალაგებთ, 5 წუთში ისევ ირევა? ნუ იდარდებთ! სახლი მუზეუმი კი არა, სიცოცხლით სავსე ადგილია. ყურადღება უწესრიგობაზე კი არა, თქვენი ბავშვის სიხარულზე გაამახვილეთ.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'შიშების გაღვიძება 👻', 'ახლა ხმაურიანი მტვერსასრუტის ეშინია და თქვენ უკან იმალება, მიუხედავად იმისა, რომ ადრე საერთოდ არ ეშინოდა? წარმოსახვის განვითარებასთან ერთად უსაფუძვლო შიშებიც ჩნდება. მოეფერეთ და თავი უსაფრთხოდ აგრძნობინეთ.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'თვალები ძილს ითხოვს 🥱', 'მიუხედავად იმისა, რომ ეძინება, დასაძინებლად წასვლა საერთოდ არ სურს. ამ საღამოს რუტინა ოდნავ შეცვალეთ. წიგნის წაკითხვის ნაცვლად, საწოლში წამოწექით და დღევანდელი სასიამოვნო ამბები გაახსენეთ.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'ენერგიის მოზღვავება ⛅', 'ბავშვი სახლში კედლებზე დადის? აუცილებელია, ენერგია დახარჯოს. ამინდის შესაბამისად ჩააცვით, პარკში გაიყვანეთ და მიეცით სირბილის საშუალება, სანამ არ დაიღლება.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'თქვენს ხმას ბაძავს 🗣️', 'სათამაშოებს ზუსტად თქვენი ხმის ტონითა და თქვენი ფრაზებით ჭკუას არიგებს? ის თქვენი საუკეთესო სარკეა. საკუთარი თავის გვერდიდან დანახვა სახალისო იქნება.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'სიმაღლისა და წონის ნახტომი! 📏', 'ჩაცმისას შეამჩნიეთ, რომ მაისურები დაუპატარავდა ან ფეხსაცმელი უჭერს? განვითარების მონიტორში შეიყვანეთ მიმდინარე სიმაღლე და ზომები და სიამაყით დააკვირდით, როგორ მიიწევს განვითარების მრუდი ზემოთ.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'როცა დედა იღლება 🛑', 'თქვენ რობოტი არ ხართ. თუ დღეს საჭმლის მოსამზადებლად ძალა არ გაქვთ, მზა კერძი გამოიძახეთ. იდეალურ დედად ყოფნა არ ნიშნავს, რომ ყველაფერი მარტო უნდა გააკეთოთ.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'გამარჯვების სადღეგრძელო 🥂', 'რთული და სიჯიუტით სავსე დღე მშვიდობით დაასრულეთ. თქვენს პარტნიორთან პირისპირ დაჯექით და ჩაის ჭიქები მიუჭახუნეთ. თქვენ ამ დიდ პასუხისმგებლობას წარმატებით უმკლავდებით.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'ფიქრობთ, რომ ცოტა წყალს სვამს?💧', 'უყიდეთ ფერადი, სხვადასხვა ფორმის ჭიქები და წყლის სმა სახალისო ჩვევად უქციეთ.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'ჩურჩულით საუბარი 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. მის გვერდით დაწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ჩურჩულით მოუყევით. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი საუკეთესო მეთოდია.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'არჩევანის თავისუფლება 👗', 'ტანსაცმლის თავად შერჩევა სურს, ფერები კი საერთოდ არ უხდება ერთმანეთს? არა უშავს. მისი ნებისყოფა რომ არ დათრგუნოთ, მხოლოდ 2 არჩევანი შესთავაზეთ: ეს თუ ის?'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'მამის უცნაური ხმები 🤡', 'ბავშვის გაცინების ყველაზე სწრაფი გზა მამის მიერ უცნაური ხმების გამოცემა და სასაცილო მიმიკების გაკეთებაა. ამ საღამოს მის მხიარულ კისკისს მოუსმინეთ და თქვენც ჩუმად გაიღიმეთ.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'გულახდილი საუბრის დროა 💬', 'დღეს ყველაფერზე ტიროდა და თქვენ ძალა გამოგელიათ. დაუყოვნებლივ შედით Anacan-ის საზოგადოებაში და დაწერეთ: დღეს ძალიან რთული დღე იყო. ნახავთ, რომ ასობით ქალი იმავეს განიცდის.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'კონსტრუქტორის ოსტატი 🧱', 'ცდილობს, LEGO-ს დიდი დეტალები ერთმანეთს შეუერთოს და რამე ააწყოს? ის გეომეტრიას აღმოაჩენს. განვითარების ტრეკერს მისი ეს პატარა საინჟინრო მცდელობებიც დაამატეთ.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'სიტყვების გამეორება 🗣️', 'თქვენგან გაგონილ ყოველ ახალ სიტყვას მაშინვე თუთიყუშივით იმეორებს? მისი ლექსიკური მარაგი იზრდება. განსაკუთრებული ყურადღება მიაქციეთ, რა სიტყვებს ამბობთ და რა ემოციებს გამოხატავთ მის გვერდით.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'ღამის მელოდია 🛀', 'მთელი დღის სირბილმა ისიც დაღალა და თქვენც. თბილი აბაზანა და ფონად ჩართული მსუბუქი, მშვიდი მელოდია მის ნერვულ სისტემას სრულად დაამშვიდებს.'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'კრიზისული მომენტი 🛒', 'ყვირის, რადგან მაღაზიაში სასურველი სათამაშო არ უყიდეთ. ყურადღებას ნუ მიაქცევთ გარშემო მყოფი „იდეალური“ მშობლების მზერას. მშვიდად დაამყარეთ ბავშვთან თვალით კონტაქტი და აუხსენით.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'საშინაო საქმეები მოიცდის 🛑', 'იატაკი არ არის მოწმენდილი, ტანსაცმელი კი — დაკეცილი? იყოს ასე. არეული სახლის დალაგება შეიძლება, ფსიქოლოგიურად გამოფიტული დედის აღდგენას კი ძალიან დიდი დრო სჭირდება. წამოწექით დივანზე.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'შეეგუეთ უძილო ღამეს 😭', 'შუაღამისას გაიღვიძა და დაძინება აღარ სურს. ნუ გაუბრაზდებით. ტირილის ხმა ტირილის ანალიზს მოასმენინეთ, დაადგინეთ მიზეზი (ტკივილი, აირები, შიში) და მოთმინებით ჩაიხუტეთ.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'ახალი მეგობრების ძიება 👫', 'პარკში თანატოლებთან ერთად სირბილსა და მათთან მიახლოებას ცდილობს? სოციალიზაციის პროცესი ოფიციალურად დაიწყო! უსაფრთხოებაზე შორიდან იზრუნეთ და ამ მომენტს სიამაყით დააკვირდით.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'ისწავლეთ ბლოგებიდან 📱', 'დაგღალათ იმან, რომ ბავშვი ყველაფერზე „არას“ ამბობს? ეს 2 წლის ასაკის კრიზისის კლასიკური ნიშანია. აპლიკაციაში ფსიქოლოგიური ბლოგების წაკითხვით გაიგეთ, რა ხდება მის გონებაში.'),
  ('19cce24b-ae51-482e-8dc7-6812a220483b', 'თავს ნუ დაიდანაშაულებთ 📝', 'დღეს მოთმინება არ გეყოთ და ხმას აუწიეთ? როცა ბავშვი დაიძინებს, განწყობის დღიურში თქვენი გრძნობები ჩაიწერეთ და საკუთარ თავს აპატიეთ. თქვენ უბრალოდ დაიღალეთ — თქვენც ადამიანი ხართ.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'კიბეზე დამოუკიდებლად ასვლა 🧗‍♂️', 'ცდილობს, ხელი ჩაგკიდოთ და კიბეზე ავიდეს, ან სულაც დამოუკიდებლად ასვლა სურს? ის საკუთარი სხეულის შესაძლებლობებს ამოწმებს. უსაფრთხოება დაუზღვიეთ და ეს თავისუფლება აუცილებლად მიეცით.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'განშორების შიში 🥺', 'ტუალეტშიც რომ შედიხართ, კარს მიღმა გელოდებათ და ტირის. განშორების შფოთვა ზოგჯერ მძაფრდება. ყოველ ჯერზე გამოეხმაურეთ და უთხარით, რომ აქ ხართ და დაბრუნდებით.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'ოთახის სიბნელე 🌙', 'დაძინების დასაჩქარებლად ოთახში ყველა დამატებითი განათება და განსაკუთრებით პლანშეტის ეკრანი გამორთეთ. მელატონინი მხოლოდ ბნელ გარემოში გამოიყოფა.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'ჭამის დროს გაჯიუტება 🥣', 'ორ კოვზს ჭამს და ამბობს, რომ დანაყრდა? ნუ დააძალებთ. საკვებთან ჯანსაღი დამოკიდებულების ჩამოყალიბება უფრო მნიშვნელოვანია, ვიდრე ძალით კვება. უფრო ხშირად შესთავაზეთ საკვები, ულუფები კი შეამცირეთ.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'ტაშის დაკვრის სიხარული 👏', 'როცა რამე გამოსდის (მაგალითად, კოშკს ააშენებს), საკუთარ თავს ტაშს უკრავს და ამაყობს? მას თქვენი მოწონება სურს! თქვენც დიდი სიხარულით აღნიშნეთ მისი ეს პატარა წარმატება.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'სიმშვიდის საათი ☕', 'თუ ბავშვს დღისით არ სძინავს, მინიმუმ 1-საათიანი სიმშვიდის საათი (quiet time) დაუწესეთ. მან თავის საწოლში წიგნი ათვალიეროს, თქვენ კი ჩაი დალიეთ და ტელეფონს გადახედეთ.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'შესვენება წყვილისთვის 🥂', 'ბავშვს ჩაეძინა. ახლა ტელეფონები და საოჯახო საქმეები გვერდზე გადადეთ. თქვენს პარტნიორს მინიმუმ 20 წუთის განმავლობაში ესაუბრეთ ნებისმიერ თემაზე, ბავშვის გარდა. გახსოვდეთ, რომ თქვენ წყვილიც ხართ.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'ზღაპრის დასასრული 🪄', 'კლასიკური ზღაპრები შეიძლება დამღლელი იყოს. ამჯერად ზღაპრის დასასრული თქვენს ბავშვს აარჩევინეთ. ჰკითხეთ: „შენი აზრით, დათუნიას ვინ დაეხმარა?“ — და ასე მისი წარმოსახვა გაააქტიურეთ.'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'საზღვრების გამოცდა ⚠️', 'მიუხედავად იმისა, რომ ეუბნებით, ეს არ გააკეთოს, თვალებში გიყურებთ და მაინც აკეთებს? ის თქვენს გაბრაზებას კი არ ცდილობს, არამედ ამოწმებს, რამდენად მყარია თქვენ მიერ დაწესებული საზღვრები. იყავით თანმიმდევრული.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'რეაქცია სურათებზე 📖', 'როცა წიგნში ცხოველებს ან ბავშვებს ხედავს, მათ ეხება ან ხმებს გამოსცემს? მისი ვიზუალური აღქმა გასაოცარია. მონიშნეთ ეს დეტალი განვითარების მონიტორინგის განყოფილებაში.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'პატარა დამხმარე 🧹', 'როცა ტანსაცმელს კეცავთ ან იატაკს წმენდთ, ცდილობს, საქმე ხელიდან გამოგართვათ? ის თავს დიდად გრძნობს. მიეცით პატარა ტილო და მიეცით საშუალება, დაგეხმაროთ.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'ბალიშების ციხესიმაგრე 🏰', 'ამ საღამოს ოთახი სათამაშო მოედნად აქციეთ. დივნის ბალიშებისგან პატარა ციხესიმაგრე ააშენეთ და შიგნით შეძვერით. ცოტა არეულობა იქნება, მაგრამ ეს სიცილი ნამდვილად ღირს ამად.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'ყურადღების ტესტი 🧩', 'ერთი სათამაშოთი თამაშის ხანგრძლივობამ უკვე 10-15 წუთს მიაღწია? ყურადღების კონცენტრაციის ხანგრძლივობა იზრდება.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'ძილის რუტინა მამასთან ერთად 👨‍🍼', 'დღეს საღამოს ბავშვის დასაძინებლად მომზადება, კბილების გახეხვა და პიჟამის ჩაცმა მამას მიანდეთ, თავად კი მშვიდად დალიეთ ჩაი.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'მწვანილის დეტოქსი 🌿', 'შებერილობას გრძნობთ? მენსტრუაციის ტრეკერში შეამოწმეთ თქვენი ციკლი, ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან კი მოამზადეთ მწვანე სმუზი, რათა ორგანიზმი გაიწმინდოთ და ენერგია აღიდგინოთ.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'სითხის მიღება და ყაბზობა 💩', 'ბევრს დარბის და ცოტა წყალს სვამს? საფენის გამოცვლისას (ან ქოთნის გამოყენებისას) დააკვირდით განავალს. თუ ყაბზობის რისკია, მენიუში შვრია დაამატეთ.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'მონსტრზე ნადირობა! 👾', 'საწოლის ქვეშ მონსტრს ეძებს? წარმოსახვითი შიშები ძლიერდება. თეთრი ხმებიდან ჩართეთ ვენტილატორის ხმა, რათა ოთახში უსაფრთხო და ერთგვაროვანი გარემო შექმნათ და ბავშვი დაამშვიდოთ.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'საწოლიდან გაქცევის გეგმა 🛌', 'საბავშვო საწოლიდან გადმოძრომას ცდილობს? დიდ საწოლზე გადასვლის დრო ახლოვდება. ოთახის უსაფრთხოება ხელახლა შეამოწმეთ ბავშვის სიმაღლიდან.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'შესვენება დედისთვის ☕', 'როცა ბავშვი დამოუკიდებლად თამაშობს, მაშინვე საოჯახო საქმეების კეთებას ნუ შეუდგებით. ოთახში არეულობა არსად გაიქცევა, თქვენი ენერგია კი შეიძლება ამოიწუროს. დაჯექით და ცხელი ყავა დალიეთ.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', '„რატომ?“ პერიოდის პიკი 🤔', '„ის იქ რატომ არის?“, „რატომ მძინავს?“... მისი ტვინი ღრუბელივით ისრუტავს ყველაფერს! მის დაუსრულებელ კითხვებს მოკლე, მაგრამ ლოგიკური პასუხები გაეცით. ის სამყაროს თქვენი სიტყვებით შეიცნობს.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'მენიუს საზრუნავი 🍲', 'დღეს არ იცით, რა მოამზადოთ? ინტერნეტში ძიებით დროს ნუ დაკარგავთ — აპლიკაციის ბლოგების განყოფილებაში ბავშვთა კვების შესახებ სტატიებში ახალ და მარტივ რეცეპტებს იპოვით.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'მიზეზ-შედეგობრივი კავშირების ძიება 🤔', '„რა მოხდება, თუ ამას გადავაგდებ?“, „ეს ღილაკი რისთვისაა?“ ბავშვი მუდმივად ატარებს ფიზიკურ ექსპერიმენტებს. კიდევ ერთხელ გადაამოწმეთ, რამდენად უსაფრთხოა თქვენი სახლი.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'ურთიერთობა პარკში 🌳', 'სხვა ბავშვებთან თამაშის ნაცვლად, მათ გვერდით თავისთვის თამაშობს? პარალელური თამაში ამ ასაკისთვის სრულიად ბუნებრივია. ამინდის შესაბამისად ჩააცვით და ხშირად წაიყვანეთ ისეთ ადგილებში, სადაც თანატოლებთან ერთად იქნება.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'წარმოსახვითი მეგობრები 🧸', 'სათამაშო დათუნიას ზღაპარს უყვება ან ცარიელი ჭიქიდან ჩაის სვამს? სიმბოლური თამაშები განვითარების ნამდვილი შედევრია. განვითარების მონიტორინგის განყოფილებაში სიამაყით აღნიშნეთ ეს კოგნიტიური ნახტომი.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'სიჩუმის საჭიროება 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმის საზომით შეამოწმეთ გარემოში დეციბელების დონე და მეზობელ ოთახში ტელევიზორის ხმას შესაბამისად დაუწიეთ.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'ყველაფრის მისაკუთრება სურს? 🛑', 'გაზიარების ცნება ჯერ ჩამოყალიბებული არ აქვს. ნუ აიძულებთ, ამის ნაცვლად თანდათან შემოიღეთ წესი „მორიგეობით ვითამაშოთ“.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'პატარა ინჟინერი 🏗️', 'კოშკების აშენება და დანგრევა ძალიან უყვარს? რეკომენდებულ პროდუქტებში ახლავე აღმოაჩინეთ მაგნიტური ან ხის კუბიკები, რომლებიც კიდევ უფრო განუვითარებს აზროვნებასა და მოტორულ უნარებს.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'ღრმად ჩაისუნთქეთ 🌬️', 'დღეს მის დევნაში ძალა გამოგელიათ? გახსენით განწყობის დღიური და ჩაწერეთ თქვენი დაღლილობის შესახებ. ნუ ეცდებით, იდეალური დედა იყოთ — თქვენი გრძნობებიც მნიშვნელოვანია!'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'რთული დღე იყო?', 'განწყობის დღიურში დღევანდელი სტრესის შესახებ დაწერეთ და გულზე მოგეშვებათ. ყველა დედა გადის ასეთ კრიზისულ მომენტებს — თქვენ მარტო არ ხართ.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'ნადიმი დედისთვის 🥑', 'მის დასანაყრებლად ყველაფერს აკეთებთ. თქვენ კი? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინით მდიდარი სადილი, რომელიც ძალას შეგმატებთ, მშვიდად დაჯექით და მიირთვით.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'ორსიტყვიანი წინადადებები 🗣️', '„დედა, მოდი“, „ბურთი ისროლე“ — მისი ლექსიკური მარაგი დღითი დღე მდიდრდება. მისი წარმოთქმული არასრული სიტყვები სწორად გაიმეორეთ და ამით მეტყველების განვითარებაში დაეხმარეთ.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'ჭირვეულობა მაღაზიაში 🛒', 'იმის გამო, რომ მაღაზიაში სასურველი ნივთი არ უყიდეთ, იატაკზე გაწვა და ჭირვეულობა დაიწყო? გარშემომყოფთა მზერას ყურადღებას ნუ მიაქცევთ. ჩაიმუხლეთ, რათა მისი თვალების დონეზე აღმოჩნდეთ, და უთხარით, რომ მისი გრძნობები გესმით.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'უკუღმა ჩაცმული ტანსაცმელი 👗', 'ფეხსაცმელი არასწორ ფეხზე აცვია, მაისური კი უკუღმა ჩაიცვა და არაფრით უნდა გახდა? დატოვეთ ასე! ეს საკუთარი ინდივიდუალურობის გამოხატვის ყველაზე უწყინარი გზაა.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'მუსიკალური სიმშვიდე 🎶', 'საღამოს დაწყებული ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზა მისი საყვარელი მელოდიის ჩართვა, ჩახუტება და მასთან ერთად ნელა ცეკვაა.'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'იამაყეთ საკუთარი თავით 🌟', 'ყოველი ახალი უნარი, რომელსაც ბავშვი ყოველდღიურად სწავლობს, და ყოველი თავდაჯერებული ნაბიჯი თქვენი და თქვენი პარტნიორის შრომის შედეგია.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'დამოუკიდებლობის დეკლარაცია 📜', 'ყველაფერზე „მე თვითონ გავაკეთებ!“ ამბობს და საქმეებს აჭიანურებს? დაუყოვნებლივ ჰკითხეთ Anacan AI-ს, როგორ აქციოთ ეს უსაზღვრო სიჯიუტე განვითარების შესაძლებლობად.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'დეტალები წიგნებში 📖', 'წიგნს ფურცლავს და სურათზე ყველაზე პატარა დეტალსაც თითით გაჩვენებთ? მისი ვიზუალური მეხსიერება შესანიშნავად მუშაობს. ესაუბრეთ მას სურათზე გამოსახული საგნების შესახებ.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'ჯღაბნის ოსტატი 🖍️', 'როგორც კი ხელში ფანქარი ჩაუვარდება, კედლებს ან ქაღალდს აჯღაბნის. ფერებით ხატვა მის ნატიფ მოტორულ უნარებს ავითარებს.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'ღამის სიმშვიდე 🛀', 'თბილი აბაზანა, მსუბუქი მასაჟი და ჩაბნელებული ოთახი. ძილის რუტინა არასდროს დაარღვიოთ, რადგან ეს ბავშვის ტვინს მიანიშნებს, რომ ძილის საუკეთესო დრო დადგა.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'დედების გულახდილი საუბარი 💬', 'ფიქრი „რატომ არის ჩემი ბავშვი ასეთი ჯიუტი?“ გღლით? შეუერთდით Anacan-ის საზოგადოებას და დაინახავთ, რომ ყველა ბავშვი განსხვავებულ კრიზისულ პერიოდებს გადის.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'საღამოს გმირი: მამა 🦸‍♂️', 'ამ საღამოს ძილის რუტინა პარტნიორის ფუნქციის დახმარებით თქვენს მეუღლეს მიანდეთ. ზღაპარი მან წაიკითხოს, თქვენ კი თბილი აბაზანა მოიმზადეთ და დღის სტრესი მოიხსენით.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'საკვების არჩევითობა 🥦', 'დღეს უარს ამბობს საკვებზე, რომელიც გუშინ მადიანად მიირთვა? კვების მონიტორინგის ხელსაწყოთი გააანალიზეთ მენიუ, ხოლო ბავშვის რეცეპტებში განსხვავებული და სახალისო გაფორმების იდეები იპოვეთ.'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'უმტკივნეულო დღეები 🩸', 'მენსტრუაცია ახლოვდება და სპაზმები უკვე დაიწყო? სანამ მედიკამენტებს მიმართავთ, ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ მაგნიუმით მდიდარი ფინიკისა და ნიგვზის წასახემსებელი და საკუთარ თავზე იზრუნეთ.'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'ტანსაცმელი პატარავდება! 📏', 'პერანგების სახელოები ისევ დაუმოკლდა? 29-ე თვისთვის ზრდის ნახტომი თვალსაჩინოდ რომ დაინახოთ, წონის მონიტორინგის ხელსაწყოში მიმდინარე მონაცემები შეიყვანეთ და მზარდ გრაფიკს დააკვირდით.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'წიგნის გმირი 📖', 'გთხოვთ, იგივე ზღაპარი მე-100-ედ წაუკითხოთ? ბლოგებში გაეცანით, რა საოცარ როლს ასრულებს ეს ერთი შეხედვით მომაბეზრებელი გამეორება გონებრივ განვითარებაში, და მოთმინება აღიდგინეთ.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'პირველი ლოგიკური ვარაუდები 🤔', 'აწყობს წინადადებებს ამგვარად: „თუ ამას გავაკეთებ, ასე მოხდება“? ეს შესანიშნავი შემეცნებითი ნახტომი ბავშვის ალბომში ხმიან ვიდეოდ დაამატეთ, რათა არცერთი წამი არ გამოგრჩეთ, და იამაყეთ.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'ძილის გაპროტესტება 🥱', 'შუადღის ძილი არ სურს და ტირის? ნუ შეეწინააღმდეგებით. ამის ნაცვლად, გამოაცხადეთ 30-წუთიანი სიმშვიდის საათი, რომლის დროსაც ოთახში ჩუმად დაათვალიერებს წიგნებს.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'ცვლის გადაბარება 👨‍👧', 'მთელი დღე „რატომ?“ კითხვებზე პასუხის გაცემით გონება დაგეღალათ. დღეს საღამოს პიჟამის ჩაცმისა და დაძინების მოვალეობა პარტნიორს გადააბარეთ, თქვენ კი დაისვენეთ.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'უჩვეულო მოდა 👗', 'შუა ზამთარში საზაფხულო შორტის ჩაცმა, შარვლის კი თავზე წამოცმა სურს? მის გემოვნებაში ნუ ჩაერევით. ამ სახალისო ექსპერიმენტებით ის საკუთარ ინდივიდუალურობას გამოხატავს.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'აღმოჩენები თეფშზე 🥦', 'საჭმელს, რომელიც გუშინ უყვარდა, დღეს იატაკზე აგდებს? შედით კვების გეგმის ინსტრუმენტში და ისარგებლეთ სპეციალისტების მიერ 2.5 წლის ბავშვისთვის მომზადებული მრავალფეროვანი და ფერადი მენიუს იდეებით.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'მოულოდნელი შიშები 👻', 'ოთახის სიბნელის ან წარმოსახვითი ჩრდილების შიში დაიწყო? წარმოსახვის განვითარებასთან ერთად უსაფუძვლო შიშებიც ჩნდება. დაამშვიდეთ და აგრძნობინეთ, რომ მის გვერდით ხართ.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'დაუშრეტელი ელემენტი 🔋', 'თქვენ ჯერ თვალების გახელაც ვერ მოასწარით, ის კი უკვე ხალიჩაზე სირბილის მარათონშია ჩართული. დიდი ფინჯანი ყავა დაისხით — ძალიან აქტიური დღე გელით.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'ხელოვანის კვალდაკვალ 🖍️', 'ქაღალდი გათავდა და ახლა კედლებისა და კარების ჯერია? ფერებით მისი წვრილი მოტორიკა ვითარდება. ოთახში დიდი მუყაო დააფინეთ და უთხარით, რომ ხატვა მხოლოდ აქ შეიძლება.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'ალოგიკური სიჯიუტე 🛑', 'წყალი ლურჯის ნაცვლად წითელ ჭიქაში მიეცით და ქვეყანა დაიქცა? ეს ჭირვეულობა არ არის — ბავშვი უბრალოდ ამოწმებს თქვენს საზღვრებს და იმას, შეუძლია თუ არა სამყაროს მართვა. მოთმინება გამოიჩინეთ.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'წყლის თერაპიული ძალა 🛀', 'მთელი დღე სირბილმა თქვენც დაგღალათ და ბავშვიც? თბილი აბაზანა მხოლოდ სისუფთავისთვის არ არის — ეს მისი დაძაბული ნერვული სისტემის დასამშვიდებლად ერთ-ერთი საუკეთესო ბუნებრივი საშუალებაა.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'შეეგუეთ არეულობას 🌪️', 'ყოველდღე ერთი და იმავე სათამაშოების ალაგებით დაიღალეთ? დღეს ნუ აალაგებთ! სახლში არეულობა სამყაროს დასასრული არ არის — თქვენი ფსიქოლოგიური სიმშვიდე ყველაფერზე მნიშვნელოვანია.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'დაადუმეთ დანაშაულის გრძნობა 💬', 'თავს იდანაშაულებთ, რადგან ბავშვმა დღეს ეკრანთან ზედმეტად ბევრი დრო გაატარა? შეუერთდით Anacan-ის საზოგადოებას, წაიკითხეთ, რომ სხვა დედებიც ზოგჯერ იმავეს გრძნობენ, და დამშვიდდით. თქვენ მარტო არ ხართ.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'პიროვნება სარკეში 👀', 'სარკის წინ სხვადასხვა გამომეტყველებას იღებს, საკუთარ თავს ელაპარაკება და იცინის? საკუთარი პიროვნების გაცნობიერება შესანიშნავად აქვს განვითარებული. ჩუმად დააკვირდით და ამ სახალისო მომენტებით სიამაყით დატკბით.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'დილის ცეკვა 🎶', 'თვალის გახელისთანავე ენერგიით სავსეა? დილის ქაოსის დასამშვიდებლად ჩართეთ მხიარული საბავშვო სიმღერა, რამდენიმე წუთი ოთახში იცეკვეთ და დღე ღიმილით დაიწყეთ.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'საჭირო ნივთების სია 🛒', 'ბავშვის საფენები, შამპუნი ან ხილის პიურე გამოგელიათ? თავს ნუ დაიტვირთავთ — ყველაფერი მაშინვე ჩაწერეთ საყიდლების სიაში და ერთი დაწკაპუნებით გაუზიარეთ თქვენს პარტნიორს.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'ღრმა სიჩუმე 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმის საზომით შეამოწმეთ გარემოში ხმაურის დონე დეციბელებში, ტელევიზორს ხმას დაუწიეთ და დააფასეთ სახლში გამეფებული ეს ღრმა სიჩუმე.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'ეგოიზმი პარკში 🧸', 'ქვიშაში თამაშისას თავის სათამაშო ჭურჭელს არავის აძლევს? ეს ეგოიზმი კი არა, საკუთარი საზღვრების დაცვაა. ნუ დააძალებთ გაზიარებას; ამის ნაცვლად, მშვიდად ასწავლეთ წესი — „მორიგეობით ვითამაშოთ“.'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'წარმოსახვითი თამაშები 🧸', 'ცდილობს, სათამაშო დათუნიას ან თოჯინას წყალი დაალევინოს და მათთან დიალოგს მართავს? სიმბოლური თამაშები განვითარების ნამდვილი შედევრია. ინტერესით დააკვირდით ამ საყვარელ პატარა რეჟისორს.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'ახალი სიტყვები 🧠', 'დღეს უჩვეულო და უფროსივით რთული წინადადება ააწყო? დაუყოვნებლივ გახსენით განვითარების ტრეკერი და ეს კოგნიტიური ნახტომი მოგონებად ჩაინიშნეთ, რათა მომავალში წაიკითხოთ.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'დრო წყვილისთვის 🥂', 'ბავშვს ჩაეძინა. ახლა საოჯახო საქმეები გვერდზე გადადეთ. სულ მცირე 20 წუთის განმავლობაში პარტნიორს ბავშვის გარდა ნებისმიერ თემაზე ესაუბრეთ. გახსოვდეთ, რომ თქვენ წყვილიც ხართ.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'მიზანმიმართული ხოხვა 🐢', 'სიარულთან ერთად, ზოგჯერ გასართობად სწრაფად ხოხავს და თქვენგან გარბის? ოთახიდან სახიფათო დაბრკოლებები მოაშორეთ და ამ დაჭერობანას თქვენც შეუერთდით.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'ოფლაინ საათი დედისთვის ☕', 'როდესაც ბავშვი თავის სამყაროში ჩაფლული თამაშობს, მაშინვე ჭურჭლის სარეცხ მანქანასთან ნუ გაიქცევით. დაისხით ცხელი ჩაი, ტელეფონი გვერდზე გადადეთ და 15 წუთით არაფერზე იფიქროთ — უბრალოდ ოფლაინ იყავით.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'რკინის საიდუმლო: C ვიტამინი 🍋', 'ფერმკრთალია ან მადა არ აქვს? კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი რკინა და მის უკეთ შესაწოვად ხორცთან ერთად აუცილებლად მიეცით უხვად ლიმონმოსხმული სალათი.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'ღამით გაღვიძება 🌌', 'შუაღამისას ტირილით იღვიძებს და ვერ მშვიდდება? ღამის ტერორსა და კოშმარს შორის განსხვავების გასაგებად და სწორი ფსიქოლოგიური მიდგომის შესარჩევად, გაეცანით ბლოგების განყოფილებას.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'წრეების ხატვის ხელოვნება! 🎨', 'ცდილობს ფანქრით ქაღალდზე (ან კედელზე!) შეკრული წრეები დახატოს? ეს მოტორული უნარების განვითარების შესანიშნავი წინსვლაა.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'ჩურჩულით საუბრები 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. მის გვერდით დაწექით და დღის განმავლობაში მომხდარი ამბები ძალიან ხმადაბლა, ჩურჩულით მოუყევით. ჩურჩული ტვინის ძილისთვის მომზადების ერთ-ერთი ყველაზე დამამშვიდებელი გზაა.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'უმტკივნეულო დღეები 🩸', 'მენსტრუაცია გიახლოვდებათ და სპაზმები უკვე დაიწყო? სანამ მედიკამენტებს მიმართავთ, „ჯანსაღი რეცეპტებიდან“ მოამზადეთ მაგნიუმით მდიდარი ფინიკისა და ნიგვზის წასახემსებელი და საკუთარ თავზე იზრუნეთ.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'თითებით დათვლა 🔢', 'კიბეზე ასვლისას ან სათამაშოების დალაგებისას ცდილობს თქვას ერთი, ორი, სამი? მისი მათემატიკური აზროვნება იღვიძებს. მასთან ერთად ხმამაღლა დაითვალეთ ოთახში არსებული ნივთები.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'აღიდგინეთ ენერგია 🍲', 'ყოველდღიურმა ფუსფუსმა ძალა გამოგაცალათ. ფეხზე დგომისას წახემსების ნაცვლად, მოიმზადეთ ნოყიერი, კალციუმით მდიდარი განსაკუთრებული კერძი და სიამოვნებით მიირთვით.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'მამის სასაცილო სახე 🤡', 'ბავშვის გაცინების ყველაზე სწრაფი გზა მამის მიერ უცნაური ხმების გამოცემა და სასაცილო მიმიკების გაკეთებაა. ამ საღამოს მხიარულ კისკისს მოუსმინეთ და თქვენც ღიმილით ადევნეთ თვალი.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'დედის დილის ენერგია ⚡', 'დილით დაღლილმა გაიღვიძეთ? შაქარს ნუ მიეძალებით. „ჯანსაღ რეცეპტებში“ აღმოაჩინეთ ცილებითა და ხილით მდიდარი შვრიის საუზმე, რომელიც 5 წუთში მზადდება, და დღე ენერგიულად დაიწყეთ.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'მამის მხარდაჭერა გჭირდებათ 🫂', 'მენსტრუაციის ტრეკერის მიხედვით, PMS-ის დღეები გაქვთ და განსაკუთრებით მგრძნობიარე ხართ? პარტნიორის ფუნქციით აცნობეთ მას, რომ დღეს ცოტა მეტი მხარდაჭერა გჭირდებათ.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'ბალიშების ციხესიმაგრე 🏰', 'ამ საღამოს ოთახი სათამაშო მოედნად აქციეთ. დივნის ბალიშებით პატარა ციხესიმაგრე ააშენეთ და შიგნით შეძვერით. ცოტა არეულობა იქნება, მაგრამ ეს მხიარული სიცილი ნამდვილად ღირს ამად.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'ადვოკატური მოლაპარაკება 🗣️', 'გეუბნებათ, კიდევ ცოტას ვითამაშებ და მერე ჩავიცვამო? ის უკვე პროფესიონალივით ცდილობს თქვენთან შეთანხმებას. მეტყველების განვითარება შესანიშნავად მიმდინარეობს, თუმცა არ დაგავიწყდეთ, სიყვარულით დაიცვათ თქვენი საზღვრები.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'ბუნების აღმოჩენა 🌳', 'ოთხ კედელში ყოფნა უკვე გაწუხებთ. გრილი ამინდიც რომ იყოს, ბავშვს თბილად ჩააცვით და 20 წუთით პარკში გაიყვანეთ. მიეცით საშუალება, ფოთლები და ქვები შეისწავლოს — სუფთა ჰაერი ორივეს კარგ ხასიათზე დაგაყენებთ.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', '„გიპოვე!“ — მხიარული მოლოდინი 🙈', 'დამალობანა უკვე მისი საყვარელი თამაშია. ფარდის უკან იმალება და ელოდება, როდის იპოვით. ეს თამაში თქვენი ყოველდღიური რუტინის ყველაზე სახალისო ნაწილად აქციეთ.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'სიბნელესთან შეგუება 🌙', 'იმისთვის, რომ უფრო სწრაფად ჩაეძინოს, ოთახში ყველა ეკრანი გამორთეთ. ტელევიზორის ლურჯი სინათლე ძილის ჰორმონის გამომუშავებას აფერხებს.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'გაბედული ნაბიჯები 🧗‍♂️', 'დივანს ან სავარძელს ეჭიდება და ზემოთ აძრომას ცდილობს? მისი წონასწორობა და კუნთების ძალა იზრდება. დაიცავით, თუმცა ამ პატარა მთამსვლელის მცდელობებს ხელს ნუ შეუშლით.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'საკვებზე უარის თქმა 🥣', 'ორ კოვზს ჭამს, ამბობს, რომ დანაყრდა და გარბის? ნუ დააძალებთ. საკვებთან ჯანსაღი დამოკიდებულების ჩამოყალიბება უფრო მნიშვნელოვანია, ვიდრე ძალით კვება.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'დღის შეჯამება 📝', 'დღეს საოცრად დაიღალეთ თუ მან ძალიან საყვარელი რამ თქვა? ორივე შემთხვევაში გახსენით განწყობის დღიური, ეს წამი სამომავლოდ ჩაინიშნეთ და გულზე მოეშვით.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'ყურადღების ტესტი 🧩', 'ერთი სათამაშოთი, მაგალითად, ფაზლით თამაშს უკვე 10-15 წუთს უთმობს? ეს ნიშნავს, რომ ყურადღების კონცენტრაციის ხანგრძლივობა იზრდება. ჩუმად დადექით ოთახის ერთ კუთხეში და დააკვირდით.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'მიზეზშედეგობრივი კავშირების ძიება 🤔', '„რა მოხდება, ამას თუ გადავაგდებ?“, „ეს ღილაკი რისთვისაა?“ ბავშვი მუდმივად ატარებს პრაქტიკულ ექსპერიმენტებს. კიდევ ერთხელ შეამოწმეთ სახლის უსაფრთხოება იატაკის დონიდან.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'ზღაპრის გარეშე არ ვიძინებთ 🪄', 'კლასიკური ზღაპრები მის ყურადღებას აღარ იპყრობს? მოიფიქრეთ განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თავად იქნება, ფონად ბუნების ხმები დაურთეთ და მის წარმოსახვით სამყაროში შეაბიჯეთ.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'გუნდური შეხვედრა 🥂', 'მას შემდეგ, რაც ბავშვი დაიძინებს, დღის სტრესის მოსახსნელად პარტნიორთან ერთად ჩაი დაისხით, უთხარით ერთმანეთს „ჩვენ შესანიშნავი გუნდი ვართ“ და გამოხატეთ ერთმანეთის მიმართ მადლიერება.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'ცეკვა მუსიკის თანხლებით 🎶', 'მხიარული მუსიკის გაგონებისთანავე რიტმს აჰყვება და ირწევა? სმენასა და მოტორულ უნარებს შორის კავშირი შესანიშნავად ვითარდება! ჩართეთ მხიარული სიმღერა და მასთან ერთად ოთახში იცეკვეთ.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'მამის ზღაპარი 📖', 'დღეს საღამოს ხმას დასვენების საშუალება მიეცით. ბავშვის საყვარელი წიგნების სხვადასხვა ხმითა და სახალისოდ წაკითხვა მამას მიანდეთ.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', '„რატომ?“ დასრულდა, „როგორ?“ დაიწყო 🤔', 'წარმოსახვისა და ლოგიკური აზროვნების ახალი ნახტომი! ახლა ბავშვი უკვე იმასაც გეკითხებათ, როგორ მუშაობს სხვადასხვა ნივთი. ჩვენი Anacan AI ექსპერტისგან ისწავლეთ, როგორ უპასუხოთ ამ კითხვებს ბავშვის ასაკის შესაბამისად და საინტერესოდ.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'შეეგუეთ უძილო ღამეებს 😭', 'ბავშვმა შუაღამისას გაიღვიძა და დაძინება აღარ სურს. ნუ გაუბრაზდებით. გაარკვიეთ მიზეზი (ტკივილი, აირები, შიში), მოთმინებით ჩაეხუტეთ და უსაფრთხოების განცდა აგრძნობინეთ.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'ჯიუტი ლაქები 👗', 'ტანსაცმელზე მუდმივად გაჩენილი ლაქები გღლით? ნუ გაბრაზდებით. ბავშვი საკვებს ეცნობა. გამოიყენეთ სილიკონის წინსაფრები და დატკბით ამ ფერადი, არეულ-დარეული მომენტებით.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'მეც დაგეხმარებით! 🧹', 'როდესაც იატაკს წმენდთ ან მტვერს იღებთ, ცდილობს ნივთი ხელიდან გამოგართვათ? ის უკვე დიდად გრძნობს თავს. მიეცით პატარა ტილო და ნება დართეთ, თქვენს გუნდს შეუერთდეს.'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'აღმოაჩინეთ ადგილი დედისთვის ☕', 'სახლში ერთი და იმავე კედლების ყურებამ დაგღალათ. „დედებისთვის მეგობრულ ადგილებში“ აღმოაჩინეთ კაფე საბავშვო სათამაშო კუთხით. სანამ ბავშვი თამაშობს, თქვენ ყავით ისიამოვნეთ.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'ცხოველების ხმები 🐶', 'კატის დანახვისას კნავის, ძაღლის დანახვისას კი „ჰავ-ჰავის“ თქმას ცდილობს? ცხოველების ხმებით სიტყვათა მარაგი შესანიშნავად ვითარდება. ითამაშეთ მასთან ეს თამაში.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'სწრაფი პედიატრი 🤖', '2.5 წლის ასაკთან მიახლოებისას, რა ზომის უნდა იყოს ულუფა? თუ ეჭვი გეპარებათ, დაუყოვნებლივ სთხოვეთ Anacan AI-ს ზუსტი და მეცნიერულად დასაბუთებული ცხრილი.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'მოუსმინეთ თქვენს სხეულს 🩸', 'ტკბილეულის უეცარი მოთხოვნილება ან დაღლილობა გაწუხებთ? გადახედეთ მენსტრუაციის ტრეკერის კალენდარს. თუ მენსტრუაცია გაქვთ, ჯანსაღი რეცეპტებიდან მაგნიუმით მდიდარი წასახემსებელი შეარჩიეთ.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'ჩრდილები ოთახში 🌌', 'სიბნელისა და წარმოსახვითი ურჩხულების ეშინია? ოთახი სრულად არ ჩააბნელოთ და თეთრი ხმებიდან საშვილოსნოს ხმები ჩაურთეთ, რათა კვლავ ნაცნობი, სრული უსაფრთხოების განცდა აგრძნობინოთ.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'განშორების შფოთვა 🥺', 'როცა ოთახიდან გადიხართ, თუნდაც საპირფარეშოში, უკან გამოგყვებათ და ტირის? მას ჰგონია, რომ აღარ დაბრუნდებით. დაამშვიდეთ სიტყვებით: „მე ყოველთვის აქ ვარ, ჩემი ხმა გესმის?“'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'პატარა მოსაუბრე 🗣️', 'უკვე 4-5 სიტყვას აერთიანებს და სასაცილო ამბებს ჰყვება? მისი სიტყვათა მარაგი საოცარი სისწრაფით იზრდება! არ გამოტოვოთ ეს ოქროს დრო.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'გაფილტრეთ ხმები 🤫', 'დაძინების მომენტში მისი მგრძნობელობა იმატებს. ფანჯრიდან შემოსული ხმების გასანეიტრალებლად ოთახში დაბალ ხმაზე ჩართეთ თეთრი ხმაურის (white noise) აპარატი ან მუსიკა.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'ერთად სამზარეულოში 🧑‍🍳', 'სურს, სამზარეულოში თქვენთან ერთად აკეთოს საქმე? მიეცით საშუალება, ფქვილის ან წყლის დამატებაში დაგეხმაროთ. ყველაფერიც რომ დასვაროს, მისი ბედნიერება და სწავლის სურვილი ამად ღირს.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'ზღაპრის გმირი 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ შექმენით განსაკუთრებული ამბავი, რომლის გმირიც თქვენი შვილი იქნება: მამაცი პატარა, რომელსაც კბილების გახეხვა უყვარს.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'სია სასურველი კი არა, აუცილებელია 🛒', 'უძილობამ მეხსიერება დაგიქვეითათ და მაღაზიაში მისვლისას გასაყიდი ნივთები გავიწყდებათ? ნუ გადატვირთავთ გონებას. ყველაფერი აპში არსებულ საყიდლების სიაში ჩაწერეთ.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც თამაშია საჭირო და არც წიგნი. ამ საღამოს უბრალოდ გულში ჩაიკარით, მისი სურნელი ღრმად შეიგრძენით და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'კონსტრუქტორის ოსტატი 🧱', 'დიდი LEGO-ს კუბიკების ერთმანეთზე შეერთებით რაღაცის აწყობას ცდილობს? ის სივრცესა და გეომეტრიას იკვლევს. განვითარების ტრეკერში მონიშნეთ მისი ეს განსაკუთრებული საინჟინრო მცდელობა.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', '10 წუთი განმარტოებისთვის 🛀', 'ოთახში სიჩუმემ დაისადგურა. სთხოვეთ პარტნიორს, ცოტა ხნით სახლის ყველა საქმეს მან მიხედოს. თქვენ კი თბილი შხაპი მიიღეთ და მხოლოდ საკუთარ თავთან დარჩით.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', '2 წლის ასაკის კრიზისი 📱', 'დაიღალეთ იმით, რომ ბავშვი ყველაფერზე „არას“ ამბობს? წაიკითხეთ ბლოგების განყოფილებაში არსებული სტატიები და გაიგეთ, რა იწვევს მის ტვინში მიმდინარე განვითარების ამ ქარიშხალს.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'ბოსტნეულის დამალვის ოპერაცია 🥦', 'მწვანილს ან ბროკოლის თეფშიდან ყრის? ბავშვებისთვის განკუთვნილ რეცეპტებში აღმოაჩინეთ ფერადი, ბოსტნეულიანი შინ მომზადებული კექსი და კვების კონტროლის ხელსაწყოში მარტივად მონიშნეთ ვიტამინების დღიური ნორმა.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', '„მიყვარხარ“ ჩახუტება 🫂', 'უეცრად მოდის, კისერზე გეხვევათ ან სახეზე გეფერებათ? ის თავის სიყვარულს უკვე ფიზიკურად გამოხატავს. დატკბით ამ მომენტის შეუდარებელი სიმშვიდით.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'ღრმად ჩაისუნთქეთ 🧘‍♀️', 'მთელი დღე კითხვებზე პასუხის გაცემით ყელი გაგიშრათ. როგორც კი ოთახში სიჩუმე დაისადგურებს, არცერთ ეკრანს არ შეხედოთ — უბრალოდ ღრმად ჩაისუნთქეთ და ამოისუნთქეთ, რათა დაისვენოთ.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'სიტყვების წარმოთქმა 🗣️', 'ზოგიერთ სიტყვას არასრულად ან ძალიან სასაცილოდ წარმოთქვამს? ნუ გაიცინებთ, უბრალოდ სწორად და სათანადო მახვილით გაუმეორეთ, რათა მისმა ტვინმა სწორი ვარიანტი დაიმახსოვროს.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'დამოუკიდებელი თამაში 🧸', 'არ ხართ ვალდებული, ყოველ წუთს გაართოთ. მოწყენა ბავშვებისთვის შემოქმედებითობის დასაწყისია. მიეცით საშუალება, ოთახში დამოუკიდებლად აღმოაჩინოს რამე.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'წამი, რომელიც დროს აჩერებს 📸', 'როცა ბავშვს სძინავს, შეხედეთ მის უმანკო სახეს. მიუხედავად იმისა, რომ მთელი დღე შეიძლება ჭკუიდან გადაჰყავდეთ, როგორც კი დაიძინებს, მაშინვე გენატრებათ, ხომ ასეა? დედობა სწორედ ეს პარადოქსია.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'წყლის სმის ჩვევა 💧', 'წყლის ნაცვლად სულ ტკბილ წვენებს ითხოვს? კვების გეგმაში სითხის მიღების რეჟიმი შეამოწმეთ. წყალი ფერად ჭიქებში, სპეციალური საწრუპით შესთავაზეთ, რათა მისი დალევის სურვილი გაუჩინოთ.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'ტაშის გუნდი 👏', 'როცა რამე გამოსდის, საკუთარ თავს ტაშს უკრავს და ასე გამოხატავს სიხარულს? როგორც კი ამ შესანიშნავ მომენტს დაინახავთ, სახლში გამარჯვების პატარა ცეკვა შეასრულეთ და მისი სიხარული გაიზიარეთ!'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'სითხის მიღება და ყაბზობა 💩', 'ბევრს დარბის და ცოტა წყალს სვამს? დააკვირდით მის განავალს ქოთანში ან საფენში. თუ ყაბზობის რისკია, მონიშნეთ ეს აპში და კვების კონტროლის ინსტრუმენტის დახმარებით მენიუში დაუყოვნებლივ დაამატეთ შვრია ან მსხალი.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'ახალი მეგობრების ძიება 👫', 'პარკში თანატოლებთან ერთად სირბილსა და მათთან მიახლოებას ცდილობს? სოციალიზაცია ოფიციალურად დაიწყო! უსაფრთხოება დისტანციიდან აკონტროლეთ და ამ მცდელობებს სიამაყით ადევნეთ თვალი.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'ღამის მელოდია 🛀', 'მთელი დღის სირბილმა ისიც დაღალა და თქვენც. თბილი აბაზანა და ფონად ჩართული მსუბუქი, ნაზი მელოდია მის ნერვულ სისტემას სრულად დაამშვიდებს.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'დღის ძილზე უარი 🥱', 'ისევ ვერ დაიძინა? ნუ შეეჭიდებით და ნუ დაღლით არც მას და არც საკუთარ თავს. ოთახში სათამაშოებით ჩუმად თამაში ტვინისთვის დასვენების ერთ-ერთი ფორმაა.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'სიჩუმე და ყავა 🤫', 'დაიძინა! ახლა, ჭურჭლის სარეცხი მანქანის დაცლის ნაცვლად, ჩაბნელებულ ოთახში ჩამოჯექით. დააფასეთ 15 წუთი სიჩუმე და დაისვენეთ.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'დაბლა ჩაიხედეთ! 👣', 'უკვე ფეხის თითებს იჭერს და აკვირდება, ან თუნდაც ფეხშიშველი სიარული სიამოვნებს? ტერფებზე არსებული ნერვული დაბოლოებების შეგრძნებით შესწავლა მისი წონასწორობის განვითარებისთვის ძალიან მნიშვნელოვანია.'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'როცა დედა იღლება 🛑', 'თქვენ რობოტი არ ხართ. თუ დღეს საჭმლის მოსამზადებლად ენერგია არ გაქვთ, შეუკვეთეთ. იდეალური დედობა არ ნიშნავს, რომ ყველაფერი მარტო უნდა გააკეთოთ.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'მტკიცე „არა“ 🛑', 'როცა ვინმეს მისი კოცნა სურს, თავს არიდებს და მტკიცედ ამბობს „არას“? პატივი ეცით მისი სხეულის საზღვრებს. ძალიან მნიშვნელოვანია, რომ უნებართვო შეხებას აპროტესტებდეს.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'გულახდილი საუბრები 💬', 'ძალიან დაიღალეთ? შეუერთდით Anacan-ის საზოგადოებას. წაიკითხეთ ათასობით დედის რეალური ისტორია და ძალა მოიკრიბეთ იმის გაცნობიერებით, რომ მარტო არ ხართ.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'დამალეთ ბოსტნეული 🥦', 'წვნიანში ყველა ბოსტნეულს გვერდზე დებს? ნუ შეებრძოლებით. ბოსტნეულის პიურედ ქცევა და სოუსში ან კატლეტში დამალვა დედების ერთ-ერთი უძველესი ხრიკია.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'სურათებზე რეაქცია 📖', 'წიგნში ცხოველების ან სხვადასხვა საგნის დანახვისას ეხება მათ ან ბგერებს გამოსცემს? მისი ვიზუალური აღქმა გასაოცარია. ესაუბრეთ წიგნის პერსონაჟებზე.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'ძილთან ჭიდილი 🏃‍♂️', 'დაძინების თავიდან ასაცილებლად გამუდმებით იგონებს მიზეზებს? ჩართეთ ძილის ტაიმერი, დაიცავით საზღვრები და ოთახში მშვიდი გარემოს შესაქმნელად თეთრი ხმებიდან წვიმის ხმა ჩართეთ.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'მეხსიერების გაკოტრება 🛒', 'უძილობამ მეხსიერება დაგიქვეითათ და მაღაზიაში საყიდლები გავიწყდებათ? ნუ გადატვირთავთ ტვინს. ყველაფერი სიაში ჩაწერეთ და თქვენს პარტნიორს სთხოვეთ, შინ დაბრუნებისას იყიდოს.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'დიპლომატიური მოლაპარაკებები 🤝', 'პარკში თავის სათამაშოს სხვას არ აძლევს? აუცილებლად წაიკითხეთ ბლოგების განყოფილებაში, როგორ ასწავლოთ 2.5 წლის შემდეგ არა გაზიარება, არამედ მორიგეობით თამაში.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'ღამით გაღვიძებები 🌌', 'შუაღამისას ტირილით იღვიძებს და ვერ მშვიდდება? გადახედეთ ძილის ტაიმერის გრაფიკს. ღამის ტერორსა და კოშმარს შორის განსხვავების გასაგებად ახლავე ეწვიეთ ბლოგების განყოფილებას.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'ოთხ კედელს მიღმა ☕', 'სახლის რუტინამ უკვე დაგღალათ. დღეს რაიმე განსხვავებული სცადეთ. ახლომდებარე მშვიდ კაფეში წადით, რომ ბავშვს გარემო შეუცვალოთ, თავად კი ყავით დატკბეთ.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'ძილისადმი მგრძნობელობა 🤫', 'როგორც კი დაიძინებს, უმცირეს ხმაურზეც კი კრთება? შეამოწმეთ ოთახის აკუსტიკა და ფანჯრიდან შემოსული ხმების გასანეიტრალებლად თეთრი ხმაური ჩართეთ.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'ავეჯზე აცოცება 🧗‍♂️', 'დივანს ან სკამს ეჭიდება და ზემოთ აცოცებას ცდილობს? მისი ფეხის კუნთები სხვადასხვა სიმაღლეს ცდის. დაიცავით, თუმცა ამ პატარა ალპინისტის მცდელობებს ხელს ნუ შეუშლით.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'ხელოვნების ნიმუში თეფშზე 🥦', 'საჭმელს არ ჭამს? ზოგჯერ პრობლემა გემო კი არა, გარეგნობაა. ფერადი ბოსტნეულით სახალისო სახეები შექმენით და მისი მადის გაღვიძება სცადეთ.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'ღამის იავნანა 🎶', 'ვერცერთი აპლიკაცია თუ ხმა დედის იავნანას ვერ შეცვლის. ამ საღამოს უბრალოდ გულში ჩაიკარით და ჩუმად უმღერეთ მისი საყვარელი იავნანა, რომელიც სიმშვიდისა და დაცულობის შეგრძნებას ანიჭებს.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'პირველი გამარჯვება ტუალეტში! 🚽', 'ქოთანზე თავად დაჯდომა სურს? ეს 2.5 წლის ასაკის ერთ-ერთი უდიდესი გამარჯვებაა! მონიშნეთ ეს წარმატება საფენის/ქოთნის ტრეკერში და ბლოგებში წაიკითხეთ, როგორ შეგიძლიათ ეს გადასვლა კიდევ უფრო გაუადვილოთ.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა შეცდომაში არ შეგიყვანოთ და ბავშვი არ გააციოთ. გადაწყვეტილებას მხოლოდ ფანჯრიდან გახედვით ნუ მიიღებთ — წინასწარ შეამოწმეთ გარეთ ქარის სიჩქარე და რეალური ტემპერატურა.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'საკუთარ „მე“-ს აღმოაჩენს 👑', '„მე ვარ!“, „ჩემია!“ — ამ სიტყვებს ხშირად იმეორებს. ეს ეგოცენტრიზმის პერიოდის ყველაზე მკვეთრი ეტაპია. პატივი ეცით მის ინდივიდუალურობას — ეს განვითარების ბუნებრივი ეტაპია.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'მამის პასუხისმგებლობა 👨‍🍼', 'დღის განმავლობაში ისედაც საკმარისად იღლებით. საღამოს ბავშვის დასაძინებლად მომზადება და პიჟამის ჩაცმა მამას მიანდეთ, თავად კი უბრალოდ გვერდიდან ადევნეთ თვალი.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'ენერგიის მარაგი გჭირდებათ 🍲', 'დაღლილობას მთელ სხეულში გრძნობთ? დააჯილდოეთ საკუთარი თავი განსაკუთრებული სალათით, რომელიც 10 წუთში მზადდება, დაგანაყრებთ და ენერგიით აგავსებთ.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'კბილის ჯაგრისთან ბრძოლა სრულდება 🪥', 'კბილის ჯაგრისის დანახვისთანავე პირს მჭიდროდ კუმავს? რეკომენდებულ პროდუქტებში მოძებნეთ საბავშვო მუსიკალური ან მბრუნავი ჯაგრისები, რომლებიც ამ პროცესს გაამარტივებს და ჰიგიენას სახალისო საქმიანობად აქცევს.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'ღამის ქარიშხალი 😭', 'შუაღამისას უმიზეზოდ ტირილით გაიღვიძა? აირები აწუხებს თუ უბრალოდ ღამის შიშია? მშვიდად ჩაიხუტეთ და ხმის აუწევლად დაამშვიდეთ.'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'სიჯიუტის შეტევები 🛑', 'ყოველ თქვენს „არას“ ყვირილით პასუხობს? გაესაუბრეთ Anacan AI-ს, რათა ისწავლოთ, როგორ მართოთ სიმშვიდის შენარჩუნებით ეს უკონტროლო ემოციური აფეთქებები და როგორ გამოიყენოთ ყურადღების გადატანის ტაქტიკები.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'მამიკოს ზღაპრების საათი 📚', 'ამ საღამოს ძილისწინა რიტუალი თქვენს პარტნიორს მიანდეთ! აპში პარტნიორის რეჟიმის გამოყენებით ზღაპარი მან წაიკითხოს, თქვენ კი მშვიდად მიირთვით ჩაი.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'გამოცდილების გაზიარება 💬', 'ბავშვის ახალმა ქცევამ შეგაშინათ? ინტერნეტში შემაშფოთებელ სტატიებს ნუ მოძებნით. ისარგებლეთ Anacan-ის საზოგადოებაში გამოცდილი დედების რჩევებით.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'რკინის საიდუმლო: ვიტამინი C 🍋', 'ბავშვი ფერმკრთალია ან მადა არ აქვს? კვების კონტროლის ხელსაწყოში შეამოწმეთ, მიიღო თუ არა დღეს საკმარისი რკინა და შეწოვის გასაუმჯობესებლად ხორცთან ერთად აუცილებლად მიეცით უხვად ლიმონმოსხმული სალათი.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'მხოლოდ მშრალი საკვები? 🍞', 'პიურესა და თხევად კერძებზე უარს ამბობს და მხოლოდ პურსა და ორცხობილას ითხოვს? ეს საკვების ტექსტურისადმი შერჩევითი დამოკიდებულებაა. კვების კონტროლის ხელსაწყოთი გააანალიზეთ მენიუ და ბავშვის რეცეპტებში ჯანსაღი ალტერნატივები იპოვეთ.'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'მოუსმინეთ თქვენს სხეულს 🩸', 'მოულოდნელად ტკბილეული მოგინდათ და გაღიზიანებული ხართ? მენსტრუაციის ტრეკერში კალენდარს გადახედეთ. თუ მენსტრუაცია გიახლოვდებათ, ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ მაგნიუმით მდიდარი ფინიკისა და ნიგვზის წასახემსებელი.'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'ბუნების დეტექტივი 🔍', 'სახლში ყველაფერს ყრის და აფუჭებს? აიღეთ გამადიდებელი შუშა და გარეთ გადით! დედებისთვის მეგობრულ სივრცეებს შორის იპოვეთ გამწვანებული პარკი, ერთად აღმოაჩინეთ მწერები და ფოთლები და მისი ენერგია ბუნებისკენ მიმართეთ.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'საღამოს რუტინა გართულდა?🛀', 'თბილი აბაზანის მიღებისას ფონად დამამშვიდებელი მუსიკა ჩართეთ. წყლისა და მელოდიის ჰარმონია ყველაზე ჯიუტ ბავშვსაც კი ამშვიდებს.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'ქაოსი სახლში 🌪️', 'ოთახი სათამაშოებითაა სავსე? დალაგებაზე უფრო მნიშვნელოვანია მასთან მხიარულად გატარებული 10 წუთი. სათამაშოები ხვალაც იქ იქნება, თავს ნუ გადაიღლით.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'სრული სიმშვიდის ძიება 🛋️', 'როგორც კი ბავშვი დაიძინებს, ჭურჭლის სარეცხი მანქანის დასაცლელად ნუ გაიქცევით! წამოწექით დივანზე, დახუჭეთ თვალები და 15 წუთით დატკბით სახლში გამეფებული იმ იშვიათი, სრული სიმშვიდით.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'სიბნელესთან შეგუება 🌙', 'ბავშვმა უფრო სწრაფად რომ დაიძინოს, ოთახში ყველა დამატებითი სინათლის წყარო და ეკრანი გამორთეთ. ჰორმონ მელატონინის გამომუშავება მხოლოდ მშვიდ და ბნელ გარემოში ჩქარდება.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'მე შენ გისმენ 🗣️', 'ყურადღებით გისმენთ და მსგავსი წინადადებების წარმოთქმას ცდილობს? ის თქვენ გესაუბრებათ! ხშირად გაუღიმეთ, უპასუხეთ და ასეთი კომუნიკაცია წაახალისეთ.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'სუფთა ჰაერზე გასვლის დრო 🌳', 'ოთხ კედელში ყოფნა უკვე გაწუხებთ. ჩასვით ბავშვი ეტლში და თუნდაც 20 წუთით გაიყვანეთ სუფთა ჰაერზე. ბუნების სიმშვიდე შესანიშნავად იმოქმედებს როგორც ბავშვზე, ისე თქვენს ფსიქოლოგიურ მდგომარეობაზე.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'დაბლა ჩაიხედეთ! 👣', 'უკვე სიამოვნებს ბავშვს ფეხშიშველი სიარული და ტერფებით სხვადასხვა ზედაპირის შეგრძნება? ტერფის ნერვული დაბოლოებების ასეთი სტიმულაცია მისი წონასწორობის განვითარებისთვის ძალიან მნიშვნელოვანია.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'ზღაპრის ჯადოსნური სამყარო 🪄', 'ამ საღამოს სრულიად განსხვავებული რამ სცადეთ: მოუყევით ამბავი პატარა ღრუბელზე, რომელიც ცას იკვლევს. თქვენი ხმის ტონი ზღაპრის რიტმს მოარგეთ.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'სიმშვიდე საღამოს რუტინაში 🌬️', 'მთელი დღე დარბოდა და ახლა ვერ მშვიდდება? ჩართეთ ძილის ტაიმერი, თეთრი ხმებიდან ოკეანის ტალღების ხმა აირჩიეთ და ოთახი მშვიდ, ძილისთვის განკუთვნილ მყუდრო სივრცედ აქციეთ, რათა ბავშვი დამშვიდდეს და განიტვირთოს.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'მამის დღე სამზარეულოში 👨‍🍳', 'გაააქტიურეთ პარტნიორის რეჟიმი. დღეს სადილის მომზადება და ბავშვის კვება მამას ევალება! თქვენ კი ეს დრო საკუთარ თავს დაუთმეთ — წაიკითხეთ წიგნი ან უბრალოდ დაისვენეთ.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'მიზანმიმართული ხოხვა 🐢', 'უკვე დადის, მაგრამ ზოგჯერ გასართობად სწრაფად ხოხავს და თქვენგან გარბის? ოთახიდან სახიფათო დაბრკოლებები მოაშორეთ და თქვენც შეუერთდით ამ დაჭერობანას თამაშს.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'თავადაც არ იცის, რატომ ტირის 😭', 'იმიტომ ატყდა დიდი ისტერიკა, რომ ჭიქა ლურჯი კი არა, წითელია? სინამდვილეში ამის მიზეზი დაღლილობა ან ემოციური გადატვირთვაა. ამ უკონტროლო ემოციურ აფეთქებებს მშვიდად რომ გაუმკლავდეთ, გაესაუბრეთ Anacan AI-ს.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'უცხო ხმები ოთახში 🌌', 'ოთახში სრული სიჩუმე ან მეზობლის სახლიდან შემოსული სუსტი კაკუნი აღვიძებს? თეთრი ხმებიდან ვენტილატორის ხმა ჩართეთ და ნახეთ, როგორ შექმნით ძილისთვის იდეალურად იზოლირებულ გარემოს.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'ერთად დავალაგოთ სახლი 🧹', 'სახლია დასალაგებელი? ჩართეთ პარტნიორის რეჟიმი! აღმოაჩინეთ, როგორ შეგიძლიათ თქვენ, მამამ და თქვენმა პატარამ (ხელში პატარა ტილოს მიცემით) დალაგება მხიარულ ოჯახურ თამაშად აქციოთ.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'ეკრანის ნაცვლად თამაში 📱', 'საღამოობით მულტფილმს ითხოვს და ტირის? Anacan AI-სგან შეიტყვეთ, როგორ შეზღუდოთ ეკრანთან გატარებული დრო სტრესის გარეშე და დაუყოვნებლივ გადაიტანოთ მისი ყურადღება სხვა თამაშზე.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'თქვენი ყავის დრო ☕', 'მუდმივად სახლში ყოფნით დაიღალეთ? დედებისთვის მეგობრული ადგილების სიაში იპოვეთ საბავშვო კაფეები, სადაც ბევრი დედა იკრიბება, და თქვენთვისაც შექმენით ახალი გარემო სოციალური ურთიერთობებისთვის.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'რიგის ლოდინის ხელოვნება 🧸', 'პარკში არ სურს დაელოდოს, სანამ სხვა ბავშვი სასრიალოდან ჩამოვა? ბლოგების განყოფილებაში აუცილებლად წაიკითხეთ, როგორ ასწავლოთ 2.5 წლის შემდეგ მოთმინება და რიგის დაცვით თამაში.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'D ვიტამინი ძვლებისთვის ☀️', 'კალციუმის შესათვისებლად D ვიტამინი აუცილებელია! კვების კონტროლის ხელსაწყოთი შეამოწმეთ დღევანდელი რაციონი და რეკომენდებულ პროდუქტებში ექიმების მიერ რჩეულ წვეთებს გადახედეთ.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'დაგვიანების კრიზისი 🛑', 'სახლიდან უნდა გახვიდეთ, ის კი ყველაფერს ნელა აკეთებს და არ ჩქარობს? ამ ასაკში ბავშვს დროის აღქმა ჯერ არ აქვს! აჩქარების ნაცვლად, ჩვენი Anacan AI ექსპერტისგან შეიტყვეთ, როგორ გაუადვილოთ ერთი საქმიანობიდან მეორეზე გადასვლა.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'იდეალური დედის ძიებაში 💖', 'დღეს მოთმინება დაკარგეთ და ხმას აუწიეთ? თავს ნუ დაიდანაშაულებთ. ბავშვის დაძინების შემდეგ განწყობის დღიურში თქვენი წუხილის ჩაწერით ემოციური ტვირთი შეიმსუბუქეთ.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'დღის ძილი წარსულს ბარდება? ⏱️', 'შუადღის ძილზე კატეგორიულ უარს ამბობს, საღამოს კი მეტისმეტად იღლება? ძილის ტაიმერის სტატისტიკის გაანალიზებით შეამოწმეთ, მზად არის თუ არა სრულად მშვიდი დროის (quiet time) რეჟიმზე გადასასვლელად.'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'დედის PMS კრიზისი 🍫', 'მენსტრუაციის მოახლოებისას ენერგია დაგიქვეითდათ? სანამ მედიკამენტებს მიმართავთ, ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ბუნებრივი შაქრის შემცველი კენკრის სმუზი, რომელიც ენერგიას სწრაფად შეგმატებთ და ორგანიზმის აღდგენაში დაგეხმარებათ.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'მე თვითონ დავჭრი! ✂️', 'სამზარეულოში ბანანის ან სათამაშო ცომის თავად დაჭრა სურს? ეს შესანიშნავი სურვილია, რომელიც ნატიფ მოტორულ უნარებს ავითარებს! რეკომენდებულ პროდუქტებში ახლავე ნახეთ ბავშვებისთვის უსაფრთხო, არამჭრელი დანები და მაკრატლები.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'რკინის მარაგის შემოწმება 🥩', 'ფერმკრთალია ან მადა არ აქვს? კვების კონტროლის ინსტრუმენტში შეამოწმეთ, რამდენი რკინა მიიღო დღეს და მისი ათვისების გასაუმჯობესებლად ხორცთან ერთად აუცილებლად მიეცით უხვად ლიმონიანი სალათა.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'მამის მასაჟი 💆‍♀️', 'მთელი დღე ბავშვის დევნისგან წელი გაგიშეშდათ? პარტნიორის ფუნქციის მეშვეობით აცნობეთ მას, რომ დღეს საღამოს, ბავშვის დაძინების შემდეგ, თქვენთვის მხრების მოკლე მასაჟის გაკეთების დროა.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'წყლის სმა თამაშად აქციეთ 💧', 'ბევრს დარბის, მაგრამ ცოტა წყალს სვამს? ყაბზობის რისკი იზრდება. აპლიკაციაში მონიშნეთ ნაწლავთა მოქმედება, კვების კონტროლის ინსტრუმენტით მენიუში დაუყოვნებლივ დაამატეთ შვრია და რეკომენდებული პროდუქტებიდან ფერადი საბავშვო წყლის ბოთლები შეუკვეთეთ.'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'არჩევითი მადა 🍝', 'მხოლოდ მაკარონი უნდა? კვების კონტროლის ინსტრუმენტით შეამოწმეთ კვირის კვების ბალანსი. ერთი დღის გამო ნუ ინერვიულებთ და თავს ზედმეტად ნუ დაიტვირთავთ.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'დაღლილობის ცრემლები 💧', 'თქვენც გინდათ ტირილი? ეს სრულიად ნორმალურია. განწყობის დღიურში ჩაწერეთ თქვენი გრძნობები და დანაშაულის განცდა გვერდზე გადადეთ.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'ციფრებს ცნობს? 🔢', 'კიბეზე ასვლისას ან სათამაშოების ალაგებისას ცდილობს რამე დაითვალოს? მათემატიკური განვითარების ეს პირველი ნაპერწკლები დაუყოვნებლივ დაამატეთ ბავშვის ალბომში ხმიან ვიდეოდ და სამუდამო მოგონებად აქციეთ.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'რკინა და ძალა 🥩', 'ფერმკრთალია? კვების კონტროლის ხელსაწყოში შეამოწმეთ, იღებს თუ არა საკმარის რკინას. რკინის უკეთ შესათვისებლად ხორცთან ერთად ლიმონიანი სალათაც მიეცით.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'კბილის ჯაგრისთან ბრძოლა 🪥', 'ჯაგრისის დანახვისას გარბის? რეკომენდებულ პროდუქტებში მუსიკალური ჯაგრისები ნახეთ. ჰიგიენა იძულების ნაცვლად თამაშად აქციეთ.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'ეკრანთან დაკავშირებული კრიზისები 📱', 'ტელეფონის წართმევისას ისტერიკა იწყება? ჰკითხეთ Anacan AI-ს, როგორ დაუწესოთ ეკრანთან გატარებულ დროს საზღვრები სტრესის გარეშე — რეალურად ეფექტური ფსიქოლოგიური მეთოდებით.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'ღამის შიშები 🤖', 'შუაღამისას ყვირილით იღვიძებს და ვერ გცნობთ? ბლოგების განყოფილებაში მოცემული სტატიებიდან ახლავე გაიგეთ, როგორ მოიქცეთ ასეთ დროს და რით განსხვავდება ეს მდგომარეობა სხვა ძილის დარღვევებისგან.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'თქვენც გყავთ მეგობარი ☕', 'მხოლოდ ბავშვთან საუბარი დამღლელია. დედებისთვის მეგობრულ სივრცეებში იპოვეთ საბავშვო კაფეები, დალიეთ ყავა და სხვა დედებს გაესაუბრეთ.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'დილის კრიზისები 🛑', 'ყოველ თქვენს „არაზე“ ტირის? ემოციური აფეთქებების მშვიდად მართვისა და ყურადღების გადატანის გზებზე Anacan AI-ს გაუზიარეთ თქვენი წუხილი.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'დასვრის უფლება 🏖️', 'ტალახში თამაში უნდა? მიეცით დასვრის უფლება! სენსორული განვითარების ხელშემწყობი საუკეთესო ნივთები რეკომენდებულ პროდუქტებში იპოვეთ.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'ზრდის ნახტომი 📏', 'მაისურები დაუმოკლდა? იზრდება! წონის ტრეკერში მიმდინარე მონაცემები შეიყვანეთ და სიამაყით დააკვირდით, როგორ მაღლდება ზრდის მრუდი.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'ცხელი ჩაი და სიმშვიდე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. დაივიწყეთ საოჯახო საქმეები! ჯანსაღი რეცეპტებიდან მელისას ჩაი მოამზადეთ და უბრალოდ სიმშვიდით დატკბით.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'რეჟიმის ანალიზი ⏱️', 'საღამოს დაძინება ძალიან იწელება? გადახედეთ ძილის ტაიმერის გრაფიკს. იქნებ დროა, დღის ძილი მნიშვნელოვნად შეამციროთ.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'კალციუმის ფარი 🦴', 'რძეს არ სვამს? ძვლებისთვის კალციუმი აუცილებელია. კვების კონტროლის ხელსაწყოთი გამოთვალეთ, რამდენ იოგურტსა თუ ბროკოლს იღებს ბავშვი და დანაკლისი შეავსეთ.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'გრძელი წინადადებები 🗣️', 'უკვე სასაცილო ამბებს ჰყვება? მისი ლექსიკური მარაგი სწრაფად იზრდება! არ გაუშვათ ხელიდან ეს ოქროს მომენტი — ბავშვის ალბომში ხმოვანი მოგონება შეინახეთ.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'ბოსტნეული დამალეთ 🥦', 'მწვანილს ან ბროკოლის თეფშიდან ყრის? ბავშვების რეცეპტებში აღმოაჩინეთ ფერადი, ბოსტნეულიანი შინ მომზადებული კექსის რეცეპტი და კვების კონტროლის ხელსაწყოში ვიტამინების დღიური ნორმა მარტივად შეავსეთ.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'თქვენ იდეალური გუნდი ხართ 🌟', 'ყოველი ახალი უნარი, რომელსაც ყოველდღე იძენს, და ყოველი თავდაჯერებული ნაბიჯი თქვენი და თქვენი პარტნიორის შრომის შედეგია. გახსენით განწყობის დღიური და დღეს გუნდური წარმატებისთვის საკუთარ თავს ფეხზე წამოუდექით და ტაში დაუკარით!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'სიმაღლისა და წონის მკვეთრი მატება! 📏', 'ჩაცმისას შენიშნეთ, რომ მაისურები დაუპატარავდა ან ფეხსაცმელი უჭერს? წონის მონიტორინგის ხელსაწყოში შეიყვანეთ მიმდინარე სიმაღლე და სხვა მონაცემები და სიამაყით დააკვირდით, როგორ მიიწევს ზრდის მრუდი ზემოთ.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'მამას ზღაპრის საათი 📚', 'ამ საღამოს ბავშვის დაძინება თქვენს პარტნიორს მიანდეთ. ზღაპარი მან წაიკითხოს, თქვენ კი დატკბით ამ პატარა შესვენებით, რომელიც გაჩუქეს.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', '„რატომ?“ კითხვები 🤔', 'მას სამყაროს გაგება სურს. ბლოგებიდან შეიტყვეთ, როგორ უპასუხოთ მოთმინებით მის დაუსრულებელ კითხვებს. თქვენი მოთმინება – მისი განვითარების საფუძველია.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'ოთხ კედელში ვეღარ ეტევით 🌳', 'სახლში ყველაფერი ჰაერში დაფრინავს? დედებისთვის მეგობრულ სივრცეებში იპოვეთ ახლომდებარე პარკი. სუფთა ჰაერი საუკეთესო წამალია მისთვისაც და თქვენთვისაც.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'ადრეული გაღვიძებები 🌅', 'მზის ამოსვლამდე იღვიძებს და ენერგიით სავსეა? თქვენ კი ძალა აღარ გაქვთ. ჰკითხეთ Anacan AI-ს, როგორ მოაწესრიგოთ ეს რეჟიმი. უძილობა სამუდამოდ არ გაგრძელდება.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'მამის ზღაპარი 📚', 'ჩართეთ პარტნიორის რეჟიმი. ამ საღამოს ზღაპრის მთავარი გმირი მამაა! მან წაიკითხოს, თქვენ კი ყავა მოიმზადეთ და ოთახის გარეთ სიმშვიდით დატკბით.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'გაზიარების სირთულე 🧸', 'თავის სათამაშოს არავის აძლევს? ეს ეგოიზმი კი არა, ასაკისთვის დამახასიათებელი განვითარების ეტაპია. ბლოგებიდან შეიტყვეთ, როგორ ასწავლოთ რიგრიგობით თამაში.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'ცრემლები ნორმალურია 💧', 'დაიღალეთ და უბრალოდ ტირილი გინდათ? ძლიერი დედობა ზოგჯერ საკუთარი სისუსტის აღიარებასაც ნიშნავს.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'ენერგიის დაქვეითება ⚡', 'შუადღისას ფეხზე მდგარს გეძინებათ? კოფეინის ნაცვლად ცილა აირჩიეთ! ჯანსაღ რეცეპტებში მოცემული არაქისის კარაქის სმუზით ენერგია მყისიერად აღიდგინეთ.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'უეცარი ყვირილი 🛑', 'უმიზეზოდ იატაკზე ეცემა? Anacan AI-ს გაუზიარეთ თქვენი დარდი და შეიტყვეთ, როგორ მართოთ ეს კრიზისები სიმშვიდის შენარჩუნებით და არ მიაქციოთ ყურადღება გარშემომყოფთა მზერას.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'გატეხილი ორცხობილის ტრაგედია 🍪', 'ორცხობილა ორად გატყდა და თითქოს სამყაროს აღსასრული დადგა? კეთილი იყოს თქვენი მობრძანება 2.5 წლის ასაკისთვის დამახასიათებელ კლასიკურ კრიზისებში. ლოგიკას ნუ ეძებთ, უბრალოდ უთხარით, რომ გესმით, რამდენად დიდი დარდია ეს მისთვის.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'გაუფილტრავი რეალობა 🛑', 'სოციალურ ქსელებში მშვიდი და სუფთა ბავშვების ვიდეოებს უყურებთ და საკუთარ თავს ადანაშაულებთ? ისინი მხოლოდ 15-წამიანი ილუზიებია. თქვენი არეული და ხმაურიანი რეალობა ყველაზე მშვენიერია.'),
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc', 'პიჟამის პროტესტი 👕', 'ჩაცმა არ უნდა და სახლში დარბის? ეს ბრძოლა თამაშად აქციეთ. აბა, ვნახოთ, ვინ უფრო სწრაფად ჩაიცვამს? შეჯიბრი ხშირად სიჯიუტის დასაძლევად საუკეთესო საშუალებაა.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'პატარა დიქტოფონი ჩაირთო 🎙️', 'თქვენ მიერ შემთხვევით ნათქვამ თითოეულ სიტყვას მაშინვე იმეორებს? ის თქვენი ცოცხალი სარკეა. ამ ასაკში სიტყვების მარაგი ელვის სისწრაფით იზრდება — მონიშნეთ ეს ახალი სიტყვები განვითარების ტრეკერში.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'სწრაფი მომარაგება 🛒', 'უძილობამ ყურადღება გაგიფანტათ? სულ გავიწყდებათ, რა უნდა იყიდოთ? ყველაფერი მაშინვე დაამატეთ საყიდლების სიაში და მიეცით თქვენს პარტნიორს საშუალება, მაღაზიაში საყიდლებზე ზრუნვა მთლიანად საკუთარ თავზე აიღოს.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'მამას ზღაპრების თეატრი 📖', 'მთელი დღე „არას“ თქმისგან თქვენი ხმის იოგები დაიღალა. ამ საღამოს ზღაპრის დრო მამას გადააბარეთ. მან სხვადასხვა ხმით სასაცილო ისტორიები მოყვეს, თქვენ კი დაისვენეთ.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'ხელოვანის ახალი ტილო 🖍️', 'ქაღალდი გაუთავდა და ახლა კედელზე ან კარზე ხატვა უნდა? ის უბრალოდ კი არ ჯღაბნის, არამედ ნატიფი მოტორიკის დახმარებით სამყაროს შეისწავლის. მიეცით დიდი მუყაო და შემოუხაზეთ საზღვრები.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'შეიგრძენით სიჩუმე 🤫', 'სახლში ქაოსი როგორც იქნა დასრულდა და ბავშვმა დაიძინა. ჩართეთ ხმის საზომი, შეამოწმეთ, რამდენად ჩუმია ოთახში და 15 წუთის განმავლობაში არცერთ ეკრანს არ შეხედოთ — უბრალოდ ჩაიძირეთ ამ სიჩუმეში.'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'ბოსტნეულის კამუფლაჟი 🥦', 'თეფშზე ყველაფერ მწვანეს გვერდზე სწევს? საკვებისადმი პრეტენზიულობამ პიკს მიაღწია. კვების გეგმის განყოფილებაში იპოვეთ ეშმაკური რეცეპტები, რომლებშიც ბოსტნეულს პიურედ აქცევთ და კატლეტში დამალავთ.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'საზღვრები პარკში 🧸', 'ქვიშის მოედანზე თავის სათლს არავის აძლევს? ეს ეგოიზმი კი არა, საკუთრების ცნების გააზრებაა. გაზიარება ძალდატანებით კი არა, რიგრიგობით ასწავლეთ: ახლა მისი ჯერია.'),
  ('b0edd680-c98e-4626-b7fa-18383befe832', 'წარმოსახვითი სტუმრები მოვიდნენ ☕', 'ოთახში მარტო მყოფი თავის უხილავ მეგობრებს ესაუბრება და ჩაის უსხამს? ეს წარმოსახვის განვითარების მწვერვალია! გვერდიდან სიამაყით დააკვირდით ამ შესანიშნავ სცენარისტს.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'ჯადოქრობას ბავშვი მართავს 🪄', 'კლასიკურმა ზღაპრებმა დაღალა? ჭკვიან ზღაპრებში ამჯერად თავად აარჩევინეთ მთავარი გმირი. მფრინავი ძაღლი თუ მოლაპარაკე ხე — მიეცით მის ფანტაზიას სრული თავისუფლება.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'თავის წესებს ადგენს 🛑', 'ყველაფრის გაკეთება თავად სურს! ფეხსაცმელს უკუღმა იცვამს, მაისურს — არასწორად, მაგრამ მაინც თავისას არ იშლის. ამით არაფერი დაშავდება — დამოუკიდებლობის სურვილი გარეგნობაზე მნიშვნელოვანია, ამიტომ მიეცით ამის უფლება.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'წყლის თერაპია 🛀', 'მთელი დღის სირბილისგან ნერვები მასაც დაეძაბა და თქვენც. თბილი აბაზანა მხოლოდ ჰიგიენისთვის არ არის — გამოიყენეთ წყლის საოცარი უნარი, მოხსნას დაძაბულობა.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'ემოციური გამოფიტვა 🔋', 'გინდათ, ყველაფერზე იყვიროთ? ეს ემოციური გამოფიტვაა. დაუყოვნებლივ შეუერთდით Anacan-ის საზოგადოებას, წაიკითხეთ იმ დედების გულწრფელი ამბები, რომლებიც იმავე ეტაპს გადიან, და მიიღეთ მხარდაჭერა.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'სამზარეულოს დივერსია 🧑‍🍳', 'სანამ თქვენ საჭმელს ამზადებთ, ის ქვაბებით კონცერტს მართავს? მასაც სურს, გუნდის წევრი იყოს. მიეცით ცომის პატარა ნაჭერი და მასაც მიეცით საშუალება, საჭმელი მოამზადოს.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'ერთად ვუმკლავდებით 🥂', 'ბავშვის დაძინების შემდეგ პარტნიორთან პირისპირ დაჯექით. ბავშვზე საუბრის ნაცვლად, გაუღიმეთ ერთმანეთს და თქვით: „დღესაც გადავრჩით“. იგრძენით, რომ ერთი გუნდი ხართ.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'გარეთ გასვლის აუცილებლობა ⛅', 'ოთხ კედელში ყოფნა გახრჩობთ. ამინდისა და ტანსაცმლის ხელსაწყოში რეალური ტემპერატურა შეამოწმეთ და დაუფიქრებლად გაეშურეთ პარკისკენ. სუფთა ჰაერი ყველაზე მწვავე კრიზისსაც კი სწრაფად აცხრობს.')
) AS v(id, t, b)
WHERE x.id = v.id;
